#include <bits/stdc++.h>
using namespace std;

const int N = 5005;
const int inf = 1e9;

int h[N], e[N*2], nxt[N*2], idx;
int dis[N][N];
int n, m, k;
int s1, t1, s2, t2;
int path[N];
double ans;

void add(int u, int v) {
    e[idx] = v;
    nxt[idx] = h[u];
    h[u] = idx++;
}

void bfs(int s) {
    for (int i = 1; i <= n; ++i) {
        dis[s][i] = (i == s) ? 0 : inf;
    }
    queue<int> q;
    q.push(s);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int i = h[u]; ~i; i = nxt[i]) {
            int v = e[i];
            if (dis[s][v] == inf) {
                dis[s][v] = dis[s][u] + 1;
                q.push(v);
            }
        }
    }
}

double calc(int tot, int val) {
    if (tot == 0) return 0.0;
    if (val == 0) return (double)tot;
    int ave = val / tot;
    int lef = val % tot;
    return (double)(tot - lef) / (ave + 1) + (double)lef / (ave + 2);
}

double check(int sha, int idv, int mid) {
    return 2.0 * calc(sha, mid) + calc(idv, k - mid);
}

double solve(int sha, int idv) {
    int l = 0, r = k;
    double ret = 1e30;
    while (l <= r) {
        int lmid = l + (r - l) / 3;
        int rmid = r - (r - l) / 3;
        double lval = check(sha, idv, lmid);
        double rval = check(sha, idv, rmid);
        if (lval < rval) {
            r = rmid - 1;
            ret = min(ret, lval);
        } else {
            l = lmid + 1;
            ret = min(ret, rval);
        }
    }
    return ret;
}

int main() {
    scanf("%d%d%d", &n, &m, &k);
    memset(h, -1, sizeof h);
    for (int i = 1; i <= m; ++i) {
        int u, v;
        scanf("%d%d", &u, &v);
        add(u, v);
        add(v, u);
    }
    scanf("%d%d%d%d", &s1, &t1, &s2, &t2);

    for (int i = 1; i <= n; ++i) {
        bfs(i);
    }

    for (int i = 0; i <= n; ++i) {
        path[i] = inf;
    }

    for (int u = 1; u <= n; ++u) {
        for (int v = 1; v <= n; ++v) {
            if (dis[u][v] != inf) {
                if (dis[s1][u] != inf && dis[s2][u] != inf && dis[v][t1] != inf && dis[v][t2] != inf) {
                    int total = dis[s1][u] + dis[s2][u] + dis[v][t1] + dis[v][t2];
                    if (total < path[dis[u][v]]) {
                        path[dis[u][v]] = total;
                    }
                }
                if (dis[s1][u] != inf && dis[t2][u] != inf && dis[v][t1] != inf && dis[v][s2] != inf) {
                    int total = dis[s1][u] + dis[t2][u] + dis[v][t1] + dis[v][s2];
                    if (total < path[dis[u][v]]) {
                        path[dis[u][v]] = total;
                    }
                }
            }
        }
    }

    ans = check(0, dis[s1][t1] + dis[s2][t2], 0);
    for (int i = 0; i <= n; ++i) {
        if (path[i] != inf) {
            double current = solve(i, path[i]);
            if (current < ans) {
                ans = current;
            }
        }
    }

    printf("%.20lf\n", ans);

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 5e4+5;
const int MAXM = 1e6+5;
const int MAXV = 4e6+5;
const int MAXE = 3e7+5;
const int MAXP = 17;
const int INF = 1<<30;

int n,m,s;

int u1[MAXM];
int v1[MAXM];
int u2[MAXM];
int v2[MAXM];
int weight[MAXM];
int cntq;

int head1[MAXN];
int nxt1[MAXN<<1];
int to1[MAXN<<1];
int cnt1=1;

int head2[MAXV];
int nxt2[MAXE];
int to2[MAXE];
int weight2[MAXE];
int cnt2=1;

int fa[MAXN];

int dep[MAXN];
int st[MAXN][MAXP];
int stout[MAXN][MAXP];
int stin[MAXN][MAXP];
int cntt;

int dist[MAXV];
bool vis[MAXV];

struct node{
    int u,d;
};
struct compare{
    bool operator()(const node &a,const node &b){
        return a.d>b.d;
    }
};
priority_queue<node,vector<node>,compare>heap;

void addedge1(int u,int v){
    nxt1[cnt1]=head1[u];
    to1[cnt1]=v;
    head1[u]=cnt1++;
}

void addedge2(int u,int v,int w){
    nxt2[cnt2]=head2[u];
    to2[cnt2]=v;
    weight2[cnt2]=w;
    head2[u]=cnt2++;
}

int find(int x){
    return x==fa[x]?x:fa[x]=find(fa[x]);
}

void build(int u,int fa){
    dep[u]=dep[fa]+1;
    st[u][0]=fa;

    stout[u][0]=++cntt;
    addedge2(u,cntt,0);
    addedge2(fa,cntt,0);

    stin[u][0]=++cntt;
    addedge2(cntt,u,0);
    addedge2(cntt,fa,0);

    for(int p=1;p<MAXP;p++){
        st[u][p]=st[st[u][p-1]][p-1];

        stout[u][p]=++cntt;
        addedge2(stout[u][p-1],cntt,0);
        addedge2(stout[st[u][p-1]][p-1],cntt,0);

        stin[u][p]=++cntt;
        addedge2(cntt,stin[u][p-1],0);
        addedge2(cntt,stin[st[u][p-1]][p-1],0);
    }

    for(int i=head1[u];i;i=nxt1[i]){
        int v=to1[i];
        if(v!=fa){
            build(v,u);
        }
    }
}

void pathout(int x,int y,int vnode){
    if (dep[x] < dep[y]) {
        swap(x, y);
    }
    addedge2(y, vnode, 0);
    for (int p = MAXP - 1; p >= 0; p--) {
        if (dep[st[x][p]] >= dep[y]) {
            addedge2(stout[x][p], vnode, 0);
            x = st[x][p];
        }
    }
    if (x == y) {
        return;
    }
    for (int p = MAXP - 1; p >= 0; p--) {
        if (st[x][p] != st[y][p]) {
            addedge2(stout[x][p], vnode, 0);
            addedge2(stout[y][p], vnode, 0);
            x = st[x][p];
            y = st[y][p];
        }
    }
    addedge2(stout[x][0], vnode, 0);
}

void pathin(int x,int y,int vnode){
    if(dep[x]<dep[y]){
        swap(x,y);
    }
    addedge2(vnode,y,0);
    for(int p=MAXP-1;p>=0;p--){
        if(dep[st[x][p]]>=dep[y]){
            addedge2(vnode,stin[x][p],0);
            x=st[x][p];
        }
    }

    if(x==y){
        return ;
    }

    for(int p=MAXP-1;p>=0;p--){
        if(st[x][p]!=st[y][p]){
            addedge2(vnode, stin[x][p], 0);
            addedge2(vnode, stin[y][p], 0);
            x=st[x][p];
            y=st[y][p];
        }
    }
    addedge2(vnode,stin[x][0],0);
}

void pathtopath(int a,int b,int c,int d,int w){
    int x=++cntt;
    int y=++cntt;
    pathout(a,b,x);
    pathin(c,d,y);
    addedge2(x,y,w);
}

void dijkstra(){
    for(int i=1;i<=cntt;i++){
        dist[i]=INF;
    }
    dist[s]=0;
    heap.push({s,0});
    while(!heap.empty()){
        node cur=heap.top();
        heap.pop();
        int u=cur.u;
        int d=cur.d;
        if(vis[u]){
            continue;
        }
        vis[u]=true;
        for(int i=head2[u];i;i=nxt2[i]){
            int w=weight2[i];
            int v=to2[i];
            if(!vis[v]&&dist[v]>d+w){
                dist[v]=d+w;
                heap.push({v,dist[v]});
            }
        }
    }
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m>>s;
    cntt=n;

    for(int i=1;i<=n;i++){
        fa[i]=i;
    }
    for(int i=1;i<=m;i++){
        int op,a,b,c,d,u,v,w;
        cin>>op;
        if(op==1){
            cin>>a>>b>>c>>d>>w;
            if((find(a)==find(b))&&(find(c)==find(d))){
                ++cntq;
                u1[cntq]=a;
                v1[cntq]=b;
                u2[cntq]=c;
                v2[cntq]=d;
                weight[cntq]=w;
            }
        }
        else{
            cin>>u>>v>>w;
            int ufa=find(u);
            int vfa=find(v);
            if(ufa!=vfa){
                addedge1(u,v);
                addedge1(v,u);
                addedge2(u,v,w);
                addedge2(v,u,w);
                fa[ufa]=vfa;
            }
        }
    }

    for(int i=1;i<=n;i++){
        if(dep[i]==0){
            build(i,i);
        }
    }

    for(int i=1;i<=cntq;i++){
        pathtopath(u1[i],v1[i],u2[i],v2[i],weight[i]);
    }

    dijkstra();

    for(int i=1;i<=n;i++){
        cout<<((dist[i]==INF)?-1:dist[i])<<" ";
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 10005;
const int MAXM = MAXN*60;

int n,m;

int f[MAXN];

int cnt=1;
int path;
int tree[MAXM][55];

void insert(string word){
    int cur=1;
    for (char ch : word){
        if(ch>='a'&&ch<='z'){
            path=ch-'a';
        }
        else{
            path=26+ch-'A';
        }
        if(tree[cur][path]==0){
            tree[cur][path]=++cnt;
            //没有路就要新建一条路  并赋予编号
        }
        cur=tree[cur][path];
    }
}

int preword(string word){
    int cur=1;
    for (char ch : word){
        if(ch>='a'&&ch<='z'){
            path=ch-'a';
        }
        else{
            path=26+ch-'A';
        }
        if(tree[cur][path]==0){
            return 0;
            //没有路说明走不通
        }
        cur=tree[cur][path];
    }
    return 1;
}

int main()
{
    cin>>n>>m;
    int ans=0;
    string str;
    for(int i=1;i<=n;i++){
        cin>>str;
        insert(str);
    }
    for(int i=1;i<=m;i++){
        cin>>str;
        ans+=preword(str);
    }
    cout<<ans<<endl;
    f[1]=1,f[2]=2;
    for(int i=3;i<=n;i++){
        f[i]=f[i-1]+f[i-2];
    }
    cout<<f[n];
    return 0;
}

#include<iostream>
#include<algorithm>
using namespace std;
int main()
{
	int n, a[502], b[500],c[500],sum=0;
	scanf("%d", &n);
	for (int i = 1; i <= n + 1; i++)
	{
		scanf("%d", &a[i]);
		sum += a[i];
	}
	int num = 0, res[501];
	for (int i = 1; i <= n + 1; i++){
		if (sum % 2 != a[i] % 2)
			continue;
		int index = 0;
		for (int j = 1; j <= n + 1; j++)
			if (j != i)
				b[index++] = a[j];
		sort(b, b + n, [](const int x, const int y) {
			return x > y;
        });
		bool flag = 1;
		for (int j = 1; j <= n; j++){
			if (b[0] == 0)
				break;
			int in = 1;
			while (b[0] > 0 && b[in] > 0){
				b[0]--;
				b[in++]--;
			}
			if (b[0] > 0){
				flag = 0;
				break;
			}
			int p = 1, q = in, cnt = 0;
			while (p < in && q < n)
				if (b[p] > b[q])
					c[cnt++] = b[p++];
				else
					c[cnt++] = b[q++];
			while (p < in)
				c[cnt++] = b[p++];
			while (q < n)
				c[cnt++] = b[q++];
			for (int k = 0; k < n - 1; k++)
				b[k] = c[k];
			b[n - 1] = 0;
		}
		if (flag)
			res[num++] = i;
	}
	printf("%d\n", num);
	for (int i = 0; i < num; i++)
		printf("%d\n", res[i]);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

// 快速读入整数函数
inline int read() {
    int s = 0, w = 1;
    char ch = getchar();
    while (ch < '0' || ch > '9') {
        if (ch == '-') w = -1;
        ch = getchar();
    }
    while (ch >= '0' && ch <= '9') {
        s = s * 10 + ch - '0';
        ch = getchar();
    }
    return s * w;
}

const int MAXN = 1003;
int tree[MAXN], n;  // tree: 树状数组，n: 网格大小
int a[MAXN][MAXN];  // 存储网格数据，a[列][行]
vector<int> v[MAXN][MAXN];  // v[列][颜色]存储该颜色在该列中的行位置

// 树状数组更新函数：在位置x更新最大值k
void add(int x, int k) {
    while (x <= n) {
        tree[x] = max(tree[x], k);  // 维护最大值
        x += x & -x;  // 跳转到父节点
    }
}

// 树状数组查询函数：查询[1,x]范围内的最大值
int find(int x) {
    int res = 0;
    while (x) {
        res = max(res, tree[x]);  // 取最大值
        x -= x & -x;  // 跳转到前一个区间
    }
    return res;
}

int main() {
    n = read();  // 读取网格大小n

    // 读取网格数据并预处理
    // 注意：j从n到1，表示从底部到顶部读取
    for (int j = n; j >= 1; --j) {
        for (int i = 1; i <= n; ++i) {
            // 读取颜色值并记录位置
            v[i][a[i][j] = read()].push_back(j);
        }
    }

    int ans = n * n;  // 初始答案为最坏情况下的操作次数（每个珠子单独消除）

    // 遍历所有相邻的列对 (i, i+1)
    for (int i = 1; i < n; ++i) {
        // 清空树状数组，为新的列对做准备
        fill(tree + 1, tree + n + 1, 0);
        int q = 0;  // 记录当前列对的最长公共子序列长度

        // 按第i+1列的顺序处理（从顶部到底部，即j=1到n）
        for (int j = 1; j <= n; ++j) {
            vector<pair<int, int>> z;  // 临时存储匹配的位置和对应的DP值

            // 在第i列中查找与第i+1列当前位置颜色相同的位置
            for (int k : v[i][a[i + 1][j]]) {
                // 对于每个匹配位置k，查询[1,k-1]范围内的最大DP值
                z.emplace_back(k, find(k - 1));
            }

            // 处理所有匹配位置
            for (auto &k : z) {
                // 更新最长公共子序列长度
                q = max(q, k.second + 1);
                // 更新树状数组：在位置k处记录新的DP值
                add(k.first, k.second + 1);
            }
        }

        // 从总操作次数中减去这一对列的最长公共子序列长度
        // 因为每对匹配的珠子可以减少一次操作
        ans -= q;
    }

    // 输出最终的最小操作次数
    printf("%d\n", ans);
    return 0;
}

