#include<bits/stdc++.h>
using namespace std;
const int MAXN = 5e6+1;
const int MAXM = 1e7+2;

int n,a,b,m;
int nums1[MAXN];
int nums2[MAXN];
int inv[MAXM];
long long f[MAXN];

inline int power(int a,int b){
    long long ans=1;
    while(b){
        if(b&1){
            ans=(ans*a)%m;
        }
        a=(1ll*a*a)%m;
        b>>=1;
    }
    return (int)ans;
}

void build(){
    for(int i=0;i<=(n+1)/2;i++){
        nums1[i]=power(i,b);
        nums2[i]=power(n-i,a);
    }
    inv[1]=1;
    for(int i=2;i<=n+1;i++){
        inv[i]=(int)(m-1ll*inv[m%i]*(m/i)%m+m)%m;
    }
}

int main()
{
    cin>>n>>a>>b>>m;
    build();
    f[0]=1;
    for(int i=1;i<=(n+1)/2;i++){
        f[i]=(f[i-1]*(n-2*i+3)%m*(n-2*i+2)%m*inv[i]%m*inv[n-i+2]%m+m)%m;
    }
    long long ans=0;
    for(int i=0;i<=(n+1)/2;i++){
        ans+=f[i]*nums1[i]%m*nums2[i]%m;
        ans%=m;
    }
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long 
const int MOD = 1e9+7;
const int MAXN = 1e6+5;

int n,m,k;
int f[MAXN];
int g[MAXN];

int power(int a,int b){
    int ans=1;
    while(b){
        if(b&1){
            ans=(ans*a)%MOD;
        }
        a=(a*a)%MOD;
        b>>=1;
    }
    return ans;
}

signed main()
{
    cin>>n>>m>>k;
    if(k>n){
        cout<<0<<endl;
        return 0;
    }
    f[0]=1;
    for(int i=1;i<k;i++){
        f[i]=(m*f[i-1])%MOD;
        g[i]=(g[i-1]+f[i])%MOD;
    }
    for(int i=k;i<=n;i++){
        f[i]=(m-1)*(g[i-1]-g[i-k])%MOD;
        g[i]=(g[i-1]+f[i])%MOD;
    }
    int ans=power(m,n);
    ans=((ans-f[n])%MOD+MOD)%MOD;
    cout<<ans<<endl;
    return 0;
}

#include <iostream>
#include <cstdio>
#include <queue>
#include <cstring>
#include <cmath>
#include <algorithm>
using namespace std;

const int MAXN = 100005;
const int INF = 0x3f3f3f3f;

struct edge {
    int nxt, to, weight, val;
} e[MAXN << 2];

int T, n, a, b, tot, s, t;
int h[MAXN], cur[MAXN], dep[MAXN], cost;
int node[MAXN], cnt, plane[MAXN][3], sum[MAXN];
double p;
bool vis[MAXN];

inline void add(int x, int y, int w, int val) {
    e[++tot].nxt = h[x];
    h[x] = tot;
    e[tot].to = y;
    e[tot].weight = w;
    e[tot].val = val;

    e[++tot].nxt = h[y];
    h[y] = tot;
    e[tot].to = x;
    e[tot].weight = 0;
    e[tot].val = -val;
}

inline bool SPFA() {
    for(int i = 0; i <= t; ++i) {
        vis[i] = false;
        dep[i] = INF;
        cur[i] = h[i];
    }
    queue<int> q;
    q.push(s);
    dep[s] = 0;

    while(!q.empty()) {
        int k = q.front();
        q.pop();
        vis[k] = false;

        for(int i = h[k]; i; i = e[i].nxt) {
            if(e[i].weight && dep[e[i].to] > dep[k] + e[i].val) {
                dep[e[i].to] = dep[k] + e[i].val;
                if(!vis[e[i].to]) {
                    vis[e[i].to] = true;
                    q.push(e[i].to);
                }
            }
        }
    }
    return dep[t] != INF;
}

int dfs(int k, int f) {
    if(k == t) {
        vis[t] = true;
        return f;
    }
    vis[k] = true;
    int r = 0, used = 0;

    for(int &i = cur[k]; i; i = e[i].nxt) {
        if((!vis[e[i].to] || e[i].to == t) && e[i].weight && dep[e[i].to] == dep[k] + e[i].val) {
            if((r = dfs(e[i].to, min(e[i].weight, f - used)))) {
                e[i].weight -= r;
                e[i ^ 1].weight += r;
                used += r;
                cost += r * e[i].val;
                if(f == used) break;
            }
        }
    }
    return used;
}

inline int dinic() {
    cost = 0;
    while(SPFA()) {
        vis[t] = true;
        while(vis[t]) {
            memset(vis, false, sizeof(vis));
            dfs(s, INF);
        }
    }
    return cost;
}

void init() {
    tot = 1;
    memset(h, 0, sizeof(h));
    memset(node, 0, sizeof(node));
    memset(sum, 0, sizeof(sum));
    cnt = 0;
}

int main() {
    scanf("%d", &T);
    while(T--) {
        init();
        scanf("%d%d%d%lf", &n, &a, &b, &p);

        // 读入飞机数据并收集时间点
        for(int i = 1; i <= n; ++i) {
            scanf("%d%d%d", &plane[i][0], &plane[i][1], &plane[i][2]);
            node[++cnt] = plane[i][1];
            node[++cnt] = plane[i][2];
        }

        // 离散化时间
        sort(node + 1, node + cnt + 1);
        cnt = unique(node + 1, node + cnt + 1) - node - 1;

        // 设置源点和汇点
        s = n + cnt + 1;
        t = s + 1;

        // 检查可行性
        bool flag = true;
        for(int i = 1; i <= n; ++i) {
            int s_idx = lower_bound(node + 1, node + cnt + 1, plane[i][1]) - node;
            int t_idx = lower_bound(node + 1, node + cnt + 1, plane[i][2]) - node;
            sum[s_idx]++;
            sum[t_idx]--;
        }

        for(int i = 1; i <= cnt; ++i) {
            sum[i] += sum[i - 1];
            if(sum[i] > a + b) {
                puts("impossible");
                flag = false;
                break;
            }
        }
        if(!flag) continue;

        // 重新初始化sum数组用于建图
        memset(sum, 0, sizeof(sum));

        // 建图
        // 1. 时间点之间的边（登机桥容量限制）
        for(int i = 1; i < cnt; ++i) {
            add(i, i + 1, a, 0);
        }

        // 2. 飞机相关的边
        for(int i = 1; i <= n; ++i) {
            int s_idx = lower_bound(node + 1, node + cnt + 1, plane[i][1]) - node;
            int t_idx = lower_bound(node + 1, node + cnt + 1, plane[i][2]) - node;
            int x = plane[i][0];

            // 源点到登机时间点
            add(s, s_idx, 1, 0);

            // 飞机点到汇点
            add(i + cnt, t, 1, 0);

            // 方案1：一直在摆渡车（从登机时间点直接到飞机点）
            add(s_idx, i + cnt, 1, x);

            // 方案2：一直在登机桥（从起飞时间点到飞机点）
            add(t_idx, i + cnt, 1, 0);

            // 方案3：先登机桥后摆渡车（从登机时间+1到飞机点）
            if(s_idx + 1 <= cnt) {
                add(s_idx + 1, i + cnt, 1, (int)floor(x * p + 1e-5));
            }
        }

        printf("%d\n", dinic());
    }
    return 0;
}

