    int l,r,v;
}nums[MAXN];

// 可持久化线段树
int root[MAXN<<1];//表示 离散化后编号为i的书 的线段树
//初始时最多有MAXN个编号  再加上后续修改操作的个数
int ls[MAXT];
int rs[MAXT];
// 可持久化线段树的节点空间计数
int cnt = 0;
int tree[MAXT];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

int getrank(int val){
    int l=1,r=t,ans=1;
    while(l<=r){
        int mid=(l+r)/2;
        if(help[mid]>=val){
            ans=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    return ans;
}

// 建树，返回头节点编号
int build(int l, int r) {
    int rt = ++cnt;
    if (l == r) {
        tree[rt] = 0;
    } else {
        int mid = (l + r) >> 1;
        ls[rt] = build(l, mid);
        rs[rt] = build(mid + 1, r);
    }
    return rt;
}

//增加位置jobi的数目为jobv
int update(int jobi, int jobv, int l, int r, int i) {
    int rt = ++cnt;//新建一个节点（沿途节点）
    ls[rt] = ls[i];
    rs[rt] = rs[i];
    tree[rt] = tree[i]+jobv;
    //拷贝原有信息
    if (l == r) {
        //到达了要修改的节点位置
        //tree[rt] += jobv;
    } else {
        int mid = (l + r) >> 1;
        if (jobi <= mid) {
            ls[rt] = update(jobi, jobv, l, mid, ls[rt]);
        } else {
            rs[rt] = update(jobi, jobv, mid + 1, r, rs[rt]);
        }
    }
    return rt;
}

// 线段树范围l~r，信息在i号节点里
// 返回l~r范围上jobi位置的值
int query(int jobl,int jobr, int l, int r, int i) {
	if(jobl<=l&&r<=jobr){
        return tree[i];
	}
	else{
        int mid=(l+r)/2;
        int ans=0;
        if(jobl<=mid){
            ans+=query(jobl,jobr,l,mid,ls[i]);
        }
        if(jobr>mid){
            ans+=query(jobl,jobr,mid+1,r,rs[i]);
        }
        return ans;
	}
}

