        int mid=(l+r)>>1;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        up(i);
    }
}

void lazy(int i,int val){
    tag[i]^=val;
    for(int k=0;k<10;k++){
        if(val&(1<<k)){
            tree[i][k]=len[i]-tree[i][k];
        }
    }
}

void down(int i){
    if(tag[i]){
        lazy(i<<1,tag[i]);
        lazy(i<<1|1,tag[i]);
        tag[i]=0;
    }
}

void update(int jobl,int jobr,int jobv,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        lazy(i,jobv);
    }
    else{
        int mid=(l+r)>>1;
        down(i);
        if(jobl<=mid){
            update(jobl,jobr,jobv,l,mid,i<<1);
        }
        if(jobr>mid){
            update(jobl,jobr,jobv,mid+1,r,i<<1|1);
        }
        up(i);
    }
}

void query(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        for(int k=0;k<10;k++){
            res[k]+=tree[i][k];
        }
    }
    else{
        int mid=(l+r)>>1;
        down(i);
        if(jobl<=mid){
            query(jobl,jobr,l,mid,i<<1);
        }
        if(jobr>mid){
            query(jobl,jobr,mid+1,r,i<<1|1);
        }
    }
}

void query(int x,int y){
    for(int i=0;i<10;i++){
        res[i]=0;
    }
    all=0;

    while(top[x]!=top[y]){
        if(dep[top[x]]<dep[top[y]]){
            swap(x,y);
        }
        all+=dfn[x]-dfn[top[x]]+1;
        query(dfn[top[x]],dfn[x],1,n,1);
        x=fa[top[x]];
    }
    if(dep[x]<dep[y]){
        swap(x,y);
    }
    all+=dfn[x]-dfn[y]+1;
    query(dfn[y],dfn[x],1,n,1);
}

