using namespace std;
const int MAXN = 1e6+5;

int n,m,p;

int doorkey[MAXN];
int keyblock[MAXN];
int belong[MAXN];
int in[MAXN];
int lt[MAXN];
int rt[MAXN];
int que[MAXN];

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m>>p;
    for(int i=1;i<=m;i++){
        int x,y;
        cin>>x>>y;
        doorkey[x]=y;
    }

    int cnt=1;
    belong[1]=1;
    for(int i=2;i<=n;i++){
        if(doorkey[i-1]!=0){
            cnt++;
        }

        belong[i]=cnt;
    }

    for(int i=1;i<n;i++){
        if(doorkey[i]!=0){
            keyblock[belong[i]]=belong[doorkey[i]];
        }
    }

    for(int i=1;i<cnt;i++){
        if(keyblock[i]<=i){
            in[i]++;
        }
        else{
            in[i+1]++;
        }
    }

    int l=1,r=0;

    for(int i=1;i<=cnt;i++){
        lt[i]=rt[i]=i;
        if(in[i]==0){
            que[++r]=i;
        }
    }

    while(l<=r){
        int x=que[l++];

        while(true){
            bool flag=false;

            if(lt[x]>1&&keyblock[lt[x]-1]>=lt[x]&&keyblock[lt[x]-1]<=rt[x]){
                lt[x]=lt[lt[x]-1];
                flag=true;
            }
            if(rt[x]<cnt&&keyblock[rt[x]]>=lt[x]&&keyblock[rt[x]]<=rt[x]){
                rt[x]=rt[rt[x]+1];
                flag=true;
            }

            if(!flag){
                break;
            }
        }

        if(x>1&&keyblock[x-1]<=x-1){
            if(--in[x-1]==0){
                que[++r]=x-1;
            }
        }
        if(x<cnt&&keyblock[x]>x){
            if(--in[x+1]==0){
                que[++r]=x+1;
            }
        }
    }

    while(p--){
        int s,t;
        cin>>s>>t;
        s=belong[s];
        t=belong[t];
        if(lt[s]<=t&&t<=rt[s]){
            cout<<"YES"<<endl;
        }
        else{
            cout<<"NO"<<endl;
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 1e5+5;

int n,m;
int val[MAXN];

//链式前向星建图
int head[MAXN];
int Next[MAXN];
int to[MAXN];
int tot=1;

//线段树
int tree[MAXN<<2];
int lazy[MAXN<<2];
int len[MAXN<<2];//要记录长度 因为这里加的话是每一个元素都要加

//树链剖分部分
int son[MAXN];//重儿子编号  叶子结点没有
int id[MAXN];//重新编号后的编号
int rk[MAXN];//重新编号后的编号对应原来的编号是什么
int cnt;
int fa[MAXN];//父亲节点编号
int deep[MAXN];//节点深度
int sz[MAXN];//以该节点为首的子树节点总数
int top[MAXN];//这条重链的头结点

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v){
    Next[tot]=head[u];
    to[tot]=v;
    head[u]=tot++;
}

//第一遍dfs 完成sz、deep、fa、son数组的统计
void dfs1(int u,int f){
    fa[u]=f;
    deep[u]=deep[f]+1;
    sz[u]=1;
    for(int i=head[u];i;i=Next[i]){
        int v=to[i];
        if(v==f){
            continue;
        }
        dfs1(v,u);
        sz[u]+=sz[v];
        if(sz[son[u]]<sz[v]){
            son[u]=v;
        }
    }
}

//第二遍dfs 完成top、rk、id
void dfs2(int u,int t){
    top[u]=t;
    id[u]=++cnt;
    rk[cnt]=u;
    if(son[u]){
        //存在重儿子  优先遍历
        dfs2(son[u],t);
    }
    for(int i=head[u];i;i=Next[i]){
        int v=to[i];
        if(v!=fa[u]&&v!=son[u]){
            dfs2(v,v);
            //另外在开一条重链
        }
    }
}

//线段树部分
void up(int i){
    tree[i]=tree[i<<1]+tree[i<<1|1];
}

//注意编号问题
void build(int l,int r,int i){
    lazy[i]=0;
    len[i]=r-l+1;
    if(l==r){
        tree[i]=val[rk[l]];
    }
    else{
        int mid=(l+r)/2;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        up(i);
    }
}

void downlazy(int i,int v){
    tree[i]+=len[i]*v;
    lazy[i]+=v;
}

void down(int i){
    if(lazy[i]){
        downlazy(i<<1,lazy[i]);
        downlazy(i<<1|1,lazy[i]);
        lazy[i]=0;
    }
}

void add(int jobl,int jobr,int jobv,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        downlazy(i,jobv);
    }
    else{
        int mid=(l+r)/2;
        down(i);
        if(jobl<=mid){
            add(jobl,jobr,jobv,l,mid,i<<1);
        }
        if(jobr>mid){
            add(jobl,jobr,jobv,mid+1,r,i<<1|1);
        }
        up(i);
    }
}

int query(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        return tree[i];
    }
    else{
        int mid=(l+r)/2;
        down(i);
        int ans=0;
        if(jobl<=mid){
            ans+=query(jobl,jobr,l,mid,i<<1);
        }
        if(jobr>mid){
            ans+=query(jobl,jobr,mid+1,r,i<<1|1);
        }
        return ans;
    }
}

inline void update(int x,int y,int val){
    while(top[x]!=top[y]){
        if(deep[top[x]]<deep[top[y]])
            swap(x,y);
        add(id[top[x]],id[x],val,1,n,1);//结算这条重链上存在的贡献
        x=fa[top[x]];
    }
    //两点在同一条重链上
    if(id[x]>id[y])
        swap(x,y);
    add(id[x],id[y],val,1,n,1);
    //结算贡献区间
}

inline int sum(int x,int y){
    int ans=0;
    while(top[x]!=top[y]){
        if(deep[top[x]]<deep[top[y]])
            swap(x,y);
        ans+=query(id[top[x]],id[x],1,n,1);
        x=fa[top[x]];
    }
    if(id[x]>id[y])
        swap(x,y);
    ans+=query(id[x],id[y],1,n,1);
    return ans;
}

