const int BASE = 499;
const int MOD = 1e9+7;
const int BASE2 = 131;
const int MOD2 = 998244353;
const int MAXN = 2e5+5;

int n,m;
char s[MAXN];
int h[26][MAXN];
int h2[26][MAXN];
int p[MAXN];
int p2[MAXN];

