inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

int gethash(int l,int r,int op){
    return (h[op][r]-h[op][l-1]*p[r-l+1]%MOD+MOD)%MOD;
}

int gethash2(int l,int r,int op){
    return (h2[op][r]-h2[op][l-1]*p2[r-l+1]%MOD2+MOD2)%MOD2;
}

void prepare(){
    p[0]=1;
    p2[0]=1;
    for(int i=1;i<=n;i++){
        p[i]=(p[i-1]*BASE)%MOD;
        p2[i]=(p2[i-1]*BASE2)%MOD2;
    }
    for(int i=1;i<=n;i++){
        for(int j=0;j<26;j++){
            h[j][i]=(h[j][i-1]*BASE)%MOD;
            h2[j][i]=(h2[j][i-1]*BASE2)%MOD2;
        }
        int op=s[i]-'a';
        h[op][i]=(h[op][i]+1)%MOD;
        h2[op][i]=(h2[op][i]+1)%MOD2;
    }
}

