    for(int i=1;i<=m;i++){
        int u,v,w,c;
        u=read(),v=read(),w=read(),c=read();
        addedge(u,v,w,c);
    }
    mincostmaxflow();
    cout<<maxflow<<' '<<mincost<<endl;
    return 0;
}

