        sum[i]+=sum[i-1];
    }
    head=tail=0;
    for(int i=1;i<=2*n;i++){
        while(head<tail&&q[head]<=i-n-1){
            head++;
        }
        if(i>n){
            if(sum[i]-sum[q[head]]>=0){
                ans[i-n]=true;
            }
        }
        while(head<tail&&sum[q[tail-1]]<=sum[i]){
            tail--;
        }
        q[tail++]=i;
    }
    for(int i=1;i<=n;i++){
        if(ans[i]){
            printf("TAK\n");
        }
        else{
            printf("NIE\n");
        }
    }
    return 0;
}

