const int MAXN = 1e5+5;
const int MAXM = 2e6+5;
const int BIT = 16;

int n,m,T;

int val[MAXN];

int op[MAXN];
int s[MAXN];
int v[MAXN];
int sl[MAXN];
int sr[MAXN];
int x[MAXN];
int d[MAXN];
int t[MAXN];

int root[MAXN];
int tree[MAXM][2];
int pass[MAXM];
int cntt;

int headp[MAXN<<2];
int nxtp[MAXM];
int top[MAXM];
int cntp=1;

int headb[MAXN<<2];
int nxtb[MAXM];
int tob[MAXM];
int cntb=1;

struct Product {
    int s, v;
};
bool cmp(Product a, Product b) {
    return a.s < b.s;
}

Product product[MAXN];
int ans[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

int insert(int val,int i){
    int rt=++cntt;
    tree[rt][0]=tree[i][0];
    tree[rt][1]=tree[i][1];
    pass[rt]=pass[i]+1;
    for(int b=BIT,pre=rt,cur;b>=0;b--,pre=cur){
        int path=(val>>b)&1;
        i=tree[i][path];
        cur=++cntt;
        tree[cur][0]=tree[i][0];
        tree[cur][1]=tree[i][1];
        pass[cur]=pass[i]+1;
        tree[pre][path]=cur;
    }
    return rt;
}

int query(int val,int u,int v){
    int ans=0;
    for(int b=BIT;b>=0;b--){
        int path=(val>>b)&1;
        int best=path^1;
        if(pass[tree[v][best]]>pass[tree[u][best]]){
            ans+=(1<<b);
            u=tree[u][best];
            v=tree[v][best];
        }
        else{
            u=tree[u][path];
            v=tree[v][path];
        }
    }
    return ans;
}

void addp(int u,int v){
    nxtp[cntp]=headp[u];
    top[cntp]=v;
    headp[u]=cntp++;
}

void addproduct(int jobi,int pi,int l,int r,int i){
    addp(i,pi);
    if(l<r){
        int mid=(l+r)>>1;
        if(jobi<=mid){
            addproduct(jobi,pi,l,mid,i<<1);
        }
        else{
            addproduct(jobi,pi,mid+1,r,i<<1|1);
        }
    }
}

void addb(int u,int v){
    nxtb[cntb]=headb[u];
    tob[cntb]=v;
    headb[u]=cntb++;
}

void addbuy(int jobl,int jobr,int jobi,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        addb(i,jobi);
    }
    else{
        int mid=(l+r)>>1;
        if(jobl<=mid){
            addbuy(jobl,jobr,jobi,l,mid,i<<1);
        }
        if(jobr>mid){
            addbuy(jobl,jobr,jobi,mid+1,r,i<<1|1);
        }
    }
}

void prepare(){
    for(int i=1;i<=n;i++){
        root[i]=insert(val[i],root[i-1]);
    }
    for(int i=1;i<=m;i++){
        if(op[i]==0){
            addproduct(t[i],i,1,T,1);
        }
        else{
            ans[i]=query(x[i],root[sl[i]-1],root[sr[i]]);
            int st=max(t[i]-d[i]+1,1);
            if(st<=t[i]){
                addbuy(st,t[i],i,1,T,1);
            }
        }
    }
}

int lower(int size, int num) {
    int l = 1, r = size, ansv = size + 1;
    while (l <= r) {
        int mid = (l + r) >> 1;
        if (product[mid].s >= num) {
            ansv = mid;
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }
    return ansv;
}

int upper(int size, int num) {
    int l = 1, r = size, ansv = 0;
    while (l <= r) {
        int mid = (l + r) >> 1;
        if (product[mid].s <= num) {
            ansv = mid;
            l = mid + 1;
        } else {
            r = mid - 1;
        }
    }
    return ansv;
}

void dfs(int l,int r,int i){
    int pcnt=0;
    for(int ei=headp[i];ei;ei=nxtp[ei]){
        product[++pcnt]={s[top[ei]],v[top[ei]]};
    }
    sort(product+1,product+pcnt+1,cmp);
    cntt=0;
    for(int k=1;k<=pcnt;k++){
        root[k]=insert(product[k].v,root[k-1]);
    }
    for (int e = headb[i], id, pre, post; e > 0; e = nxtb[e]) {
        id = tob[e];
        pre = lower(pcnt, sl[id]) - 1;
        post = upper(pcnt, sr[id]);
        ans[id] = max(ans[id], query(x[id], root[pre], root[post]));
    }
    if (l < r) {
        int mid = (l + r) >> 1;
        dfs(l, mid, i << 1);
        dfs(mid + 1, r, i << 1 | 1);
    }
}

int main()
{
    n=read(),m=read();
    T=0;
    for(int i=1;i<=n;i++){
        val[i]=read();
    }
    for(int i=1;i<=m;i++){
        op[i]=read();
        if(op[i]==0){
            T++;
            s[i]=read(),v[i]=read();
        }
        else{
            sl[i]=read(),sr[i]=read(),x[i]=read(),d[i]=read();
        }
        t[i]=T;
    }
    prepare();
    dfs(1,T,1);
    for(int i=1;i<=m;i++){
        if(op[i]==1){
            printf("%d\n",ans[i]);
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;

int n, m, a[MAXN];
long long f[MAXN], g[MAXN];  // f[i]: 到i位置的最大评分和; g[i]: 后缀最大值
int x[MAXN];          // x[i]: 当前块从块首到i的最大值
int pos[MAXN], L[MAXN], R[MAXN], numb;  // 分块信息

int main() {
    scanf("%d%d", &n, &m);
    for(int i = 1; i <= n; i++) scanf("%d", &a[i]);

    // 分块处理
    numb = n / m;  // 基本块数
    for(int i = 1; i <= numb; i++) {
        L[i] = R[i-1] + 1;
        R[i] = i * m;
    }
    // 处理剩余部分
    if(R[numb] <= n) {
        numb++;
        L[numb] = R[numb-1] + 1;
        R[numb] = n;
    }

    // 预处理每块的前缀最大值
    for(int i = 1; i <= numb; i++) {
        for(int j = L[i]; j <= R[i]; j++) {
            if(j == L[i]) x[j] = a[j];
            else x[j] = max(x[j-1], a[j]);
        }	
    }

    // 初始化第一块
    for(int i = L[1]; i <= R[1]; i++) f[i] = x[i];
    for(int i = R[1]; i >= L[1]; i--) 
        g[i] = max(g[i+1], f[i]);

    // 处理后续块
    for(int k = 2; k <= numb; k++) {
        long long mx = 0;
        int j = R[k-1], mx2 = 0;

        // 预处理：从上一块右端点向左扫描
        while(j > R[k] - m) {
            mx = max(mx, f[j] + mx2);
            mx2 = max(mx2, a[j]);
            j--;
        }

        // 处理当前块（从右向左）
        for(int i = R[k]; i >= L[k]; i--) {
            mx = max(mx, f[j] + mx2);
            f[i] = max(mx, g[j] + x[i]);
            mx2 = max(mx2, a[j]);
            g[i] = max(g[i+1], f[i]);
            j--;
        }
    }

    cout << f[n] << endl;
    return 0;
}

