inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedgeg(int u,int v){
    nxtg[cntg]=headg[u];
    tog[cntg]=v;
    headg[u]=cntg++;
}

void dfs(int u,int fa){
    dep[u]=dep[fa]+1;
    dfn[u]=++dfncnt;
    st[u][0]=fa;
    for(int i=1;i<=p;i++){
        st[u][i]=st[st[u][i-1]][i-1];
    }
    for(int i=headg[u];i;i=nxtg[i]){
        int v=tog[i];
        if(v!=fa){
            dfs(v,u);
        }
    }
}

bool cmp(int a,int b){
    return dfn[a]<dfn[b];
}

int lca(int a,int b){
    if(dep[a]<dep[b]){
        swap(a,b);
    }
    for(int i=p;i>=0;i--){
        if(dep[st[a][i]]>=dep[b]){
            a=st[a][i];
        }
    }
    if(a==b){
        return a;
    }
    for(int i=p;i>=0;i--){
        if(st[a][i]!=st[b][i]){
            a=st[a][i];
            b=st[b][i];
        }
    }
    return st[a][0];
}

inline void addedgev(int u,int v){
    nxtv[cntv]=headv[u];
    tov[cntv]=v;
    headv[u]=cntv++;
}

int buildvirtualtree1(){
    sort(arr+1,arr+k+1,cmp);
    int len=0;
    for(int i=1;i<k;i++){
        tmp[++len]=arr[i];
        tmp[++len]=lca(arr[i],arr[i+1]);
    }
    tmp[++len]=arr[k];
    sort(tmp+1,tmp+len+1,cmp);

    int m=1;
    for(int i=2;i<=len;i++){
        if(tmp[i]!=tmp[i-1]){
            tmp[++m]=tmp[i];
        }
    }

    cntv=1;
    for(int i=1;i<=m;i++){
        headv[tmp[i]]=0;
    }
    for(int i=1;i<m;i++){
        addedgev(lca(tmp[i],tmp[i+1]),tmp[i+1]);
    }
    return tmp[1];
}

int buildvirtualtree2(){
    sort(arr+1,arr+k+1,cmp);
    cntv=1;

    int top=0;
    sta[++top]=arr[1];
    headv[arr[1]]=0;
    for(int i=2;i<=k;i++){
        int x=arr[i];
        int y=sta[top];
        int fa=lca(x,y);
        while(top>1&&dfn[sta[top-1]]>=dfn[fa]){
            addedgev(sta[top-1],sta[top]);
            top--;
        }
        if(fa!=sta[top]){
            headv[fa]=0;
            addedgev(fa,sta[top]);
            sta[top]=fa;
        }
        headv[x]=0;
        sta[++top]=x;
    }
    while(top>1){
        addedgev(sta[top-1],sta[top]);
        top--;
    }
    return sta[1];
}

void dp(int u){
    cost[u]=sz[u]=0;
    for(int i=headv[u];i;i=nxtv[i]){
        int v=tov[i];
        dp(v);
        cost[u]+=cost[v];
        sz[u]+=sz[v];
    }
    if(iskey[u]){
        cost[u]+=sz[u];
        sz[u]=1;
    }
    else if(sz[u]>1){
        cost[u]+=1;
        sz[u]=0;
    }
}

int compute(){
    for(int i=1;i<=k;i++){
        iskey[arr[i]]=true;
    }
    bool flag=true;
    for(int i=1;i<=k;i++){
        if(iskey[st[arr[i]][0]]){
            flag=false;
            break;
        }
    }
    int ans=-1;
    if(flag){
        // int tree=buildvirtualtree1();
        int tree=buildvirtualtree2();
        dp(tree);
        ans=cost[tree];
    }
    for(int i=1;i<=k;i++){
        iskey[arr[i]]=false;
    }
    return ans;
}

