int Next[MAXN<<1];
int to[MAXN<<1];
int weight[MAXN<<1];

void addedge(int u,int v,int w){
    Next[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    head[u]=cnt++;
}

void dfs(int u,int f,int w){
    for(int i=head[u];i;i=Next[i]){
        int v=to[i];
        if(v!=f){
            dfs(v,u,weight[i]);
            dis[u]=max(dis[u],dis[v]+weight[i]);
        }
    }
    if(dis[u]+w>=val){
        //父亲即使安装了  这个点可以满足   但是下面的点无法满足
        //所以这个点也要安装
        ans++;
        dis[u]=0;
    }
}

