#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;

int n,m,k,q;

struct node{
    int u,v,w;
    bool operator<(node other)const {
        return w<other.w;
    }
};
node nums[MAXN];

// 并查集
int fa[MAXN];

// 这个块的开头和结尾
int head[MAXN];
int tail[MAXN];

// 这个节点的前驱与后继  以及和后继节点之间的权值
int pre[MAXN];
int suf[MAXN];
int val[MAXN];

// 节点颜色
int col[MAXN];

multiset<int>ans;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

int find(int x){
    return x==fa[x]?x:fa[x]=find(fa[x]);
}

int main()
{
    n=read(),m=read(),k=read(),q=read();

    for(int i=1;i<=m;i++){
        nums[i].u=read(),nums[i].v=read(),nums[i].w=read();
    }
    sort(nums+1,nums+m+1);

    // 初始化  一个节点作为一个块
    for(int i=1;i<=n;i++){
        fa[i]=i;
        head[i]=i,tail[i]=i;
        pre[i]=0,suf[i]=0;
        val[i]=0;
    }

    // 这个过程可以认为是构建最小生成树  但是认为是kruskal重构树更合适
    // 因为这里的逻辑实际上是按照重构树来的
    for(int i=1;i<=m;i++){
        int u=nums[i].u,v=nums[i].v,w=nums[i].w;
        int fx=find(u),fy=find(v);
        if(fx!=fy){
            int fxtail=tail[fx];
            int fyhead=head[fy];
            suf[fxtail]=fyhead;
            pre[fyhead]=fxtail;
            val[fxtail]=w;
            fa[fy]=fx;
            tail[fx]=tail[fy];
        }
    }

    for(int i=1;i<=n;i++){
        col[i]=read();
    }

    for(int i=1;i<=n;i++){
        if(suf[i]){
            if(col[i]!=col[suf[i]]){
                ans.insert(val[i]);
            }
        }
    }

    while(q--){
        int a,b;
        a=read(),b=read();
        int old=col[a];
        col[a]=b;

        if(pre[a]){
            int p=pre[a];
            if(col[p]!=old){
                auto it=ans.find(val[p]);
                ans.erase(it);
            }
            if(col[p]!=b){
                ans.insert(val[p]);
            }
        }
        if(suf[a]){
            int s=suf[a];
            if(col[s]!=old){
                auto it=ans.find(val[a]);
                ans.erase(it);
            }
            if(col[s]!=b){
                ans.insert(val[a]);
            }
        }

        cout<<*ans.begin()<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 305;
const int MAXM = 2e5;
const int INF = 1e18;

int n,m,s,t;

int dep[MAXN];
int iter[MAXN];

int head[MAXN];
int nxt[MAXM];
int to[MAXM];
int now[MAXM];
int cap[MAXM];
int cnt=2;

void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    cap[cnt]=w;
    head[u]=cnt++;

    nxt[cnt]=head[v];
    to[cnt]=u;
    cap[cnt]=0;
    head[v]=cnt++;
}

//BFS构建分层图，并判断是否存在增广路径
bool bfs(){
    for(int i=1;i<=n;i++){
        dep[i]=-1;
    }
    queue<int>q;
    dep[s]=0;
    q.push(s);
    while(!q.empty()){
        int u=q.front();
        q.pop();
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            int w=cap[i];
            int k=now[i];
            if(dep[v]<0&&(k<w)){
                dep[v]=dep[u]+1;
                q.push(v);
            }
        }
    }
    return dep[t]>=0;// 如果汇点未被访问到，说明无增广路径
}

// DFS寻找增广路径（多路增广）
//多路增广的含义是来到了一个节点 不仅仅是只去一条边增广  而是去多条边一起增广
int dfs(int u,int f){
    //表示当前来到了u节点 有f的流量可供使用  f就是目前这条路最多可以消耗掉的流量
    if(u==t){
        return f;
    }
    int flow=0;
    for(int &i=iter[u];i;i=nxt[i]){
        //注意这里是引用  iter会随着i发生变化
        int v=to[i];
        int w=cap[i];
        int k=now[i];
        if(dep[u]+1==dep[v]&&k<w){
            int d=dfs(v,min(f,w-k));
            if(d>0){
                now[i]+=d;
                now[i^1]-=d;//更新反向边
                flow+=d;
                f-=d;
                if(f==0){
                    break;
                }
            }
        }
    }
    return flow;
}

// Dinic算法主函数
int maxflow(){
    int flow=0;
    while(bfs()){
        //当前弧全部初始化为最初值
        for(int i=1;i<=n;i++){
            iter[i]=head[i];
        }
        int maxflow;
        while((maxflow=dfs(s,INF))>0){
            flow+=maxflow;
        }
    }
    return flow;
}

