double check(int pos,int len){
    double ans=1.0*(sum[n]-sum[n-len]+sum[pos]-sum[pos-len-1])/(2*len+1);
    return ans-nums[pos];
}

void compute(int pos,int len){
    int l=0,r=len;
    while(r-l>4){
        int midl=(r-l)/3+l;
        int midr=r-(r-l)/3;
        double k1=check(pos,midl);
        double k2=check(pos,midr);
        if(k1<k2){
            l=midl;
        }
        else{
            r=midr;
        }
    }
    for(int k=l;k<=r;k++){
        double res=check(pos,k);
        if(res>ans){
            ans=res;
            p=pos;
            le=k;
        }
    }
}

