int cnt;
long long key[MAXN];
string name[MAXN];
int ls[MAXN];
int rs[MAXN];
int sz[MAXN];
double pritority[MAXN];
map<string,long long>vis;

string str;
long long val;

void up(int i){
    sz[i]=sz[ls[i]]+sz[rs[i]]+1;
}

void inorder(int u){
    if(u!=0){
        inorder(ls[u]);
        cout<<name[u]<<' ';
        inorder(rs[u]);
    }
}

void split(int l,int r,int i,int rk){
    if(i==0){
        rs[l]=ls[r]=0;
    }
    else{
        if (sz[ls[i]] + 1 <= rk) {
            rs[l] = i;
            split(i, r, rs[i], rk - sz[ls[i]] - 1);
        } else {
            ls[r] = i;
            split(l, i, ls[i], rk);
        }
        up(i);
    }
}

int merge(int l,int r){
    if (l == 0 || r == 0) {
        // 遇到了空树  直接结束
        return l + r;
    }
    if (pritority[l] >= pritority[r]) {
        rs[l] = merge(rs[l], r);
        up(l);
        return l;
    } else {
        ls[r] = merge(l, ls[r]);
        up(r);
        return r;
    }
}

void remove(int rk){
    split(0,0,head,rk);
    int lm=rs[0];
    int r=ls[0];
    split(0,0,lm,rk-1);
    int l=rs[0];
    head=merge(l,r);
}

void add(int rk){
    split(0,0,head,rk-1);
    ++cnt;
    key[cnt]=val;
    name[cnt]=str;
    sz[cnt]=1;
    pritority[cnt]=(double)rand()/RAND_MAX;
    head=merge(merge(rs[0],cnt),ls[0]);
}

// 返回大于val的个数+1
int getrank(long long val){
    int u=head;
    int ans=0;
    while(key[u]!=val&&u!=0){
        if(key[u]>val){
            ans+=sz[ls[u]]+1;
            u=rs[u];
        }
        else{
            u=ls[u];
        }
    }
    if(u!=0){
        ans+=sz[ls[u]];
    }
    return ans+1;
}

