        }
    }
    return ans;
}

void dfs(int u, int fa) {
    dep[u] = dep[fa] + 1;
    seg[++cntd] = u;
    st[u] = cntd;
    stjump[u][0] = fa;
    sz[u]=1;
    for (int p = 1; p < MAXH; p++) {
        stjump[u][p] = stjump[stjump[u][p - 1]][p - 1];
    }
    for (int e = head[u], v; e > 0; e = nxt[e]) {
        v = to[e];
        if (v != fa) {
            dfs(v, u);
            sz[u]+=sz[v];
            if(son[u]==0||sz[son[u]]<sz[v]){
                son[u]=v;
            }
        }
    }
    seg[++cntd] = u;
    ed[u] = cntd;
}

void dfs2(int u,int t){
    top[u]=t;
    dfn[u]=++dfncnt;
    dfnseg[dfncnt]=u;
    if(son[u]){
        fromtop[son[u]]=fromtop[u]|smallprime[son[u]];
        dfs2(son[u],t);
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=stjump[u][0]&&v!=son[u]){
            fromtop[v]=smallprime[v];
            dfs2(v,v);
        }
    }
}

bool cmp(Query &a, Query &b) {
    if (bi[a.l] != bi[b.l]) {
        return bi[a.l] < bi[b.l];
    }
    if ((bi[a.l] & 1) == 1) {
        return a.r < b.r;
    } else {
        return a.r > b.r;
    }
}

int lca(int a, int b) {
    if (dep[a] < dep[b]) {
        swap(a, b);
    }
    for (int p = MAXH - 1; p >= 0; p--) {
        if (dep[stjump[a][p]] >= dep[b]) {
            a = stjump[a][p];
        }
    }
    if (a == b) {
        return a;
    }
    for (int p = MAXH - 1; p >= 0; p--) {
        if (stjump[a][p] != stjump[b][p]) {
            a = stjump[a][p];
            b = stjump[b][p];
        }
    }
    return stjump[a][0];
}

void build(int l,int r,int i){
    if(l==r){
        tree[i]=smallprime[dfnseg[l]];
    }
    else{
        int mid=(l+r)>>1;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        tree[i]=(tree[i<<1]|tree[i<<1|1]);
    }
}

bitset<MAXP>querytree(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        return tree[i];
    }
    else{
        int mid=(l+r)>>1;
        if(jobl<=mid&&jobr>mid){
            return (querytree(jobl,jobr,l,mid,i<<1)|querytree(jobl,jobr,mid+1,r,i<<1|1));
        }
        else if(jobl<=mid){
            return querytree(jobl,jobr,l,mid,i<<1);
        }
        else{
            return querytree(jobl,jobr,mid+1,r,i<<1|1);
        }
    }
}

bitset<MAXP>querypath(int x,int y){
    bitset<MAXP>ans;
    while (top[x] != top[y]) {
        if (dep[top[x]] <= dep[top[y]]) {
            ans|=fromtop[y];
            y = stjump[top[y]][0];
        } else {
            ans|=fromtop[x];
            x = stjump[top[x]][0];
        }
    }
    ans|=querytree(min(dfn[x], dfn[y]), max(dfn[x], dfn[y]), 1, n, 1);
    return ans;
}

int findfac(int val){
    int l=1,r=cntp,ans=0;
    while(l<=r){
        int mid=(l+r)>>1;
        if(primes[mid]>=val){
            ans=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    return ans;
}

void prepare(){
    for(int i=1;i<=n;i++){
        if(val[i]<=LIMIT){
            compute1(val[i],i);
        }
        else{
            int fac=max_prime(val[i]);
            if(fac>LIMIT){
                bigprime[i]=fac;
                val[i]/=fac;
            }
            else{
                int p=findfac(fac);
                smallprime[i].set(p-1);
                while(val[i]%fac==0){
                    val[i]/=fac;
                }
            }
            if(val[i]<LIMIT){
                compute1(val[i],i);
            }
            else{
                compute2(val[i],i);
            }
        }
    }
    for(int i=1;i<=n;i++){
        sorted[i]=bigprime[i];
    }
    sorted[n+1]=0;
    sort(sorted+1,sorted+n+2);
    m=1;
    for(int i=2;i<=n+1;i++){
        if(sorted[i]!=sorted[i-1]){
            sorted[++m]=sorted[i];
        }
    }
    for(int i=1;i<=n;i++){
        bigprime[i]=find(bigprime[i]);
    }
    dfs(1,0);
    fromtop[1]=smallprime[1];
    dfs2(1,1);
    build(1,n,1);
    blen=sqrt(cntd);
    // blen=max(1,(int)pow(cntd,3.0/2));
    for(int i=1;i<=cntd;i++){
        bi[i]=(i-1)/blen+1;
    }
}

void invert(int node) {
    int val = bigprime[node];
    if(val==1){
        return ;
    }
    if (vis[node]) {
        if (--cnt[val] == 0) {
            kind--;
        }
    } else {
        if (++cnt[val] == 1) {
            kind++;
        }
    }
    vis[node] = !vis[node];
}

void compute() {
    int winl = 1, winr = 0;
    for (int i = 1; i <= q; i++) {
        int jobl = query[i].l;
        int jobr = query[i].r;
        int lca = query[i].lca;
        int id = query[i].id;
        while (winl > jobl) {
            invert(seg[--winl]);
        }
        while (winr < jobr) {
            invert(seg[++winr]);
        }
        while (winl < jobl) {
            invert(seg[winl++]);
        }
        while (winr > jobr) {
            invert(seg[winr--]);
        }
        if (lca > 0) {
            invert(lca);
        }
        ans[id] = kind;
        if (lca > 0) {
            invert(lca);
        }
        ans[id]+=querypath(query[i].u,query[i].v).count();
    }
}

