{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m;
    for(int i=1;i<=m;i++){
        int k,x,y;
        cin>>k>>x;
        for(int j=2;j<=k;j++){
            cin>>y;
            addedge(x,y);
            addedge(y,x);
            x=y;
        }
    }

    tarjan(1,0);

    cout<<diameter<<endl;
    return 0;
}

