}

void compute() {
    len = 1;
    for (int i = BIT; i >= 0; i--) {
        for (int j = len; j <= n; j++) {
            if (arr[j] & (1LL << i)) {
                swap(arr[j], arr[len]);
                break;
            }
        }
        if (arr[len] & (1LL << i)) {
            //表示找到了这一位上是1的数字
            for (int j = 1; j <= n; j++) {
                //将所有这一位置上是1的数字全部异或掉
                if (j != len && (arr[j] & (1LL << i))) {
                    arr[j] ^= arr[len];
                }
            }
            len++;
        }
    }
    len--;//表示有len位可以确定
    zero = len != n;
}

