#include<bits/stdc++.h>
using namespace std;
const int MAXN = (1<<21)+1e4;

int n;
int it;

int head;
int cnt;
int ls[MAXN];
int rs[MAXN];
int sz[MAXN];
char key[MAXN];
bool rev[MAXN];
double priority[MAXN];

int newnode(char c){
    ++cnt;
    key[cnt]=c;
    sz[cnt]=1;
    priority[cnt]=(double)rand()/RAND_MAX;
    return cnt;
}

void up(int i) {
    sz[i] = sz[ls[i]] + sz[rs[i]] + 1;
}

void down(int i) {
    if (rev[i]) {
        swap(ls[i], rs[i]);
        rev[ls[i]] ^= 1;
        rev[rs[i]] ^= 1;
        rev[i] = false;
    }
}

void split(int l, int r, int i, int rank) {
    if (i == 0) {
        rs[l] = ls[r] = 0;
    } else {
        down(i);
        if (sz[ls[i]] + 1 <= rank) {
            rs[l] = i;
            split(i, r, rs[i], rank - sz[ls[i]] - 1);
        } else {
            ls[r] = i;
            split(l, i, ls[i], rank);
        }
        up(i);
    }
}

int merge(int l, int r) {
    if (l == 0 || r == 0) {
        return l + r;
    }
    if (priority[l] >= priority[r]) {
        down(l);//下发懒信息
        rs[l] = merge(rs[l], r);
        up(l);
        return l;
    } else {
        down(r);
        ls[r] = merge(l, ls[r]);
        up(r);
        return r;
    }
}

char getrank(int rk){
    int u=head;
    while(u){
        down(u);
        if(sz[ls[u]]+1==rk){
            return key[u];
        }
        else if(sz[ls[u]]+1<rk){
            rk-=sz[ls[u]]+1;
            u=rs[u];
        }
        else{
            u=ls[u];
        }
    }
    return '\0'; // Return null character if not found
}

