    int val,cost;
}nums[MAXN];
int m=1;//用于去重和离散化
int help[MAXN];

int cnt=1;
int root[MAXN];
int ls[MAXT];
int rs[MAXT];
long long sum[MAXT];
int sz[MAXT];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

int find(int val){
    int l=1,r=m,ans=m;
    while(l<=r){
        int mid=(l+r)/2;
        if(help[mid]>=val){
            ans=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    return ans;
}

bool cmp(node a,node b){
    return a.val<b.val;
}

int build(int l, int r) {
    int rt = ++cnt;
    if (l == r) {
        return rt;
    } else {
        int mid = (l + r) >> 1;
        ls[rt] = build(l, mid);
        rs[rt] = build(mid + 1, r);
        return rt;
    }
}

int add(int pos,int jobv,int l,int r,int i){
    int rt=++cnt;
    ls[rt]=ls[i];
    rs[rt]=rs[i];
    sum[rt]=sum[i]+jobv;
    sz[rt]=sz[i]+1;
    if(l==r){
        return rt;
    }
    else{
        int mid=(l+r)/2;
        if(pos<=mid){
            ls[rt]=add(pos,jobv,l,mid,ls[rt]);
        }
        else{
            rs[rt]=add(pos,jobv,mid+1,r,rs[rt]);
        }
        return rt;
    }
}

long long query(int goal,int l,int r,int u,int v){
    //v版本减去u版本
    if(l==r){
        return (sum[v]-sum[u])/(sz[v]-sz[u])*goal;
    }
    int mid=(l+r)/2;
    if(sz[ls[v]]-sz[ls[u]]>=goal){
        return query(goal,l,mid,ls[u],ls[v]);
    }
    else{
        long long ans=sum[ls[v]]-sum[ls[u]];
        ans+=query(goal-sz[ls[v]]+sz[ls[u]],mid+1,r,rs[u],rs[v]);
        return ans;
    }
}

