        for(int j=1;j<=n;j++){
            dp[i][j]=INF;
        }
    }
    for(int i=1;i<=k;i++){
        dp[1<<(i-1)][key[i-1]]=0;
    }
    for(int s=1;s<=status;s++){
        for(int sub=(s-1)&s;sub;sub=(sub-1)&s){
            int other=s-sub;
            for(int u=1;u<=n;u++){
                if(dp[sub][u]<INF&&dp[other][u]<INF){
                    dp[s][u]=min(dp[s][u],dp[sub][u]+dp[other][u]);
