            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

bool cmp(node a,node b){
    if((a.w+a.op*mid)!=(b.w+b.op*mid)){
        return (a.w+a.op*mid)<(b.w+b.op*mid);
    }
    return a.op>b.op;
}

int find(int x){
    return x==fa[x]?x:fa[x]=find(fa[x]);
}

bool check(){
    int cnt=0;
    sort(nums+1,nums+2*m+1,cmp);
    for(int i=1;i<=n;i++){
        fa[i]=i;
    }
    int now=0;
    int tmp=INT_MIN;
    for(int i=1;i<=2*m;i++){
        int x=nums[i].u;
        int y=nums[i].v;
        int fx=find(x),fy=find(y);
        if(cnt>=k&&nums[i].op==1){
            continue;
        }
        if(fx!=fy){
            fa[fx]=fy;
            tmp=max(tmp,nums[i].w);
            if(nums[i].op==1){
                cnt++;
            }
            now++;
            if(now==n-1){
                break;
            }
        }
    }
    if(cnt>=k){
        res=min(res,tmp);
    }
    return cnt>=k;
}

