    for(int i=1;i<=n;i++){
        int v=read();
        while(v){
            vec[v].push_back(i);
            food[i].push_back(v);
            in[i]++;
            v=read();
        }
    }
    for(int i=1;i<=n;i++){
        if(in[i]==0){
            q.push(i);
        }
    }
    while(!q.empty()){
        int u=q.front();
        q.pop();
        topo.push_back(u);
        for(int i=0;i<(int)vec[u].size();i++){
            int v=vec[u][i];
            in[v]--;
            if(in[v]==0){
                q.push(v);
            }
        }
    }
    for(int i=0;i<n;i++){
        int v=topo[i];
        int u;
        if(food[v].empty()){
            u=0;
        }
        else{
            u=food[v][0];
            for(int j=1;j<(int)food[v].size();j++){
                u=lca(u,food[v][j]);
            }
        }
        dep[v]=dep[u]+1;
        st[v][0]=u;
        for(int j=1;j<MAXH;j++){
            st[v][j]=st[st[v][j-1]][j-1];
        }
        addedge(u,v);
    }
    dfs(0);
    for(int i=1;i<=n;i++){
        cout<<(sz[i]-1)<<endl;
    }
    return 0;
}

