    if(vl==vr){
        for(int i=ql;i<=qr;i++){
            int id=qid[i];
            ans[id]=vl;
        }
    }
    else{
        int mid=(vl+vr)/2;
        while(used<mid){
            used++;
            add(pos[used],1);
        }
        while(used>mid){
            add(pos[used],-1);
            used--;
        }
        int lsz=0,rsz=0;
        for(int i=ql;i<=qr;i++){
            int id=qid[i];
            int all=sum(l[id],min(r[id],maxp));
            if(all>=k[id]){
                lset[++lsz]=id;
            }
            else{
                rset[++rsz]=id;
            }
        }
        for(int i=ql;i<=ql+lsz-1;i++){
            qid[i]=lset[i-ql+1];
        }
        for(int i=ql+lsz;i<=qr;i++){
            qid[i]=rset[i-ql-lsz+1];
        }
        compute(ql,ql+lsz-1,vl,mid);
        compute(ql+lsz,qr,mid+1,vr);
    }
}

