int len;
int vis[MAXN];

void insert(string word){
    int cur=1;
    for (char ch : word){
        path=ch-'a';
        if(tree[cur][path]==0){
            tree[cur][path]=++cnt;
            //没有路就要新建一条路  并赋予编号
        }
        cur=tree[cur][path];
    }
    en[cur]++;
    //cout<<cur<<endl;
}

int search(string word){
    int cur=1;
    for (char ch : word){
        path=ch-'a';
        if(tree[cur][path]==0){
            return 0;
            //没有路说明走不通
        }
        cur=tree[cur][path];
    }
    return en[cur];
}

void dfs(int cur,int u,bool f,int now){
    if(u==len+1){
        if(f){
            if(vis[cur]!=now){
                ans+=en[cur];
                vis[cur]=now;
            }
        }
        else{
            for(int i=0;i<26;i++){
                if(vis[tree[cur][i]]!=now){
                    ans+=en[tree[cur][i]];
                    vis[tree[cur][i]]=now;
                }
            }
        }
    }
    path=s[u-1]-'a';
    if(tree[cur][path]!=0){
        dfs(tree[cur][path],u+1,f,now);
    }
    if(tree[cur][path]==0){
        if(u==len&&!f){
            if(vis[cur]!=now){
                ans+=en[cur];
                vis[cur]=now;
            }
        }
    }
    if(!f){
        //以前没有用过
        for(int i=0;i<26;i++){
            dfs(tree[cur][i],u,1,now);//删除字母
            dfs(tree[cur][i],u+1,1,now);//变换字母
        }
        dfs(cur,u+1,1,now);//添加字母
    }
}

