{
    n=read(),m=read();
    for(int i=1;i<=n;i++){
        val[i]=read();
    }
    build(1,n,1);
    for(int i=1;i<=m;i++){
        int op,l,r,x;
        op=read(),l=read(),r=read();
        for(int j=0;j<(int)vec[i].size();j++){
            int lt=vec[i][j].first;
            int rt=vec[i][j].second;
            deblock(lt,rt,1,n,1);
        }
        if(op==1){
            x=read();
            add(l,r,x,1,n,1);
        }
        else if(op==2){
            x=read();
            mul(l,r,x,1,n,1);
        }
        else if(op==3){
            x=read();
            block(l,r,1,n,1);
            if(i+x+1<=m){
                vec[i+x+1].push_back({l,r});
            }
        }
        else{
            printf("%lld\n",query(l,r,1,n,1));
        }

    }
    return 0;
}

