    arr[m]={x,y,v,0};
}

void addquery(int x,int y,int d,int q){
    ++m;
    arr[m]={x,y,d,q};
}

int lowbit(int x){
    return x&-x;
}

int query(int x){
    int ans=0;
    while(x){
        ans+=tree[x];
        x-=lowbit(x);
    }
    return ans;
}

void add(int x,int v){
    while(x<=n){
        tree[x]+=v;
        x+=lowbit(x);
    }
}

bool cmp(node a,node b){
    return a.x<b.x;
}

void merge(int l,int mid,int r){
    int p1,p2;
    for(p1=l-1,p2=mid+1;p2<=r;p2++){
        while(p1+1<=mid&&arr[p1+1].x<=arr[p2].x){
            p1++;
            if(arr[p1].q==0){
                add(arr[p1].y,arr[p1].d);
            }
        }
        if(arr[p2].q){
            ans[arr[p2].q]+=arr[p2].d*query(arr[p2].y);
        }
    }

    for(int i=l;i<=p1;i++){
        if(arr[i].q==0){
            add(arr[i].y,-arr[i].d);
        }
    }

    sort(arr+l,arr+r+1,cmp);
}

void cdq(int l,int r){
    if(l==r){
        return ;
    }
    int mid=(l+r)>>1;
    cdq(l,mid);
    cdq(mid+1,r);
    merge(l,mid,r);
}

