// 查询数值v的排名(离散值)
int getrank(int n, int v) {
    int ans = 0;
    int l = 1, r = n, mid;
    while (l <= r) {
        mid = (l + r) >> 1;
        if (xsort[mid] >= v) {
            ans = mid;
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }
    return ans;
}

// 准备工作如下
// 1) 收集大楼左边界、右边界-1、右边界的值
// 2) 收集的所有值排序、去重
// 3) 大楼的左边界和右边界，修改成排名值
// 4) 大楼根据左边界排序
// 5) 清空height数组
// 6) 返回离散值的个数
int prepare(){
    int cnt=0;
    for(int i=1;i<=n;i++){
        xsort[++cnt]=nums[i].l;
        xsort[++cnt]=nums[i].r-1;
        xsort[++cnt]=nums[i].r;
    }
    sort(xsort+1,xsort+cnt+1);
    int m = 1;
    for (int i = 1; i <= cnt; i++) {
        if (xsort[m] != xsort[i]) {
            xsort[++m] = xsort[i];
        }
    }
    //cout<<m<<endl;
    // 修改大楼影响到的左右边界，都变成排名值
    for (int i = 1; i <= n; i++) {
        nums[i].l = getrank(m, nums[i].l);
        // 大楼影响到的右边界，减少1！
        // 课上重点说明的内容
        nums[i].r = getrank(m, nums[i].r - 1);
    }
    // 所有大楼根据左边界排序
    sort(nums+1,nums+n+1,cmp);
    // 返回有多少个不同的离散值
//    for(int i=1;i<=n;i++){
//        cout<<nums[i].l<<' '<<nums[i].r<<' '<<nums[i].h<<endl;
