void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    cap[cnt]=w;
    now[cnt]=0;
    head[u]=cnt++;

    nxt[cnt]=head[v];
    to[cnt]=u;
    cap[cnt]=0;
    now[cnt]=0;
    head[v]=cnt++;
}

bool bfs(){
    for(int i=1;i<=n*m+2;i++){
        dep[i]=-1;
    }
    queue<int>q;
    dep[s]=0;
    q.push(s);
    while(!q.empty()){
        int u=q.front();
        q.pop();
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            int w=cap[i];
            int k=now[i];
            if(dep[v]<0&&(k<w)){
                dep[v]=dep[u]+1;
                q.push(v);
            }
        }
    }
    return dep[t]>=0;// 如果汇点未被访问到，说明无增广路径
}

int dfs(int u,int f){
    if(u==t){
        return f;
    }
    int flow=0;
    for(int &i=iter[u];i;i=nxt[i]){
        int v=to[i];
        int w=cap[i];
        int k=now[i];
        if(dep[u]+1==dep[v]&&k<w){
            int d=dfs(v,min(f,w-k));
            if(d>0){
                now[i]+=d;
                now[i^1]-=d;//更新反向边
                flow+=d;
                f-=d;
                if(f==0){
                    break;
                }
            }
        }
    }
    return flow;
}

int maxflow(){
    int flow=0;
    while(bfs()){
        for(int i=1;i<=n*m+2;i++){
            iter[i]=head[i];
        }
        int maxflow;
        while((maxflow=dfs(s,INF))>0){
            flow+=maxflow;
        }
    }
    return flow;
}

bool check(int x){
    s=n*m+1,t=n*m+2;
    for(int i=1;i<=t;i++){
        head[i]=0;
    }
    cnt=2;
    int need=(n%2==0||m%2==0)?(n*m/2*x-black):((n*m+1)/2*x-black);
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            int id=(i-1)*m+j;
            if((i+j)%2==0){
                addedge(s,id,x-val[i][j]);
                for(int k=0;k<4;k++){
                    int nx=i+walk[k][0];
                    int ny=j+walk[k][1];
                    if(nx>=1&&nx<=n&&ny>=1&&ny<=m){
                        int nid=(nx-1)*m+ny;
                        addedge(id,nid,INF);
                    }
                }
            }
            else{
                addedge(id,t,x-val[i][j]);
            }
        }
    }
    int flow=maxflow();
    return flow==need;
}

