    for(int i=1;i<=bnum;i++){
        bl[i]=(i-1)*blen+1;
        br[i]=min(n,i*blen);
    }
    sort(nums+1,nums+n+1,cmpm);
    for(int i=1;i<=bnum;i++){
        maxm[i]=nums[br[i]].m;
        sort(nums+bl[i],nums+br[i]+1,cmpd);
    }
}

