    prepare(m);
    int ans=0;
    int v=1;
    for(int i=0;i<=m;i++){
        ans=((ans+v*comb(m,i)*power(n-i,q))%MOD+MOD)%MOD;
        v*=-1;
    }
    ans=(ans*power(k,q-m))%MOD;
    ans=(ans*(n-m+1))%MOD;
    cout<<ans<<endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

typedef long long ll;

const int MAX_N = 1000000;

vector<ll> phi_sum(MAX_N + 1);

void precompute() {
    vector<int> phi(MAX_N + 1);
    for (int i = 1; i <= MAX_N; i++) {
        phi[i] = i;
    }
    for (int i = 2; i <= MAX_N; i++) {
        if (phi[i] == i) {
            for (int j = i; j <= MAX_N; j += i) {
                phi[j] = phi[j] / i * (i - 1);
            }
        }
    }
    phi_sum[0] = 0;
    for (int i = 1; i <= MAX_N; i++) {
        phi_sum[i] = phi_sum[i - 1] + phi[i];
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    precompute();
    int t;
    cin >> t;
    while (t--) {
        ll n, m;
        cin >> n >> m;
        ll M_max_real = 0;
        for (ll d = 2; d <= n; d++) {
            ll c = n / d;
            if (c < 2) {
                continue;
            }
            ll avail = phi_sum[c] - 1;
            ll volume = d - 1;
            ll max_ops_d = avail / volume;
            ll edges_d = max_ops_d * volume;
            M_max_real += edges_d;
        }
        if (m > M_max_real) {
            cout << -1 << '\n';
            continue;
        }
        ll cost = 0;
        ll rem = m;
        for (ll d = n; d >= 2; d--) {
            ll volume = d - 1;
            ll c = n / d;
            if (c < 2) {
                continue;
            }
            ll avail = phi_sum[c] - 1;
            ll max_ops_d = avail / volume;
            if (max_ops_d == 0) {
                continue;
            }
            ll ops = rem / volume;
            if (ops > max_ops_d) {
                ops = max_ops_d;
            }
            cost += ops * d;
            rem -= ops * volume;
            if (rem == 0) {
                break;
            }
        }
        cout << cost << '\n';
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e3+5;

int n;
int sg[MAXN];
bool appear[MAXN];

void build(){
    sg[1]=0;
    for (int i = 2; i <= 1000; i++) {
        int k=0;
        memset(appear, false, sizeof(appear)); // 重置 appear 数组
        for (int j = 1; j <= i/2; j++) {
            if(i%j==0){
                k^=sg[j];
            }
        }
        for (int j = 1; j <= i/2; j++) {
            if(i%j==0){
                appear[k^sg[j]]=1;
            }
        }
        for (int s = 0; s < MAXN; s++) {
            if (!appear[s]) {
                sg[i] = s; // 找到最小的未出现的 SG 值
                break;
            }
        }
        //cout<<i<<": "<<sg[i]<<endl;
    }
}

int main()
{
    build();
    while(cin>>n){
        int ans=0;
        for(int i=1;i<=n;i++){
            int u;
            cin>>u;
            ans^=sg[u];
        }
        if(ans){
            cout<<"freda"<<endl;
        }
        else{
            cout<<"rainbow"<<endl;
        }
    }
    return 0;
}

