    for(int i=1;i<=m;i++){
        int u,limit;
        u=read(),limit=read();
        if(limit==0){
            cout<<st<<' ';
            continue;
        }
        sum(u,limit);
        //cout<<st<<' '<<endl;
        cout<<st<<' ';
    }
    return 0;
}

