    for(int i=2;i<=cnt;i++){
        if(nums[i]!=nums[i-1]){
            nums[++m]=nums[i];
        }
    }

    inv[1]=1;
    for(int i=2;i<=n;i++){
        inv[i]=(MOD-inv[MOD%i]*(MOD/i)%MOD+MOD)%MOD;
    }

    for(int i=1;i<=n;i++){
        l[i]=find(l[i]);
        r[i]=find(r[i]);
    }

    g[0]=1;
    for(int j=1;j<m;j++){

        int len=nums[j+1]-nums[j];
        comb[0]=1;
        for(int i=1;i<=n;i++){
            comb[i]=((comb[i-1]*inv[i])%MOD)*(len+i-1)%MOD;
        }

        for(int i=n;i>=1;i--){
            if(j>=l[i]&&j<=r[i]){
                int f=0,m=1,c=comb[1];
                for(int p=i-1;p>=0;p--){
                    f=(f+c*g[p]%MOD)%MOD;
                    if(l[p]<=j&&r[p]>=j){
                        c=comb[++m];
                    }
                }
                g[i]=(g[i]+f)%MOD;
            }
        }
    }
    int ans=0;
    for(int i=1;i<=n;i++){
        ans=(ans+g[i])%MOD;
    }
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 1e5+5;
const int MAXM = 25005;
const int MAXK = 30;
const int MOD = 998244353;
const int BASE = 499;

int n,m,k;
int s[MAXN];
int t[MAXM];

int hasht;

int p[MAXM];
int all[MAXK];

int rk[MAXK];
int cnt[MAXK];

int anslen;
int ans[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void build(){
    p[0]=1;
    for(int i=1;i<=m;i++){
        p[i]=(p[i-1]*BASE)%MOD;
    }
}

inline void buildrank(){
    for(int i=1;i<=k;i++){
        rk[i]=0;
    }
    int rank=0;
    for(int i=1;i<=k;i++){
        if(cnt[i]){
            rk[i]=++rank;
        }
    }
}

inline int gethash(){
    int val=0;
    for(int i=1;i<=k;i++){
        val=(val+(all[i]*rk[i]%MOD))%MOD;
    }
    val=(val%MOD+MOD)%MOD;
    return val;
}

signed main()
{
    n=read(),m=read(),k=read();
    for(int i=1;i<=n;i++){
        s[i]=read();
    }
    for(int i=1;i<=m;i++){
        t[i]=read();
    }

    build();

    for(int i=1;i<=m;i++){
        cnt[t[i]]++;
    }
    buildrank();
    for(int i=1;i<=m;i++){
        hasht=(hasht+(p[m-i]*rk[t[i]]%MOD))%MOD;
    }

    for(int i=1;i<=k;i++){
        cnt[i]=0;
    }
    for(int i=1;i<=m;i++){
        cnt[s[i]]++;
        all[s[i]]=(all[s[i]]+p[m-i])%MOD;
    }
    buildrank();
    if(gethash()==hasht){
        ans[++anslen]=1;
    }

    for(int i=m+1;i<=n;i++){
        cnt[s[i-m]]--;
        cnt[s[i]]++;

        buildrank();
        for(int j=1;j<=k;j++){
            all[j]=(all[j]*BASE)%MOD;
        }
        all[s[i-m]]=(all[s[i-m]]-p[m])%MOD;
        all[s[i]]=(all[s[i]]+p[0])%MOD;

        if(gethash()==hasht){
            ans[++anslen]=i-m+1;
        }
    }

    cout<<anslen<<endl;
    for(int i=1;i<=anslen;i++){
        cout<<ans[i]<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 3e3+5;
const int MAXM = 7e4+5;
const int INF = 1e9;

int n,m;

int cnt=1;
int head[MAXN];
int nxt[MAXM];
int to[MAXM];
int weight[MAXM];

int degree[MAXN];
vector<int>vec[MAXN];

int dis[MAXN];
bool vis[MAXN];

struct compare{
    bool operator()(const pair<int, int>& a, const pair<int, int>& b) {
         return a.second > b.second; // 小根堆
    }
};
priority_queue<pair<int,int>,vector<pair<int,int>>,compare>heap;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9') {
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    head[u]=cnt++;
}

void dijstra(){
    for(int i=1;i<=n;i++){
        dis[i]=INF;
    }
    dis[1]=0;
    heap.push({1,0});
    while(!heap.empty()){
        int u=heap.top().first;
        heap.pop();
        if(vis[u]){
            continue;
        }
        vis[u]=true;
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            int w=weight[i];
            if(dis[v]>dis[u]+w){
                dis[v]=dis[u]+w;
                if(degree[v]==0){
                    heap.push({v,dis[v]});
                }
            }
        }
        for(int i=0;i<(int)vec[u].size();i++){
            degree[vec[u][i]]--;
            dis[vec[u][i]]=max(dis[vec[u][i]],dis[u]);
            if(degree[vec[u][i]]==0){
                heap.push({vec[u][i],dis[vec[u][i]]});
            }
        }
    }
}

int main()
{
    n=read(),m=read();
    for(int i=1;i<=m;i++){
        int u,v,w;
        u=read(),v=read(),w=read();
        if(u==v){
            continue;
        }
        addedge(u,v,w);
    }
    for(int i=1;i<=n;i++){
        int t;
        cin>>t;
        if(t){
            degree[i]=t;
            for(int j=1;j<=t;j++){
                int u=read();
                vec[u].push_back(i);
            }
        }
    }
    dijstra();
    cout<<dis[n]<<endl;
    return 0;
}

