            char tmp;
            cin>>pos>>tmp;
            if(tmp=='(')
                v=1;
            else if(tmp==')')
                v=2;
            else
                v=0;
            update(pos,v,1,n,1);
        }
        else{
            int l,r;
            cin>>l>>r;
            cout<<query(l,r,1,n,1).ok<<endl;
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 5e4+5;
const int MAXC = 11;
const int MOD = 987654321;

int n,m,c;
long long f[MAXN][MAXC];
bool used[MAXN][MAXC];//表示是否可以选择这种颜色
bool same[MAXN];

void compute(){
    for(int i=2;i<=n+1;i++){
		if(same[i]){
			for(int j=1;j<=c;j++){
				if(used[i][j]){
                    f[i][j]=f[i-1][j];
				}
			}
		}
		else{
			long long sum=0;
			for(int j=1;j<=c;j++){
				sum=(sum+f[i-1][j])%MOD;
			}
			for(int j=1;j<=c;j++){
				if(used[i][j]){
					f[i][j]=(sum-f[i-1][j]+MOD)%MOD;
				}
			}
		}
    }
	return;
}

int work(){
    long long ans=0;
    for(int i=1;i<=c;i++){
        if(used[1][i]){
            for(int j=1;j<=n;j++){
                for(int k=1;k<=c;k++){
                    f[j][k]=0;
                }
            }
            f[1][i]=1;
            compute();
            ans=(ans+f[n+1][i])%MOD;
        }
    }
    return ans;
}

