                cout<<0<<endl;
                return 0;
            }
            for(int j=1;j<=c;j++){
                used[x][j]=false;
            }
            used[x][y]=true;
        }
        else if(op==2){
            used[x][y]=false;
        }
        else{
            same[max(x,y)]=true;
        }
    }
    cout<<work()<<endl;
    return 0;
}

