    int num,id;
}arr[MAXN];
int tree[MAXN<<1];
int cnt=0;
struct con{
    int l,r;
}mix[MAXN<<1];
struct prob{
    int l,r,id,ans;
}nums[MAXM];

bool cmp1(node a,node b){
    return a.num<b.num;
}

bool cmp2(con a,con b){
    return a.r<b.r;
}

bool cmp3(prob a,prob b){
    return a.r==b.r?a.l<b.l:a.r<b.r;
}

inline void add(node a,node b){
    mix[++cnt].l=min(a.id,b.id);
    mix[cnt].r=max(a.id,b.id);
}

int lowbit(int x){
    return x & -x;
}

void add(int i,int v){
    while(i<=n){
        tree[i]+=v;
        i+=lowbit(i);
        //每一次都加上自己最右侧的1
        //相当于把所有包含该状态的数字都增加
    }
}

int sum(int i){
    int ans=0;
    while(i>0){
        ans+=tree[i];
        i-=lowbit(i);
        //每一次都减去自己最右侧的1
        //相当于将整个区间拆分开为几个小区间加速  和乘法快速幂相似
    }
    return ans;
}
