inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void dfs(int u,int f){
    if(arr[u]!=arr[f]){
        deep[u]=deep[f]+1;
    }
    else{
        deep[u]=deep[f];
    }
    for(int i=head[u];i>0;i=Next[i]){
        int v=to[i];
        if(v!=f)
            dfs(v,u);
    }
}

