            for(int k=1;k<=3;k++){
                t[i][j][k]=INF;
            }
        }
    }
    t[1][1][0]=0;
    heap.push({0,1,1,0});
    while(!heap.empty()){
        node u=heap.top();
        heap.pop();
        if(vis[u.x][u.y][u.t]){
            continue;
        }
        if(u.x==n&&u.y==n){
            cout<<u.val<<endl;
            return 0;
        }
        vis[u.x][u.y][u.t]=true;
        for(int i=0;i<4;i++){
            int x=u.x+walk[i][0];
            int y=u.y+walk[i][1];
            int ti=nxt[u.t];
            if(x<1||x>n||y<1||y>n||vis[x][y][ti]){
                continue;
            }
            if((u.val+m+(ti==3?nums[x][y]:0))<t[x][y][ti]){
                t[x][y][ti]=u.val+m+(ti==3?nums[x][y]:0);
                heap.push({t[x][y][ti],x,y,ti});
            }
        }
    }
    return 0;
}

