#include<bits/stdc++.h>
using namespace std;
const int MAXN = 205;
const int MAXM = 2005;

int n,m;
int dfn[MAXN],low[MAXN];
int st[MAXN],top;
int color,Time;
int col[MAXN];
bool instack[MAXN];

int cnt=1;
int head[MAXN];
int Next[MAXM];
int to[MAXM];

void init(){
    cnt=1;
    top=0;
    color=0;
    Time=0;
    for(int i=0;i<=2*n;i++){
        dfn[i]=0;
        low[i]=0;
        col[i]=0;
        head[i]=0;
    }
}

void addedge(int u,int v){
    Next[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

void tarjan(int x){
    dfn[x]=++Time;
    low[x]=Time;
    st[++top]=x;
    instack[x]=true;
    for(int i=head[x];i;i=Next[i]){
        int v=to[i];
        if(!dfn[v]){
            //表示这个节点没有被访问过
            tarjan(v);
            low[x]=min(low[x],low[v]);
        }
        else if(instack[v]){
            //表示这个属于是回溯了 一定是同一个环上的
            low[x]=min(low[x],dfn[v]);
        }
    }
    if(dfn[x]==low[x]){
        col[x]=++color;
        //将所有节点按照颜色分类  完成缩点
        while(st[top]!=x){
            //属于同一个强联通分量
            col[st[top]]=color;
            instack[st[top]]=false;
            top--;
        }
        instack[x]=false;
        top--;
    }
}

int main()
{
    int T;
    cin>>T;
    while(T--){
        cin>>n>>m;
        //12  34  56  78
        init();
        for(int i=1;i<=m;i++){
            char c1,c2;
            int u,v;
            cin>>c1>>u>>c2>>v;
            //cout<<u<<' '<<v;
            u=2*(u-1),v=2*(v-1);
            u+=(c1=='m')?2:1;
            v+=(c2=='m')?2:1;
            //cout<<' '<<u<<' '<<v<<endl;
            addedge((v%2)?(v+1):(v-1),u);
            addedge((u%2)?(u+1):(u-1),v);
        }
        for(int i=1;i<=2*n;i++){
            if(!dfn[i]){
                tarjan(i);
            }
        }
        bool flag=true;
        for(int i=1;i<=2*n;i+=2){
            if(col[i]==col[i+1]){
                flag=false;
                cout<<"BAD"<<endl;
                break;
            }
        }
        if(flag){
            cout<<"GOOD"<<endl;
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;

int n,m;
int val[MAXN];

struct node{
    int lt,rt;
    long long lval,rval;
    int len;
    int ans;
    long long tag;
};
node tree[MAXN<<2];

void merge(node &u,node ls,node rs){
    bool flag=(ls.rval==rs.lval);
    u.len=ls.len+rs.len;
    u.lval=ls.lval;
    u.rval=rs.rval;
    u.ans=ls.ans+rs.ans;

    if(ls.ans==0&&rs.ans==0){
        if(flag){
            u.lt=ls.lt-1;
            u.rt=rs.rt-1;
            u.ans=1;
        }
        else{
            u.lt=u.rt=u.len;
        }
    }
    else if(ls.ans==0){
        u.rt=rs.rt;
        if(flag){
            u.lt=ls.lt-1;
            if(rs.lt){
                u.ans+=(rs.lt-1)/2+1;
            }
        }
        else{
            u.lt=ls.len+rs.lt;
        }
    }
    else if(rs.ans==0){
        u.lt=ls.lt;
        if(flag){
            u.rt=rs.rt-1;
            if(ls.rt){
                u.ans+=(ls.rt-1)/2+1;
            }
        }
        else{
            u.rt=rs.len+ls.rt;
        }
    }
    else{
        u.rt=rs.rt;
        u.lt=ls.lt;
        if(ls.rt==0&&rs.lt==0){
            if(flag){
                u.ans--;
            }
        }
        else if(ls.rt==0){
            if(flag){
                u.ans+=(rs.lt-1)/2;
            }
            else{
                u.ans+=rs.lt/2;
            }
        }
        else if(rs.lt==0){
            if(flag){
                u.ans+=(ls.rt-1)/2;
            }
            else{
                u.ans+=ls.rt/2;
            }
        }
        else{
            if(flag){
                u.ans+=(ls.rt-1)/2+(rs.lt-1)/2+1;
            }
            else{
                u.ans+=(ls.rt+rs.lt)/2;
            }
        }
    }
}

void build(int l,int r,int i){
    if(l==r){
        tree[i].lval=tree[i].rval=val[l];
        tree[i].lt=tree[i].rt=tree[i].len=1;
    }
    else{
        int mid=(l+r)>>1;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        merge(tree[i],tree[i<<1],tree[i<<1|1]);
    }
}

void lazy(int i,long long val){
    tree[i].lval+=val;
    tree[i].rval+=val;
    tree[i].tag+=val;
}

void down(int i){
    if(tree[i].tag){
        lazy(i<<1,tree[i].tag);
        lazy(i<<1|1,tree[i].tag);
        tree[i].tag=0;
    }
}

void add(int jobl,int jobr,long long jobv,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        lazy(i,jobv);
    }
    else{
        int mid=(l+r)>>1;
        down(i);
        if(jobl<=mid){
            add(jobl,jobr,jobv,l,mid,i<<1);
        }
        if(jobr>mid){
            add(jobl,jobr,jobv,mid+1,r,i<<1|1);
        }
        merge(tree[i],tree[i<<1],tree[i<<1|1]);
    }
}

node query(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        return tree[i];
    }
    else{
        int mid=(l+r)>>1;;
        down(i);
        if(jobl<=mid&&jobr>mid){
            node ans;
            merge(ans,query(jobl,jobr,l,mid,i<<1),query(jobl,jobr,mid+1,r,i<<1|1));
            return ans;
        }
        else if(jobl<=mid){
            return query(jobl,jobr,l,mid,i<<1);
        }
        else{
            return query(jobl,jobr,mid+1,r,i<<1|1);
        }
    }
}

int main()
{
    scanf("%d",&n);
    for(int i=1;i<=n;i++){
        scanf("%d",&val[i]);
    }
    for(int i=1;i<n;i++){
        val[i]=val[i+1]-val[i];
    }
    n--;
    build(1,n,1);
    scanf("%d",&m);
    for(int i=1;i<=m;i++){
        char op;
        int s,t,a,b;
        scanf(" %c %d %d",&op,&s,&t);
        if(op=='A'){
            scanf("%d %d",&a,&b);
            if(s>1){
                add(s-1,s-1,a,1,n,1);
            }
            if(t<=n){
                add(t,t,-(1ll*a+1ll*(t-s)*b),1,n,1);
            }
            if(s<t){
                add(s,t-1,b,1,n,1);
            }
        }
        else{
            if(s==t){
                printf("1\n");
                continue;
            }
            node res=query(s,t-1,1,n,1);
            if(res.ans==0){
