    for(int i=1;i<=q;i++){
        int l,r;
        l=read(),r=read();
        addedge(r,l,i);
    }
    for(int i=1;i<=n;i++){
        if(lst[val[i]]){
            update(lst[val[i]]+1,i,i,1,n,1);
            fa[lst[val[i]]]=lst[val[i]]+1;
        }
        else{
            update(1,i,i,1,n,1);
        }
        lst[val[i]]=i;
        for(int ei=head[i];ei;ei=nxt[ei]){
            int l=to[ei];
            int r=find(l);
            ans[id[ei]]=query(l,r,1,n,1);
        }
    }
    for(int i=1;i<=q;i++){
        printf("%d\n",ans[i]);
    }
    return 0;
}

