    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

void addEdge(int u,int v,int w){
    nxt1[tot]=head1[u];
    to1[tot]=v;
    weight[tot]=w;
    head1[u]=tot++;
}

bool spfa(){
    for(int i=1;i<=n;i++){
        vis[i]=false;
    }
    dis[0]=0;
    vis[0]=1;
    q.push(0);
    updatecnt[0]++;
    while(!q.empty()){
        int u=q.front();
        q.pop();
        vis[u]=false;
        for(int i=head1[u];i;i=nxt1[i]){
            int v=to1[i];
            int w=weight[i];
            if(dis[v]>dis[u]+w){
                dis[v]=dis[u]+w;
                if(!vis[v]){
                    if(++updatecnt[v]>n){
                        return true;
                    }
                    vis[v]=true;
                    q.push(v);
                }
            }
        }
    }
    return false;
}

