#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e6+5;
const int INF = 1e6+10;

int n;
int aim[MAXN];

int indeg[MAXN];
int in[MAXN];

int dp0[MAXN];
int dp1[MAXN];

int que[MAXN];

int dponcycle(int len){
    if(len==1){
        return dp0[que[1]];
    }

    int f0=dp0[que[1]];
    int f1=-INF;
    for(int i=2;i<=len;i++){
        int u=que[i];
        int nf0=max(f0,f1)+dp0[u];
        int nf1=f0+dp1[u];

        f0=nf0;
        f1=nf1;
    }
    int ans=max(f0,f1);

    f0=-INF;
    f1=dp1[que[1]];
    for(int i=2;i<=len;i++){
        int u=que[i];
        int nf0=max(f0,f1)+dp0[u];
        int nf1=f0+dp1[u];

        f0=nf0;
        f1=nf1;
    }
    ans=max(ans,f0);
    return ans;
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>aim[i];
        indeg[aim[i]]++;
        in[aim[i]]++;
    }
    for(int i=1;i<=n;i++){
        dp0[i]=0;
        dp1[i]=1;
    }

    int maxdead=0;
    for(int i=1;i<=n;i++){
        if(indeg[i]>0){
            maxdead++;
        }
    }
    int l=1,r=0;
    for(int i=1;i<=n;i++){
        if(indeg[i]==0){
            que[++r]=i;
        }
    }
    while(l<=r){
        int u=que[l++];
        int v=aim[u];
        dp0[v]+=max(dp0[u],dp1[u]);
        dp1[v]+=dp0[u];

        indeg[v]--;
        if(indeg[v]==0){
            que[++r]=v;
        }
    }

    int maxalive=0;

    for(int i=1;i<=n;i++){
        if(indeg[i]){
            int len=0;
            int x=i;
            que[++len]=x;
            x=aim[x];
            while(x!=i){
                indeg[x]=0;
                que[++len]=x;
                x=aim[x];
            }
            maxalive+=dponcycle(len);
            if(len>1){
                bool ok=true;
                for(int j=1;j<=len;j++){
                    int u=que[j];
                    if(in[u]!=1){
                        ok=false;
                        break;
                    }
                }
                if(ok){
                    maxdead--;
                }
            }
        }
    }
    cout<<(n-maxalive)<<' '<<maxdead<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 5e5+5;
const int BASE = 499;

int n;
int nums[MAXN];

int p[MAXN];

int tree[MAXN<<2];
int front[MAXN<<2];
int back[MAXN<<2];

struct node{
    int len,f,b;
};

void build(int l,int r,int i){
    tree[i]=r-l+1;
    if(l==r){
        return;
    }
    else{
        int mid=(l+r)>>1;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
    }
}

void up(int i){
    front[i]=front[i<<1]*p[tree[i<<1|1]]+front[i<<1|1];
    back[i]=back[i<<1|1]*p[tree[i<<1]]+back[i<<1];
}

void update(int pos,int l,int r,int i){
    if(l==r){
        front[i]=back[i]=1;
    }
    else{
        int mid=(l+r)>>1;
        if(pos<=mid){
            update(pos,l,mid,i<<1);
        }
        else{
            update(pos,mid+1,r,i<<1|1);
        }
        up(i);
    }
}

node merge(node a,node b){
    return {a.len+b.len,a.f*p[b.len]+b.f,b.b*p[a.len]+a.b};
}

node query(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        return {tree[i],front[i],back[i]};
    }
    else{
        int mid=(l+r)>>1;
        if(jobl<=mid&&jobr>mid){
            return merge(query(jobl,jobr,l,mid,i<<1),query(jobl,jobr,mid+1,r,i<<1|1));
        }
        else if(jobl<=mid){
            return query(jobl,jobr,l,mid,i<<1);
        }
        else if(jobr>mid){
            return query(jobl,jobr,mid+1,r,i<<1|1);
        }
    }
}

signed main()
{
    p[0]=1;
    for(int i=1;i<=500000;i++){
        p[i]=p[i-1]*BASE;
    }
    int T;
    cin>>T;
    while(T--){
        cin>>n;
        memset(tree,0,sizeof(tree));
        memset(front,0,sizeof(front));
        memset(back,0,sizeof(back));
        build(1,n,1);
        bool flag=false;
        for(int i=1;i<=n;i++){
            cin>>nums[i];
        }
        for(int i=1;i<=n;i++){
            int len=min(nums[i]-1,n-nums[i]);
            update(nums[i],1,n,1);
            if(len==0){
                continue;
            }
            node lt=query(nums[i]-len,nums[i]-1,1,n,1);
            node rt=query(nums[i]+1,nums[i]+len,1,n,1);
            if(lt.b!=rt.f){
                flag=true;
                break;
            }
        }
        if(flag){
            cout<<'Y'<<endl;
        }
        else{
            cout<<'N'<<endl;
        }
    }
    return 0;
}

