void build(){
    int top=0;
    for(int i=1;i<=n;i++){
        int pos=top;
        while(pos&&val[st[pos]]<val[i]){
            pos--;
        }
        if(pos>0){
            rs[st[pos]]=i;
            f[i]=st[pos];
        }
        if(pos<top){
            ls[i]=st[pos+1];
            f[ls[i]]=i;
        }

        st[++pos]=i;
        top=pos;

        if(ls[i]){
            int father=find(ls[i]);
            if(father!=ls[i]){
                fa[i]=father;
                sz[father]++;
            }
            else{
                if(sum[i-1]-sum[st[top-1]]>=val[i]){
                    fa[father]=i;
                    sz[i]+=sz[father];
                }
