    ios::sync_with_stdio(0);
    cin >> n >> m;
    n2 = 1 << n;

    for (int i = 1; i < n2; ++i) 
		cin >> op[i];

    dfs(1, 1, n2, n);

    f[0][0] = 1;  // 记得处理第一场比赛啊
    for (int i = 0; i <= n; ++i) {
        for (int j = 1; j <= n2; ++j) {
            f[i][j] += f[i][j - 1];
        }
    }

    while (m--) {
        int a, b;
        cin >> a >> b;
        cout << (f[b - 1][a] > 0 ? "Yes\n" : "No\n");
    }

    return 0;
}

