    st[1]=1;

    for(int i=2;i<=R;i++)
        st[i]=st[i-1]+cnt[i-1];

    for(int i=1;i<=R;i++)
        cur[i]=st[i];

    // 按地区保存所有节点的DFS序
    for(int t=1;t<=n;t++){
        int x=ord[t];
        ptin[cur[col[x]]++]=t;
    }

    for(int i=1;i<=R;i++)
        cur[i]=st[i];

    // 按地区保存所有节点的子树右端点
    for(int x=1;x<=n;x++)
        pout[cur[col[x]]++]=out[x];

    for(int i=1;i<=R;i++)
        sort(pout+st[i],pout+st[i]+cnt[i]);

    for(int i=1;i<=R;i++){
        if(cnt[i]>=B){
            hid[i]=++hcnt;
            hreg[hcnt]=i;
        }
    }

    for(int i=1;i<=hcnt;i++)
