void init(){
    cnt=1;
    last=0;
    len[0]=0,len[1]=-1;
    fail[0]=1,fail[1]=1;
    addedge(0,1);
    addedge(1,0);
    s[0]='#';
}

int getfail(int p,int i){
    while(s[i-len[p]-1]!=s[i]){
        p=fail[p];
    }
    return p;
}

void insert(int i){
    int c=s[i]-'a';
    int cur=getfail(last,i);

    if(!tree[cur][c]){
        int x=++cnt;
        len[x]=len[cur]+2;

        int p=getfail(fail[cur],i);
        fail[x]=tree[p][c];
        addedge(x,fail[x]);
        addedge(fail[x],x);

        tree[cur][c]=x;
        firstpos[x]=i-len[x]+1;
        addedgeh(len[x],x);
    }
    last=tree[cur][c];
}

void dfs(int u,int fa){
    dep[u]=dep[fa]+1;
    st[u][0]=fa;
    for(int i=1;i<=p;i++){
        st[u][i]=st[st[u][i-1]][i-1];
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa){
            dfs(v,u);
        }
    }
}

