    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

int power(int a,int b,int mod){
    a%=mod,b%=mod;
    a=(a+mod)%mod;
    b=(b+mod)%mod;
    int ans=1;
    while(b){
        if(b&1){
            ans=(ans*a)%mod;
        }
        b>>=1;
        a=(a*a)%mod;
    }
    return ans;
}

int geteuler(int n){
    if(n==0){
        return 0;
    }
	int ans=1;
	int tmp=n;
	for(int i=2;i*i<=tmp;i++){
		if(tmp%i){
			continue;
		}
		ans*=(i-1);
		tmp/=i;
		while(tmp%i==0){
			ans*=i;
			tmp/=i;
		}
	}
	if(tmp>1){
		ans*=(tmp-1);
	}
	return ans;
}

int exeuler(int u,int mod){
    if(u==n+1){
        return 1;
    }
    else{
        int m=geteuler(mod);
        int tmp=exeuler(u+1,m);
        if(tmp>=m){
            tmp=tmp+m;
        }
        return power(nums[u],tmp,mod);
    }
}

