void prepare(){
    blen=sqrt(n);
    for(int d=1;d<=blen;d++){
        for(int i=n;i>=1;i--){
            f[d][i]=(i+d>n?0:f[d][i+d])+nums[i];
        }
    }
    for(int d=1;d<=blen;d++){
        for(int i=n;i>=1;i--){
            g[d][i]=(i+d>n?0:g[d][i+d])+f[d][i];
        }
    }
}

long long query(int s,int d,int k){
    long long ans=0;
    if(d>blen){
        for(int i=1;i<=k;i++){
            ans+=1ll*nums[s+(i-1)*d]*i;
        }
    }
    else{
        ans=g[d][s];
        if(s+d*k<=n)
            ans-=g[d][s+d*k]+f[d][s+d*k]*k;
    }
    return ans;
}

