    for(int i=1;i<=day;i++){
        cout<<ans[i]<<endl;
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define ll long long
int n,m,md;
ll a[400005],sum[400005],mu[400005],add[400005],lll[400005],rrr[400005];
#define ls(x) x<<1
#define rs(x) x<<1|1
void build(ll p,ll l,ll r){
	lll[p]=l,rrr[p]=r,mu[p]=1;
	if(l==r){
		sum[p]=a[l]%md;
		return;
	}
	ll mid=(l+r)>>1;
	build(ls(p),l,mid);
	build(rs(p),mid+1,r);
	sum[p]=sum[ls(p)]+sum[rs(p)]%md;
}
void pushdown(ll p){
	sum[ls(p)]=(mu[p]*sum[ls(p)]+(rrr[ls(p)]-lll[ls(p)]+1)*add[p]%md)%md;
	sum[rs(p)]=(mu[p]*sum[rs(p)]+(rrr[rs(p)]-lll[rs(p)]+1)*add[p]%md)%md;
	mu[ls(p)]=(mu[p]*mu[ls(p)])%md;
	mu[rs(p)]=(mu[p]*mu[rs(p)])%md;
	add[ls(p)]=(mu[p]*add[ls(p)]+add[p])%md;
	add[rs(p)]=(mu[p]*add[rs(p)]+add[p])%md;
	mu[p]=1,add[p]=0;
}
void addd(ll p,ll l,ll r,ll k){
	if(lll[p]>=l && rrr[p]<=r){
		add[p]+=k;
		add[p]%=md;
		sum[p]+=(rrr[p]-lll[p]+1)*k;
		sum[p]%=md;
		return;
	}
	pushdown(p);
	sum[p]=(sum[ls(p)]+sum[rs(p)])%md;
	ll mid=(lll[p]+rrr[p])>>1;
	if(l<=mid)addd(ls(p),l,r,k);
	if(mid<r)addd(rs(p),l,r,k);
	sum[p]=(sum[ls(p)]+sum[rs(p)])%md;
}
void mul(ll p,ll l,ll r,ll k){
	if(lll[p]>=l && rrr[p]<=r){
		add[p]*=k,add[p]%=md;
		mu[p]*=k,mu[p]%=md;
		sum[p]*=k,sum[p]%=md;
		return;
	}
	pushdown(p);
	sum[p]=(sum[ls(p)]+sum[rs(p)])%md;
	ll mid=(lll[p]+rrr[p])>>1;
	if(l<=mid)mul(ls(p),l,r,k);
	if(mid<r)mul(rs(p),l,r,k);
	sum[p]=(sum[ls(p)]+sum[rs(p)])%md;
}
ll query(ll p,ll l,ll r){
	if(lll[p]>=l && rrr[p]<=r)return sum[p];
	pushdown(p);
	ll v=0,mid=(lll[p]+rrr[p])>>1;
	if(l<=mid)v+=query(ls(p),l,r),v%=md;
	if(mid<r)v+=query(rs(p),l,r),v%=md;
	return v;
}
int main() {
	cin>>n>>md;
	for(int i=1;i<=n;i++)scanf("%d",&a[i]);
	build(1,1,n);
	cin>>m;
	while(m--){
		ll x,y,typ;
		scanf("%lld%lld%lld",&typ,&x,&y);
		if(typ==1){
			ll z;
			scanf("%lld",&z);
			mul(1,x,y,z);
		}else if(typ==2){
			ll z;
			scanf("%lld",&z);
			addd(1,x,y,z);
		}else printf("%lld\n",query(1,x,y));
	}
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 2e5+5;

int arr[MAXN];
//阶乘表
int fac[MAXN];
// 线段树
int sum[MAXN << 2];
int n;
int MOD;

// 初始化线段树，单点范围的初始累加和为1，认为所有数字都可用
void build(int l, int r, int i) {
    if (l == r) {
        sum[i] = 1;
    } else {
        int mid = (l + r) >> 1;
        build(l, mid, i << 1);
        build(mid + 1, r, i << 1 | 1);
        sum[i] = sum[i << 1] + sum[i << 1 | 1];
    }
}

// 单点jobi上，增加jobv，因为是单点更新，所以不需要建立懒更新机制
void add(int jobi, int jobv, int l, int r, int i) {
    if (l == r) {
        sum[i] += jobv;
    } else {
        int mid = (l + r) >> 1;
        if (jobi <= mid) {
            add(jobi, jobv, l, mid, i << 1);
        } else {
            add(jobi, jobv, mid + 1, r, i << 1 | 1);
        }
        sum[i] = sum[i << 1] + sum[i << 1 | 1];
    }
}

// 查询jobl~jobr范围的累加和
int Sum(int jobl, int jobr, int l, int r, int i) {
    if (jobl <= l && r <= jobr) {
        return sum[i];
    }
    int mid = (l + r) >> 1;
    int ans = 0;
    if (jobl <= mid) {
        ans += Sum(jobl, jobr, l, mid, i << 1);
    }
    if (jobr > mid) {
        ans += Sum(jobl, jobr, mid + 1, r, i << 1 | 1);
    }
    return ans;
}

// 线段树上找到第k名的是什么，找到后删掉词频，返回的过程修改累加和
// 注意这个排名是在子树中的排名
int getAndDelete(int k, int l, int r, int i) {
    int ans;
    if (l == r) {
        //找到目标 删除词频
        sum[i]--;
        ans = l;
    } else {
        int mid = (l + r) >> 1;
        if (sum[i << 1] >= k) {
            ans = getAndDelete(k, l, mid, i << 1);
        } else {
            ans = getAndDelete(k - sum[i << 1], mid + 1, r, i << 1 | 1);
            //要减去左侧排名的影响
        }
        sum[i] = sum[i << 1] + sum[i << 1 | 1];
        //返回的过程修改累加和
    }
    return ans;
}

void compute(int k) {
    build(1, n, 1);
    //将线段树重新复原
    for (int i = 1; i <= n; i++) {
        arr[i] = getAndDelete((int) arr[i] + 1, 1, n, 1);
        //此时这个arr数组用来存放排列
    }
}

