}

void getlist(int u,int fa,int dis,int rt){
    curarr[++cntc]={age[u],dis};
    if(centfa[rt]){
        faarr[++cntf]={age[u],getdist(u,centfa[rt])};
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        int w=weight[i];
        if(v!=fa&&!vis[v]){
            getlist(v,u,dis+w,rt);
        }
    }
}

void centroidtree(int u,int fa){
    centfa[u]=fa;
    vis[u]=true;
    curl[u]=cntc+1;
    fal[u]=cntf+1;
