    for(int i=1;i<=n;i++){
        if(val1[i]!=val2[i]&&val1[i]==val[i]){
            if(val2[i]==0){
                printf("-1 ");
            }
            else{
                ans1=0;
                if(pos[i]!=0){
                    dfs3(pos[i]);
                }
                if(ans1!=0){
                    ans1--;
                }
                printf("%d ",ans+ans1);
            }
        }
        else{
            printf("%d ",ans);
        }
    }
    return 0;
}

