void dfs(int x,int y){
    vis[x][y]=true;
    for(int i=0;i<4;i++){
        int nx=x+walk[i][0];
        int ny=y+walk[i][1];
        if(nx<1||nx>n||ny<1||ny>m){
            continue;
        }
        if (high[nx][ny]>=high[x][y])
            continue;
        if(!vis[nx][ny]){
            dfs(nx,ny);
        }
        l[x][y]=min(l[x][y],l[nx][ny]);
        r[x][y]=max(r[x][y],r[nx][ny]);
    }
}

