        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void up(int i){
    tree[i]=tree[i<<1]+tree[i<<1|1];
}

void build(int l,int r,int i){
    if(l==r){
        tree[i]=val[l];
    }
    else{
        int mid=(l+r)>>1;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        up(i);
    }
}

inline void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

void add(int jobl,int jobr,int jobv,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        addedge(i,jobv);
        need[jobv]++;
    }
    else{
        int mid=(l+r)>>1;
        if(jobl<=mid){
            add(jobl,jobr,jobv,l,mid,i<<1);
        }
        if(jobr>mid){
            add(jobl,jobr,jobv,mid+1,r,i<<1|1);
        }
    }
}

void update(int pos,int l,int r,int i){
    if(tree[i]==0){
        return ;
    }
    if(l==r){
        tree[i]--;
        if(tree[i]==0){
            for(int ei=head[i];ei;ei=nxt[ei]){
                int v=to[ei];
                need[v]--;
                if(need[v]==0){
                    ans++;
                }
            }
        }
    }
    else{
        int mid=(l+r)>>1;
        if(pos<=mid){
            update(pos,l,mid,i<<1);
        }
        else{
            update(pos,mid+1,r,i<<1|1);
        }
        up(i);
        if(tree[i]==0){
            for(int ei=head[i];ei;ei=nxt[ei]){
                int v=to[ei];
                need[v]--;
                if(need[v]==0){
                    ans++;
                }
            }
        }
    }
}

