// 0...i范围上的会议，根据结束日期排序了
// 找到结束时间<s，最右的会议编号
// 如果不存在这样的会议返回-1
int find(int i, int s) {
	int l = 1, r = i, mid;
	int ans = 0;
	while (l <= r) {
		mid = (l + r) / 2;
		if (nums[mid].en < s) {
			ans = mid;
            l = mid + 1;
        } else {
            r = mid - 1;
        }
    }
    return ans;
}

