    return ans;
}

int range(int l, int r) {
	return sum(r) - sum(l - 1);
}

bool cmp(Query a,Query b){
    return a.r<b.r;
}

void compute() {
    sort(query+1,query+ m + 1,cmp);
    for (int s = 1, q = 1, l, r, i; q <= m; q++) {
        r = query[q].r;
        for (; s <= r; s++) {
            int color = arr[s];
            if (Map[color] != 0) {
                add(Map[color], -1);
            }
            add(s, 1);
            Map[color] = s;
        }
        l = query[q].l;
        i = query[q].subsrcipt;
        ans[i] = range(l, r);
    }
}

