}

// 仙人掌最长路线，C++版
// 给定n个点、m条边的无向连通图，输入保证图是仙人掌
// 路线可以从任何城市开始，但必须在1号点结束
// 路线可以重复经过同一个点，但不能重复经过同一条边
// 计算最长路线的边数
// 1 <= n <= 10^4
// 1 <= m <= 2 * 10^4
// 测试链接 : https://www.luogu.com.cn/problem/P6335
// 如下实现是C++的版本，C++版本和java版本逻辑完全一样
// 提交如下代码，可以通过所有测试用例
// 这个dp设置是非常巧妙的
// 尤其是f和g g=f+delta
// 这里的delta 对于割边而言，就是完全可以实现f之后  
// 直接去往割边方向，相当于割边方向就是完全的可以多走的
// 对于环而言  可以是先把其他环走完  这个环尽量看看有没有最大值
// 对于一个节点而言，f就是所有环的长度
#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e4+5;
const int MAXM = 4e4+5;

int n,m;

int head[MAXN];
int nxt[MAXM<<1];
int to[MAXM<<1];
int cntg=2;

int dfncnt;
int dfn[MAXN];
int low[MAXN];
int sta[MAXN];
int top;

// 用于收集环上的节点
int cycle[MAXN];
// 在以u为头的子仙人掌树下
// 表示从这个出发，最终回到这个点的最长距离
int f[MAXN];
// 表示从这个出发，最终不需要回到这个点的最长距离
int g[MAXN];

inline void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

int dponcycle(int u,int v){
    int sz=0;
    int pop;
    do{
        pop=sta[top--];
        cycle[++sz]=pop;
    }while(pop!=v);
    int best=0;
    int sum=1;
    for(int i=1;i<=sz;i++){
        best=max(best,sum+g[cycle[i]]);
        sum+=f[cycle[i]]+1;
    }
    f[u]+=sum;
    int oth=sum;
    for(int i=1;i<=sz;i++){
        oth-=f[cycle[i]]+1;
        best=max(best,oth+g[cycle[i]]);
    }
    return best-sum;
}

void tarjan(int u,int preedge){
    dfn[u]=low[u]=++dfncnt;
    sta[++top]=u;
    int delta=0;
    for(int i=head[u];i;i=nxt[i]){
        if((i^1)==preedge){
            continue;
        }

        int v=to[i];
        if(dfn[v]==0){
            tarjan(v,i);
            if(low[v]<dfn[u]){
                low[u]=min(low[u],low[v]);
            }
            else if(low[v]>dfn[u]){
                top--;
                delta=max(delta,g[v]+1);
            }
            else{
                delta=max(delta,dponcycle(u,v));
            }
        }
        else if(dfn[v]<dfn[u]){
            low[u]=min(low[u],dfn[v]);
        }
    }
    g[u]=f[u]+delta;
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m;
    for(int i=1;i<=m;i++){
        int u,v;
        cin>>u>>v;
        addedge(u,v);
        addedge(v,u);
    }

    tarjan(1,0);
    cout<<g[1]<<endl;
    return 0;
}

#include<bits/stdc++.h>

#define MAX 305
using namespace std;

struct coord{
    int x,y;
};
queue<coord>Q;
int walk[4][2]={{1,0},{-1,0},{0,1},{0,-1}};
int death[MAX][MAX],ans[MAX][MAX];

int main()
{
    int m,Ans=100000;
    scanf("%d",&m);
    memset(ans,-1,sizeof(ans));
    memset(death,1e9,sizeof(death));
    while(m--){
        int x,y,t;
        scanf("%d %d %d",&x,&y,&t);
        if(x>=0&&y>=0)
            death[x][y]=min(death[x][y],t);
        for(int i=0;i<4;i++){
            if(x+walk[i][0]>=0&&y+walk[i][1]>=0)
                death[x+walk[i][0]][y+walk[i][1]]=min(death[x+walk[i][0]][y+walk[i][1]],t);
        }
    }
    Q.push({0,0});
    ans[0][0]=0;
    while(!Q.empty()){
        coord now=Q.front();
        Q.pop();
        for(int i=0;i<4;i++){
            int x=now.x+walk[i][0],y=now.y+walk[i][1];
            if(x<0||y<0||ans[x][y]!=-1||ans[now.x][now.y]+1>=death[x][y]){
                continue;
            }
            ans[x][y]=ans[now.x][now.y]+1;
            Q.push({x,y});
        }
    }
    for(int i=0;i<305;i++){
        for(int j=0;j<305;j++){
            if(death[i][j]>1000&&ans[i][j]!=-1)
                Ans=min(Ans,ans[i][j]);
        }
    }
    if(Ans==100000)
        printf("-1\n");
    else
        printf("%d\n",Ans);
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 200005;

int arr[MAXN];
int sum0[MAXN<<2],sum1[MAXN<<2];
bool Reverse[MAXN<<2];
int n,m;

void up(int i){
    sum0[i]=sum0[i<<1]+sum0[i<<1|1];
    sum1[i]=sum1[i<<1]+sum1[i<<1|1];
}

void lazy(int i,int n){
    sum0[i]=n-sum0[i];
    sum1[i]=n-sum1[i];
    Reverse[i]=!Reverse[i];
}

void down(int i,int ln,int rn){
    if(Reverse[i]){
        lazy(i<<1,ln);
        lazy(i<<1|1,rn);
        Reverse[i]=false;
    }
}

void build(int l,int r,int i){
    if(l==r){
        sum0[i]= (arr[l]==1)?0:1;
        sum1[i]= (arr[l]==1)?1:0;
    }else{
        int mid=(l+r)/2;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        up(i);
    }
    Reverse[i]=false;
}

void reversE(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        lazy(i,r-l+1);
    }else{
        int mid=(l+r)/2;
        down(i,mid-l+1,r-mid);
        if(jobl<=mid){
            reversE(jobl,jobr, l, mid,i<<1);
        }
        if(jobr>mid){
            reversE(jobl,jobr,mid+1,r,i<<1|1);
        }
        up(i);
    }
}

int query(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        return sum1[i];
    }else{
        int mid=(l+r)/2;
        down(i,mid-l+1,r-mid);
        int ans=0;
        if(jobl<=mid){
            ans+=query(jobl,jobr,l,mid,i<<1);
        }
        if(jobr>mid){
            ans+=query(jobl,jobr,mid+1,r,i<<1|1);
        }
        return ans;
    }
}

int main()
{
    cin>>n>>m;
    char c;
    for(int i=1;i<=n;i++){
        cin>>c;
        arr[i]=c-'0';
        //printf("%3d",arr[i]);
    }
    //cout<<endl;
    build(1,n,1);
    for(int i=1,op,jobl,jobr;i<=m;i++){
        cin>>op>>jobl>>jobr;
        if(op==0){
            reversE(jobl,jobr,1,n,1);
        }else{
            cout<<query(jobl,jobr,1,n,1)<<endl;
        }
    }
    return 0;
}

