#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
#define N 500050

ll f[N][22],a[N];
int n,Q,nxt[N][22];
ll ans;
int st[N],top;
int buf[111],p;

inline int read(){
    int x=0,f=1;
    char c=getchar();
    while(c<'0'||c>'9'){
        if(c=='-')f=-1;
        c=getchar();
    }
    while(c>='0'&&c<='9'){
        x=(x<<3)+(x<<1)+c-'0';
        c=getchar();
    }
    return x*f;
}

inline void Output(ll x){
	p=0;
	while(x)buf[++p]=x%10,x/=10;
	while(p)putchar(buf[p--]+'0');
	putchar('\n');
}

int main()
{
	n=read(),Q=read();
	int MX=log2(n)+1;
	for(int i=1;i<=n;i++){
		a[i]=read();
	}

	for(int i=1;i<=n;i++){
		while(top&&a[st[top]]<a[i]){
			nxt[st[top]][0]=i;
			--top;
		}
		st[++top]=i;
	}

	while(top)nxt[st[top--]][0]=n+2;
	nxt[n+1][0]=nxt[n+2][0]=n+2;
	for(register int i=1;i<=n;++i){
		f[i][0]=1LL*a[i]*(nxt[i][0]-i);
	}
	for(register int j=1;j<=MX;++j){
		for(register int i=1;i<=n+2;++i){
			nxt[i][j]=n+2;
		}
		for(register int i=1;i+(1<<j)-1<=n;++i){
			nxt[i][j]=nxt[nxt[i][j-1]][j-1];
			f[i][j]=f[i][j-1]+f[nxt[i][j-1]][j-1];
		}
	}
	while(Q--){
		int u=read(),v=read();
		int l=1+(u^ans)%n,r=(v^(ans+1))%(n-l+1)+l;
		int pos=l;
		ans=0;
		for(register int i=MX;i>=0;--i){
			if(nxt[pos][i]-1>r)continue;
			ans+=f[pos][i];
			pos=nxt[pos][i];
		}
		ans+=a[pos]*(r-pos+1);
		Output(ans);
	}
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int MAXC = 1e5+5;
const int MAXT = 2e6+5;

int n,m;

int val[MAXN];
int kind[MAXN];

int root[MAXC];
int maxx[MAXT];
int sum[MAXT];
int ls[MAXT];
int rs[MAXT];
int cnt;

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int cntg=1;

int dep[MAXN];
int dfncnt;
int dfn[MAXN];
int seg[MAXN];
int sz[MAXN];
int son[MAXN];
int fa[MAXN];
int top[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

void dfs1(int u,int f){
    dep[u]=dep[f]+1;
    fa[u]=f;
    sz[u]=1;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=f){
            dfs1(v,u);
            if(son[u]==0||sz[son[u]]<sz[v]){
                son[u]=v;
            }
            sz[u]+=sz[v];
        }
    }
}

void dfs2(int u,int t){
    top[u]=t;
    dfn[u]=++dfncnt;
    seg[dfncnt]=u;
    if(son[u]){
        dfs2(son[u],t);
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v==fa[u]||v==son[u]){
            continue;
        }
        dfs2(v,v);
    }
}

void up(int i){
    maxx[i]=max(maxx[ls[i]],maxx[rs[i]]);
    sum[i]=sum[ls[i]]+sum[rs[i]];
}

void update(int pos,int val,int l,int r,int i){
    if(l==r){
        maxx[i]=val;
        sum[i]=val;
    }
    else{
        int mid=(l+r)>>1;
        if(pos<=mid){
            if(ls[i]==0){
                ls[i]=++cnt;
            }
            update(pos,val,l,mid,ls[i]);
        }
        else{
            if(rs[i]==0){
                rs[i]=++cnt;
            }
            update(pos,val,mid+1,r,rs[i]);
        }
        up(i);
    }
}

int querymax(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        return maxx[i];
    }
    else{
        int mid=(l+r)>>1;
        int ans=0;
        if(jobl<=mid){
            if(ls[i]){
                ans=max(ans,querymax(jobl,jobr,l,mid,ls[i]));
            }
        }
        if(jobr>mid){
            if(rs[i]){
                ans=max(ans,querymax(jobl,jobr,mid+1,r,rs[i]));
            }
        }
        return ans;
    }
}

int querysum(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        return sum[i];
    }
    else{
        int mid=(l+r)>>1;
        int ans=0;
        if(jobl<=mid){
            if(ls[i]){
                ans+=querysum(jobl,jobr,l,mid,ls[i]);
            }
        }
        if(jobr>mid){
            if(rs[i]){
                ans+=querysum(jobl,jobr,mid+1,r,rs[i]);
            }
        }
        return ans;
    }
}

int pathmax(int x,int y,int c){
    int ans=0;
    while(top[x]!=top[y]){
        if(dep[top[x]]<=dep[top[y]]){
            ans=max(ans,querymax(dfn[top[y]],dfn[y],1,n,root[c]));
            y=fa[top[y]];
        }
        else{
            ans=max(ans,querymax(dfn[top[x]],dfn[x],1,n,root[c]));
            x=fa[top[x]];
        }
    }
    ans=max(ans,querymax(min(dfn[x],dfn[y]),max(dfn[x],dfn[y]),1,n,root[c]));
    return ans;
}

int pathsum(int x,int y,int c){
    int ans=0;
    while(top[x]!=top[y]){
        if(dep[top[x]]<=dep[top[y]]){
            ans+=querysum(dfn[top[y]],dfn[y],1,n,root[c]);
            y=fa[top[y]];
        }
        else{
            ans+=querysum(dfn[top[x]],dfn[x],1,n,root[c]);
            x=fa[top[x]];
        }
    }
    ans+=querysum(min(dfn[x],dfn[y]),max(dfn[x],dfn[y]),1,n,root[c]);
    return ans;
}

int main()
{
    n=read(),m=read();
    for(int i=1;i<=n;i++){
        val[i]=read();
        kind[i]=read();
    }
    for(int i=1;i<n;i++){
        int u,v;
        u=read(),v=read();
        addedge(u,v);
        addedge(v,u);
    }
    dfs1(1,0);
    dfs2(1,1);
    // for(int i=1;i<=n;i++){
    //     cout<<i<<": "<<dfn[i]<<' '<<sz[i]<<' '<<son[i]<<' '<<fa[i]<<' '<<kind[i]<<' '<<val[i]<<endl;
    // }
    for(int i=1;i<=n;i++){
        if(root[kind[i]]==0){
            root[kind[i]]=++cnt;
        }
        update(dfn[i],val[i],1,n,root[kind[i]]);
    }
    for(int i=1;i<=m;i++){
