        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 405;
const int MAXM = 1005;
const int MAXV = 1405;
const int MAXE = 3e5+5;
const int INF = 1e15;

int n,m,s,t;
int ss,tt;// 附加源点、汇点
int val[MAXM];

int dep[MAXV];
int iter[MAXV];

int cnt=2;
int head[MAXV];
int nxt[MAXE];
int to[MAXE];
int now[MAXE];
int cap[MAXE];
int ts_id; // 记录t->s边的编号

// 每个节点的下界净流量
int in[MAXV];

void init(){
    s=n+m+1,t=s+1,ss=t+1,tt=ss+1;
    for(int i=1;i<=tt;i++){
        head[i]=0;
        in[i]=0;
    }
    cnt=2;
}

void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    cap[cnt]=w;
    now[cnt]=0;
    head[u]=cnt++;

    nxt[cnt]=head[v];
    to[cnt]=u;
    cap[cnt]=0;
    now[cnt]=0;
    head[v]=cnt++;
}

bool bfs(int s,int t){
    for(int i=1;i<=tt;i++){
        dep[i]=-1;
    }
    queue<int>q;
    dep[s]=0;
    q.push(s);
    while(!q.empty()){
        int u=q.front();
        q.pop();
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            int w=cap[i];
            int k=now[i];
            if(dep[v]<0&&(k<w)){
                dep[v]=dep[u]+1;
                q.push(v);
            }
        }
    }
    return dep[t]>=0;
}

int dfs(int u,int t,int f){
    if(u==t){
        return f;
    }
    int flow=0;
    for(int &i=iter[u];i;i=nxt[i]){
        int v=to[i];
        int w=cap[i];
        int k=now[i];
        if(dep[u]+1==dep[v]&&k<w){
            int d=dfs(v,t,min(f,w-k));
            if(d>0){
                now[i]+=d;
                now[i^1]-=d;
                flow+=d;
                f-=d;
                if(f==0){
                    break;
                }
            }
        }
    }
    return flow;
}

int maxflow(int s,int t){
    int flow=0;
    while(bfs(s,t)){
        for(int i=1;i<=tt;i++){
            iter[i]=head[i];
        }
        int maxflow;
        while((maxflow=dfs(s,t,INF))>0){
            flow+=maxflow;
        }
    }
    return flow;
}

signed main()
{
    while(scanf("%lld %lld",&n,&m)==2){
        init();
        for(int i=1;i<=m;i++){
            scanf("%lld",&val[i]);
        }
        for(int i=1;i<=n;i++){
            int c,d;
            scanf("%lld %lld",&c,&d);
            // 源点到第i天 容量为d  下界为0 此时由于流入流出是0 所以不用改变in数组
            addedge(s,i,d);

            for(int j=1;j<=c;j++){
                int t,l,r;
                scanf("%lld %lld %lld",&t,&l,&r);
                // 从第i天到少女t(从0开始) 边的容量是上界减去下界
                addedge(i,n+1+t,r-l);

                in[n+1+t]+=l;
                in[i]-=l;
            }
        }
        // 从每位少女到汇点t，容量为INF，下界为G[j]
        for(int i=1;i<=m;i++){
            addedge(n+i,t,INF);
            in[t]+=val[i];
            in[n+i]-=val[i];
        }

        // 记录添加t->s边前的cnt  添加t->s边，容量INF
        ts_id=cnt;
        addedge(t,s,INF);

        // 建立所有的附加边
        int all=0;
        for(int i=1;i<=t;i++){
            if(in[i]>0){
                addedge(ss,i,in[i]);
                all+=in[i];
            }
            else if(in[i]<0){
                addedge(i,tt,-in[i]);
            }
        }

        int flow1=maxflow(ss,tt);
        if(flow1!=all){
            printf("-1\n\n");
        }
        else{
            // 记录可行流值
            int f0=now[ts_id];

            // 删除t->s边：将容量和当前流量设为0
            // 附加边不需要改变 因为他们的剩余流量一定是0
            cap[ts_id] = 0;
            cap[ts_id ^ 1] = 0;
            now[ts_id] = 0;
            now[ts_id ^ 1] = 0;

            // 在残余网络上从s到t跑最大流
            int flow2 = maxflow(s, t);

            printf("%lld\n\n", f0 + flow2);
        }
    }
    return 0;
}

