int main() {
    cin >> testCases;
    // 初始化：单个字符时，其 ASCII 值减去 'a' 的结果即为对应的和
    for (int i = 0; i < 26; i++) {
        dp[1][i] = 1;
    }

    // 动态规划填充 dp 数组
    for (int length = 2; length <= 100; length++) {
        dp[length][0] = 1; // 任何长度的字符串，和为 0 的情况只有一种（即不包含任何字符）
        for (int sum = 1; sum <= 2700; sum++) {
            for (int charValue = 0; charValue < 26; charValue++) { // 'a' 到 'z' 的 ASCII 差值
                if (sum - charValue >= 0) {
                    dp[length][sum] = (dp[length][sum] % MOD + dp[length - 1][sum - charValue] % MOD) % MOD;
                }
            }
        }
    }

    // 处理每个测试用例
    while (testCases--) {
        cin >> inputString;
        int stringSum = 0;
        for (char c : inputString) {
            stringSum += c - 'a'; // 计算字符串中所有字符对应的和
        }
        // 输出结果，减去 1 是因为我们要排除空字符串的情况（和为 0 的情况已经在 dp 中考虑）
        cout << (dp[inputString.size()][stringSum] % MOD - 1 + MOD) % MOD << endl; // 使用 (x + MOD) % MOD 防止负数
    }

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long

int power(int a, int b,int mod) {
    int ans = 1;
    while (b) {
        if (b & 1) 
            ans = (ans * a) % mod;
        a = (a * a) % mod;
        b >>= 1;
    }
    return ans;
}

int bsgs(int g, int h, int mod) {
    // 处理特殊情况
    h%=mod;
    g%=mod;

    if(g==0){
        if (h == 0) return 1;  
        if (h == 1) return 0; 
        return -1;           
    }

    if (h == 1 ) return 0;
    if (h == 0 ) return -1;  // h=0 无解

    int t = ceil(sqrt(mod));
    map<int, int> mp;
    int base = h; 

    // 小步：存储 h * g^j (j=0 到 t-1)
    for (int j = 0; j < t; j++) {
        mp[base] = j;  // 直接覆盖，保留最大j
        base = (base * g) % mod;
    }

    // 计算大步参数
    int tmp = power(g, t,mod);  // g^t
    int cur = 1;  // 当前大步值 (g^{i*t})

    // 大步：i 从 0 到 t
    for (int i = 0; i <= t; i++) {
        if (mp.find(cur) != mp.end()) {
            int x = i * t - mp[cur];
            // 调整解到[0, mod-2]范围内
            //费马小定理：a^(p−1)≡1(modp)(对于任意 a!≡0)
            //这意味着指数x在模(p−1)意义下具有周期性：
            //y^x≡y^(x%(p−1))(mod p)
            x = (x % (mod-1) + (mod-1)) % (mod-1);
            return x;
        }
        cur = (cur * tmp) % mod;  // 下一个大步
    }
    return -1;
}

