}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 4e6+5;
const int g = 3;
const int P = 998244353;

int n,m,invg,invn;
int A[MAXN],B[MAXN],G[MAXN];
char s[MAXN];

int power(int a,int b){
    int ans=1;
    while(b){
        if(b&1){
            ans=(ans*a)%P;
        }
        b>>=1;
        a=(a*a)%P;
    }
    return ans;
}

int rev[MAXN];
void NTT(int *A,int n,int op){
    for(int i=0;i<n;i++){
        if(i<rev[i]){
            swap(A[i],A[rev[i]]);
        }
    }
    for(int m=2;m<=n;m<<=1){
        int g1=power(op==1?g:invg,(P-1)/m);
        for(int i=0;i<n;i+=m){
            int gk=1;
            for(int j=i;j<i+m/2;j++){
                int x=A[j],y=gk*A[j+m/2]%P;
                A[j]=(x+y)%P;
                A[j+m/2]=(x-y+P)%P;
                gk=gk*g1%P;
            }
        }
    }
}

void change(int x){
    for(int i=0;i<n;i++){
        B[i]=G[i];
    }
    B[0]+=x;
    NTT(A,n,1);
    NTT(B,n,1);
    for(int i=0;i<n;i++){
        A[i]=(A[i]*B[i])%P;
    }
    NTT(A,n,-1);
    for(int i=0;i<n;i++){
        A[i]=A[i]*invn%P;
    }

    int now=0;
    for(int i=0;i<n;i++){
        now=A[i]+now;
        A[i]=now%10;
        now/=10;
    }
}

