    while(n<=len*4){
        n<<=1;
    }
    for(int i=0;i<n;i++){
        rev[i]=(rev[i>>1]>>1)+((i&1)?(n>>1):0);
    }
    invg=power(g,P-2);
    invn=power(n,P-2);

    A[0]=1;
    for(int i=0;i<n;i++){
        A[i]+=G[i];
    }

    change(2);
    change(3);
    change(4);

    int now=0;
    for(int i=0;i<n;i++){
        now=A[i]+now;
        A[i]=now%10;
        now/=10;
    }

    for(int i=n-1;i>=1;i--){
        A[i-1]+=(A[i]%24)*10;
        A[i]/=24;
    }
