const int INF = 1e15;

int n, m, s, t;
int need[MAXN];
int ok[MAXN][MAXN];
int tim[9];
int mincost, maxflow;

int pot[MAXV];  
int dis[MAXV];
int pre[MAXV]; 
bool vis[MAXV];

queue<int> q;
bool in[MAXV];

int head[MAXV];
int nxt[MAXE];
int to[MAXE];
int cap[MAXE];
int cost[MAXE];
int cnt = 2;

struct cmp {
    bool operator()(pair<int,int> a, pair<int,int> b) {
        return a.first > b.first;
    }
};
priority_queue<pair<int,int>, vector<pair<int,int>>, cmp> heap;

