        }
        int k=log2(n);
        int ans=0;
        ans=res2[k];
        if(3*(1<<(k-1))<=n){
            ans=(ans+res3[k])%MOD;
        }

        // cout<<' '<<ans<<' ';
        // cout<<n<<' '<<k<<' '<<all(n,k+1)<<endl;
        ans=ans*all(n,k+1)%MOD;
        cout<<ans<<endl;
    }
    return 0;
}
