                st[i][k]=st[i][k-1];
                pos[i][k]=pos[i][k-1];
            }
            else{
                st[i][k]=st[i+(1<<(k-1))][k-1];
                pos[i][k]=pos[i+(1<<(k-1))][k-1];
            }
        }
    }
}

pair<int,int> query(int l,int r,int i){
    int p=one[r-l+1];
    if(st[l][p]>=st[r-(1<<p)+1][p]){
        return {st[l][p]-sum[i-1],pos[l][p]};
    }
    else{
        return {st[r-(1<<p)+1][p]-sum[i-1],pos[r-(1<<p)+1][p]};
    }
}

