		n -- , m -- ;
		for (int i = 0; i <= m; i ++ ) {
			int n0 = n - i, m0 = m - i;
			(ans += (c(n0 + m0, m0) - c(n0 + m0, m0 - 1) + MOD) % MOD * c(n0 + m0 + i, i) % MOD) %= MOD;
		}
