#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;

int n,q;
int val[MAXN];

int head=0;
int cnt=0;
int key[MAXN];
int ls[MAXN];
int rs[MAXN];
int sz[MAXN];
double priority[MAXN];
int tag[MAXN];

int newnode(int val){
    ++cnt;
    key[cnt]=val;
    priority[cnt]=(double)rand()/RAND_MAX;
    sz[cnt]=1;
    return cnt;
}

void lazy(int i,int v){
    if(i){
        key[i]+=v;
        tag[i]+=v;
    }
}

void down(int i){
    if(i && tag[i]){
        lazy(ls[i],tag[i]);
        lazy(rs[i],tag[i]);
        tag[i]=0;
    }
}

void up(int i){
    if(i){
        sz[i]=sz[ls[i]]+sz[rs[i]]+1;
    }
}

void split(int l, int r, int i, int rank) {
    if (i == 0) {
        rs[l] = ls[r] = 0;
    } else {
        down(i);
        if (sz[ls[i]] + 1 <= rank) {
            rs[l] = i;
            split(i, r, rs[i], rank - sz[ls[i]] - 1);
        } else {
            ls[r] = i;
            split(l, i, ls[i], rank);
        }
        up(i);
    }
}

int merge(int l, int r) {
    if (l == 0 || r == 0) {
        return l + r;
    }
    down(l);
    down(r);
    if (priority[l] >= priority[r]) {
        rs[l] = merge(rs[l], r);
        up(l);
        return l;
    } else {
        ls[r] = merge(l, ls[r]);
        up(r);
        return r;
    }
}

int getrank(int val, int head){
    int ans=0;
    int u=head;
    while(u){
        down(u);
        if(key[u]<val){
            ans+=sz[ls[u]]+1;
            u=rs[u];
        }
        else{
            u=ls[u];
        }
    }
    return ans;
}

int get_kth_value(int tree, int k) {
    int u = tree;
    while (u) {
        down(u);
        if (sz[ls[u]] + 1 == k) {
            return key[u];
        } else if (sz[ls[u]] + 1 < k) {
            k -= sz[ls[u]] + 1;
            u = rs[u];
        } else {
            u = ls[u];
        }
    }
    return 0;
}

