int compute(int i,int j,int s){
    if(i==n){
        return 0;
    }
    if(j==m){
        return compute(i+1,0,s);
    }
    if(f[i][j][s]!=-1){
        return f[i][j][s];
    }
    int ans=0;
    if(get(s,j)==1){
