inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    in[v]++;
    head[u]=cnt++;
}

int build(int l,int r){
    if(l==r){
        return l;
    }
    else{
        int now=++nodecnt;
        int mid=(l+r)>>1;
        ls[now]=build(l,mid);
        rs[now]=build(mid+1,r);
        addedge(now,ls[now],0);
        addedge(now,rs[now],0);
        return now;
    }
}

bool cmp(point a,point b){
    return a.val<b.val;
}

int merge(int a,int b){
    if(a==0||b==0){
        return a+b;
    }
    int now=++nodecnt;
    addedge(now,a,0);
    addedge(now,b,0);
    return now;
}

int query(int jobl,int jobr,int jobv,int l,int r,int i){
    if(jobl>jobr){
        return jobv;
    }
    if(jobl<=l&&r<=jobr){
        return merge(jobv,i);
    }
    else{
        int mid=(l+r)>>1;
        if(jobl<=mid&&jobr>mid){
            return merge(query(jobl,jobr,jobv,l,mid,ls[i]),query(jobl,jobr,jobv,mid+1,r,rs[i]));
        }
        else if(jobl<=mid){
            return query(jobl,jobr,jobv,l,mid,ls[i]);
        }
        else{
            return query(jobl,jobr,jobv,mid+1,r,rs[i]);
        }
    }
}

int main()
{
    n=read(),s=read(),m=read();
    nodecnt=n;
    root=build(1,n);
    for(int i=1;i<=s;i++){
        nums[i].pos=read(),nums[i].val=read();
        val[nums[i].pos]=nums[i].val;
        ok[nums[i].pos]=true;
    }
    sort(nums+1,nums+s+1,cmp);
    int st=0;
    int now=0;
    for(int i=2;i<=s;i++){
        while(st+1<i&&nums[st+1].val<nums[i].val){
            st++;
            now=merge(now,nums[st].pos);
        }
        if(now){
            addedge(nums[i].pos,now,1);
        }
    }
    while(m--){
        int now=0;
        int l,r,k;
        l=read(),r=read(),k=read();
        for(int i=1;i<=k;i++){
            tmp[i]=read();
        }
        int lt=l;
        for(int i=1;i<=k;i++){
            now=query(lt,tmp[i]-1,now,1,n,root);
            lt=tmp[i]+1;
        }
        if(lt<=r){
            now=query(lt,r,now,1,n,root);
        }
        for(int i=1;i<=k;i++){
            addedge(tmp[i],now,1);
        }
    }

    bool flag=false;
    queue<int>q;
    for(int i=1;i<=nodecnt;i++){
        if(!ok[i]){
            val[i]=INF;
        }
        if(in[i]==0){
            q.push(i);
        }
    }
    while(!q.empty()){
        int u=q.front();
        q.pop();
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            in[v]--;
            int w=val[u]-weight[i];
            if(ok[v]){
                if(val[v]>w){
                    flag=true;
                    break;
                }
            }
            else{
                val[v]=min(val[v],w);
            }
            if(in[v]==0){
                q.push(v);
            }
        }
        if(flag){
            break;
        }
    }
    for(int i=1;i<=nodecnt;i++){
        if(in[i]){
            flag=true;
            break;
        }
        if(val[i]<=0){
            flag=true;
            break;
        }
    }
    if(flag){
        printf("NIE\n");
    }
    else{
        printf("TAK\n");
        for(int i=1;i<=n;i++){
            printf("%d ",val[i]);
        }
    }
    return 0;
}

