{
	cin>>n>>m;
	for(int i=1;i<=n;i++)cin>>c[i],b[i]=m;
    //把箱子剩余容量初始化为m
    dfs(1,0);
	cout<<ans;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MOD = 1e9+7;
const int MAXN = 2e7+5;

int fac[MAXN];
int inv[MAXN];

int power(int a,int b){
    int ans=1;
    while(b){
        if(b&1){
            ans=(a*ans)%MOD;
        }
        b>>=1;
        a=(a*a)%MOD;
    }
    return ans;
}

void prepare(int n){
    inv[0]=1;
    fac[0]=1;
    for(int i=1;i<=n;i++){
        fac[i]=(fac[i-1]*i)%MOD;
    }
    inv[n]=power(fac[n],MOD-2);
    for(int i=n-1;i>=1;i--){
        inv[i]=(inv[i+1]*(i+1))%MOD;
    }
}

int comb(int a,int b){
    return fac[a]*inv[b]%MOD*inv[a-b]%MOD;
}

signed main()
{
    prepare(20000000);
    int T;
    cin>>T;
    while(T--){
        int n,k;
        cin>>n>>k;
        int ans;
        if(k%2){
            ans=(comb(n+(k+1)/2-1,(k+1)/2-1)+comb(n+k-(k+1)/2-1,n))%MOD;
        }
        else{
            ans=(comb(n+k/2-1,k/2-1)+comb(n+k/2-1,n))%MOD;
        }
        cout<<ans<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 1e6+5;

struct node{
    int l,r,all,sum;
}tree[MAXN<<2];
int n,m;
int arr[MAXN];
int val[MAXN];
int pre[MAXN];
int last[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

node up(node l,node r){
    node u;
    u.all=max(max(l.all,r.all),l.r+r.l);
    u.sum=l.sum+r.sum;
    u.l=max(l.l,l.sum+r.l);
    u.r=max(r.r,r.sum+l.r);
    return u;
}

void build(int l,int r,int i){
    if(l==r){
        tree[i].l=tree[i].r=tree[i].all=tree[i].sum=0;
    }
    else{
        int mid=(l+r)/2;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        tree[i]=up(tree[i<<1],tree[i<<1|1]);
    }
}

void update(int pos,int jobv,int l,int r,int i){
    if(l==r){
        tree[i].l=tree[i].r=tree[i].all=tree[i].sum=jobv;
    }
    else{
        int mid=(l+r)/2;
        if(pos<=mid){
            update(pos,jobv,l,mid,i<<1);
        }
        else{
            update(pos,jobv,mid+1,r,i<<1|1);
        }
        tree[i]=up(tree[i<<1],tree[i<<1|1]);
    }
}

node query(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        return tree[i];
    }
    else{
        int mid=(l+r)/2;
        if(jobl<=mid&&jobr>mid){
            return up(query(jobl,jobr,l,mid,i<<1),query(jobl,jobr,mid+1,r,i<<1|1));
        }
        else if(jobl<=mid){
            return query(jobl,jobr,l,mid,i<<1);
        }
        else{
            return query(jobl,jobr,mid+1,r,i<<1|1);
        }
    }
}

