int query(int limit){
    int kind=0,cnt=0,st=1;
    for(int i=1;i<=n;i++){
        if(!vis[nums[i]]){
            kind++;
            if(kind>limit){
                cnt++;
                for(int j=st;j<i;j++){
                    vis[nums[j]]=false;
                }
                st=i;
                kind=1;
            }
            vis[nums[i]]=true;
        }
    }
    if(kind>0){
        cnt++;
        for(int i=st;i<=n;i++){
            vis[nums[i]]=false;
        }
    }
    return cnt;
}

int jump(int l,int r,int len){
    int ans=l;
    while(l<=r){
        int mid=(l+r)>>1;
        int check=query(mid);
        if(check==len){
            ans=mid;
            l=mid+1;
        }
        else{
            r=mid-1;
        }
    }
    return ans+1;
}

