bool check(int i,int q,int *p){
    int nxt=q+1;
    int st=i-q;

    int lt=low[nxt];
    if(lt!=0&&p[st+lt-1]>=p[i]){
        return false;
    }
    int rt=high[nxt];
    if(rt!=0&&p[st+rt-1]<=p[i]){
        return false;
    }
    return true;
}

