            int v=x%(s+1);
            if(v==s){
                return 2;
            }
            return v&1;
        }
    }
    if(k==3){
        return x/s;
    }
    if(k==4){
        if(x%4==0){
            return x-1;
        }
        if(x%4==3){
            return x+1;
        }
    }
    return x;
}

void init(){
    for(int i=1;i<=n;i++){
        head[i]=0;
        vis[i]=false;
    }
    cntg=1;
}

void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

void getsize(int u,int fa){
    sz[u]=1;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa&&!vis[v]){
            getsize(v,u);
            sz[u]+=sz[v];
        }
    }
}

int getcentroid(int u,int fa){
    getsize(u,fa);
    int half=sz[u]>>1;
    bool flag=false;
    while(!flag){
        flag=true;
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            if(v!=fa&&!vis[v]&&sz[v]>half){
                flag=true;
                fa=u;
                u=v;
                break;
            }
        }
    }
    return u;
}

bool ans;

unordered_set<int>seen;
vector<int>cur;

void dfs(int u,int fa,int va){
    cur.push_back(va^val[u]);
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa&&!vis[v]){
            dfs(v,u,va^val[u]);
        }
    }
}

void calc(int u){
    seen.clear();
    if(val[u]==0){
        ans=true;
        return ;
    }
    seen.insert(val[u]);

    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(!vis[v]){
            cur.clear();
            dfs(v,u,0);
            for(int i=0;i<(int)cur.size();i++){
                int v=cur[i];
                if(seen.find(v)!=seen.end()){
                    ans=true;
                    break;
                }
            }
            for(int i=0;i<(int)cur.size();i++){
                int v=cur[i];
                seen.insert(v^val[u]);
            }
        }
    }
}

void solve(int u){
    vis[u]=true;
    calc(u);
    if(ans){
        return ;
    }

    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=u&&!vis[v]){
            solve(getcentroid(v,u));
            if(ans){
                break;
            }
        }
    }
}

