inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

inline int lowbit(int x){
    return x&(-x);
}

inline void update(int u,int v){
    while(u<=n){
        tree[u]^=v;
        u+=lowbit(u);
    }
}

inline int query(int x){
    int ans=0;
    while(x){
        ans^=tree[x];
        x-=lowbit(x);
    }
    return ans;
}

void dfs1(int u,int fa){
    dep[u]=dep[fa]+1;
    st[u][0]=fa;
    sz[u]=1;
    for(int i=1;i<LIMIT;i++){
        st[u][i]=st[st[u][i-1]][i-1];
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v==fa){
            continue;
        }
        dfs1(v,u);
        if(son[u]==0||sz[son[u]]<sz[v]){
            son[u]=v;
        }
        sz[u]+=sz[v];
    }
}

void dfs2(int u,int t){
    dfn[u]=++dfncnt;
    top[u]=t;
    if(son[u]){
        dfs2(son[u],t);
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v==st[u][0]||v==son[u]){
            continue;
        }
        dfs2(v,v);
    }
}

int lca(int a,int b){
    if(dep[a]<dep[b]){
        swap(a,b);
    }
    for(int i=LIMIT-1;i>=0;i--){
        if(dep[st[a][i]]>=dep[b]){
            a=st[a][i];
        }
    }
    if(a==b){
        return a;
    }
    for(int i=LIMIT-1;i>=0;i--){
        if(st[a][i]!=st[b][i]){
            a=st[a][i];
            b=st[b][i];
        }
    }
    return st[a][0];
}

void pathupdate(int x,int y,int val){
    while(top[x]!=top[y]){
        if(dep[top[x]]<=dep[top[y]]){
            swap(x,y);
        }
        update(dfn[top[x]],val);
        update(dfn[x]+1,val);
        x=st[top[x]][0];
    }
    if(dep[x]<=dep[y]){
        swap(x,y);
    }
    update(dfn[y],val);
    update(dfn[x]+1,val);
}

