int f[15][MAXN][2];

unordered_map<int,int>mp;
bool vis[15][MAXN];
int cnt;
int val[MAXN];
int t[MAXN];

struct cmp{
    bool operator()(const pair<int,int>a,const pair<int,int>b){
        return (1.0*t[a.first]/t[b.second])<(1.0*t[b.first]/t[a.second]);
    }
};
priority_queue<pair<int,int>,vector<pair<int,int>>,cmp>heap;

bool compare(int a,int b){
    return a>b;
}

void init(int x,int now,bool free){
    if(x==0){
        if(!mp.count(now)){
            ++cnt;
            mp[now]=cnt;
            val[cnt]=now;
        }
        return ;
    }
    if(!mp.count(now)){
        ++cnt;
        mp[now]=cnt;
        val[cnt]=now;
    }
    if(vis[x][mp[now]]){
        return ;
    }
    vis[x][mp[now]]=true;
    int up=free?9:nums[x];
    for(int i=1;i<=up;i++){
        init(x-1,now*i,free||i<nums[x]);
    }
}

int dfs(int x,int now,bool free){
    if(x==0){
        return val[now]==1;
    }
    if(f[x][now][free]!=-1){
        return f[x][now][free];
    }
    int up=free?9:nums[x];
    int ans=0;
    for(int i=1;i<=up;i++){
        if(val[now]%i==0){
            int t=val[now]/i;
            if(mp.count(t)){
                ans+=dfs(x-1,mp[t],free||i<nums[x]);
            }
        }
    }
    f[x][now][free]=ans;
    return ans;
}

