        init(i-1,1,i<len+1);
    }

    // cout<<cnt<<endl;
    // for(int i=1;i<=cnt;i++){
    //     cout<<val[i]<<' ';
    // }
    // cout<<endl;

    memset(f,-1,sizeof(f));
    for(int i=1;i<=cnt;i++){
        for(int j=2;j<=len+1;j++){
            t[i]+=dfs(j-1,i,j<len+1);
        }
        // cout<<i<<":  "<<t[i]<<endl;
    }
    sort(t+1,t+cnt+1,compare);
    for(int i=1;i<=cnt;i++){
        nxt[i]=1;
    }
    for(int i=1;i<=cnt;i++){
        heap.push({i,1});
    }
    int ans=0;
    while(k--&&!heap.empty()){
        pair<int,int>u=heap.top();
        // cout<<u.first<<' '<<u.second<<endl;
        heap.pop();
        ans=(ans+(t[u.first]%MOD)*(t[u.second]%MOD)%MOD)%MOD;
        if(nxt[u.first]<cnt){
            u.second=++nxt[u.first];
            heap.push(u);
        }
    }
    cout<<ans<<endl;
    return 0;
}

