    sz[x]=sz[l]+sz[r]+1;
    cnt[x]=cnt[l]+cnt[r]+1;

    lcol[x]=l?lcol[l]:col[x];
    rcol[x]=r?rcol[r]:col[x];

    if(l&&rcol[l]==col[x]){
        cnt[x]--;
    }

    if(r&&lcol[r]==col[x]){
        cnt[x]--;
    }
}

inline bool isroot(int x){
    return ls[fa[x]]!=x&&rs[fa[x]]!=x;
}

inline int lr(int x){
    return rs[fa[x]]==x;
}

inline void updatecolor(int x,int v){
    if(!x){
        return;
    }

    col[x]=v;
    lcol[x]=v;
    rcol[x]=v;

    cnt[x]=1;
    lazy[x]=v;
}

inline void reversex(int x){
    if(!x){
        return;
    }

    swap(ls[x],rs[x]);
    swap(lcol[x],rcol[x]);

    rev[x]^=1;
}

inline void down(int x){
    if(lazy[x]){
        updatecolor(ls[x],lazy[x]);
        updatecolor(rs[x],lazy[x]);

        lazy[x]=0;
    }

    if(rev[x]){
        reversex(ls[x]);
        reversex(rs[x]);

        rev[x]=false;
    }
}

inline void rotate(int x){
    int f=fa[x];
    int g=fa[f];
    int k=lr(x);
    int w=k?ls[x]:rs[x];

    if(!isroot(f)){
        if(rs[g]==f){
            rs[g]=x;
        }
        else{
            ls[g]=x;
        }
    }

    fa[x]=g;

    if(k){
        ls[x]=f;
        rs[f]=w;
    }
    else{
        rs[x]=f;
        ls[f]=w;
    }

    if(w){
        fa[w]=f;
    }

    fa[f]=x;

    up(f);
    up(x);
}

inline void splay(int x){
    int top=0;

    sta[++top]=x;

    for(int y=x;!isroot(y);y=fa[y]){
        sta[++top]=fa[y];
    }

    while(top){
        down(sta[top--]);
    }

    while(!isroot(x)){
        int f=fa[x];

        if(!isroot(f)){
            if(lr(x)==lr(f)){
                rotate(f);
            }
            else{
                rotate(x);
            }
        }

        rotate(x);
    }
}

inline void access(int x){
    for(int y=0;x;y=x,x=fa[x]){
        splay(x);
        rs[x]=y;
        up(x);
    }
}

inline void makeroot(int x){
    access(x);
    splay(x);
    reversex(x);
}

inline void split(int x,int y){
    makeroot(x);
    access(y);
    splay(y);
}

inline void pathupdate(int x,int y){
    split(x,y);
    updatecolor(y,++colcnt);
}

inline int pathquery(int x,int y){
    split(x,y);
    return sz[y]-cnt[y];
}

