            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

bool cmp(node a,node b){
    return ((a.val-a.sub)==(b.val-b.sub))?(a.sub<b.sub):((a.val-a.sub)>(b.val-b.sub));
}

int lowbit(int x){
    return x&(-x);
}

int query(int x){
    int ans=0;
    while(x){
        ans=max(tree[x],ans);
        x-=lowbit(x);
    }
    return ans;
}

void update(int x,int val){
    while(x<=n){
        tree[x]=max(tree[x],val);
        x+=lowbit(x);
    }
}

