#include<bits/stdc++.h>
using namespace std;
const int MAXN = 5e5+5;
const int MAXM = 3e6+5;

int n;
char s[MAXN];

int cnt;
int tree[MAXM][26];
int en[MAXM];

int dp[MAXM];// dp[u] 表示以节点 u 为根的子树的最大值
//实际上 如果这个节点en[u]==0 那么dp实际上即使0
int ans;

//反向建立前缀树
void insert(char *s){
    int u=0;
    int len=strlen(s+1);
    for(int i=len;i>=1;i--){
        //反向插入
        int path=s[i]-'a';
        if(!tree[u][path]){
            tree[u][path]=++cnt;
        }
        u=tree[u][path];
    }
    en[u]++;
}

//dp[u]实际上表示的是u如果作为一个接口  最大可以是多少
//首先他应该是有最长的一个儿子maxx1  然后加上所有有效儿子节点个数-1（这里的减一是maxx1占据1个儿子）
//然后加上1 表示这个位置自己也要算
//为什么不加上maxx2  因为加上之后u就是中间位置 不能成为接口了
//但是加上所有有效儿子  不影响其继续作为接口
void dfs(int u){
    int sz=0;
    int maxx1=0,maxx2=0;
    for(int i=0;i<26;i++){
        int v=tree[u][i];
        if(v){
            dfs(v);
        }
        sz+=en[v];
        if(maxx1<dp[v]){
            maxx2=maxx1;
            maxx1=dp[v];
        }
        else if(maxx2<dp[v]){
            maxx2=dp[v];
        }
    }
    if(en[u]){
        dp[u]=maxx1+max(sz,1);//最好改成dp[u]=maxx1+1+max(sz-1,0);
    }
    ans=max(ans,maxx1+maxx2+en[u]+max(sz-2,0));
}

int main()
{
    cin>>n;
    for(int i=1;i<=n;i++){
        scanf("%s",s+1);
        insert(s);
    }
    dfs(0);
    cout<<ans<<endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

struct Node {
    ll val, l, r;
};

const int MAXN = 500010;

ll a[MAXN], l[MAXN], r[MAXN];
Node g[MAXN], o[MAXN];
ll cnt_g, cnt_o;

ll gcd(ll a, ll b) {
    return b ? gcd(b, a % b) : a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, k, ans = 0;
    cin >> n >> k;
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
    }

    for (int i = 1; i <= n; ++i) {
        // 更新 gcd 列表
        for (int j = 1; j <= cnt_g; ++j) {
            g[j].val = gcd(g[j].val, a[i]);
        }
        cnt_g++;
        g[cnt_g] = {a[i], i, i};

        // 去重 gcd 列表
        int len = 0;
        for (int j = 1; j <= cnt_g; ++j) {
            if (g[j].val == g[j - 1].val) {
                g[len].r = g[j].r;
            } else {
                len++;
                g[len] = g[j];
            }
        }
        cnt_g = len;

        // 记录每个 gcd 值对应的左右边界
        for (int j = 1; j <= cnt_g; ++j) {
            l[g[j].val] = g[j].l;
            r[g[j].val] = g[j].r;
        }

        // 更新按位或列表
        for (int j = 1; j <= cnt_o; ++j) {
            o[j].val |= a[i];
        }
        cnt_o++;
        o[cnt_o] = {a[i], i, i};

        // 去重按位或列表
        len = 0;
        for (int j = 1; j <= cnt_o; ++j) {
            if (o[j].val == o[j - 1].val) {
                o[len].r = o[j].r;
            } else {
                len++;
                o[len] = o[j];
            }
        }
        cnt_o = len;

        // 统计满足条件的子数组
        for (int j = 1; j <= cnt_o; ++j) {
            ll target = o[j].val ^ k;
            if (l[target] != 0 && min(o[j].r, r[target]) >= max(o[j].l, l[target])) {
                ans += min(o[j].r, r[target]) - max(o[j].l, l[target]) + 1;
            }
        }

        // 清空 gcd 值的左右边界记录
        for (int j = 1; j <= cnt_g; ++j) {
            l[g[j].val] = r[g[j].val] = 0;
        }
    }

    cout << ans << endl;
    return 0;
}

