//对数组进行更新操作，并求最大值
#include<bits/stdc++.h>
using namespace std;
const int MAXN = 100001;

long arr[MAXN];
long sum[MAXN << 2];
long change[MAXN << 2];
long Max[MAXN<<2];
bool update[MAXN << 2];
int n,m;

//比较左右两边最大值
void up(int i) {
    Max[i] = max(Max[i << 1] ,Max[i << 1 | 1]);
}

// 当前的区间对应的信息下标是i
// 现在收到一个懒更新任务 : 这个区间范围上每个数字变为v
// 这个懒更新任务有可能是任务范围把当前线段树范围全覆盖导致的
// 也有可能是父范围的懒信息下发下来的
// 总之把线段树当前范围的Max数组和change   update数组调整好
// 就不再继续往下下发了，懒住了
void lazy(int i, long v) {
    Max[i] = v;
    change[i] = v;
    update[i] = true;//这个数组表示是否有信息可以向下传递
}

// 懒信息的下发
void down(int i) {
    if (update[i]) {
        lazy(i << 1, change[i]);
        lazy(i << 1 | 1, change[i]);
        update[i] = false;
    }
}

void build(int l, int r, int i) {
    if (l == r) {
        Max[i] = arr[l];
    } else {
        int mid = (l + r) >> 1;
        build(l, mid, i << 1);
        build(mid + 1, r, i << 1 | 1);
        up(i);
    }
    change[i] = 0;
    update[i] = false;//初始化每一个位置都没有向下传递的信息
}

// 范围修改
// jobl ~ jobr范围上每个数字变为jobv
void Update(int jobl, int jobr, long jobv, int l, int r, int i) {
    if (jobl <= l && r <= jobr) {
        if(jobv>Max[i])
            lazy(i, jobv);
    } else {
        int mid = (l + r) >> 1;
        down(i);
        if (jobl <= mid) {
            Update(jobl, jobr, jobv, l, mid, i << 1);
        }
        if (jobr > mid) {
            Update(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);
        }
        up(i);
    }
}

long query(int jobl, int jobr, int l, int r, int i) {
    if (jobl <= l && r <= jobr) {
        return Max[i];
    }
    int mid = (l + r) >> 1;
    down(i);
    long ans = 0;
    if (jobl <= mid) {
        ans =max(ans, query(jobl, jobr, l, mid, i << 1));
    }
    if (jobr > mid) {
        ans =max(ans, query(jobl, jobr, mid + 1, r, i << 1 | 1));
    }
    return ans;
}

int main()
{
    cin>>n>>m;
    for(int i=1;i<=n;i++)
        cin>>arr[i];
    build(1,n,1);
    long jobv;
    char op;
    for (int i = 1, jobl, jobr; i <= m; i++) {
        cin>>op;
        if (op == 'U') {
            cin>>jobl;
            jobr=jobl;
            cin>>jobv;
            Update(jobl, jobr, jobv, 1, n, 1);
        } else {
            cin>>jobl;
            cin>>jobr;
            cout<<query(jobl, jobr, 1, n, 1)<<endl;
        }
    }
    return 0;
}

#include<iostream>
#include<cstdio>
#include<cstring>
#include<cmath>
#include<set>
#include<algorithm>
#include<vector>
using namespace std;
const int N=3e5+10;
const int M=3e6+10;
int n,m,fa[M],siz[M],seq[N],maxn,cnt[N];
struct node{
	int x,y;
}p[M];
vector<int> ple[N];
set<int> q;
multiset<int> res;
inline bool cmp(node a,node b){
	if(a.x==b.x){
		return a.y<b.y;
	}
	return a.x<b.x;
}
inline int find(int x){
	//查找root
	if(fa[x]==x){
		return x;
	}
	return fa[x]=find(fa[x]);
}
inline void hb(int fx,int fy){
	//启发式合并
	if(siz[fx]<siz[fy]){
		swap(fx,fy);
	}
	siz[fx]+=siz[fy];
	fa[fy]=fx;
}
inline void build(int x,int l,int r){
	//建树
	maxn=max(maxn,x);
	if(l==r){
		seq[l]=x;
		return;
	}
	int mid=(l+r)>>1;
	build(x<<1,l,mid);
	build(x<<1|1,mid+1,r);
}
inline void ycl(){
	//预处理
	build(1,1,n);
	for(int i=1;i<=maxn;i++){
		fa[i]=i;
		siz[i]=1;
	}
}
inline void unify(int x,int l,int r,int ql,int qr,int k){
	//普通线段树修改式遍历
	if(ql<=l&&r<=qr){
		int fy=find(x),fx=find(seq[k]);
		//不同才合并，节省时间
		if(fx!=fy){
			hb(fx,fy);
		}
		return;
	}
	int mid=(l+r)>>1;
	if(ql<=mid){
		unify(x<<1,l,mid,ql,qr,k);
	}
	if(qr>mid){
		unify(x<<1|1,mid+1,r,ql,qr,k);
	}
}
