		scanf("%d%d",&p[i].x,&p[i].y);
		if(p[i].x>p[i].y){
			swap(p[i].x,p[i].y);
			//保证第一关键字比第二关键字小
		}
	}
	//排序
	sort(p+1,p+m+1,cmp);
	for(int i=1;i<=m;i++){
		ple[p[i].x].push_back(p[i].y);
	}
	int l=0,r=0;
	for(int i=1;i<=n;i++){
		int len=ple[i].size();
		l=0;
		if(!len){
			if(i+1<=n){
				unify(1,1,n,i+1,n,i);
			}
			continue;
		}
		for(int j=0;j<len;j++){
			if(j!=0){
				l=ple[i][j-1]+1;
			}
			r=ple[i][j]-1;
			if(r<=i||l>r){
				//不能和比自己小的区间合并，因为第一关键字比第二关键字小，无法确定关系
				continue;
			}
			if(l<=i){
				//同上
				l=i+1;
			}
			unify(1,1,n,l,r,i);
		}
		if(ple[i][len-1]+1<=n){
			//小学奥数的植树问题的原理
			unify(1,1,n,ple[i][len-1]+1,n,i);
		}
	}
