                int v = to[i];
                if (cap[i] > 0 && dist[v] > dist[u] + cost[i]) {
                    dist[v] = dist[u] + cost[i];
                    pre[v] = u;
                    preEdge[v] = i;

                    if (!inQueue[v]) {
                        inQueue[v] = true;
                        q.push(v);
                    }
                }
            }
        }

