        int flow = INF;
        for (int u = t; u != s; u = pre[u]) {
            int edgeIdx = preEdge[u];
            flow = min(flow, cap[edgeIdx]);
        }

        // 更新流量和费用
        totalFlow += flow;
        totalCost += flow * dist[t];

        // 更新残余网络
        for (int u = t; u != s; u = pre[u]) {
            int edgeIdx = preEdge[u];
            cap[edgeIdx] -= flow;
            cap[edgeIdx ^ 1] += flow; // 反向边
        }
    }

    return -totalCost; // 返回最大费用
}

int main() {
    cin >> n >> K;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            cin >> grid[i][j];
        }
    }

    if (K == 0) {
        cout << 0 << endl;
        return 0;
    }

    s = 2 * n * n + 1;
    t=s+1;

    addEdge(s, 1, K, 0);

    addEdge(2 * n * n, t, K, 0);

    // 这里值是负数  意思是求的是最大费用最大流
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            int inNode = (i - 1) * n + j;
            int outNode = n * n + (i - 1) * n + j;

            // 入点到出点：取数的边（容量1，费用为负的格子值）
            addEdge(inNode, outNode, 1, -grid[i][j]);

            // 入点到出点：经过但不取数的边（容量K-1，费用0）
            if (K > 1) {
                addEdge(inNode, outNode, K - 1, 0);
            }

            // 出点到右边格子的入点
            if (j < n) {
                int rightIn = (i - 1) * n + j + 1;
                addEdge(outNode, rightIn, K, 0);
            }

            // 出点到下边格子的入点
            if (i < n) {
                int downIn = i * n + j;
                addEdge(outNode, downIn, K, 0);
            }
        }
    }

    int result = minCostMaxFlow();
    cout << result << endl;

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;

int n,m;
int force[MAXN];

int fa[MAXN];
int ls[MAXN];
int rs[MAXN];
int sta[MAXN];
bool rev[MAXN];

int sz[MAXN];

void up(int x) {
   sz[x] = sz[ls[x]] + sz[rs[x]] + 1;
}

bool isroot(int x) {
   return ls[fa[x]] != x && rs[fa[x]] != x;
}

int lr(int x) {
   return ls[fa[x]] == x ? 0 : 1;
}

void reverse(int x) {
   if (x != 0) {
       swap(ls[x], rs[x]);
       rev[x] = !rev[x];
   }
}

void down(int x) {
   if (rev[x]) {
       reverse(ls[x]);
       reverse(rs[x]);
       rev[x] = false;
   }
}

void rotate(int x) {
   int f = fa[x], g = fa[f];
   if (lr(x) == 0) {
       ls[f] = rs[x];
       if (ls[f] != 0) {
           fa[ls[f]] = f;
       }
       rs[x] = f;
   } else {
       rs[f] = ls[x];
       if (rs[f] != 0) {
           fa[rs[f]] = f;
       }
       ls[x] = f;
   }
   if (!isroot(f)) {
       if (lr(f) == 0) {
           ls[g] = x;
       } else {
           rs[g] = x;
       }
   }
   fa[f] = x;
   fa[x] = g;
   up(f);
   up(x);
}

void splay(int x) {
   int size = 0;
   sta[++size] = x;
   for (int y = x; !isroot(y); y = fa[y]) {
       sta[++size] = fa[y];
   }
   while (size != 0) {
       down(sta[size--]);
   }
   while (!isroot(x)) {
       int f = fa[x];
       if (!isroot(f)) {
           if (lr(x) == lr(f)) {
               rotate(f);
           } else {
               rotate(x);
           }
       }
       rotate(x);
   }
}

void access(int x){
    for(int y=0;x!=0;y=x,x=fa[x]){
        splay(x);
        rs[x]=y;
        up(x);
    }
}

void makeroot(int x){
    access(x);
    splay(x);
    reverse(x);
}

int findroot(int x){
    access(x);
    splay(x);
    down(x);
    while(ls[x]!=0){
        x=ls[x];
        down(x);
    }
    splay(x);
    return x;
}

void split(int x,int y){
    makeroot(x);
    access(y);
    splay(y);
}

void link(int x,int y){
    makeroot(x);
    if(findroot(y)!=x){
        fa[x]=y;
    }
}

void cut(int x,int y){
    makeroot(x);
    if(findroot(y)==x&&fa[y]==x&&ls[y]==0&&rs[x]==y){
        fa[y]=rs[x]=0;
        up(x);
    }
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n;
    for(int i=1;i<=n+1;i++){
        sz[i]=1;
    }
    for(int i=1;i<=n;i++){
        cin>>force[i];
        link(i,min(i+force[i],n+1));
    }
    cin>>m;
    for(int i=1;i<=m;i++){
        int op,x,y;
        cin>>op>>x;
        x++;
        if(op==1){
            split(x,n+1);
            cout<<sz[n+1]-1<<endl;
        }
        else{
            cin>>y;
            cut(x,min(n+1,x+force[x]));
            force[x]=y;
            link(x,min(n+1,x+force[x]));
        }
    }
    return 0;
}

