#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1005;
const int MAXM = 25;
const int MAXT = 2005;
const int MAXE = 6e4+5;
const int INF = 1e9;

int n,m,s,t;
int val[MAXN][MAXM];
int capacity[MAXM];

int dep[MAXT];
int iter[MAXT];

int cnt=2;
int head[MAXT];
int nxt[MAXE];
int to[MAXE];
int now[MAXE];
int cap[MAXE];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    cap[cnt]=w;
    now[cnt]=0;
    head[u]=cnt++;

    nxt[cnt]=head[v];
    to[cnt]=u;
    cap[cnt]=0;
    now[cnt]=0;
    head[v]=cnt++;
}

bool bfs(){
    for(int i=1;i<=n+m+2;i++){
        dep[i]=-1;
    }
    queue<int>q;
    dep[s]=0;
    q.push(s);
    while(!q.empty()){
        int u=q.front();
        q.pop();
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            int w=cap[i];
            int k=now[i];
            if(dep[v]<0&&(k<w)){
                dep[v]=dep[u]+1;
                q.push(v);
            }
        }
    }
    return dep[t]>=0;// 如果汇点未被访问到，说明无增广路径
}

int dfs(int u,int f){
    if(u==t){
        return f;
    }
    int flow=0;
    for(int &i=iter[u];i;i=nxt[i]){
        int v=to[i];
        int w=cap[i];
        int k=now[i];
        if(dep[u]+1==dep[v]&&k<w){
            int d=dfs(v,min(f,w-k));
            if(d>0){
                now[i]+=d;
                now[i^1]-=d;//更新反向边
                flow+=d;
                f-=d;
                if(f==0){
                    break;
                }
            }
        }
    }
    return flow;
}

int maxflow(){
    int flow=0;
    while(bfs()){
        for(int i=1;i<=n+m+2;i++){
            iter[i]=head[i];
        }
        int maxflow;
        while((maxflow=dfs(s,INF))>0){
            flow+=maxflow;
        }
    }
    return flow;
}

bool check(int len){
    for(int l=1;l+len-1<=m;l++){
        int r=l+len-1;

        for(int i=1;i<=t;i++){
            head[i]=0;
        }
        cnt=2;

        for(int i=1;i<=n;i++){
            addedge(s,i,1);
        }
        for(int i=1;i<=n;i++){
            for(int j=l;j<=r;j++){
                addedge(i,n+val[i][j],1);
            }
        }
        for(int i=1;i<=m;i++){
            addedge(n+i,t,capacity[i]);
        }
        if(maxflow()==n){
            return true;
        }
    }
    return false;
}

int main()
{
    n=read(),m=read();
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            val[i][j]=read();
        }
    }
    for(int i=1;i<=m;i++){
        capacity[i]=read();
    }
    s=n+m+1,t=n+m+2;
    int l=1,r=m,ans=0;
    while(l<=r){
        int mid=(l+r)>>1;
        if(check(mid)){
            ans=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    cout<<ans<<endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int MAX_SIZE = 1005;
const int MAX_NM = (MAX_SIZE + 2) * (MAX_SIZE + 2);
const ll MOD = 1e9 + 7;

// 全局数组定义
int n, m;
ll ans = 1;
int fa[MAX_NM];
ll dp[MAX_NM];
bool grid[MAX_SIZE][MAX_SIZE];
bool visited[MAX_NM];

inline int index(int i, int j) {
    return (i - 1) * m + j;
}

int find(int x) {
    return fa[x] == x ? x : fa[x] = find(fa[x]);
}

void un(int x, int y) {
    int fx = find(x), fy = find(y);
    if (fx != fy) {
        fa[fx] = fy;
        dp[fy] = (dp[fy] * dp[fx]) % MOD;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> m;
    const int dirs[3][2] = {{1, 0}, {0, 1}, {0, -1}};

    // 初始化并查集
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            int idx = index(i, j);
            fa[idx] = idx;
            dp[idx] = 1;
        }
    }

    // 读取网格
    for (int i = 1; i <= n; ++i) {
        string s;
        cin >> s;
        for (int j = 1; j <= m; ++j) {
            grid[i][j] = (s[j-1] == '#');
        }
    }

    // 处理网格
    for (int i = n-1; i >= 2; --i) {

        for (int j = 2; j <= m-1; ++j) {
            if (grid[i][j]) continue;
            for (const auto& d : dirs) {
                int ni = i + d[0], nj = j + d[1];
                if (ni >= 1 && ni <= n && nj >= 1 && nj <= m && !grid[ni][nj]) {
                    un(index(i, j), index(ni, nj));
                }
            }
        }

        memset(visited, 0, sizeof(visited)); // 重置访问标记
        for (int j = 2; j <= m-1; ++j) {
            if (grid[i][j]) continue;
            int root = find(index(i, j));
            if (!visited[root]) {
                visited[root] = true;
                dp[root] = (dp[root] + 1) % MOD;
            }
        }
    }

    // 计算结果
    for (int i = 2; i <= n-1; ++i) {
        for (int j = 2; j <= m-1; ++j) {
            if (grid[i][j]) continue;
            int idx = index(i, j);
            if (find(idx) == idx) {
                ans = (ans * dp[idx]) % MOD;
            }
        }
    }

    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
#define MAXN 500010
using namespace std;

int n, m, p, t, tote;
int dist[MAXN], ans[MAXN];
//dist表示到达这个点最长乘车时间
//ans其实是一个记录数组 就是用于辅助记录答案的  他记录的是这条边对应的起点的dist值

struct Bus {
    int x, t, idx, dist;
} b[MAXN];

void build(int x, int t, int idx, int dist) {
    b[++tote] = {x, t, idx, dist};
}

// 最终时间相同时，乘车时间越长排越前面。
// 最终时间不同时，最终时间更长排越后面。
bool cmp(const Bus &x, const Bus &y) {
    return (x.t == y.t) ? (x.dist > y.dist) : (x.t < y.t);
}

int main() {
    ios::sync_with_stdio(0);
    cin >> n >> m >> p >> t;

    for (int i = 1, s, t, a, b, c, d; i <= m; i++) {
        cin >> s >> t >> a >> b >> c >> d;
        build(s, a, i, 0);
        build(t, d, i, c - b);
    }

    build(n + 1, t, 0, -0x3f3f3f3f);
    sort(b + 1, b + tote + 1, cmp);

    memset(dist, 250, sizeof(dist));
    dist[1] = 0;

    for (int i = 1; i <= tote; i++) {
        if (b[i].x == n + 1) {
            break;
        }
        if (!b[i].dist) {
            ans[b[i].idx] = dist[b[i].x];
        } else {
            dist[b[i].x] = max(dist[b[i].x], ans[b[i].idx] + b[i].dist);
			//排序方式保证了一条路的起点一定在终点之前被访问过
        }
		// 接下来枚举每个点，若为起点则将对应的 ans 赋为到该点的 dist 值，
		// 若为终点，则用该点的 ans+ 到该点那班车车上所花的时间值（即 bdist?）更新该点的 dist 值。 
		// 若到达 p 点时 distp? 值小于零输出 ?1，若不是则输出 t?distp?。
    }

    (dist[p] < 0) ? cout << "-1" : cout << t - dist[p];
    return 0;
}

#include<bits/stdc++.h>
using namespace std;

