}

int dijkstra(){
    for(int i=1;i<=n;i++){
        for(int j=0;j<(1<<p);j++){
            f[i][j]=INF;
        }
    }
    f[1][val[1]]=0;
    heap.push({1,val[1],0});
    while(!heap.empty()){
        node u=heap.top();
        //cout<<u.pos<<' '<<u.st<<' '<<u.val<<endl;
        heap.pop();
        if(vis[u.pos][u.st]){
            continue;
        }
        vis[u.pos][u.st]=true;
        if(u.pos==n){
            return u.val;
        }
        for(int i=head[u.pos];i;i=nxt[i]){
            int v=to[i];
            int w=weight[i];
            if((u.st&limit[i])==limit[i]){
                if(f[v][u.st|val[v]]>f[u.pos][u.st]+w){
                    f[v][u.st|val[v]]=f[u.pos][u.st]+w;
                    heap.push({v,u.st|val[v],f[v][u.st|val[v]]});
                }
            }
        }
    }
    return -1;
}

