void build1(int l,int r,int i){
    if(l==r){
        maxx[i]=-val[seg[l]];
        // minn[i]=val[seg[l]];
    }
    else{
        int mid=(l+r)>>1;
        build1(l,mid,i<<1);
        build1(mid+1,r,i<<1|1);
        up1(i);
    }
}

void up2(int i){
    tree2[i]=max(tree2[i<<1],tree2[i<<1|1]);
}

void lazy(int i,int v){
    tree2[i]+=v;
    tag[i]+=v;
}

void down(int i){
    if(tag[i]){
        lazy(i<<1,tag[i]);
        lazy(i<<1|1,tag[i]);
        tag[i]=0;
    }
}

void add(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        lazy(i,1);
    }
    else{
        int mid=(l+r)>>1;
        down(i);
        if(jobl<=mid){
            add(jobl,jobr,l,mid,i<<1);
        }
        if(jobr>mid){
            add(jobl,jobr,mid+1,r,i<<1|1);
        }
        up2(i);
    }
}

void lazy1(int i,int v){
    all[i]+=v;
    maxx[i]+=v;
}

void down1(int i){
    if(all[i]){
        lazy1(i<<1,all[i]);
        lazy1(i<<1|1,all[i]);
        all[i]=0;
    }
}

void del(int jobl,int jobr,int jobv,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        lazy1(i,jobv);
    }
    else{
        int mid=(l+r)>>1;
        down1(i);
        if(jobl<=mid){
            del(jobl,jobr,jobv,l,mid,i<<1);
        }
        if(jobr>mid){
            del(jobl,jobr,jobv,mid+1,r,i<<1|1);
        }
        up1(i);
    }
}

