}

bool check(int limit){
    for(int i=1;i<=m;i++){
        vis[i]=false;
    }
    while(!heap1.empty()){
        heap1.pop();
    }
    while(!heap2.empty()){
        heap2.pop();
    }

    int now=1;
    for(int i=1;i<=p;i++){
        while(now<=m&&nums[now].val>=nums1[i]){
            heap1.push(now);
            now++;
        }
        int k=limit;
        while(k--){
            if(heap1.empty()){
                break;
            }
            int u=heap1.top();
            heap1.pop();
            vis[nums[u].id]=true;
        }
    }

    now=1;
    for(int i=1;i<=q;i++){
        while(now<=m&&tmp[now].cost<=nums2[i]){
            if(!vis[tmp[now].id]){
                heap2.push(now);
            }
            now++;
        }
        int k=limit;
        while(k--){
            if(heap2.empty()){
                break;
            }
            int u=heap2.top();
            heap2.pop();
            vis[tmp[u].id]=true;
        }
    }
    int all=0;
    for(int i=1;i<=m;i++){
        if(!vis[i]){
            all++;
        }
    }
    return 1ll*(n-p-q)*limit>=all;
}

