void insert(int i,string s){
    int cur=0;
    for(char ch:s){
        int path=ch-'a';
        if(tree[cur][path]==0){
            tree[cur][path]=++cnt;
        }
        cur=tree[cur][path];
    }
    st[cur]|=(1<<i);
}

void setfail(){
    queue<int>q;
    for(int i=0;i<26;i++){
        if(tree[0][i]){
            q.push(tree[0][i]);
        }
    }
    while(!q.empty()){
        int u=q.front();
        q.pop();
        for(int i=0;i<26;i++){
            if(tree[u][i]==0){
                tree[u][i]=tree[fail[u]][i];
            }
            else{
                fail[tree[u][i]]=tree[fail[u]][i];
                q.push(tree[u][i]);
            }
        }
        st[u]|=st[fail[u]];
    }
}

void dfs(int i,int j,int k,string str,int sta){
    if(i==len){
        if(k==sta){
            ans.push_back(str);
        }
        return ;
    }
    for(int c=0;c<26;c++){
        int jj=tree[j][c];
        int kk=k|st[jj];
        if(dp[i+1][jj][kk]){
            dfs(i+1,jj,kk,str+char('a'+c),sta);
        }
    }

}

