void tarjan(int u){
    dfn[u]=low[u]=++dfncnt;
    sta[++top]=u;

    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(dfn[v]==0){
            tarjan(v);
            low[u]=min(low[v],low[u]);
            if(low[v]>=dfn[u]){
                vbcccnt++;
                vbccl[vbcccnt]=idx+1;
                while(sta[top+1]!=v){
                    vbccarr[++idx]=sta[top--];
                }
                vbccarr[++idx]=u;
                vbccr[vbcccnt]=idx;
            }
        }
        else{
            low[u]=min(low[u],dfn[v]);
        }
    }
}

void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

