                    arr[i][j]=2;
                    stx=i,sty=j;
                }
                else{
                    arr[i][j]=c-'0';
                }
            }
        }
        ans=predict();
        while(!IDAdfs(stx,sty,0)){
            ans++;
            if(ans>15){
                ans=-1;
                break;
            }
        }
        cout<<ans<<endl;
    }
    return 0;
}

