#include <bits/stdc++.h>
using namespace std;
const int MAXN = 1000005;
queue <int> q;
int to[MAXN], n, ans, in[MAXN];
bool choose[MAXN], vis[MAXN]; // choose是看是否派去，vis是看在不在环中

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	cin >> n;
	for (int i = 1; i <= n; i++) {
		cin >> to[i];
		in[to[i]] ++;
	}
	for (int i = 1; i <= n; i++)
		if (!in[i]) 
			q.push(i); // 无人监管，防止为所欲为，不能派去
	while (q.size()) {
		int u = q.front();
		vis[u] = 1;
		if (choose[u]) {
			in[to[u]] --; // 他去执行任务，他监视的人脱离了他的监管
			if (in[to[u]] == 0) 
				q.push(to[u]);
		} else { // 如果他不能去执行任务，他监视的人就要去执行任务
			if (!choose[to[u]]) { // 防止重新入队和额外统计答案
				ans++;
				q.push(to[u]);
			}
			choose[to[u]] = 1;
		}
		q.pop();
	}
	for (int i = 1; i <= n; i++) {
		if (!vis[i] && in[i]) { // 在环中，肯定选一半的人派去执行任务。
			int cnt = 0;
			for (int j = i; !vis[j]; j = to[j]) {
				cnt++;
				vis[j] = 1;
			}
			ans += cnt / 2; // 向下取整
		}
	}
	cout << ans;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
int n,m;
int mat[105][105];
int st[105],en[105];

int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

inline int inv(int x) {//保证m为素数，求费马小定理逆元
	int res(1), q(m - 2);
	while (q) {
		if (q & 1) res = res * x % m;
		x = x * x % m;
		q >>= 1;
	}
	return res;
}

void swap(int a, int b) {
    int tmp[105];
    //cout<<"swap"<<endl;
    for (int j = 0; j <= n+1; j++) {
        tmp[j] = mat[a][j];
        mat[a][j] = mat[b][j];
        mat[b][j] = tmp[j];
    }
}

// 高斯消元解决同余方程组模版，保证初始系数没有负数
int gauss(int n) {
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            // 已经成为主元的行不参与
            if (j < i && mat[j][j] != 0) {
                continue;
            }
            // 找到系数不等于0的行做主元即可
            if (mat[j][i] != 0) {
                swap(i,j);
                break;
            }
        }
        if (mat[i][i] != 0) {
            for (int j = 1; j <= n; j++) {
                if (i != j && mat[j][i] != 0) {
                    int gcd_val = gcd(mat[j][i], mat[i][i]);
                    int a = mat[i][i] / gcd_val;
                    int b = mat[j][i] / gcd_val;
                    if (j < i && mat[j][j] != 0) {
                        // 如果j行有主元，那么从j列到i-1列的所有系数 * a
                        // 正确更新主元和自由元之间的关系
                        for (int k = j; k < i; k++) {
                            mat[j][k] = (mat[j][k] * a) % m;
                        }
                    }
                    // 正常消元
                    for (int k = i; k <= n + 1; k++) {
                        mat[j][k] = ((mat[j][k] * a - mat[i][k] * b) % m + m) % m;
                    }
                }
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        if(mat[i][i]==0&&mat[i][n+1]!=0)
            return 2;
        // 在模意义下应该求逆元，(a / b) % MOD = (a * b的逆元) % MOD
        mat[i][n + 1] = (mat[i][n + 1] * inv(mat[i][i])) % m;
        mat[i][i] = 1;
    }
    return 1;
}

