#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Key {
    int a[6];

    bool operator<(const Key& other) const {
        for (int i = 0; i < 6; i++) {
            if (a[i] != other.a[i]) return a[i] < other.a[i];
        }
        return false;
    }

    bool operator==(const Key& other) const {
        for (int i = 0; i < 6; i++) {
            if (a[i] != other.a[i]) return false;
        }
        return true;
    }
};

ll C[7][7];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    vector<array<int, 6>> A(N);

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < 6; j++) {
            cin >> A[i][j];
        }
    }

    // 预处理组合数
    for (int i = 0; i <= 6; i++) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; j++) {
            C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
        }
    }

    // F[x] 表示：枚举所有大小为 x 的位置集合，
    // 有多少年份对在这些位置上完全相同。
    vector<ll> F(7, 0);

    // 空集合：任意两个年份都满足
    F[0] = 1LL * N * (N - 1) / 2;

    // 枚举 6 个位置的所有非空子集
    for (int mask = 1; mask < (1 << 6); mask++) {
        int cnt_pos = __builtin_popcount(mask);

        vector<Key> keys;
        keys.reserve(N);

        for (int i = 0; i < N; i++) {
            Key key{};
            int idx = 0;

            // 把当前子集中的位置提取出来，作为比较关键字
            for (int j = 0; j < 6; j++) {
                if (mask & (1 << j)) {
                    key.a[idx++] = A[i][j];
                }
            }

            // 剩余位置补 0，保证 Key 可以直接排序比较
            while (idx < 6) {
                key.a[idx++] = 0;
            }

            keys.push_back(key);
        }

        sort(keys.begin(), keys.end());

        // 统计相同 key 的数量，贡献 C(cnt, 2)
        for (int i = 0; i < N; ) {
            int j = i + 1;
            while (j < N && keys[j] == keys[i]) {
                j++;
            }

            ll cnt = j - i;
            F[cnt_pos] += cnt * (cnt - 1) / 2;

            i = j;
        }
    }

    // 容斥反推恰好 K 个位置相同的年份对数量
    //
    // F[m] = sum_{t=m}^{6} C(t, m) * Exact[t]
    //
    // 因此：
    // Exact[K] = sum_{m=K}^{6} (-1)^(m-K) * C(m, K) * F[m]
    ll ans = 0;

    for (int m = K; m <= 6; m++) {
        ll term = C[m][K] * F[m];

        if ((m - K) % 2 == 0) {
            ans += term;
        } else {
            ans -= term;
        }
    }

    cout << ans << '\n';

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;

int n,m;

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int weight[MAXN<<1];
int cent[MAXN<<1];
int cntg=1;

int fa[MAXN];
int sz[MAXN];
int top[MAXN];
int dep[MAXN];
int son[MAXN];
int dist[MAXN];

bool vis[MAXN];
int centfa[MAXN];

long long sum[MAXN];
long long addval[MAXN];
long long minusval[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v,int w){
    nxt[cntg]=head[u];
    to[cntg]=v;
    weight[cntg]=w;
    head[u]=cntg++;
}

void dfs1(int u,int f,int dis){
    dep[u]=dep[f]+1;
    dist[u]=dis;
    fa[u]=f;
    sz[u]=1;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        int w=weight[i];
        if(v!=f){
            dfs1(v,u,dis+w);
            sz[u]+=sz[v];
            if(sz[son[u]]<sz[v]){
                son[u]=v;
            }
        }
    }
}

void dfs2(int u,int t){
    top[u]=t;
    if(son[u]){
        dfs2(son[u],t);
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa[u]&&v!=son[u]){
            dfs2(v,v);
        }
    }
}

int getlca(int a,int b){
    while(top[a]!=top[b]){
        if(dep[top[a]]<dep[top[b]]){
            b=fa[top[b]];
        }
        else{
            a=fa[top[a]];
        }
    }
    return dep[a]<dep[b]?a:b;
}

int getdist(int a,int b){
    return dist[a]+dist[b]-(dist[getlca(a,b)]<<1);
}

void getsize(int u,int fa){
    sz[u]=1;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa&&!vis[v]){
            getsize(v,u);
            sz[u]+=sz[v];
        }
    }
}

int getcentroid(int u,int fa){
    getsize(u,fa);
    int half=sz[u]>>1;
    bool find=false;
    while(!find){
        find=true;
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            if(v!=fa&&!vis[v]&&sz[v]>half){
                find=false;
                fa=u;
                u=v;
                break;
            }
        }
    }
    return u;
}

void centroidtree(int u,int fa){
    centfa[u]=fa;
    vis[u]=true;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(!vis[v]){
            int nxtcent=getcentroid(v,u);
            cent[i]=nxtcent;
            centroidtree(nxtcent,u);
        }
    }
}

void add(int x,int v){
    sum[x]+=v;
    for(int cur=x,fa=centfa[cur];fa;cur=fa,fa=centfa[cur]){
        int dist=getdist(x,fa);
        sum[fa]+=v;
        addval[fa]+=1ll*v*dist;
        minusval[cur]+=1ll*v*dist;
    }
}

long long query(int x){
    long long ans=addval[x];
    for(int cur=x,fa=centfa[cur];fa;cur=fa,fa=centfa[cur]){
        int dist=getdist(x,fa);
        ans+=addval[fa];
        ans-=minusval[cur];
        ans+=(sum[fa]-sum[cur])*dist;
    }
    return ans;
}

long long compute(int u){
    long long ans=query(u);
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(query(v)<ans){
            return compute(cent[i]);
        }
    }
    return ans;
}

int main()
{
    n=read(),m=read();
    for(int i=1;i<n;i++){
        int u,v,w;
        u=read(),v=read(),w=read();
        addedge(u,v,w);
        addedge(v,u,w);
    }
    dfs1(1,0,0);
    dfs2(1,1);
    int root=getcentroid(1,0);
    centroidtree(root,0);
    for(int i=1;i<=m;i++){
        int x,v;
        x=read(),v=read();
        add(x,v);
        cout<<compute(root)<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int MAXB = 405;

int n,c,m;
int nums[MAXN];

int blen;
int bnum;
int bi[MAXN];
int bl[MAXB];
int br[MAXB];

int freq[MAXB][MAXN];
int even[MAXB][MAXB];
int cnt[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

int getcnt(int l,int r,int v){
    return freq[r][v]-freq[l-1][v];
}

int delta(int pre){
    if(pre==0){
        return 0;
    }
    if(pre&1){
        return 1;
    }
    return -1;
}

void prepare(){
    blen=sqrt(n);
    bnum=(n+blen-1)/blen;
    for(int i=1;i<=n;i++){
        bi[i]=(i-1)/blen+1;
    }
    for(int i=1;i<=bnum;i++){
        bl[i]=(i-1)*blen+1;
        br[i]=min(n,i*blen);
    }
    for(int i=1;i<=bnum;i++){
        for(int j=bl[i];j<=br[i];j++){
            freq[i][nums[j]]++;
        }
        for(int j=1;j<=c;j++){
            freq[i][j]+=freq[i-1][j];
        }
    }
    for(int i=1;i<=bnum;i++){
        for(int j=i;j<=bnum;j++){
            even[i][j]=even[i][j-1];
            for(int k=bl[j];k<=br[j];k++){
                even[i][j]+=delta(cnt[nums[k]]++);
            }
        }
        for(int j=1;j<=c;j++){
            cnt[j]=0;
        }
    }
}

int query(int l,int r){
    int ans=0;
    if(bi[l]==bi[r]){
        for(int i=l;i<=r;i++){
            ans+=delta(cnt[nums[i]]++);
        }
        for(int i=l;i<=r;i++){
            cnt[nums[i]]=0;
        }
    }
    else{
        ans=even[bi[l]+1][bi[r]-1];
        for(int i=l;i<=br[bi[l]];i++){
            ans+=delta(getcnt(bi[l]+1,bi[r]-1,nums[i])+cnt[nums[i]]);
            cnt[nums[i]]++;
        }
        for(int i=bl[bi[r]];i<=r;i++){
            ans+=delta(getcnt(bi[l]+1,bi[r]-1,nums[i])+cnt[nums[i]]);
            cnt[nums[i]]++;
        }
        for(int i=l;i<=br[bi[l]];i++){
            cnt[nums[i]]=0;
        }
        for(int i=bl[bi[r]];i<=r;i++){
            cnt[nums[i]]=0;
        }
    }
    return ans;
}

int main()
{
    n=read(),c=read(),m=read();
    for(int i=1;i<=n;i++){
        nums[i]=read();
    }
    prepare();
    int ans=0;
    for(int i=1;i<=m;i++){
        int l,r;
        l=read(),r=read();
        l=(l+ans)%n+1;
        r=(r+ans)%n+1;
        if(l>r){
            swap(l,r);
        }
        ans=query(l,r);
        printf("%d\n",ans);
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 525015;
const int MAXT = 21*MAXN;

int n;
int val[MAXN];
long long ans;

int root[MAXN];
int trie[MAXT][2];
int sz[MAXT];
int eorval[MAXT];
int cnt;

int head[MAXN];
int nxt[MAXN];
int to[MAXN];
int cntg=1;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

void update(int u){
    int l=trie[u][0];
    int r=trie[u][1];

    sz[u]=sz[l]+sz[r];

    eorval[u]=(eorval[l]^eorval[r])<<1;
    if(sz[r]&1){
        eorval[u]^=1;
    }
}

void addone(int u){
    if(u==0){
        return ;
    }
    swap(trie[u][0],trie[u][1]);
    addone(trie[u][0]);
    update(u);
}

int insert(int u,int bit,int x){
    if(u==0){
        u=++cnt;
    }

    if(bit>20){
        sz[u]++;
        return u;
    }

    int b=(x>>bit)&1;
    trie[u][b]=insert(trie[u][b],bit+1,x);

    update(u);

    return u;
}

int merge(int a,int b,int bit){
    if(a==0||b==0){
        return a+b;
    }
    if(bit>20){
        sz[a]+=sz[b];
        return a;
    }
    trie[a][0]=merge(trie[a][0],trie[b][0],bit+1);
    trie[a][1]=merge(trie[a][1],trie[b][1],bit+1);
    update(a);
    return a;
}

void dfs(int u){
    root[u]=0;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        dfs(v);
        addone(root[v]);
        root[u]=merge(root[u],root[v],0);
    }
    root[u]=insert(root[u],0,val[u]);
    ans+=eorval[root[u]];
}

