        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

int getnxt(int x){
    stack<int>st;
    while(x!=f[x]){
        st.push(x);
        x=f[x];
    }
    while(!st.empty()){
        int u=st.top();
        f[u]=x;
        st.pop();
    }
    return x;
}

int getpre(int x){
    stack<int>st;
    while(x!=g[x]){
        st.push(x);
        x=g[x];
    }
    while(!st.empty()){
        int u=st.top();
        g[u]=x;
        st.pop();
    }
    return x;
}

