    if(l>r)
        return 0;

    int lb=valbelong[l];
    int rb=valbelong[r];

    if(lb==rb){
        int res=valcnt[r];

        if(l>bl[lb])
            res-=valcnt[l-1];

        return res;
    }

    // 左侧残块
    int res=valblock[lb]-valblock[lb-1];

    if(l>bl[lb])
        res-=valcnt[l-1];

    // 中间完整块
    res+=valblock[rb-1]-valblock[lb];

    // 右侧残块
    res+=valcnt[r];

    return res;
}

void computebig(){
    // 值域按照limit分块
    b=limit;
    int bcnt=maxv/b+1;

    for(int v=0;v<=maxv;v++){
        valcnt[v]=0;
        valbelong[v]=v/b+1;
    }

    for(int i=0;i<=bcnt;i++)
        valblock[i]=0;

    for(int i=1;i<=bcnt;i++){
        bl[i]=(i-1)*b;
        br[i]=min(maxv,i*b-1);
    }

    for(int i=1;i<=bigcnt;i++)
        qord[i]=i;

    sort(qord+1,qord+bigcnt+1,cmp2);

    int cur=0;

    for(int i=1;i<=bigcnt;i++){
        int u=qord[i];

        while(cur<n&&cur<bigx[u]){
            cur++;

            int v=val[cur];
            int p=valbelong[v];

            // 维护所在块的块内前缀和
            for(int j=v;j<=br[p];j++)
                valcnt[j]++;

            // 维护整块数量的前缀和
            for(int j=p;j<=bcnt;j++)
                valblock[j]++;
        }

        int res=0;

        // a mod m位于[bigl,bigr]
        // 等价于a位于若干个周期值域区间
        for(int base=0;base+bigl[u]<=maxv;base+=bigm[u]){
            int l=base+bigl[u];
            int r=min(maxv,base+bigr[u]);

            res+=querybig(l,r);
        }

        ans[bigid[u]]+=bigk[u]*res;
    }
}

void addbig(int m,int x,int l,int r,int k,int id){
    bigcnt++;
    bigid[bigcnt]=id;
    bigm[bigcnt]=m;
    bigk[bigcnt]=k;
    bigx[bigcnt]=x;
    bigl[bigcnt]=l;
    bigr[bigcnt]=r;
}

int main()
{
    n=read(),q=read();
    limit=700;
    for(int i=1;i<=n;i++){
        val[i]=read();
        maxv=max(maxv,val[i]);
    }

    for(int i=1;i<=q;i++){
        int l,r,x,y,m;
        l=read(),r=read(),x=read(),y=read(),m=read();
        x%=m,y%=m;
        if(m<=limit){
            if(x>y){
                addquery(m,m-x,m-y-1,l,r,1,i);
            }
            else if(x<y){
                ans[i]=r-l+1;
                addquery(m,m-y,m-x-1,l,r,-1,i);
            }
        }
        else{
            if(x>y){
                addbig(m,r,m-x,m-y-1,1,i);
                addbig(m,l-1,m-x,m-y-1,-1,i);
            }
            else if(x<y){
                ans[i]=r-l+1;
                addbig(m,r,m-y,m-x-1,-1,i);
                addbig(m,l-1,m-y,m-x-1,1,i);
            }
        }
    }

    computesml();
    computebig();

    for(int i=1;i<=q;i++){
        write(ans[i]);
        putchar('\n');
    }
    return 0;
}

#include <iostream>
#include <cstdio>
#include <cmath>
#include <cstring>
using namespace std;

const int MAXN = 225;
const int MAXR = 135;

double f[MAXN][MAXR]; // f[i][j]: 前i张卡牌中有j张发动过技能的概率
double p[MAXN]; // 每张卡牌的发动概率
int d[MAXN]; // 每张卡牌的伤害
double pow_p[MAXN][MAXR]; // 预计算(1-p_i)^k

int main() {
    int T;
    scanf("%d", &T);

    while (T--) {
        int n, r;
        scanf("%d%d", &n, &r);

        for (int i = 1; i <= n; i++) {
            scanf("%lf%d", &p[i], &d[i]);
        }

        // 预计算幂次
        for (int i = 1; i <= n; i++) {
            pow_p[i][0] = 1.0;
            for (int j = 1; j <= r; j++) {
                pow_p[i][j] = pow_p[i][j-1] * (1 - p[i]);
            }
        }

        // 初始化
        memset(f, 0, sizeof(f));
        f[0][0] = 1.0;
        double ans = 0.0;

        // 动态规划
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= min(i, r); j++) {
                // 第i张卡牌没有被发动
                if (j <= i - 1) {
                    f[i][j] += f[i-1][j] * pow_p[i][r - j];
                }

                // 第i张卡牌被发动
                if (j > 0) {
                    double prob = 1.0 - pow_p[i][r - (j - 1)];
                    f[i][j] += f[i-1][j-1] * prob;
                }
            }
        }

        // 计算每张卡牌被发动的概率
        for (int i = 1; i <= n; i++) {
            double prob_i = 0.0;
            for (int j = 0; j <= min(i - 1, r); j++) {
                if (f[i-1][j] > 1e-10) {
                    double prob = 1.0 - pow_p[i][r - j];
                    prob_i += f[i-1][j] * prob;
                }
            }
            ans += prob_i * d[i];
        }

        printf("%.10lf\n", ans);
    }

    return 0;
}

#include <iostream>
#include <cstring>
#include <queue>
#include <vector>
#include <climits>
using namespace std;

const int MAXN = 2500;      // 最大点数：2*35*35 + 2 = 2452
const int MAXM = 30000;     // 最大边数
const int INF = INT_MAX;

// 网络流图结构
struct Edge {
    int to, next;
    long long cap;
    int rev;  // 反向边索引
} edges[MAXM];

int head[MAXN], level[MAXN], cur[MAXN];
int tot = 0;

// 四个方向：上下左右
const int dx[] = {1, -1, 0, 0};
const int dy[] = {0, 0, 1, -1};

int n, m;

// 加边函数
void add_edge(int u, int v, long long cap) {
    edges[tot].to = v;
    edges[tot].cap = cap;
    edges[tot].next = head[u];
    edges[tot].rev = tot + 1;
    head[u] = tot++;

    edges[tot].to = u;
    edges[tot].cap = 0;
    edges[tot].next = head[v];
    edges[tot].rev = tot - 1;
    head[v] = tot++;
}

// BFS分层
bool bfs(int s, int t) {
    memset(level, -1, sizeof(level));
    queue<int> q;
    q.push(s);
    level[s] = 0;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = head[u]; i != -1; i = edges[i].next) {
            int v = edges[i].to;
            if (level[v] == -1 && edges[i].cap > 0) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[t] != -1;
}

// DFS多路增广
long long dfs(int u, int t, long long flow) {
    if (u == t || flow == 0) return flow;

    long long total = 0;
    for (int &i = cur[u]; i != -1; i = edges[i].next) {
        int v = edges[i].to;
        if (level[v] == level[u] + 1 && edges[i].cap > 0) {
            long long f = dfs(v, t, min(flow, edges[i].cap));
            if (f > 0) {
                edges[i].cap -= f;
                edges[edges[i].rev].cap += f;
                total += f;
                flow -= f;
                if (flow == 0) break;
            }
        }
    }
    return total;
}

// Dinic算法主函数
long long dinic(int s, int t) {
    long long total_flow = 0;
    while (bfs(s, t)) {
        memcpy(cur, head, sizeof(head));
        total_flow += dfs(s, t, INF);
    }
    return total_flow;
}

// 获取点的入点编号
inline int get_in(int i, int j) {
    return (i-1)*n + j;
}

// 获取点的出点编号
inline int get_out(int i, int j) {
    return n*n + (i-1)*n + j;
}

int main() {
    cin >> n >> m;

    // 初始化图
    memset(head, -1, sizeof(head));
    tot = 0;

    // 源点0，汇点T=2*n*n+1
    const int T = 2*n*n + 1;

    // 1. 拆点：每个网格点拆为入点和出点
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            int u = get_in(i, j);
            int v = get_out(i, j);
            add_edge(u, v, 1);
        }
    }

    // 2. 添加起始点（源点到起始点入点）
    for (int i = 0; i < m; i++) {
        int x, y;
        cin >> x >> y;
        int u = get_in(x, y);
        add_edge(0, u, 1);
    }

    // 3. 添加边界点（边界点出点到汇点）
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (i == 1 || i == n || j == 1 || j == n) {
                int u = get_out(i, j);
                add_edge(u, T, 1);
            }
        }
    }

    // 4. 添加相邻点之间的边
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            for (int k = 0; k < 4; k++) {
                int ni = i + dx[k];
                int nj = j + dy[k];

                // 检查相邻点是否在网格内
                if (ni >= 1 && ni <= n && nj >= 1 && nj <= n) {
                    int u = get_out(i, j);
                    int v = get_in(ni, nj);
                    add_edge(u, v, 1);
                }
            }
        }
    }

    // 5. 计算最大流
    long long max_flow = dinic(0, T);

    // 6. 判断是否有解
    cout << (max_flow == m ? "YES" : "NO") << endl;

    return 0;
}

#include<bits/stdc++.h>
