inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline int lowbit(int x){
    return x&-x;
}

node merge(node a,node b){
    if(a.val==b.val){
        return {a.val,min(a.cnt+b.cnt,MAXVAL)};
    }
    else if(a.val>b.val){
        return a;
    }
    else{
        return b;
    }
}

void update(int x,node v){
    while(x){
        tree[x]=merge(tree[x],v);
        x-=lowbit(x);
    }
}

node query(int x){
    node ans={0,0};
    while(x<=n){
        ans=merge(ans,tree[x]);
        x+=lowbit(x);
    }
    return ans;
}

