#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int INF = 1e9;

int d,n1,n2,c1,c2,tc;
int need[MAXN];

struct node{
    int day;
    int cnt;
};
deque<node>dq1,dq2,dq3;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void add(int day,int cnt){
    dq1.push_back({day,cnt});
}

void update(int now){
    while(!dq1.empty()&&now-dq1.front().day>=n1){
        dq2.push_back(dq1.front());
        dq1.pop_front();
    }
    while(!dq2.empty()&&now-dq2.front().day>=n2){
        dq3.push_back(dq2.front());
        dq2.pop_front();
    }
}

int compute(int x){
    dq1.clear();
    dq2.clear();
    dq3.clear();

    int ans=(tc-c2)*x;
    add(-100005,x);
    for(int i=1;i<=d;i++){
        update(i);
        int now=need[i];
        while(now>0&&!dq3.empty()){
            node tmp=dq3.back();;
            dq3.pop_back();
            if(tmp.cnt>=now){
                tmp.cnt-=now;
                ans+=now*c2;
                now=0;
                dq3.push_back(tmp);
            }
            else{
                now-=tmp.cnt;
                ans+=c2*tmp.cnt;
            }
        }

        while(now>0&&!dq2.empty()){
            node tmp=dq2.back();;
            dq2.pop_back();
            if(tmp.cnt>=now){
                tmp.cnt-=now;
                ans+=now*c1;
                now=0;
                dq2.push_back(tmp);
            }
            else{
                now-=tmp.cnt;
                ans+=c1*tmp.cnt;
            }
        }
        if(now){
            return INF;
        }
        add(i,need[i]);
    }
    return ans;
}

