void bfs(int st){
    memset(dis,-1,sizeof(dis));
    queue<int>q;
    q.push(st);
    dis[st]=0;

    while(!q.empty()){
        int u=q.front();
        q.pop();
        if(u!=st){
            ok[st][u]=true;
            if(st!=1&&ok[1][u]){
                f[st].push_back(u);
                std :: sort(f[st].begin(), f[st].end(), [](int u, int v) {
                    return val[u] > val[v];
                });
                if(f[st].size()>3){
                    f[st].pop_back();
                }
            }
        }

        if(dis[u]==k+1){
            continue;
        }
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            if(dis[v]==-1){
                dis[v]=dis[u]+1;
                q.push(v);
            }
        }
