#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 2e5+5;

int n,m,d,s;

int val[MAXN];

int u[MAXN];
int v[MAXN];
int ok[MAXN];
map<pair<int,int>,int>mp;

int op[MAXN];
int x[MAXN];
int y[MAXN];

int qx[MAXN];
int qy[MAXN];
int qz[MAXN];

int ans[MAXN];

int qid[MAXN];
int lset[MAXN];
int rset[MAXN];

int fa[MAXN];
int sz[MAXN];
int sum[MAXN];

struct node{
    int op;
    int x,y,z;
    int all;
};
node rollback[MAXN*4];
int opsize;

int find(int x){
    while(x!=fa[x]){
        x=fa[x];
    }
    return x;
}

void un(int x,int y){
    int fx=find(x);
    int fy=find(y);
    if(fx!=fy){
        if(sz[fx]>sz[fy]){
            swap(fx,fy);
        }
        rollback[++opsize]={1,fx,fy,sz[fy],sum[fy]};
        fa[fx]=fy;
        sz[fy]+=sz[fx];
        sum[fy]+=sum[fx];
    }
}

void add(int x,int val){
    int fx=find(x);
    rollback[++opsize]={2,fx,0,0,sum[fx]};
    sum[fx]+=val;
}

void undo(){
    if(rollback[opsize].op==1){
        fa[rollback[opsize].x]=rollback[opsize].x;
        sz[rollback[opsize].y]=rollback[opsize].z;
        sum[rollback[opsize].y]=rollback[opsize].all;
    }
    else{
        sum[rollback[opsize].x]=rollback[opsize].all;
    }
    opsize--;
}

void event(int day){
    if(op[day]==1){
        un(x[day],y[day]);
    }
    else{
        add(x[day],y[day]);
    }
}

bool check(int id){
    return sum[find(qx[id])]+sum[find(qy[id])]>=qz[id];
}

void compute(int ql,int qr,int vl,int vr){
    if(ql>qr){
        return ;
    }
    if(vl==vr){
        for(int i=ql;i<=qr;i++){
            ans[qid[i]]=vl;
        }
        return ;
    }

    int mid=(vl+vr+1)/2;
    int snapshot=opsize;

    for(int day=vr;day>mid;day--){
        event(day);
    }

    int lsz=0,rsz=0;
    for(int i=ql;i<=qr;i++){
        int id=qid[i];

        if(check(id)){
            rset[++rsz]=id;
        }
        else{
            lset[++lsz]=id;
        }
    }

    for (int i = 1; i <= lsz; i++) {
        qid[ql + i - 1] = lset[i];
    }

    for (int i = 1; i <= rsz; i++) {
        qid[ql + lsz + i - 1] = rset[i];
    }

    int snapshot2=opsize;
    if(lsz){
        if(mid>0){
            event(mid);
        }
        compute(ql,ql+lsz-1,vl,mid-1);
        while(opsize!=snapshot2){
            undo();
        }
    }
    while(opsize!=snapshot){
        undo();
    }
    if(rsz){
        compute(ql+lsz,qr,mid,vr);
    }
}

