int Next[MAXN<<1];
int to[MAXN<<1];
int weight[MAXN<<1];
int cnt=1;
int arr[MAXN];
int sum[MAXN][3];
// sum[u][i] : 以u为头的子树内，距离为i的节点权值和
int dp[MAXN][3];
// dp[u][i] : 以u做根，整棵树上，距离为i的节点权值和
int maxans=0;

void dfs1(int u,int f){
    for(int i=head[u];i>0;i=Next[i]){
        int v=to[i];
        if(v!=f){
            dfs1(v,u);
            for(int j=1;j<=2;j++){
                sum[u][j]+=sum[v][j-1];
            }
        }
    }
}

void dfs2(int u,int f){
    for (int e = head[u], v; e != 0; e = Next[e]) {
        v = to[e];
        if (v != f) {
            dp[v][0] = sum[v][0];
            dp[v][1] = sum[v][1] + dp[u][0];
            for (int i = 2; i <= 2; i++) {
                dp[v][i] = sum[v][i] + dp[u][i - 1] - sum[v][i - 2];
            }
            dfs2(v, u);
        }
    }
}

