void dfs(int u,int p){
    for(int i=head[u];i>0;i=Next[i]){
        int v=to[i];
        if(v!=p){
            dfs(v,u);
            dp[u][0]=(dp[u][0]*((dp[v][1]+dp[v][2])%MOD))%MOD;
            dp[u][1]=(dp[u][1]*((dp[v][0]+dp[v][2])%MOD))%MOD;
            dp[u][2]=(dp[u][2]*((dp[v][0]+dp[v][1])%MOD))%MOD;
        }
    }
}

