        for(int j=1;j<=i;j++){
            comb[i][j]=(comb[i-1][j-1]+comb[i-1][j])%MOD;
        }
    }
    dfs(1);
    int ans=0;
    for(int i=1;i<=n;i++){
        ans=(ans+f[1][i])%MOD;
    }
    cout<<ans<<endl;
    return 0;
}

