int getfa(int u){//找祖先
	if(fa[u]==u) return u;//不用找，直接返回
	int tmp=fa[u];//深坑，解释见上
	fa[u]=getfa(fa[u]);//浅坑2
	dis[u]+=dis[tmp];
	return fa[u];//返回
}
void unio(int u,int v){//合并
	int fu=getfa(u),fv=getfa(v);//先找祖先
	if(fu==fv) ans=min(ans,dis[v]+1);//更新答案，解释见上
	else fa[fu]=fv,dis[u]=dis[v]+1;//更新fa和dis，浅坑3
