{
    row=read(),col=read(),n=read();
    for(int i=1;i<=n;i++){
        int x=read(),y=read();
        vec[x].push_back(y);
    }
    head=build(1,col);
    long long res=0;
    for(int i=1;i<=row;i++){
        for(int x:vec[i]){
            split(0,0,head,x);
            int lm=rs[0];
            int r=ls[0];
            split(0,0,lm,x-1);
            val[ls[0]]=priority[ls[0]]=i;
            head=merge(merge(rs[0],ls[0]),r);
        }
        res+=1ll*i*(col+1)*col/2-all[head];
    }
    res=1ll*row*(row+1)/2*col*(col+1)/2-res;
    cout<<res<<endl;
    return 0;
}

