bool cmp(node a,node b){
    if(a.x!=b.x){
        return a.x<b.x;
    }
    return a.id<b.id;//让添加操作类型在前面
}

void merge(int l,int mid,int r){
    int p1,p2,tree=0;
    for(p1=l-1,p2=mid+1;p2<=r;p2++){
        while(p1+1<=mid&&nums[p1+1].y<=nums[p2].y){
            p1++;
            if(nums[p1].id==0){
                tree++;
            }
        }
        ans[nums[p2].id]+=nums[p2].v*tree;
    }

    p1=l,p2=mid+1;
    int i=l;
    while(p1<=mid&&p2<=r){
        tmp[i++]=nums[p1].y<nums[p2].y?nums[p1++]:nums[p2++];
    }
    while(p1<=mid){
        tmp[i++]=nums[p1++];
    }
    while(p2<=r){
        tmp[i++]=nums[p2++];
    }
    for(int i=l;i<=r;i++){
        nums[i]=tmp[i];
    }
}

void cdq(int l,int r){
    if(l==r){
        return ;
    }
    int mid=(l+r)>>1;
    cdq(l,mid);
    cdq(mid+1,r);
    merge(l,mid,r);
}

