        }
        if(arr[i]==-1){
            arr[i]=0;
            ans=(ans*(n-i+1))%MOD;
        }
    }
    cout<<ans<<endl;
    compute();
    for (int i = 1; i <= n; i++) {
        cout<<arr[i] <<" ";
    }
    return 0;
}

