#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;
const int MAXM = 1e6+5;
const int MAXP = MAXN*2*20;
const long long INF = 1ll<<60;

int n,m;

struct Query{
    int x,y,id;
};
Query query[MAXM];

struct Pair{
    int a,b;
    long long d;
};
Pair pairarr[MAXP];
int cntp;

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int weight[MAXN<<1];
int cnt=1;

bool vis[MAXN];
int sz[MAXN];

long long dist[MAXN];
int node[MAXN];
int cnta;

int sta[MAXN];
int top;

long long tree[MAXN<<2];
long long ans[MAXM];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    head[u]=cnt++;
}

void getsize(int u, int fa) {
    sz[u] = 1;
    for (int e = head[u]; e; e = nxt[e]) {
        int v = to[e];
        if (v != fa && !vis[v]) {
            getsize(v, u);
            sz[u] += sz[v];
        }
    }
}

int getCentroid(int u, int fa) {
    getsize(u, fa);
    int half = sz[u] >> 1;
    bool find = false;
    while (!find) {
        find = true;
        for (int e = head[u]; e; e = nxt[e]) {
            int v = to[e];
            if (v != fa && !vis[v] && sz[v] > half) {
                fa = u;
                u = v;
                find = false;
                break;
            }
        }
    }
    return u;
}

bool cmp(Query &a,Query &b){
    return a.y<b.y;
}

bool cmp1(Pair &a,Pair &b){
    return a.b<b.b;
}

void dfs(int u,int fa,long long dis){
    dist[u]=dis;
    node[++cnta]=u;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        int w=weight[i];
        if(v!=fa&&!vis[v]){
            dfs(v,u,dis+w);
        }
    }
}

void stackadd(int cur){
    while(top>0&&dist[sta[top]]>=dist[cur]){
        pairarr[++cntp]={min(sta[top],cur),max(sta[top],cur),dist[sta[top]]+dist[cur]};
        top--;
    }
    sta[++top]=cur;
}

void calc(int u){
    cnta=0;
    dfs(u,0,0);
    sort(node+1,node+cnta+1);
    top=0;
    for(int i=1;i<=cnta;i++){
        stackadd(node[i]);
    }
    top=0;
    for(int i=cnta;i>=1;i--){
        stackadd(node[i]);
    }
}

void solve(int u){
    vis[u]=true;
    calc(u);
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(!vis[v]){
            solve(getCentroid(v,u));
        }
    }
}

void build(int l,int r,int i){
    tree[i]=INF;
    if(l<r){
        int mid=(l+r)>>1;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
    }
}

void update(int pos,long long jobv,int l,int r,int i){
    if(l==r){
        tree[i]=min(tree[i],jobv);
    }
    else{
        int mid=(l+r)>>1;
        if(pos<=mid){
            update(pos,jobv,l,mid,i<<1);
        }
        else{
            update(pos,jobv,mid+1,r,i<<1|1);
        }
        tree[i]=min(tree[i<<1],tree[i<<1|1]);
    }
}

long long querymin(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        return tree[i];
    }
    else{
        int mid=(l+r)>>1;
        long long ans=INF;
        if(jobl<=mid){
            ans=min(ans,querymin(jobl,jobr,l,mid,i<<1));
        }
        if(jobr>mid){
            ans=min(ans,querymin(jobl,jobr,mid+1,r,i<<1|1));
        }
        return ans;
    }
}

void compute(){
    solve(getCentroid(1,0));
    sort(query+1,query+m+1,cmp);
    sort(pairarr+1,pairarr+cntp+1,cmp1);
    build(1,n,1);
    for(int i=1,j=1;i<=m;i++){
        for(;j<=cntp&&pairarr[j].b<=query[i].y;j++){
            update(pairarr[j].a,pairarr[j].d,1,n,1);
        }
        if(query[i].x==query[i].y){
            ans[query[i].id]=-1;
        }
        else{
            ans[query[i].id]=querymin(query[i].x,query[i].y,1,n,1);
        }
    }
}

int main()
{
    n=read();
    for(int i=1;i<n;i++){
        int u,v,w;
        u=read(),v=read(),w=read();
        addedge(u,v,w);
        addedge(v,u,w);
    }
    m=read();
    for(int i=1;i<=m;i++){
        query[i].x=read();
        query[i].y=read();
        query[i].id=i;
    }
    compute();
    for(int i=1;i<=m;i++){
        cout<<ans[i]<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 5e5+5;
const int MAXM = 1e5+5;
const int MOD = 1e9+7;

int n;
int fac[MAXN];
int inv[MAXN];

int nums[MAXM];

int power(int a,int b){
    int ans=1;
    while(b){
        if(b&1){
            ans=(a*ans)%MOD;
        }
        b>>=1;
        a=(a*a)%MOD;
    }
    return ans;
}

void prepare(int n){
    inv[0]=1;
    fac[0]=1;
    for(int i=1;i<=n;i++){
        fac[i]=(fac[i-1]*i)%MOD;
    }
    inv[n]=power(fac[n],MOD-2);
    for(int i=n-1;i>=1;i--){
        inv[i]=(inv[i+1]*(i+1))%MOD;
    }
}

int comb(int a,int b){
    return fac[a]*inv[b]%MOD*inv[a-b]%MOD;
}

signed main()
{
    prepare(500000);
    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>nums[i];
        nums[i]/=2;
    }
    int ans=1;
    for(int i=1;i<n;i++){
        if(nums[i]>nums[i+1]){
            ans=(ans*comb(nums[i],nums[i+1]))%MOD;
        }
        else{
            ans=(ans*comb(nums[i+1]-1,nums[i]-1))%MOD;
        }
    }
    cout<<ans<<endl;
    return 0;
}

// https://www.luogu.com.cn/problem/P8085
//这道题哈希完全就是工具人的作用
//首先处理出每个位置上的字符串到左边相同的字符距离是多少
//也要记录自己右边相同字符的位置
//然后对第一个维护一个窗口  只要最左边的字符弹出 那么将自己右边的那个设置为-1
//然后对窗口哈希调整
#include <bits/stdc++.h>
using namespace std;
const int INF = 2147483647;
const int MAXN = 1e6 + 3;
const int BASE = 13131;

int L1[MAXN], R1[MAXN];
int L2[MAXN], R2[MAXN];
int A[MAXN], B[MAXN], n, m;
long long H[MAXN], P[MAXN];
map<string, int> M;

int main() {
    string t;

    while (cin >> t && t != "$") {
        R1[M[t]] = ++n;//表示这个词语右边最早再次出现的位置
        L1[n] = M[t];//表示这个词语左边最早再次出现的位置
        M[t] = n;
    }

    M.clear();

    while (cin >> t && t != "$") {
        R2[M[t]] = ++m;
        L2[m] = M[t];
        M[t] = m;
    }

    for (int i = 1; i <= n; ++i) if (!R1[i]) R1[i] = INF;
    for (int i = 1; i <= m; ++i) if (!R2[i]) R2[i] = INF;//如果右边没有出现过

    for (int i = 1; i <= n; ++i) A[i] = (L1[i] ? i - L1[i] : -1);
    for (int i = 1; i <= m; ++i) B[i] = (L2[i] ? i - L2[i] : -1);//该位置的单词距离自己左边出现最早位置的距离

    long long h0 = 0, h = 0;
    P[0] = 1;
    for (int i = 1; i <= m; ++i) P[i] = P[i - 1] * BASE;

    for (int i = 1; i <= m; ++i) h0 = h0 * BASE + B[i];//h0是我们所要求的
    for (int i = 1; i <= m; ++i) h = h * BASE + A[i];

    if (h == h0) {
        cout << 1 << endl;
        return 0;
    }

    for (int i = m + 1; i <= n; ++i) {
        h = h * BASE + A[i] - A[i - m] * P[m];//还没有完全修正前的哈希值

        if (R1[i - m] <= i) {//即引发的变化在如今查询的范围中
            int overlapIndex = R1[i - m];
            h -= A[overlapIndex] * P[i - overlapIndex];//减去错误的哈希值
            A[overlapIndex] = -1;
            h += A[overlapIndex] * P[i - overlapIndex];  // 加上修正后的哈希值
        } else if (R1[i - m] <= n) {
            A[R1[i - m]] = -1;
        }

        if (h == h0) {
            cout << i - m + 1 << endl;
            return 0;
        }
    }

    return 0;
}

