#include<bits/stdc++.h>
using namespace std;
const int MAXN = 5e4+5;

int n;
int val[MAXN];

int tree[MAXN<<2];
int cnt[MAXN<<2];
int tag[MAXN<<2];

int st1[MAXN],top1;
int st2[MAXN],top2;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void up(int i){
    tree[i]=min(tree[i<<1],tree[i<<1|1]);
    cnt[i]=0;
    if(tree[i]==tree[i<<1]){
        cnt[i]+=cnt[i<<1];
    }
    if(tree[i]==tree[i<<1|1]){
        cnt[i]+=cnt[i<<1|1];
    }
}

void build(int l,int r,int i){
    if(l==r){
        tree[i]=l;
        cnt[i]=1;
    }
    else{
        int mid=(l+r)>>1;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        up(i);
    }
}

void lazy(int i,int v){
    tag[i]+=v;
    tree[i]+=v;
}

void down(int i){
    if(tag[i]){
        lazy(i<<1,tag[i]);
        lazy(i<<1|1,tag[i]);
        tag[i]=0;
    }
}

void update(int jobl,int jobr,int jobv,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        lazy(i,jobv);
    }
    else{
        int mid=(l+r)>>1;
        down(i);
        if(jobl<=mid){
            update(jobl,jobr,jobv,l,mid,i<<1);
        }
        if(jobr>mid){
            update(jobl,jobr,jobv,mid+1,r,i<<1|1);
        }
        up(i);
    }
}

int query(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        if(tree[i]==0){
            return cnt[i];
        }
        else{
            return 0;
        }
    }
    else{
        int mid=(l+r)>>1;
        int ans=0;
        down(i);
        if(jobl<=mid){
            ans+=query(jobl,jobr,l,mid,i<<1);
        }
        if(jobr>mid){
            ans+=query(jobl,jobr,mid+1,r,i<<1|1);
        }
        return ans;
    }
}

int main()
{
    n=read();
    for(int i=1;i<=n;i++){
        val[i]=read();
    }
    build(1,n,1);
    int ans=0;
    for(int i=1;i<=n;i++){
        update(1,n,-1,1,n,1);

        while(top1&&val[st1[top1]]<val[i]){
            int pos=st1[top1];
            top1--;
            int lt=st1[top1]+1;
            update(lt,pos,val[i]-val[pos],1,n,1);
        }
        st1[++top1]=i;

        while(top2&&val[st2[top2]]>val[i]){
            int pos=st2[top2];
            top2--;
            int lt=st2[top2]+1;
            update(lt,pos,val[pos]-val[i],1,n,1);
        }
        st2[++top2]=i;

        ans+=query(1,i,1,n,1);
    }
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const long long INF = 1e12;

int n,p,cnt;

int m=1;
int arr[MAXN<<1];

int to[MAXN<<1];
int val[MAXN<<1];

long long tree[MAXN<<1];

long long ans;

long long f[MAXN<<1];

struct node{
    int x,y,id;
}nums[MAXN<<1];

node tmp[MAXN<<1];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

bool cmp1(node a,node b){
    if(a.x!=b.x) return a.x<b.x;
    if(a.y!=b.y) return a.y<b.y;
    return a.id<b.id;
}

bool cmp2(node a,node b){
    return a.y<b.y;
}

int find(int val){
    int l=1,r=m,ans;
    while(l<=r){
        int mid=(l+r)/2;
        if(arr[mid]>=val){
            ans=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    return ans;
}

inline int lowbit(int x){
    return x&-x;
}

void update(int x,long long val){
    while(x<=m){
        tree[x]=min(tree[x],val);
        x+=lowbit(x);
    }
}

long long query(int x){
    long long ans=INF;
    while(x){
        ans=min(ans,tree[x]);
        x-=lowbit(x);
    }
    return ans;
}

void clear(int x){
    while(x<=m){
        tree[x]=INF;
        x+=lowbit(x);
    }
}

void merge(int l,int mid,int r){
    for(int i=l;i<=r;i++){
        tmp[i]=nums[i];
    }
    sort(tmp+l,tmp+mid+1,cmp2);
    sort(tmp+mid+1,tmp+r+1,cmp2);
    int p1=l-1,p2=mid+1;
    for(;p2<=r;p2++){
        while(p1+1<=mid&&tmp[p1+1].y<=tmp[p2].y){
            p1++;
            update(tmp[p1].y,f[tmp[p1].id]);
        }
        f[tmp[p2].id]=min(f[tmp[p2].id],query(tmp[p2].y));
    }
    for(int i=l;i<=p1;i++){
        clear(tmp[i].y);
    }
}

void cdq(int l,int r){
    if(l==r){
        if(to[nums[l].id]){
            f[to[nums[l].id]]=min(f[to[nums[l].id]],f[nums[l].id]+val[nums[l].id]);
        }
        return ;
    }
    int mid=(l+r)/2;
    cdq(l,mid);
    merge(l,mid,r);
    cdq(mid+1,r);
}

