    int st=1;
    if(nums[2].x+nums[2].y==0){
        f[nums[2].id]=0;
        st=2;
    }
    cdq(st,cnt);
    for(int i=1;i<=cnt;i++){
        ans=min(ans,f[i]);
    }
    ans+=2*n;
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int MAXM = 2e5+5;
const int MAXH = 20;
const int INF = 1e9+5;

int n,m;

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int cnt=1;

int fa[MAXN];
int dep[MAXN];
int st[MAXN][MAXH];
int dfn[MAXN];
int sz[MAXN];
int dfncnt;

int tree[MAXN];

// 事件编号组成的数组
int eid[MAXM];
// 如果op == 0，添加点x到点y，重要度为v的路径
// 如果op == 1，删除点x到点y，重要度为v的路径
// 如果op == 2，查询和x相关的答案，y表示问题的编号
int op[MAXM];
int x[MAXM];
int y[MAXM];
int v[MAXM];
int cntq = 0;

int lset[MAXM];
int rset[MAXM];

int ans[MAXM];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

void dfs(int u,int f){
    fa[u]=f;
    dep[u]=dep[f]+1;
    sz[u]=1;
    dfn[u]=++dfncnt;
    st[u][0]=f;
    for(int i=1;i<MAXH;i++){
        st[u][i]=st[st[u][i-1]][i-1];
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v==f){
            continue;
        }
        dfs(v,u);
        sz[u]+=sz[v];
    }
}

int lca(int a,int b){
    if(dep[a]<dep[b]){
        swap(a,b);
    }
    for(int i=MAXH-1;i>=0;i--){
        if(dep[st[a][i]]>=dep[b]){
            a=st[a][i];
        }
    }
    if(a==b){
        return a;
    }
    for(int i=MAXH-1;i>=0;i--){
        if(st[a][i]!=st[b][i]){
            a=st[a][i];
            b=st[b][i];
        }
    }
    return st[a][0];
}

inline int lowbit(int x){
    return x&(-x);
}

void add(int x,int v){
    while(x<=n){
        tree[x]+=v;
        x+=lowbit(x);
    }
}

int query(int x){
    int ans=0;
    while(x){
        ans+=tree[x];
        x-=lowbit(x);
    }
    return ans;
}

void pathadd(int a,int b,int v){
    int lcaab=lca(a,b);
    int falca=st[lcaab][0];
    add(dfn[a],v);
    add(dfn[b],v);
    add(dfn[lcaab],-v);
    if(falca!=0){
        add(dfn[falca],-v);
    }
}

int pathquery(int x){
    return query(dfn[x]+sz[x]-1)-query(dfn[x]-1);
}

void compute(int el,int er,int vl,int vr){
    if(el>er){
        return ;
    }
    if(vl==vr){
        for(int i=el;i<=er;i++){
            int id=eid[i];
            if(op[id]==2){
                ans[y[id]]=vl;
            }
        }
    }
    else{
        int mid=(vl+vr)/2;
        int lsz=0,rsz=0;
        int request=0;
        for(int i=el;i<=er;i++){
            int id=eid[i];
            if(op[id]==0){
                if(v[id]<=mid){
                    lset[++lsz]=id;
                }
                else{
                    pathadd(x[id],y[id],1);
                    request++;
                    rset[++rsz]=id;
                }
            }
            else if(op[id]==1){
                if(v[id]<=mid){
                    lset[++lsz]=id;
                }
                else{
                    pathadd(x[id],y[id],-1);
                    request--;
                    rset[++rsz]=id;
                }
            }
            else{
                if(pathquery(x[id])==request){
                    lset[++lsz]=id;
                }
                else{
                    rset[++rsz]=id;
                }
            }
        }
        for (int i = 1; i <= lsz; i++) {
            eid[el + i - 1] = lset[i];
        }
        for (int i = 1; i <= rsz; i++) {
            eid[el + lsz + i - 1] = rset[i];
        }
        //复原操作
        for (int i = 1; i <= rsz; i++) {
            int id = rset[i];
            if (op[id] == 0 && v[id] > mid) {
                pathadd(x[id], y[id], -1);
            }
            if (op[id] == 1 && v[id] > mid) {
                pathadd(x[id], y[id], 1);
            }
        }
        compute(el, el + lsz - 1, vl, mid);
        compute(el + lsz, er, mid + 1, vr);
    }
}

int main()
{
    n=read(),m=read();
    for(int i=1;i<n;i++){
        int u,v;
        u=read(),v=read();
        addedge(u,v);
        addedge(v,u);
    }
    for(int i=1;i<=m;i++){
        op[i]=read();
        x[i]=read();
        if(op[i]==0){
            y[i]=read(),v[i]=read();
        }
        else if(op[i]==1){
            y[i]=y[x[i]];
            v[i]=v[x[i]];
            x[i]=x[x[i]];
        }
        else{
            y[i]=++cntq;
        }
        eid[i]=i;
    }
    dfs(1,0);
    compute(1,m,0,INF);
    for(int i=1;i<=cntq;i++){
        if (ans[i] == 0) {
            cout << -1 << '\n';
        } else {
            cout << ans[i] << '\n';
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;

int n,m;

// 表示每个操作之后的答案
int ans[MAXN];

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int cntg=1;

int fa[MAXN];
int son[MAXN];
int sz[MAXN];
int top[MAXN];
int dep[MAXN];
int dfncnt;
int dfn[MAXN];
int seg[MAXN];

// 表示某个点第一次被染成黑色的时间
int first[MAXN];

// 表示从位置i开始之后，第一个没有染色的位置
int father[MAXN];

bool okay[MAXN];
int dial[MAXN];
int diar[MAXN];
int dia[MAXN];

int maxlen;

struct node{
    int x;
    int t;
};
node nums[MAXN];

bool cmp(node &a,node &b){
    return a.t<b.t;
}

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9')
    {
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void write(int x){
    if(x<0)
        putchar('-'),x=-x;
    if(x>9)
        write(x/10);
    putchar(x%10+'0');
    return;
}

void clear(){
    for(int i=1;i<=n;i++){
        head[i]=0;
        son[i]=0;
    }
    cntg=1;
    dfncnt=0;
}

inline void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

void dfs1(int u,int f){
    sz[u]=1;
    dep[u]=dep[f]+1;
    fa[u]=f;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=f){
            dfs1(v,u);
            sz[u]+=sz[v];
            if(sz[son[u]]<sz[v]){
                son[u]=v;
            }
        }
    }
}

void dfs2(int u,int t){
    top[u]=t;
    dfn[u]=++dfncnt;
    seg[dfncnt]=u;
    if(son[u]){
        dfs2(son[u],t);
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=son[u]&&v!=fa[u]){
            dfs2(v,v);
        }
    }
}

void prepare(){
    dfs1(1,0);
    dfs2(1,1);
    for(int i=1;i<=n+1;i++){
        father[i]=i;
        first[i]=m+1;
    }
}

int find(int x){
    return x==father[x]?x:father[x]=find(father[x]);
}

void calc(int x,int y,int t){
    for(int i=find(x);i<=y;i=find(i+1)){
        father[i]=i+1;
        first[i]=t;
    }
}

void pathcalc(int x,int y,int t){
    while(top[x]!=top[y]){
        if(dep[top[x]]<dep[top[y]]){
            swap(x,y);
        }
        calc(dfn[top[x]],dfn[x],t);
        x=fa[top[x]];
    }
    calc(min(dfn[x],dfn[y]),max(dfn[x],dfn[y]),t);
}

int lca(int x,int y){
    while(top[x]!=top[y]){
        if(dep[top[x]]<dep[top[y]]){
            swap(x,y);
        }
        x=fa[top[x]];
    }
    return dfn[x]<dfn[y]?x:y;
}

void func(int x,int y,int u){
    int xylca=lca(x,y);
    int len=dep[x]+dep[y]-2*dep[xylca]+1;
    if(len>dia[u]){
        dia[u]=len;
        dial[u]=x;
        diar[u]=y;
    }
}

void un(int x,int y){
    x=find(x);
    y=find(y);
    if(x!=y){
        father[x]=y;
        int l1=dial[x];
        int r1=diar[x];
        int l2=dial[y];
        int r2=diar[y];

        func(l1,r1,y);
        func(l1,r2,y);
        func(l1,l2,y);
        func(r1,r2,y);
        func(r1,l2,y);
    }
}

void activate(int u){
    okay[u]=true;

    dial[u]=diar[u]=u;
    dia[u]=1;

    maxlen=max(maxlen,dia[u]);

    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(okay[v]){
            v=find(v);
            un(u,v);
            maxlen=max(maxlen,dia[v]);
        }
    }
}

void compute(){
    for(int i=1;i<=n;i++){
        nums[i]={i,first[dfn[i]]};
    }
    sort(nums+1,nums+n+1,cmp);

    // 先处理黑色部分
    for(int i=1;i<=n;i++){
        father[i]=i;
        okay[i]=false;
    }
    maxlen=0;
    int lt=0,rt=n;
    for(int i=1;i<=m;i++){
        while(lt+1<=n&&nums[lt+1].t==i){
            lt++;
            activate(nums[lt].x);
        }
        ans[i]=maxlen;
    }

    // 处理白色部分
    for(int i=1;i<=n;i++){
        father[i]=i;
        okay[i]=false;
    }
    maxlen=0;
    for(int i=m+1;i>=2;i--){
        // 这里多一个m+1  不会影响答案 但是可以统一代码
        while(rt>=1&&nums[rt].t==i){
            activate(nums[rt].x);
            rt--;
        }
        ans[i-1]=max(ans[i-1],maxlen);
    }
}

int main()
{
    int T=read();
    while(T--){
        n=read(),m=read();
        clear();

        for(int i=1;i<n;i++){
            int u,v;
            u=read(),v=read();
            addedge(u,v);
            addedge(v,u);
        }

        prepare();

        for(int i=1;i<=m;i++){
            int u,v;
            u=read(),v=read();
            pathcalc(u,v,i);
        }

        compute();

        for(int i=1;i<=m;i++){
            write(ans[i]);
            putchar('\n');
        }
    }
    return 0;
}

// 软件安装，C++版
// 一共有n个物品，你的背包能容纳的总重量为m
// 选择某个物品时，重量消耗为当前物品的w，获得收益为当前物品的v
// 给定每个物品最多一件依赖物品，不拿依赖物品无法选择当前物品
// 如果一批物品循环依赖，想选的话就只能都选，有的物品不存在依赖物品
// 打印你能获得的最大收益
// 0 <= n <= 100
// 0 <= m <= 500
// 测试链接 : https://www.luogu.com.cn/problem/P2515
// 如下实现是C++的版本，C++版本和java版本逻辑完全一样
// 提交如下代码，可以通过所有测试用例

#include <bits/stdc++.h>

using namespace std;

const int MAXN = 301;
const int MAXM = 601;
int n, m;
int w[MAXN];
int v[MAXN];
int depend[MAXN];

int head[MAXN];
int nxt[MAXN];
int to[MAXN];
int cntg;

int dfn[MAXN];
int low[MAXN];
int cntd;

int sta[MAXN];
int top;

int belong[MAXN];
int wsum[MAXN];
int vsum[MAXN];
int sccCnt;

int indegree[MAXN];

int siz[MAXN];
int weight[MAXN];
int value[MAXN];
int dfnCnt;
int dp[MAXN][MAXM];

void addEdge(int a, int b) {
   nxt[++cntg] = head[a];
   to[cntg] = b;
   head[a] = cntg;
}

void tarjan(int u) {
   dfn[u] = low[u] = ++cntd;
   sta[++top] = u;
   for (int e = head[u]; e > 0; e = nxt[e]) {
       int v = to[e];
       if (dfn[v] == 0) {
           tarjan(v);
           low[u] = min(low[u], low[v]);
       } else {
           if (belong[v] == 0) {
               low[u] = min(low[u], dfn[v]);
           }
       }
   }
   if (dfn[u] == low[u]) {
       sccCnt++;
       int pop;
       do {
           pop = sta[top--];
           belong[pop] = sccCnt;
           wsum[sccCnt] += w[pop];
           vsum[sccCnt] += v[pop];
       } while (pop != u);
   }
}

void condense() {
   cntg = 0;
   for (int i = 0; i <= sccCnt; i++) {
       head[i] = 0;
   }
   for (int i = 1; i <= n; i++) {
       if (depend[i] > 0) {
           int scc1 = belong[depend[i]];
           int scc2 = belong[i];
           if (scc1 != scc2) {
               indegree[scc2]++;
               addEdge(scc1, scc2);
           }
       }
   }
   for (int i = 1; i <= sccCnt; i++) {
       if (indegree[i] == 0) {
           addEdge(0, i);
       }
   }
}

int dfs(int u) {
   int i = ++dfnCnt;
   siz[i] = 1;
   weight[i] = wsum[u];
   value[i] = vsum[u];
   for (int e = head[u]; e > 0; e = nxt[e]) {
       int v = to[e];
       siz[i] += dfs(v);
   }
   return siz[i];
}

int knapsackOnTree() {
   dfs(0);
   for (int i = dfnCnt; i >= 2; i--) {
       for (int j = 1; j <= m; j++) {
           dp[i][j] = dp[i + siz[i]][j];
           if (j - weight[i] >= 0) {
               dp[i][j] = max(dp[i][j], value[i] + dp[i + 1][j - weight[i]]);
           }
       }
   }
   return dp[2][m];
}

int main() {
   ios::sync_with_stdio(false);
   cin.tie(nullptr);
   cin >> n >> m;
   for (int i = 1; i <= n; i++) {
       cin >> w[i];
   }
   for (int i = 1; i <= n; i++) {
       cin >> v[i];
   }
   for (int i = 1; i <= n; i++) {
       cin >> depend[i];
       if (depend[i] > 0) {
           addEdge(depend[i], i);
       }
   }
   for (int i = 1; i <= n; i++) {
       if (dfn[i] == 0) {
           tarjan(i);
       }
   }
   condense();
   int ans = knapsackOnTree();
   cout << ans << "\n";
   return 0;
}

