void prepare(){
    high[0]=-1;
    for(int i=1;i<=n;i++){
        high[i]=high[i>>1]+1;
    }
    p=high[n];

    dfs1(root,0);
    dfs2(root,root);

    for(int u=1;u<=n;u++){
        if(top[u]==u){
            for(int i=0,a=u,b=u;i<len[u];i++,a=st[a][0],b=son[b]){
                setup(u,i,a);
                setdn(u,i,b);
            }
        }
    }
}

int query(int x,int k){
    if(k==0){
        return x;
    }
    if(k==(1<<high[k])){
        return st[x][high[k]];
    }

    x=st[x][high[k]];
    k-=(1<<high[k]);

    k-=dep[x]-dep[top[x]];
    x=top[x];
    return k>=0?getup(x,k):getdn(x,-k);
}

int main()
{
