    long long ans=0;
    for(int i=1,x,k,lastans=0;i<=m;i++){
        x=(get(s)^lastans)%n+1;
        k=(get(s)^lastans)%dep[x];
        lastans=query(x,k);
        ans^=(long long )i*lastans;
    }
    cout<<ans<<endl;
    return 0;
}

