                }
                mergetree(fx,fy);
            }
        }
        else{
            u=find(u);
            if(siz[u]<v){
                printf("-1\n");
            }
            else{
                printf("%d\n",pos[getrank(siz[u]-v+1,root[u])]);
            }
        }
    }
    return 0;
}

