    for(int i=1;i<=n;i++){
        val[i]=read();
    }
    prepare();
    for(int t=MAXT-1;m>0;m-=t){
        int k=min(m,t);
        memset(cnt,0,sizeof(cnt));
        memset(hasset,0,sizeof(hasset));
        memset(ans,0,sizeof(ans));
        curset.reset();
        int cntq=0,l,r;
        for(int i=1;i<=k;i++){
            for(int j=1;j<=3;j++){
                l=read(),r=read();
                nums[++cntq]={l,r,i};
                ans[i]+=r-l+1;
            }
        }
        sort(nums+1,nums+cntq+1,cmp);
        compute(cntq);
        for(int i=1;i<=k;i++){
            ans[i]-=bs[i].count()*3;
        }
        for(int i=1;i<=k;i++){
            printf("%d\n",ans[i]);
        }
    }
    return 0;
}

