#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;

int n;

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int cnt=1;

int fa[MAXN];
int son[MAXN];
int len[MAXN];

int dfncnt;
int fid[MAXN];
int gid[MAXN];
long long f[MAXN];
long long g[MAXN<<1];

long long ans;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

void setf(int u,int i,long long v){
    f[fid[u]+i]=v;
}

long long getf(int u,int i){
    return f[fid[u]+i];
}

void setg(int u,int i,long long v){
    g[gid[u]+i]=v;
}

long long getg(int u,int i){
    return g[gid[u]+i];
}

void dfs1(int u,int f){
    fa[u]=f;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=f){
            dfs1(v,u);
            if(son[u]==0||len[v]>len[son[u]]){
                son[u]=v;
            }
        }
    }
    len[u]=len[son[u]]+1;
}

void dfs2(int u,int top){
    fid[u]=++dfncnt;
    if(son[u]==0){
        gid[u]=2*fid[top];
        return ;
    }
    dfs2(son[u],top);
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa[u]&&v!=son[u]){
            dfs2(v,v);
        }
    }
    gid[u]=gid[son[u]]+1;
}

void dfs3(int u){
    setf(u,0,1);
    if(son[u]==0){
        return ;
    }
    dfs3(son[u]);
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa[u]&&v!=son[u]){
            dfs3(v);
        }
    }
    for(int ei=head[u];ei;ei=nxt[ei]){
        int v=to[ei];
        if(v!=son[u]&&v!=fa[u]){
            for(int i=0;i<=len[v];i++){
                if(i<len[u]&&i-1>=0){
                    ans+=getg(u,i)*getf(v,i-1);
                }
                if(i+1<len[v]&&i>0){
                    ans+=getg(v,i+1)*getf(u,i);
                }
            }
            for(int i=0;i<=len[v];i++){
                if(i+1<len[v]){
                    setg(u,i,getg(u,i)+getg(v,i+1));
                }
                if(i-1>=0){
                    setg(u,i,getg(u,i)+getf(u,i)*getf(v,i-1));
                }
            }
            for(int i=0;i<=len[v];i++){
                if(i-1>=0){
                    setf(u,i,getf(u,i)+getf(v,i-1));
                }
            }
        }
    }
    ans+=getg(u,0);
}

int main()
{
    n=read();
    for(int i=1;i<n;i++){
        int u,v;
        u=read(),v=read();
        addedge(u,v);
        addedge(v,u);
    }
    dfs1(1,0);
    dfs2(1,1);
    dfs3(1);
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;
const int MAXT = 2e6+5;
const int MAXE = 2e7+5;
const int INF = 1e8;

int n,nodecnt;
int dis[MAXT];
bool vis[MAXT];
int dist[MAXT];

int head[MAXT];
int nxt[MAXE];
int to[MAXE];
int weight[MAXE];
int cnt=1;

struct node{
    int pos;
    int d;
};
struct compare{
    bool operator()(node a,node b){
        return a.d>b.d;
    }
};
priority_queue<node,vector<node>,compare>heap;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    head[u]=cnt++;
}

void build(int l,int r,int i){
    if(l==r){
        nodecnt=max(nodecnt,i+2*n);
        addedge(l,i+2*n,0);
        return ;
    }
    else{
        int mid=(l+r)>>1;
        addedge((i<<1)+2*n,i+2*n,0);
        addedge((i<<1|1)+2*n,i+2*n,0);
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
    }
}

void add(int jobl,int jobr,int jobv,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        addedge(i+2*n,jobv,0);
    }
    else{
        int mid=(l+r)>>1;
        if(jobl<=mid){
            add(jobl,jobr,jobv,l,mid,i<<1);
        }
        if(jobr>mid){
            add(jobl,jobr,jobv,mid+1,r,i<<1|1);
        }
    }
}

void dijkstra(int st){
    for(int i=1;i<=nodecnt;i++){
        dis[i]=INF;
        vis[i]=0;
    }
    dis[st]=0;
    heap.push({st,0});
    while(!heap.empty()){
        node tmp=heap.top();
        heap.pop();
        int u=tmp.pos;
        if(vis[u]){
            continue;
        }
        vis[u]=true;
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            int w=weight[i];
            if(dis[v]>dis[u]+w){
                dis[v]=dis[u]+w;
                heap.push({v,dis[v]});
            }
        }
    }
    for(int i=1;i<=nodecnt;i++){
        dist[i]=(dis[i]<INF)?(dist[i]+dis[i]):INF;
    }
}

void compute(){
    for(int i=1;i<=2*n;i++){
        if(dist[i]<INF){
            heap.push({i,dist[i]});
        }
    }
    for(int i=1;i<=nodecnt;i++){
        vis[i]=false;
    }
    while(!heap.empty()){
        node tmp=heap.top();
        heap.pop();
        int u=tmp.pos;
        if(vis[u]){
            continue;
        }
        vis[u]=true;
        dist[u]=tmp.d;
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            int w=weight[i];
            if(!vis[v]&&tmp.d+w<dist[v]){
                heap.push({v,tmp.d+w});
            }
        }
    }
}

int main()
{
    n=read();
    nodecnt=2*n;
    build(1,n,1);
    for(int i=1;i<=n;i++){
        int l,r;
        l=read(),r=read();
        addedge(i+n,i,1);
        add(l,r,i+n,1,n,1);
    }
    dijkstra(1);
    dijkstra(n);
    compute();

    int q=read();
    while(q--){
        int x=read();
        cout<<(dist[x]<INF?dist[x]:-1)<<endl;
    }
    return 0;
}

#include <cstdio>
#include <cstring>
#include <cmath>
#define min(a,b) (((a)<(b))?(a):(b))
double a[20][20];//预处理，从第i块到第j块的距离，使用两点之间距离公式
double x[20],y[20];//每块奶酪的横、纵坐标
double F[18][34000];//状压DP数组 在第i个点上，走过的二进制状态的十进制表达为j时，最短的距离
int N;
double distance(int v,int w)//计算第v个和第w个奶酪之间的距离
{
	return sqrt((x[v]-x[w])*(x[v]-x[w])+(y[v]-y[w])*(y[v]-y[w]));//两点间距离公式
}
int main()
{
	int i,j,k;
	double ans;
	memset(F,127,sizeof(F));//这样可以给浮点数赋值无穷大
	ans=F[0][0];
	scanf("%d",&N);
	for(i=1;i<=N;i++)
	{
		scanf("%lf%lf",&x[i],&y[i]);//数据读入
	}
	x[0]=0;y[0]=0;
	for(i=0;i<=N;i++)
	{
		for(j=i+1;j<=N;j++)
		{
			a[i][j]=distance(i,j);//初始化距离数组
			a[j][i]=a[i][j];
		}
	}
	for(i=1;i<=N;i++)//初始化
	{
		F[i][(1<<(i-1))]=a[0][i];//在i点上且只有经过i点时距离是原点到i点的距离
	}
	for(k=1;k<(1<<N);k++)//枚举所有二进制的状态
	{
		for(i=1;i<=N;i++)
		{
			if((k&(1<<(i-1)))==0)
				continue;//i的位置没被走过，所以不需要再继续计算了
			for(j=1;j<=N;j++)
			{
				if(i==j)
					continue;//同一个点不需要再计算
				if((k&(1<<(j-1)))==0)
					continue;//j的位置没走过
				F[i][k]=min(F[i][k],F[j][k-(1<<(i-1))]+a[i][j]);
			}
		}
	}
	for(i=1;i<=N;i++)
	{
		ans=min(ans,F[i][(1<<N)-1]);
	}
	printf("%.2f\n",ans);
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;

char s[MAXN];
char t[MAXN];
char ss[MAXN<<1];
int ps[MAXN<<1];
int pt[MAXN<<1];
int rs[MAXN<<1];
int rt[MAXN<<1];

int n;

void manacherss(char *s) {
    n=strlen(s)*2+1;
    for(int i=0,j=0;i<n;i++){
        ss[i]=(i&1)==0?'#':s[j++];
    }
}

void manacher(char *s,int *p) {
    manacherss(s);
    for (int i = 0, c = 0, r = 0, len; i < n; i++) {
        len = r > i ? min(p[2 * c - i], r - i) : 1;
        while (i + len < n && i - len >= 0 && ss[i + len] == ss[i - len]) {
            len++;
        }
        if (i + len > r) {
            r = i + len;
            c = i;
        }
        p[i] = len;
    }
}


int main()
{
    scanf("%s",s);
    int len=strlen(s);
    for(int i=0;i<len;i++){
        t[i]=s[len-1-i];
    }
    manacher(s,ps);
    manacher(t,pt);
    for(int i=n-1,j=n-1;i>=0;i--){
        while(i-ps[i]<j){
            rs[j]=i-j;
            j-=2;
        }
    }
    for(int i=n-1,j=n-1;i>=0;i--){
        while(i-pt[i]<j){
            rt[j]=i-j;
            j-=2;
        }
    }
    int ans=max(rs[0],rt[0]);
    for(int i=1;i<=len;i++){
        if(s[i-1]!=t[i-1]){
            break;
        }
        ans=max(ans,2*i+max(rs[2*i],rt[2*i]));
    }
    cout<<ans<<endl;
    return 0;
}

