int compare(int a,int b){
    if (a < b) return 0;  // 小于
    if (a == b) return 1; // 等于
    return 2;             // 大于
}

void solve(int limit,int ans[][MAXN]){
    int len=0;
    while(limit){
        nums[++len]=limit%10;
        limit/=10;
    }

    for(int i=1;i<=n;i++){
        memset(f,0,sizeof(f));
        for(int j=i;j<=n;j++){

            for(int x=len;x>=1;x--){
                for(int y=1;y<x;y++){

                    if(x>1){
                        if(val[j]>nums[x]){
                            for(int k=0;k<2;k++){
                                f[x][y][2]=(f[x][y][2]+f[x-1][y][k])%MOD;
                            }
                        }
                        else if(val[j]==nums[x]){
                            for(int k=0;k<2;k++){
                                f[x][y][k]=(f[x][y][k]+f[x-1][y][k])%MOD;
                            }
                        }
                        else{
                            for(int k=0;k<2;k++){
                                f[x][y][0]=(f[x][y][0]+f[x-1][y][k])%MOD;
                            }
                        }
                    }

                    f[x][y][2]=(f[x][y][2]+f[x][y+1][2])%MOD;
                    f[x][y][0]=(f[x][y][0]+f[x][y+1][0])%MOD;
                    int cmp=compare(val[j],nums[y]);
                    f[x][y][cmp]=(f[x][y][cmp]+f[x][y+1][1])%MOD;

                }
            }

            for(int x=1;x<=len;x++){
                int cmp=compare(val[j],nums[x]);
                f[x][x][cmp]=(f[x][x][cmp]+2)%MOD;
            }

            int res=0;
            for(int x=1;x<=len;x++){
                res=(res+f[x][1][0])%MOD;
                res=(res+f[x][1][1])%MOD;
                if(x<len)
                    res=(res+f[x][1][2])%MOD;
            }
            ans[i][j]=res;
        }
    }
}

