{
    cin>>n;
    sum[0]=-1;
    power=log2(n);
    for(int i=1;i<n;i++){
        int u,v;
        cin>>u>>v;
        addedge(u,v);
        addedge(v,u);
    }
    dfs(1,0);
    cin>>m;
    int pre,ans=0;
    cin>>pre;
    for(int i=1;i<m;i++){
        int v,w;
        cin>>v;
        w=lca(pre,v);
        ans+=deep[pre]+deep[v]-2*deep[w];
        pre=v;
    }
    cout<<ans<<endl;
    return 0;
}

