int check(int limit){
    int now=m;
    for(int i=1;i<=n;i++){
        tmp[i]=val[i];
    }
    for(int i=n-1;i>=1;i--){
        if(tmp[i]-tmp[i+1]>limit){
            int delta=tmp[i]-tmp[i+1]-limit;
            tmp[i]-=delta;
            now-=delta;
        }
    }
    for(int i=2;i<=n;i++){
        if(tmp[i]-tmp[i-1]>limit){
            int delta=tmp[i]-tmp[i-1]-limit;
            tmp[i]-=delta;
            now-=delta;
        }
    }
    if(now<0){
        return 0;
    }

    for(int i=1;i<=n;i++){
        sum[i]=sum[i-1]+tmp[i];
    }
    int l=1,r=1;
    for(int i=1;i<=n;i++){
        while(l<i&&tmp[l]<limit*(i-l)){
            l++;
        }
        while(r+1<=n&&tmp[r+1]>=limit*(r+1-i)){
            r++;
        }
        int all=limit*((i-l)*(i-l+1)+(r-i)*(r-i+1))/2;
        if(sum[r]-sum[l-1]-now<=all){
            return i;
        }
    }
    return 0;
}

