            if((i+j)%2){
                addedge(s,id(i,j),val[i][j]);
                for(int k=0;k<4;k++){
                    int ni=i+walk[k][0];
                    int nj=j+walk[k][1];
                    if(ni>=1&&ni<=n&&nj>=1&&nj<=m){
                        addedge(id(i,j),id(ni,nj),INF);
                    }
