// 群岛，C++版
// 一共n个点，每个点有点权，初始时没有边，一共m条操作，类型如下
// 操作 bridge x y    : 如果x和y已经连通，打印no，表示不需要连边
//                      如果x和y不连通，打印yes，然后增加无向边
// 操作 penguins x y  : x的点权变成y
// 操作 excursion x y : 如果x和y不连通，打印impossible
//                      如果x和y连通，打印路径的点权累加和
// 1 <= n <= 3 * 10^4
// 1 <= m <= 3 * 10^5
// 测试链接 : https://www.luogu.com.cn/problem/P4312
// 如下实现是C++的版本，C++版本和java版本逻辑完全一样
// 提交如下代码，可以通过所有测试用例

#include <bits/stdc++.h>

using namespace std;

const int MAXN = 30001;
int n, m;
int arr[MAXN];

int fa[MAXN];
int ls[MAXN];
int rs[MAXN];
int sta[MAXN];
bool rev[MAXN];

int sum[MAXN];

void up(int x) {
   sum[x] = sum[ls[x]] + sum[rs[x]] + arr[x];
}

bool isroot(int x) {
   return ls[fa[x]] != x && rs[fa[x]] != x;
}

int lr(int x) {
   return ls[fa[x]] == x ? 0 : 1;
}

void reverse(int x) {
   if (x != 0) {
       swap(ls[x], rs[x]);
       rev[x] = !rev[x];
   }
}

void down(int x) {
   if (rev[x]) {
       reverse(ls[x]);
       reverse(rs[x]);
       rev[x] = false;
   }
}

void rotate(int x) {
   int f = fa[x], g = fa[f];
   if (lr(x) == 0) {
       ls[f] = rs[x];
       if (ls[f] != 0) {
           fa[ls[f]] = f;
       }
       rs[x] = f;
   } else {
       rs[f] = ls[x];
       if (rs[f] != 0) {
           fa[rs[f]] = f;
       }
       ls[x] = f;
   }
   if (!isroot(f)) {
       if (lr(f) == 0) {
           ls[g] = x;
       } else {
           rs[g] = x;
       }
   }
   fa[f] = x;
   fa[x] = g;
   up(f);
   up(x);
}

void splay(int x) {
   int siz = 0;
   sta[++siz] = x;
   for (int y = x; !isroot(y); y = fa[y]) {
       sta[++siz] = fa[y];
   }
   while (siz != 0) {
       down(sta[siz--]);
   }
   while (!isroot(x)) {
       int f = fa[x];
       if (!isroot(f)) {
           if (lr(x) == lr(f)) {
               rotate(f);
           } else {
               rotate(x);
           }
       }
       rotate(x);
   }
}

void access(int x) {
   for (int y = 0; x != 0; y = x, x = fa[x]) {
       splay(x);
       rs[x] = y;
       up(x);
   }
}

void makeroot(int x) {
   access(x);
   splay(x);
   reverse(x);
}

int findroot(int x) {
   access(x);
   splay(x);
   down(x);
   while (ls[x] != 0) {
       x = ls[x];
       down(x);
   }
   splay(x);
   return x;
}

void split(int x, int y) {
   makeroot(x);
   access(y);
   splay(y);
}

void link(int x, int y) {
   makeroot(x);
   if (findroot(y) != x) {
       fa[x] = y;
   }
}

void cut(int x, int y) {
   makeroot(x);
   if (findroot(y) == x && fa[y] == x && ls[y] == 0 && rs[x] == y) {
       fa[y] = rs[x] = 0;
       up(x);
   }
}

int main() {
   ios::sync_with_stdio(false);
   cin.tie(nullptr);
   cin >> n;
   for (int i = 1; i <= n; i++) {
       cin >> arr[i];
       sum[i] = arr[i];
   }
   cin >> m;
   string op;
   int x, y;
   for (int i = 1; i <= m; i++) {
       cin >> op >> x >> y;
       if (op == "bridge") {
           if (findroot(x) == findroot(y)) {
               cout << "no" << "\n";
           } else {
               cout << "yes" << "\n";
               link(x, y);
           }
       } else if (op == "penguins") {
           splay(x);
           arr[x] = y;
           up(x);
       } else {
           if (findroot(x) != findroot(y)) {
               cout << "impossible" << "\n";
           } else {
               split(x, y);
               cout << sum[y] << "\n";
           }
       }
   }
   return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 4e5+5;
const int g = 3;
const int P = 1004535809;

int n,op,m,invg,invn;
char s[MAXN];
int A[MAXN],B[MAXN];
int inv[MAXN];

int power(int a,int b){
    int ans=1;
    while(b){
        if(b&1){
            ans=(ans*a)%P;
        }
        b>>=1;
        a=(a*a)%P;
    }
    return ans;
}

int rev[MAXN];
void NTT(int *A,int n,int op){
    for(int i=0;i<n;i++){
        rev[i]=(rev[i>>1]>>1)+((i&1)?(n>>1):0);
    }
    for(int i=0;i<n;i++){
        if(i<rev[i]){
            swap(A[i],A[rev[i]]);
        }
    }
    for(int m=2;m<=n;m<<=1){
        int g1=power(op==1?g:invg,(P-1)/m);
        for(int i=0;i<n;i+=m){
            int gk=1;
            for(int j=i;j<i+m/2;j++){
                int x=A[j],y=gk*A[j+m/2]%P;
                A[j]=(x+y)%P;
                A[j+m/2]=(x-y+P)%P;
                gk=gk*g1%P;
            }
        }
    }
}

signed main()
{
    scanf("%lld",&n);
    scanf("%s",s);
    scanf("%lld",&op);
    for(int i=0;i<n;i++){
        scanf("%lld",&A[i]);
    }

    m=0;
    int len=strlen(s);
    for(int i=0;i<len;i++){
        m=(m*10+s[i]-'0')%P;
    }

    len=n;
    n=1;
    while(n<=2*len){
        n<<=1;
    }
    invg=power(g,P-2);
    invn=power(n,P-2);

    inv[1]=1;
    for(int i=2;i<=len;i++){
        inv[i]=(P-(inv[P%i]*(P/i)%P))%P;
    }

    B[0]=1;
    if(op==0){
        for(int i=1;i<len;i++){
            B[i]=(B[i-1]*(m+i-1))%P;
            B[i]=(B[i]*inv[i])%P;
        }
    }
    else{
        for(int i=1;i<len;i++){
            B[i]=(-B[i-1]*(m-i+1+P)%P)%P;
            B[i]=(B[i]*inv[i])%P;
        }
        // for(int i=1;i<len;i++){
        //     cout<<B[i]<<' ';
        // }
        // cout<<endl;
    }

    NTT(A,n,1);
    NTT(B,n,1);
    for(int i=0;i<n;i++){
        A[i]=(A[i]*B[i])%P;
    }
    NTT(A,n,-1);
    for(int i=0;i<len;i++){
        printf("%lld ",A[i]*invn%P);
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 5e5+5;
const int MAXT = 100*MAXN;
const int high = 32;

int n,k;
long long nums[MAXN];
long long ans1;
long long ans2;

int cnt=1;
int root[MAXN];
int pass[MAXT];
int tree[MAXT][2];

inline long long read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

int add(long long num,int i){
    int rt=++cnt;
    tree[rt][0]=tree[i][0];
    tree[rt][1]=tree[i][1];
    pass[rt]=pass[i]+1;
    for (int b = high, path, pre = rt, cur; b >= 0; b--, pre = cur) {
        path = (num >> b) & 1;
        i = tree[i][path];
        cur = ++cnt;
        tree[cur][0] = tree[i][0];
        tree[cur][1] = tree[i][1];
        pass[cur] = pass[i] + 1;
        tree[pre][path] = cur;
    }
    return rt;
}

int query(long long val,long long num,int cur){
    int ans=0;
    int path=0,way=0;
    for(int i=high;i>=0;i--){
        path=(val>>i)&1;
        way=(num>>i)&1;
        if(way==1){
            cur=tree[cur][path^1];
        }
        else{
            ans+=pass[tree[cur][path^1]];
            cur=tree[cur][path];
        }
    }
    ans+=pass[cur];
    return ans;
}

long long check(long long val){
    long long ans=0;
    for(int i=1;i<=n;i++){
        ans+=query(nums[i],val,root[i-1]);
    }
    return ans;
}

long long dfs(int cur,int u,long long val,int op){
    if(cur==0||u==-1){
        return 0;
    }
    long long ans=0;
    ans+=(op^((val>>u)&1))*pass[cur]*(1<<u);
    ans+=dfs(tree[cur][0],u-1,val,0);
    ans+=dfs(tree[cur][1],u-1,val,1);
    return ans;
}

long long fun(long long val,long long num,int cur){
    long long ans=0;
    int path=0;
    int way=0;
    long long sum=0;
    for(int i=high;i>=0;i--){
        path=(val>>i)&1;
        way=(num>>i)&1;
        if(way==1){
            cur=tree[cur][path^1];
        }
        else{
            ans+=sum*pass[tree[cur][path^1]];
            ans+=dfs(tree[cur][path^1],i,val,path^1);
            cur=tree[cur][path];
        }
        sum+=way*(1ll<<i);
        if(cur==0){
            break;
        }
    }
    ans+=num*pass[cur];
    return ans;
}

long long compute(){
    long long ans=0;
    for(int i=1;i<=n;i++){
        ans+=fun(nums[i],ans1,root[i-1]);
    }
    return ans;
}

signed main()
{
    n=read(),k=read();
    for(int i=1;i<=n;i++){
        nums[i]=read();
        nums[i]^=nums[i-1];
    }
    root[0]=add(0,0);
    for(int i=1;i<=n;i++){
        root[i]=add(nums[i],root[i-1]);
    }
    long long l=0,r=4294967295;
    while(l<=r){
        long long mid=(l+r)>>1;
        long long tmp=check(mid);
        // cout<<' '<<mid<<' '<<tmp<<endl;
        if(tmp>=k){
            ans1=mid,ans2=tmp;
            l=mid+1;
        }
        else{
            r=mid-1;
        }
    }
    // cout<<ans1<<' '<<ans2<<endl;
    long long ans=0;
    ans-=(ans2-k)*ans1;
    ans+=compute();
    printf("%lld\n",ans);
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;
const int MAXH = 20;

int n,q,ans;
int p;

int ls[MAXN];
int rs[MAXN];
int val[MAXN];
int lt[MAXN];
int rt[MAXN];
int dfn[MAXN];
int seg[MAXN];
int dfncnt;

int tree[MAXN];

int fa[MAXN][MAXH];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void dfs(int u){
    if(!u){
        return ;
    }
    lt[u]=dfncnt+1;
    dfs(ls[u]);
    dfn[u]=++dfncnt;
    seg[dfncnt]=u;
    dfs(rs[u]);
    rt[u]=dfncnt;
}

inline int lowbit(int x){
    return x&-x;
}

void add(int x,int v){
    while(x<=n){
        tree[x]+=v;
        x+=lowbit(x);
    }
}

int query(int x){
    int ans=0;
    while(x){
        ans+=tree[x];
        x-=lowbit(x);
    }
    return ans;
}

bool check(int i){
    return (query(rt[i]-1)-query(lt[i]-1))==0;
}

void update(int x,int v){
    if(dfn[x]<n){
        if(val[x]>val[seg[dfn[x]+1]]){
            add(dfn[x],-1);
        }
        if(v>val[seg[dfn[x]+1]]){
            add(dfn[x],1);
        }
    }
    if(dfn[x]>1){
        if(val[x]<val[seg[dfn[x]-1]]){
            add(dfn[x]-1,-1);
        }
        if(v<val[seg[dfn[x]-1]]){
            add(dfn[x]-1,1);
        }
    }
    val[x]=v;
}

int solve(int x){
    if(!check(x)){
        return 0;
    }
    int ans=1;
    for(int i=p;i>=0;i--){
        if(fa[x][i]&&check(fa[x][i])){
            x=fa[x][i];
            ans+=(1<<i);
        }
    }
    return ans;
}

int main()
{
    n=read(),q=read();
    p=log2(n)+1;
    for(int i=1;i<=n;i++){
        ls[i]=read(),rs[i]=read();
        if(ls[i]){
            fa[ls[i]][0]=i;
        }
        if(rs[i]){
            fa[rs[i]][0]=i;
        }
    }
    for(int i=1;i<=n;i++){
        val[i]=read();
    }
    for(int i=1;i<=p;i++){
        for(int j=1;j<=n;j++){
            fa[j][i]=fa[fa[j][i-1]][i-1];
        }
    }
    dfs(1);
    for(int i=1;i<n;i++){
        if(val[seg[i]]>val[seg[i+1]]){
            add(i,1);
        }
    }
    for(int i=1;i<=n;i++){
        if(check(i)){
            ans++;
        }
    }

    while(q--){
        int k,x;
        k=read(),x=read();
        ans-=solve(k);
        update(k,x);
        ans+=solve(k);
        printf("%d\n",ans);
    }
    return 0;
}

// FHQ-Treap，不用词频压缩，FHQ-Treap最常规的实现，C++版
// 实现一种结构，支持如下操作，要求单次调用的时间复杂度O(log n)
// 1，增加x，重复加入算多个词频
// 2，删除x，如果有多个，只删掉一个
// 3，查询x的排名，x的排名为，比x小的数的个数+1
// 4，查询数据中排名为x的数
// 5，查询x的前驱，x的前驱为，小于x的数中最大的数，不存在返回整数最小值
// 6，查询x的后继，x的后继为，大于x的数中最小的数，不存在返回整数最大值
// 所有操作的次数 <= 10^5
// -10^7 <= x <= +10^7
// 测试链接 : https://www.luogu.com.cn/problem/P3369
// 如下实现是C++的版本，C++版本和java版本逻辑完全一样
// 提交如下代码，可以通过所有测试用例
//词频不压缩的一个巨大优势是在删除和加入节点时非常方便  这也是fhq最常用的方法
#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;

int head=0;
int cnt=0;
int key[MAXN];
int ls[MAXN];
int rs[MAXN];
int sz[MAXN];
double priority[MAXN];

void up(int x){
    sz[x]=sz[ls[x]]+sz[rs[x]]+1;
}

void split(int l,int r,int i,int val){
    if(i==0){
        rs[l]=ls[r]=0;
    }
    else{
        if(key[i]<=val){
            rs[l]=i;
            split(i,r,rs[i],val);
        }
        else{
            ls[r]=i;
            split(l,i,ls[i],val);
        }
        up(i);
    }
}

int merge(int l,int r){
    if(l==0||r==0){
        return l+r;
    }
    if(priority[l]>priority[r]){
        rs[l]=merge(rs[l],r);
        up(l);
        return l;
    }
    else{
        ls[r]=merge(l,ls[r]);
        up(r);
        return r;
    }
}

void add(int val){
    key[++cnt]=val;
    priority[cnt]=(double)rand()/RAND_MAX;
    sz[cnt]=1;
    split(0,0,head,val);
    head=merge(merge(rs[0],cnt),ls[0]);
}

void del(int val){
    split(0,0,head,val);
    int lm=rs[0];
    int r=ls[0];
    split(0,0,lm,val-1);
    int l=rs[0];
    int m=ls[0];
    head=merge(merge(l,merge(rs[m],ls[m])),r);
}

int getrank(int val){
    split(0,0,head,val-1);
    int ans=sz[rs[0]]+1;
    head=merge(rs[0],ls[0]);
    return ans;
}

int index(int i,int x){
    if(sz[ls[i]]>=x){
        return index(ls[i],x);
    }
    else if(sz[ls[i]]+1<x){
        return index(rs[i],x-sz[ls[i]]-1);
    }
    else{
        return key[i];
    }
}

int pre(int i,int val){
    if(i==0){
        return INT_MIN;
    }
    if(key[i]>=val){
        return pre(ls[i],val);
    }
    else{
        return max(key[i],pre(rs[i],val));
    }
}

int pre(int val){
    return pre(head,val);
}

int suf(int i,int val){
    if(i==0){
        return INT_MAX;
    }
    if(key[i]<=val){
        return suf(rs[i],val);
    }
    else{
        return min(key[i],suf(ls[i],val));
    }
}

int suf(int val){
    return suf(head,val);
}

int index(int x){
    return index(head,x);
}

int main()
{
    int n;
    cin>>n;
    for(int i=1;i<=n;i++){
        int op,x;
        cin>>op>>x;
        if(op==1){
            add(x);
        }
        else if(op==2){
            del(x);
        }
        else if(op==3){
            cout<<getrank(x)<<endl;
        }
        else if(op==4){
            cout<<index(x)<<endl;
        }
        else if(op==5){
            cout<<pre(x)<<endl;
        }
        else if(op==6){
            cout<<suf(x)<<endl;
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 55;
const int MAXM = 1005;

int n,k;
double price[MAXN];
int need[MAXN];
double lowprice[MAXN];

int nodeid[MAXN];
int nodecnt;

struct Edge{
    int u,v;
    double w;
};
Edge edge[MAXM];
int edgecnt;

double in[MAXN];
int pre[MAXN];
int id[MAXN];
int vis[MAXN];

void prepare(){
    for(int i=1;i<=nodecnt;i++){
        pre[i]=0;
        in[i]=INT_MAX;
        id[i]=0;
        vis[i]=0;
    }
}

double zhuliu(){
    double res=0;

    while(true){
        prepare();
        for(int i=1;i<=edgecnt;i++){
            int u=edge[i].u;
            int v=edge[i].v;
            double w=edge[i].w;
            if(u!=v&&w<in[v]){
                in[v]=w;
                pre[v]=u;
            }
        }

        for(int i=1;i<=nodecnt;i++){
            if(i==nodecnt){
                continue;
            }
            res+=in[i];
        }

        int cnt=0;
        int idx=0;

        for(int i=1;i<nodecnt;i++){
            if(vis[i]){
                continue;
            }
            idx++;
            int v=i;
            while(vis[v]!=idx&&!id[v]&&v!=nodecnt){
                vis[v]=idx;
                v=pre[v];
            }
            if(v!=nodecnt&&!id[v]){
                cnt++;
                id[v]=cnt;
                for(int u=pre[v];u!=v;u=pre[u]){
                    id[u]=cnt;
                }
            }
        }

        if(cnt==0){
            break;
        }

        for(int i=1;i<=nodecnt;i++){
            if(!id[i]){
                id[i]=++cnt;
            }
        }

        for(int i=1;i<=edgecnt;i++){
            if(edge[i].u!=edge[i].v){
                edge[i].w-=in[edge[i].v];
            }
            edge[i].u=id[edge[i].u];
            edge[i].v=id[edge[i].v];
        }

        nodecnt=cnt;
    }

    return res;
}

int main()
{
    scanf("%d",&n);
    for(int i=1;i<=n;i++){
        scanf("%lf %d",&price[i],&need[i]);
        lowprice[i]=price[i];
    }
    scanf("%d",&k);
    for(int i=1;i<=k;i++){
        int a,b;
        double p;
        scanf("%d %d %lf",&a,&b,&p);
        if(need[b]&&need[a]){
            lowprice[b]=min(lowprice[b],p);
            edge[++edgecnt]={a,b,p};
        }
    }
    for(int i=1;i<=n;i++){
        if(need[i]){
            edge[++edgecnt]={n+1,i,price[i]};
        }
    }

    for(int i=1;i<=n;i++){
        if(need[i]){
            nodeid[i]=++nodecnt;
        }
    }
    nodeid[n+1]=++nodecnt;

    for(int i=1;i<=edgecnt;i++){
        edge[i].u=nodeid[edge[i].u];
        edge[i].v=nodeid[edge[i].v];
    }

    double ans=zhuliu();
    for(int i=1;i<=n;i++){
        if(need[i]){
            ans+=((need[i]-1)*lowprice[i]);
        }
    }
    printf("%.2lf",ans);
    return 0;
}

