#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;

int arr[MAXN];
int tree[MAXN<<2];
int lazy[MAXN<<2];
int n,m;
struct node{
    int l,r;
}nums[MAXN];

bool cmp(node a,node b){
    return a.r==b.r?a.l>b.l:a.r<b.r;
}

void up(int i){
    tree[i]=min(tree[i<<1],tree[i<<1|1]);
}

void build(int l,int r,int i){
    if(l==r){
        tree[i]=arr[l];
    }
    else{
        int mid=(l+r)/2;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        up(i);
    }
}

void downlazy(int i,int v){
    tree[i]+=v;
    lazy[i]+=v;
}

void down(int i){
    if(lazy[i]){
        downlazy(i<<1,lazy[i]);
        downlazy(i<<1|1,lazy[i]);
        lazy[i]=0;
    }
}

void add(int jobl, int jobr, int jobv, int l, int r, int i) {
    if (jobl <= l && r <= jobr) {
        downlazy(i, jobv);
    } else {
        int mid = (l + r) >> 1;
        down(i);
        if (jobl <= mid) {
            add(jobl, jobr, jobv, l, mid, i << 1);
        }
        if (jobr > mid) {
            add(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);
        }
        up(i);//汇总修改数据
    }
}

int query(int jobl,int jobr,int l,int r,int i){
    if (jobl <= l && r <= jobr) {
        return tree[i];
    } else {
        int ans=INT_MAX;
        int mid = (l + r) >> 1;
        down(i);
        if (jobl <= mid) {
            ans=min(ans,query(jobl, jobr,l, mid, i << 1));
        }
        if (jobr > mid) {
            ans=min(ans,query(jobl, jobr,mid + 1, r, i << 1 | 1));
        }
        return ans;
    }
}

int main()
{
    cin>>n>>m;
    for(int i=1;i<=n;i++){
        cin>>arr[i];
    }
    build(1,n,1);
    for(int i=1;i<=m;i++){
        cin>>nums[i].l>>nums[i].r;
    }
    sort(nums+1,nums+m+1,cmp);
    int ans=0;
    for(int i=1;i<=m;i++){
        if(query(nums[i].l,nums[i].r,1,n,1)>=1){
            add(nums[i].l,nums[i].r,-1,1,n,1);
            ans++;
        }
    }
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int MAXM = 3e6+4e5+5;

int nums[MAXN];
int n;
long long  ans=0;
int tree[MAXM][2];
int cnt=1;
int high;

void insert(int num) {
    int cur = 1;
    for (int i = high, path; i >= 0; i--) {
        path = (num >> i) & 1;
        if (tree[cur][path] == 0) {
            tree[cur][path] = ++cnt;
        }
        cur = tree[cur][path];
    }
}

void build(){
    int maxans=INT_MIN;
    for(int i=1;i<=n;i++){
        maxans=max(maxans,nums[i]);
    }
    high=31-__builtin_clz(maxans);//选择出有效的位数  即不要前缀0
    for(int num:nums){
        insert(num);//将数字插入前缀树中
    }
}

int maxXor(int num) {
    // 最终异或的结果(尽量大)
    int ans = 0;
    // 前缀树目前来到的节点编号
    int cur = 1;
    for (int i = high, status, want; i >= 0; i--) {
        // status : num第i位的状态
        status = (num >> i) & 1;
        // want : num第i位希望遇到的状态
        want = status ^ 1;
        if (tree[cur][want] == 0) { // 询问前缀树，能不能达成
            // 不能达成
            want ^= 1;
        }
        // want变成真的往下走的路
        ans |= (status ^ want) << i;
        cur = tree[cur][want];
    }
    return ans;
}

int main()
{
    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>nums[i];
    }
    build();//将所有的值加入树中
    for (int num : nums) {
        //将每一个数选择一个数字使答案最大
        ans = max(ans,(long long) maxXor(num));
    }
    cout<<ans;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 205;
const int MAXM = 1e4+5;

int n,m;

int x[MAXM];
int y[MAXM];
bool vis[MAXM];
int id[MAXN];

int fa[MAXM<<1];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

int find(int x){
    return x==fa[x]?x:fa[x]=find(fa[x]);
}

bool cross(int x1,int y1,int x2,int y2){
    if (x1 < x2 && x2 < y1 && y1 < y2) {
        return true;
    }
    if (x2 < x1 && x1 < y2 && y2 < y1) {
        return true;
    }
    return false;
}

void un(int x,int y){
    fa[x]=y;
}

bool compute(){
    for(int i=1;i<=m;i++){
        if(vis[i]){
            continue;
        }
        for(int j=i+1;j<=m;j++){
            if(vis[j]){
                continue;
            }
            if(!cross(x[i],y[i],x[j],y[j])){
                continue;
            }

            int fx=find(i);
            int fy=find(j);

            if(fx==fy){
                return false;
            }
            else{
                un(fx,find(j+m));
                un(fy,find(i+m));
            }
        }
    }

    for(int i=1;i<=m;i++){
        if(vis[i]){
            continue;
        }
        if(find(i)==find(i+m)){
            return false;
        }
    }

    return true;
}

