            int p0,p1;
            cin>>p0>>p1;
            go[id][i][0]=p0+1;
            go[id][i][1]=p1+1;
        }
    }

    prepare();

    for(int i=1;i<=k;i++){
        if(dfn[i]==0){
            tarjan(i);
        }
    }

    cout<<compute()<<endl;
    return 0;
}

