    }
    for (int i = 'a'; i <= 'z'; ++i) {
        if (t[i] >= (n + 1) / 2) {
            zyq = i;
        }
    }
    if (zyq < 0) {
        for (int i = 1; i <= n; ++i) {
            qu[s[i]].push_back(i);
        }
        cnt = n >> 1;
        int tot = 0;
        for (int i = 'a'; i <= 'z'; ++i) {
            for (auto it : qu[i]) {
                p[++tot] = it;
            }
        }
        for (int i = 1; i <= (n >> 1); ++i) {
            ans[i].push_back(p[i]);
            ans[i].push_back(p[i + (n >> 1)]);
        }
        if (n & 1) {
            ans[1].push_back(p[n]);
        }
    } else {
        if (t[zyq] == n) {
            cout << "Shuiniao\n";
            return;
        }
        if (t[zyq] == n - 1) {
