        cnt = 2;
        for (int i = 1; i <= n; ++i) {
            if (s[i] != zyq) {
                l = i;
                break;
            }
        }
        for (int i = n; i >= 1; --i) {
            if (s[i] != zyq) {
                r = i;
                break;
            }
        }
        ans[1].push_back(l);
        ans[2].push_back(r);
        for (int i = l + 1; i <= n; ++i) {
            if (s[i] == zyq) {
                ans[1].push_back(i);
            }
        }
        for (int i = 1; i <= l - 1; ++i) {
            if (s[i] == zyq) {
                ans[2].push_back(i);
            }
        }
        for (int i = l + 1; i <= r - 1; ++i) {
            if (s[i] != zyq) {
                ans[++cnt].push_back(i);
            }
        }
        for (int i = 1; i <= cnt; ++i) {
            if (ans[i].size() < 2) {
                if (ans[1].size() > 2) {
                    ans[i].push_back(ans[1].back());
                    ans[1].pop_back();
                } else {
                    ans[i].push_back(ans[2].back());
                    ans[2].pop_back();
                }
