int rs[MAXM];
int cnt=0;

int build(int l, int r) {
    int rt = ++cnt;
    tree[rt] = 0;
    if (l < r) {
        int mid = (l + r) / 2;
        ls[rt] = build(l, mid);
        rs[rt] = build(mid + 1, r);
    }
    return rt;
}

int insert(int jobi, int l, int r, int i) {
//    if(l==1&&r==m){
//        cout<<jobi<<endl;
//    }
    int rt = ++cnt;
    ls[rt] = ls[i];
    rs[rt] = rs[i];
    tree[rt] = tree[i] + 1;
    if (l < r) {
        int mid = (l + r) / 2;
        if (jobi <= mid) {
            ls[rt] = insert(jobi, l, mid, ls[rt]);
        } else {
            rs[rt] = insert(jobi, mid + 1, r, rs[rt]);
        }
    }
    return rt;
}

int query(int l,int r,int u,int v){
    if(l==r){
        return tree[u]>tree[v]?1:0;
    }
    else{
        int mid=(l+r)/2;
        int ans=0;
        ans+=query(l,mid,ls[u],ls[v]);
        ans+=query(mid+1,r,rs[u],rs[v]);
        return ans;
    }
}

