inline int lowbit(int x){
    return x&-x;
}

void add(int x,int v){
    while(x<=m){
        tree[x]=(tree[x]+v)%MOD;
        x+=lowbit(x);
    }
}

int query(int x){
    int ans=0;
    while(x){
        ans=(ans+tree[x])%MOD;
        x-=lowbit(x);
    }
    return ans;
}

