        addedge(v,u,w);
    }
    dfs(1,0);
    for(int i=1;i<=m;i++){
        arr[i]=read();
    }
    compute();
    for(int i=1;i<=m;i++){
        cout<<ans[i]<<endl;
    }
    return 0;
}

