#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const double eps = 1e-6;

int n;
int a[MAXN],b[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

double compute(double x){
    double ans=INT_MIN;
    for(int i=1;i<=n;i++){
        ans=max(ans,a[i]-(a[i]-b[i])*1.0/200000*(100000+x));
    }
    return ans;
}

int main()
{
    n=read();
    for(int i=1;i<=n;i++){
        a[i]=read(),b[i]=read();
    }
    double l=-100000,r=100000,ans;
    while(r-l>=eps){
        double midl=l+(r-l)/3;
        double midr=l+(r-l)*2/3;
        double k1=compute(midl);
        double k2=compute(midr);
        if(k1<k2){
            r=midr;
            ans=midl;
        }
        else{
            l=midl;
            ans=midr;
        }
    }
    printf("%.2lf\n",compute(ans));
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long 

int n,m,k;
int dp[21][21];
int nums[21];
int sum[21];
int ord[11];
priority_queue<int,vector<int>,greater<int>>heap;

int compute(){
    sum[0]=0;
    for(int i=1;i<=2*m;i++){
        sum[i]=sum[i-1]+nums[i];
        // cout<<nums[i]<<' ';
    }
    // cout<<endl;
    for(int i=1;i<=2*m;i++){
        for(int j=1;j<=2*m;j++){
            dp[i][j]=INT_MAX;
        }
    }
    for(int i=1;i<=2*m;i++){
        dp[i][i]=0;
    }
    for(int len=2;len<=m;len++){
        for(int i=1;i<=2*m-len+1;i++){
            int j=i+len-1;
            for(int k=i;k<j;k++){
                dp[i][j]=min(dp[i][j],dp[i][k]+dp[k+1][j]+sum[j]-sum[i-1]);
            }
        }
    }
    int ans=LLONG_MAX;
    for(int i=1;i<=m+1;i++){
        ans=min(ans,dp[i][i+m-1]);
    }
    return ans;
}

signed main()
{
    cin>>n>>m>>k;
    for(int i=1;i<=n;i++){
        int v;
        cin>>v;
        heap.push(v);
    }
