    for(int i=1;i<=k;i++){
        for(int j=1;j<=m;j++){
            int u;
            cin>>u;
            ord[u]=j;
        }
        int all=0;
        for(int j=1;j<=m;j++){
            int u=heap.top();
            heap.pop();
            nums[ord[j]]=u;
            all+=u;
        }
        for(int j=m+1;j<=2*m;j++){
            nums[j]=nums[j-m];
        }
        ans+=compute();
        heap.push(all);
    }
    cout<<ans<<endl;
    return 0;
}

// 左偏树模版题2，数据量增强，C++版
// 依次给定n个非负数字，表示有n个小根堆，每个堆只有一个数
// 实现如下两种操作，操作一共调用m次
// M x y : 第x个数字所在的堆和第y个数字所在的堆合并
//         如果两个数字已经在一个堆或者某个数字已经删除，不进行合并
// K x   : 打印第x个数字所在堆的最小值，并且在堆里删掉这个最小值
//         如果第x个数字已经被删除，也就是找不到所在的堆，打印0
//         若有多个最小值，优先删除编号小的
// 1 <= n <= 10^6
// 1 <= m <= 10^5
// 测试链接 : https://www.luogu.com.cn/problem/P2713
// 如下实现是C++的版本，C++版本和java版本逻辑完全一样
// 提交如下代码，可以通过所有测试用例

#include <bits/stdc++.h>

using namespace std;

const int MAXN = 1000001;
int n, m;
int num[MAXN];
int ls[MAXN];
int rs[MAXN];
int dist[MAXN];
int fa[MAXN];

void prepare() {
    dist[0] = -1;
    for(int i = 1; i <= n; i++) {
        ls[i] = rs[i] = dist[i] = 0;
        fa[i] = i;
    }
}

int find(int i) {
    fa[i] = fa[i] == i ? i : find(fa[i]);
    return fa[i];
}

int merge(int i, int j) {
    if (i == 0 || j == 0) {
        return i + j;
    }
    if (num[i] > num[j] || (num[i] == num[j] && i > j)) {
        int tmp = i;
        i = j;
        j = tmp;
    }
    rs[i] = merge(rs[i], j);
    if (dist[ls[i]] < dist[rs[i]]) {
        int tmp = ls[i];
        ls[i] = rs[i];
        rs[i] = tmp;
    }
    dist[i] = dist[rs[i]] + 1;
    fa[ls[i]] = fa[rs[i]] = i;
    return i;
}

int pop(int i) {
    fa[ls[i]] = ls[i];
    fa[rs[i]] = rs[i];
    fa[i] = merge(ls[i], rs[i]);
    ls[i] = rs[i] = dist[i] = 0;
    return fa[i];
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    prepare();
    for (int i = 1; i <= n; i++) {
        cin >> num[i];
    }
    cin >> m;
    for (int i = 1; i <= m; i++) {
        string op; cin >> op;
        if (op == "M") {
            int x, y; cin >> x >> y;
            if (num[x] != -1 && num[y] != -1) {
                int l = find(x);
                int r = find(y);
                if (l != r) {
                    merge(l, r);
                }
            }
        } else {
            int x; cin >> x;
            if (num[x] == -1) {
                cout << 0 << endl;
            } else {
                int ans = find(x);
                cout << num[ans] << endl;
                pop(ans);
                num[ans] = -1;
            }
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 20;
const int MAXM = 25;
const int MAXV = 1005*MAXN;
const int MAXE = 20*MAXV;
const int INF = 1e9;

int n,m,k,s,t;
int shipcap[MAXM];
int route[MAXN][MAXN];

int dep[MAXV];
int iter[MAXV];

int cnt=2;
int head[MAXV];
int nxt[MAXE];
int to[MAXE];
int now[MAXE];
int cap[MAXE];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    cap[cnt]=w;
    now[cnt]=0;
    head[u]=cnt++;

    nxt[cnt]=head[v];
    to[cnt]=u;
    cap[cnt]=0;
    now[cnt]=0;
    head[v]=cnt++;
}

bool bfs(){
    for(int i=1;i<=t;i++){
        dep[i]=-1;
    }
    queue<int>q;
    dep[s]=0;
    q.push(s);
    while(!q.empty()){
        int u=q.front();
        q.pop();
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            int w=cap[i];
            int k=now[i];
            if(dep[v]<0&&(k<w)){
                dep[v]=dep[u]+1;
                q.push(v);
            }
        }
    }
    return dep[t]>=0;// 如果汇点未被访问到，说明无增广路径
}

int dfs(int u,int f){
    if(u==t){
        return f;
    }
    int flow=0;
    for(int &i=iter[u];i;i=nxt[i]){
        int v=to[i];
        int w=cap[i];
        int k=now[i];
        if(dep[u]+1==dep[v]&&k<w){
            int d=dfs(v,min(f,w-k));
            if(d>0){
                now[i]+=d;
                now[i^1]-=d;
                flow+=d;
                f-=d;
                if(f==0){
                    break;
                }
            }
        }
    }
    return flow;
}

int maxflow(){
    int flow=0;
    while(bfs()){
        for(int i=1;i<=t;i++){
            iter[i]=head[i];
        }
        int maxflow;
        while((maxflow=dfs(s,INF))>0){
            flow+=maxflow;
        }
    }
    return flow;
}

int id(int t,int x){
    if(x==0){
        x=n+1;
    }
    else if(x==-1){
        x=n+2;
    }
    return t*(n+2)+x;
}

bool check(int limit){
    cnt=2;
    s=id(0,0),t=id(limit,n+2);
    for(int i=1;i<=t;i++){
        head[i]=0;
    }
    for(int i=0;i<limit;i++){
        for(int j=-1;j<=n;j++){
            int u=id(i,j);
            int v=id(i+1,j);
            addedge(u,v,INF);
        }
    }
    for(int i=1;i<=m;i++){
        for(int j=0;j<limit;j++){
            int from=route[i][(j%route[i][0])+1];
            int to=route[i][((j+1)%route[i][0])+1];
            int u=id(j,from);
            int v=id(j+1,to);
            addedge(u,v,shipcap[i]);
        }
    }
    int flow=maxflow();
    return flow>=k;
}

int main()
{
    n=read(),m=read(),k=read();
    for(int i=1;i<=m;i++){
        shipcap[i]=read();
        route[i][0]=read();
        for(int j=1;j<=route[i][0];j++){
            route[i][j]=read();
        }
    }
    int l=0,r=1000,ans=-1;
    while(l<=r){
        int mid=(l+r)>>1;
        if(check(mid)){
            ans=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    if(ans==-1){
        cout<<0<<endl;
    }
    else{
        cout<<ans<<endl;
    }
    return 0;
}

