#include<bits/stdc++.h>
using namespace std;
const int MAXN = 5e4+5;

int n;
int arr[MAXN];
int c[MAXN];
long long f[MAXN];
long long ans=0;

int mu[MAXN];
int cnt;
bool vis[MAXN];
int prime[MAXN];

void prepare(int n){
    mu[1] = 1;
    for(int i=2;i<=n;i++){
        if(!vis[i]){
            prime[++cnt] = i;
            mu[i] = -1;
        }
        for(int j=1;j<=cnt&&i*prime[j]<=n;j++){
            int p = prime[j];
            int num = i * p;
            vis[num]=true;

            if(i % p == 0){
                // p 是 i 的最小质因子
                mu[num] = 0;
                break;
            }
            else{
                // p 不是 i 的质因子
                mu[num] = -mu[i];
            }
        }
    }
    for(int i=1;i<=n;i++){
        for(int j=i;j<=n;j+=i){
            f[j]+=1ll*i*mu[i];
        }
    }
}

int main()
{
