#define int long long 
const int MAXN = 1e6+5;

int n,p;
int pre[MAXN];
int val[MAXN];
int ls[MAXN];
int rs[MAXN];
int st[MAXN];
int ans;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void build(){
    int top=0;
    for(int i=1;i<=n;i++){
        int pos=top;
        while(pos>0&&val[st[pos]]>val[i]){
            pos--;
        }
        if(pos>0){
            rs[st[pos]]=i;
        }
        if(pos<top){
            ls[i]=st[pos+1];
        }
        st[++pos]=i;
        top=pos;
    }
}

int calc(int l,int r,int h){
    l=max(l+1,(p+h-1)/h);
    if(l>r){
        return 0;
    }
    return (r-l+1)*(h+1)-pre[r]+pre[l-1];
}

void dfs(int cur,int l,int r){
    // cout<<cur<<' '<<l<<' '<<r<<endl;
    if(ls[cur]){
        dfs(ls[cur],l,cur-1);
    }
    if(rs[cur]){
        dfs(rs[cur],cur+1,r);
    }
    int lt=cur-l,rt=r-cur;
    if(lt>rt){
        swap(lt,rt);
    }
    for(int i=0;i<=lt;i++){
        ans+=calc(i,i+rt+1,val[cur]);
    }
}

