        if((arr[i+1].a==arr[i].a)&&(arr[i+1].b==arr[i].b)&&(arr[i+1].c==arr[i].c)){
            ans[arr[i].i]+=ans[arr[i+1].i]+1;
        }
    }

    cdq(1,n);

    for(int i=1;i<=n;i++){
        cnt[ans[i]]++;
    }
}

