inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

inline int lca(int a,int b){
    if(dep[a]<dep[b]){
        swap(a,b);
    }
    for(int i=p;i>=0;i--){
        if(dep[st[a][i]]>=dep[b]){
            a=st[a][i];
        }
    }
    if(a==b){
        return a;
    }
    for(int i=p;i>=0;i--){
        if(st[a][i]!=st[b][i]){
            a=st[a][i];
            b=st[b][i];
        }
    }
    return st[a][0];
}

//建立dep和st表信息
void dfs(int u,int f){
    dep[u]=dep[f]+1;
    st[u][0]=f;
    for(int i=1;i<=p;i++){
        st[u][i]=st[st[u][i-1]][i-1];
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v==f){
            continue;
        }
        dfs(v,u);
    }
}

//完成树上差分  确立边权
void dfs1(int u,int fa){
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v==fa){
            continue;
        }
        dfs1(v,u);
        weight[i]+=diff[v];
        diff[u]+=diff[v];
        // cout<<u<<' '<<v<<' '<<weight[i]<<endl;
    }
}

void dfs2(int u,int fa,int k){
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v==fa){
            continue;
        }
        dfs2(v,u,k);
    }
    for(int i=1;i<=n;i++){
        if(val[u]<val[i]||val[u]>val[i]+k){
            continue;
        }
        dp[u][i]=0;
        for(int j=head[u];j;j=nxt[j]){
            int v=to[j];
            if(v==fa){
                continue;
            }
            dp[u][i]+=min(dp[v][i],dp[v][0]+weight[j]);
        }
        dp[u][0]=min(dp[u][i],dp[u][0]);
    }
}

bool check(int limit){
    for(int i=1;i<=n;i++){
        for(int j=0;j<=n;j++){
            dp[i][j]=INF;
        }
    }
    dfs2(1,0,limit);
    if(dp[1][0]<=k){
        return true;
    }
    else{
        return false;
    }
}

