    else{
        int mid=(l+r)>>1;
        dfs(l,mid,i<<1,dep+1);
        dfs(mid+1,r,i<<1|1,dep+1);
    }
    for(int i=0;i<=1000;i++){
        dp[i]=tmp[dep][i];
    }
}

