			dp[i][3]=4;
    }
    return dp[n+1][x];
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0),cout.tie(0);
    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>arr[i];
    }
    arr[n+1]=arr[1];//将环改成链
    for(int i=1;i<=4;i++){
        //枚举第一个蛋糕的状态
        if(check(i)){
            int m=i;
            for(int j=n+1;j>=1;j--){
                if(m==1){
                    //这个蛋糕是被左边吃
                    ans[j-1]=(j-1)%n+1;
                }
                else if(m==2){
                    //这个蛋糕是被右边吃
                    ans[j]=(j-1)%n+1;
                }
                else if(m==3){
                    ans[j]=ans[j-1]=(j-1)%n+1;
                }
                m=dp[j][m];//转移状态
            }
            for(int i=1;i<=n;i++){
                cout<<ans[i]<<' ';
            }
            return 0;
        }
    }
    cout<<"NIE"<<endl;
    return 0;
}

