                nums[tot].u=i,nums[tot].v=j,nums[tot].w=arr[i][j];
            }
        }
    }
    sort(nums+1,nums+tot+1,cmp);
    kruskalRebuild();
    dfs(cntu);
    for(int i=1;i<=n;i++){
        printf("%lld ",dp[cntu][i]);
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 105;
const int MAXM = 2005;
const int MOD = 998244353;

int n,m;
int arr[MAXN][MAXM];
int sum[MAXN][MAXM];
long long f[MAXN][MAXN<<1];
long long g[MAXN][MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

int main()
{
    n=read(),m=read();
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            arr[i][j]=read();
            sum[i][0]=(sum[i][0]+arr[i][j])%MOD;//sum[i][0]计算整行的所有值总和
        }
    }
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            sum[i][j]=(sum[i][0]-arr[i][j]+MOD)%MOD;
        }
    }
    //合法的方案数=总方案书-不合法的方案数
    long long ans=0;//这个用于记录所有不合法的方案数
    for(int col=1;col<=m;col++){
        //枚举每一个不合法的列
        for(int i=1;i<=n;i++){
            for(int j=0;j<=2*n;j++){
                f[i][j]=0;//初始化  f[i][j]最终表示的是  前i行中 选定的不合法的列比其他列多(j-n)的方案数
                //这里加上n是为了使得所有量都为正数
            }
        }
        f[0][n] = 1;
        for(int i = 1; i<=n; i++){
            for(int j = n-i; j<=n+i; j++) {
                f[i][j] = (f[i-1][j]+f[i-1][j-1]*arr[i][col]%MOD+f[i-1][j+1]*sum[i][col]%MOD)%MOD;
            }
        }
        for(int j = 1; j<=n; j++){
            ans = (ans+f[n][n+j])%MOD;//计算不合法的方案数
        }
    }
    g[0][0] = 1;
	for(int i = 1; i<=n; i++){
	    for(int j = 0; j<=i; j++){
		    g[i][j] = (g[i-1][j]+(j>0?g[i-1][j-1]*sum[i][0]%MOD:0))%MOD;//计算总方案数
            //g[i][j]表示的前i行选j个总方案数  并且每一行最多只可以选一个
        }
    }
    for(int j = 1; j<=n; j++){
	    ans = (ans-g[n][j]+MOD)%MOD; 
    } 
	cout << ans*(MOD-1)%MOD << endl;//相当于乘-1
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 105;
const int MAXM = 505;
const int MAXK = 10;
const int MAXS = 1024;
const int INF = 1e9;

int n,m,k;

int head[MAXN];
int nxt[MAXM<<1];
int to[MAXM<<1];
int weight[MAXM<<1];
int cnt=1;

int key[MAXK];
int dp[MAXS][MAXN];
bool vis[MAXN];

struct node{
    int u,d;
};
struct compare{
    bool operator()(const node &a,const node &b){
        return a.d>b.d;
    }
};
priority_queue<node,vector<node>,compare>heap;

inline void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    head[u]=cnt++;
}

int main()
{
    scanf("%d %d %d",&n,&m,&k);
    for(int i=1;i<=m;i++){
        int u,v,w;
        scanf("%d %d %d",&u,&v,&w);
        addedge(u,v,w);
        addedge(v,u,w);
    }
    for(int i=0;i<k;i++){
        scanf("%d",&key[i]);
    }
    int statue=(1<<k)-1;
    for(int i=0;i<=statue;i++){
        for(int j=1;j<=n;j++){
            dp[i][j]=INF;
        }
    }
    for(int i=0;i<k;i++){
        dp[1<<i][key[i]]=0;
    }
    for(int s=1;s<=statue;s++){
        for(int sub=(s-1)&s;sub;sub=(sub-1)&s){
            int other=s-sub;
            for(int u=1;u<=n;u++){
                if(dp[sub][u]<INF&&dp[other][u]<INF){
                    dp[s][u]=min(dp[s][u],dp[sub][u]+dp[other][u]);
                }
            }
        }

        for(int i=1;i<=n;i++){
            vis[i]=false;
        }
        for(int u=1;u<=n;u++){
            if(dp[s][u]<INF){
                heap.push({u,dp[s][u]});
            }
        }
        while(!heap.empty()){
            int u=heap.top().u;
            heap.pop();
            if(vis[u]){
                vis[u]=true;
            }
            vis[u]=true;
            for(int i=head[u];i;i=nxt[i]){
                int v=to[i];
                int w=weight[i];
                if(dp[s][v]>dp[s][u]+w){
                    dp[s][v]=dp[s][u]+w;
                    heap.push({v,dp[s][v]});
                }
            }
        }
    }
    int ans=INF;
    for(int i=1;i<=n;i++){
        ans=min(ans,dp[statue][i]);
    }
    cout<<ans<<endl;
    return 0;
}

instruction:
# P2762 太空飞行计划问题

## 题目描述

W 教授正在为国家航天中心计划一系列的太空飞行。每次太空飞行可进行一系列商业性实验而获取利润。现已确定了一个可供选择的实验集合 $ E = \{ E_1, E_2, \cdots, E_m \} $，和进行这些实验需要使用的全部仪器的集合 $ I = \{ I_1, I_2, \cdots, I_n \} $。实验 $ E_j $ 需要用到的仪器是 $ I $ 的子集 $ R_j \subseteq I $。

配置仪器 $ I_k $ 的费用为 $ c_k $ 美元。实验 $ E_j $ 的赞助商已同意为该实验结果支付 $ p_j $ 美元。W 教授的任务是找出一个有效算法，确定在一次太空飞行中要进行哪些实验并因此而配置哪些仪器才能使太空飞行的净收益最大。这里净收益是指进行实验所获得的全部收入与配置仪器的全部费用的差额。

对于给定的实验和仪器配置情况，编程找出净收益最大的试验计划。

## 输入格式

第 $ 1 $ 行有 $ 2 $ 个正整数 $ m $ 和 $ n $。$ m $ 是实验数，$ n $ 是仪器数。接下来的 $ m $ 行，每行是一个实验的有关数据。第一个数赞助商同意支付该实验的费用；接着是该实验需要用到的若干仪器的编号。最后一行的 $ n $ 个数是配置每个仪器的费用。

## 输出格式

第 $ 1 $ 行是实验编号，第 $ 2 $ 行是仪器编号，最后一行是净收益。

## 数据范围与说明

感谢 @FlierKing 提供 spj

$1 \leq n, m \leq 50 ，1 \leq c,p < 2^{31}  $。

这道题数据是在 Windows 生成的，输入数据中所有的换行都是 `\r\n` 而不是 `\n`  
读入某实验需要用到的仪器编号的时候，可以这么读入。(感谢@zhouyonglong的提供)
```cpp
char tools[10000];
memset(tools,0,sizeof tools);
cin.getline(tools,10000);
int ulen=0,tool;
while (sscanf(tools+ulen,"%d",&tool)==1)//之前已经用scanf读完了赞助商同意支付该实验的费用
{//tool是该实验所需仪器的其中一个      
    //这一行，你可以将读进来的编号进行储存、处理，如连边。
    if (tool==0) 
        ulen++;
    else {
        while (tool) {
            tool/=10;
            ulen++;
        }
    }
    ulen++;
}
```

## 样例输入 #1

```text
2 3
10 1 2
25 2 3
5 6 7
```

## 样例输出 #1

```text
1 2
1 2 3
17
```

