using namespace std;

int go(int x,int y)
{
    if (x == 1 && y == 0) { return 3; }
    if (x == 2 && y == 2) { return 4; }
    if(y<=x-y){
    	if(x%2==0) {
            return x/2+(x/2-y)%2;
        }
        if(x%2==1) {
            return (x+1)/2+((x+1)/2-y+1)%2;
        }
    }
    if(y>x-y) {
        return go(x+1,y-1);
    }
}

