    for(int i=1;i<=m;i++){
        nums[i].w=dis[nums[i].u]+dis[nums[i].v]+nums[i].w;
    }
    sort(nums+1,nums+m+1,comp);
    kruskalRebuild();
    dfs(cntu,0);
    for(int i=1;i<=q;i++){
