    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXM = 100007+5;
const int MAX4M = 400028+5;

int n, m, q;
int base0[MAXM], base1[MAXM];
int seg0[MAX4M], seg1[MAX4M];

void build(int node, int l, int r) {
    if (l == r) {
        seg0[node] = base0[l];
        seg1[node] = base1[l];
        return;
    }
    int mid = (l + r) >> 1;
    build(node << 1, l, mid);
    build((node << 1) | 1, mid + 1, r);
    seg0[node] = seg0[node << 1] | seg0[(node << 1) | 1];
    seg1[node] = seg1[node << 1] | seg1[(node << 1) | 1];
}

void update(int node, int l, int r, int pos, int n0, int n1) {
    if (l == r) {
        seg0[node] = n0;
        seg1[node] = n1;
        return;
    }
    int mid = (l + r) >> 1;
    if (pos <= mid) update(node << 1, l, mid, pos, n0, n1);
    else update((node << 1) | 1, mid + 1, r, pos, n0, n1);
    seg0[node] = seg0[node << 1] | seg0[(node << 1) | 1];
    seg1[node] = seg1[node << 1] | seg1[(node << 1) | 1];
}

void query(int node, int l, int r, int ql, int qr, int &res0, int &res1, bool &conflict) {
    if (conflict) return;
    if (ql <= l && r <= qr) {
        int new0 = res0 | seg0[node];
        int new1 = res1 | seg1[node];
        if (new0 & new1) conflict = true;
        res0 = new0;
        res1 = new1;
        return;
    }
    int mid = (l + r) >> 1;
    if (ql <= mid) {
        query(node << 1, l, mid, ql, qr, res0, res1, conflict);
        if (conflict) return;
    }
    if (qr > mid) {
        query((node << 1) | 1, mid + 1, r, ql, qr, res0, res1, conflict);
    }
}

signed main() {
    scanf("%lld %lld %lld", &n, &m, &q);
    char str[35];
    for (int i = 1; i <= m; i++) {
        scanf("%s", str);
        int m0 = 0, m1 = 0;
        for (int j = 0; j < n; j++) {
            if (str[j] == '0') m0 |= (1ll << j);
            else if (str[j] == '1') m1 |= (1ll << j);
        }
        base0[i] = m0;
        base1[i] = m1;
    }

    build(1, 1, m);

    int ans_total = 0;
    while (q--) {
        int opt;
        scanf("%lld", &opt);
        if (opt == 0) {
            int l, r;
            scanf("%lld %lld", &l, &r);
            int res0 = 0, res1 = 0;
            bool conflict = false;
            query(1, 1, m, l, r, res0, res1, conflict);
            if (conflict || (res0 & res1)) {
				continue;
            } else {
                int full_mask = (1ll << n) - 1;
                int free_mask = ~(res0 | res1) & full_mask;
                int cnt = __builtin_popcount(free_mask);
                int result = (1ll << cnt);
                ans_total ^= result;
            }
        } else {
            int pos;
            scanf("%lld %s", &pos, str);
            int m0 = 0, m1 = 0;
            for (int j = 0; j < n; j++) {
                if (str[j] == '0') m0 |= (1ll << j);
                else if (str[j] == '1') m1 |= (1ll << j);
            }
            update(1, 1, m, pos, m0, m1);
        }
    }

    printf("%lld\n", ans_total);
    return 0;
}

// 染色，C++版
// 本题就是讲解161，题目5，讲了树链剖分的解法，这里用lct的解法
// 一共有n个节点，给定n-1条边，节点连成一棵树，每个节点给定初始颜色值
// 连续相同颜色被认为是一段，变化了就认为是另一段
// 比如，112221，有三个颜色段，分别为 11、222、1
// 一共有m条操作，每种操作是如下2种类型中的一种
// 操作 C x y z : x到y的路径上，每个节点的颜色都改为z
// 操作 Q x y   : x到y的路径上，打印有几个颜色段
// 1 <= n、m <= 10^5
// 1 <= 任何时候的颜色值 <= 10^9
// 测试链接 : https://www.luogu.com.cn/problem/P2486
// 如下实现是C++的版本，C++版本和java版本逻辑完全一样
// 提交如下代码，可以通过所有测试用例

#include <bits/stdc++.h>

using namespace std;

const int MAXN = 100001;
int n, m;

int fa[MAXN];
int ls[MAXN];
int rs[MAXN];
int sta[MAXN];
bool rev[MAXN];

int arr[MAXN];
int colorAns[MAXN];
int lcolor[MAXN];
int rcolor[MAXN];

int colorTag[MAXN];

void up(int x) {
    lcolor[x] = ls[x] == 0 ? arr[x] : lcolor[ls[x]];
    rcolor[x] = rs[x] == 0 ? arr[x] : rcolor[rs[x]];
    colorAns[x] = colorAns[ls[x]] + colorAns[rs[x]] + 1;
    if (ls[x] != 0 && rcolor[ls[x]] == arr[x]) {
        colorAns[x]--;
    }
    if (rs[x] != 0 && arr[x] == lcolor[rs[x]]) {
        colorAns[x]--;
    }
}

bool isroot(int x) {
    return ls[fa[x]] != x && rs[fa[x]] != x;
}

int lr(int x) {
    return ls[fa[x]] == x ? 0 : 1;
}

void reverse(int x) {
    if (x != 0) {
        swap(ls[x], rs[x]);
        swap(lcolor[x], rcolor[x]);
        rev[x] = !rev[x];
    }
}

void effect(int x, int c) {
    if (x != 0) {
        arr[x] = c;
        lcolor[x] = c;
        rcolor[x] = c;
        colorAns[x] = 1;
        colorTag[x] = c;
    }
}

void down(int x) {
    if (rev[x]) {
        reverse(ls[x]);
        reverse(rs[x]);
        rev[x] = false;
    }
    if (colorTag[x] != 0) {
        effect(ls[x], colorTag[x]);
        effect(rs[x], colorTag[x]);
        colorTag[x] = 0;
    }
}

void rotate(int x) {
    int f = fa[x], g = fa[f];
    if (lr(x) == 0) {
        ls[f] = rs[x];
        if (ls[f] != 0) {
            fa[ls[f]] = f;
        }
        rs[x] = f;
    } else {
        rs[f] = ls[x];
        if (rs[f] != 0) {
            fa[rs[f]] = f;
        }
        ls[x] = f;
    }
    if (!isroot(f)) {
        if (lr(f) == 0) {
            ls[g] = x;
        } else {
            rs[g] = x;
        }
    }
    fa[f] = x;
    fa[x] = g;
    up(f);
    up(x);
}

void splay(int x) {
    int siz = 0;
    sta[++siz] = x;
    for (int y = x; !isroot(y); y = fa[y]) {
        sta[++siz] = fa[y];
    }
    while (siz != 0) {
        down(sta[siz--]);
    }
    while (!isroot(x)) {
        int f = fa[x];
        if (!isroot(f)) {
            if (lr(x) == lr(f)) {
                rotate(f);
            } else {
                rotate(x);
            }
        }
        rotate(x);
    }
}

void access(int x) {
    for (int y = 0; x != 0; y = x, x = fa[x]) {
        splay(x);
        rs[x] = y;
        up(x);
    }
}

void makeroot(int x) {
    access(x);
    splay(x);
    reverse(x);
}

int findroot(int x) {
    access(x);
    splay(x);
    down(x);
    while (ls[x] != 0) {
        x = ls[x];
        down(x);
    }
    splay(x);
    return x;
}

void split(int x, int y) {
    makeroot(x);
    access(y);
    splay(y);
}

void link(int x, int y) {
    makeroot(x);
    if (findroot(y) != x) {
        fa[x] = y;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m;
    for (int i = 1; i <= n; i++) {
        cin >> arr[i];
        lcolor[i] = arr[i];
        rcolor[i] = arr[i];
        colorAns[i] = 1;
    }
    for (int i = 1, x, y; i < n; i++) {
        cin >> x >> y;
        link(x, y);
    }
    for (int i = 1, x, y, c; i <= m; i++) {
        string op;
        cin >> op;
        if (op == "C") {
            cin >> x >> y >> c;
            split(x, y);
            effect(y, c);
        } else {
            cin >> x >> y;
            split(x, y);
            cout << colorAns[y] << "\n";
        }
    }
    return 0;
}

