        fa[i]=i;                 //并查集，让自己是自己爸爸
	for(int k=1;k<=n;++k)
        for(int i=1;i<=n;++i)
            for(int j=1;j<=n;++j)
                if(vis[i][j]||(vis[i][k]&&vis[k][j]))
                    vis[i][j]=1;              //标记白点
	for(int i=1;i<=n;++i)
        for(int j=1;j<=n;++j)
            if(vis[i][j]==1)
                fa[j]=fa[i];
	for(int i=1;i<=n;++i)
        if(fa[i]==i)
            ans++;                     //累加光盘数
	printf("%d",ans);
	return 0;                  //大功告成，程序拜拜！
}

