inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    head[u]=cnt++;
}

void compute(int k1,int b1,int k2,int b2){
    if(k1==k2&&b1==b2){
        return ;
    }
    if(k1==k2&&b1!=b2){
        return ;
    }
    x=(b2-b1)*1.0/(k1-k2);
}

void dfs(int u,int f,int wei,int top){
    if(fa[u]==top){
        compute(k[u],b[u],-k[f],wei-b[f]);
        return ;
    }
    k[u]=-k[f],b[u]=wei-b[f],fa[u]=top;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        int w=weight[i];
        if(v==f){
            continue;
        }
        dfs(v,u,w,top);
    }
}

