void msort(int s,int t)
{
    if(s==t)return ;
    int mid=(s+t)/2;
    msort(s,mid);msort(mid+1,t);
    int i=s,k=s,j=mid+1;
    while(i<=mid && j<=t){
        if(x[i]<=x[j]){
            p[k]=x[i];
            ++k;++i;

        }else{
            p[k]=x[j];
            ++k;++j;
            ans=(ans+mid-i+1)%mod;
			//此处找到逆序对，mid-i~mid中数全都与j构成逆序，还会少算一个，+1;
        }
    }
    while(i<=mid){
        p[k]=x[i];
        ++k;++i;
    }
    while(j<=t){
        p[k]=x[j];
        ++k;++j;
    }
    for(int i=s;i<=t;i++){
        x[i]=p[i];
    }
}

