{
    n=read();
    for(int i=1;i<=n;i++){
        fa[i]=read();
    }
    for(int i=1;i<=n;i++){
        val[i]=read();
    }
    prepare();
    dfs(1);
    compute(1,m,root[1]);
    long long ans=0;
    for(int i=1;i<=m;i++){
        ans=(ans+(1ll*i*arr[i])%MOD*D[i]%MOD*D[i]%MOD)%MOD;
    }
    cout<<ans<<endl;
    return 0;
}

