#include <bits/stdc++.h>
using namespace std;

const int MAXN = 500005;
const int MAXP = 1000005;
const int MAXT = 6000000;
const int MAXE = 12000000;

int n;

// 两个候选字符串
string s[MAXN << 1];

// 2-SAT图
int head[MAXT];
int nxt[MAXE];
int to[MAXE];
int cntg;

void addEdge(int u,int v){
    nxt[++cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg;
}

// Trie
int trie[MAXP][2];
int faTrie[MAXP];
int trieCnt=1;

vector<int> endNode[MAXP];

// Trie树
int headT[MAXP];
int nxtT[MAXP<<1];
int toT[MAXP<<1];
int cntT;

void addTrieEdge(int u,int v){
    nxtT[++cntT]=headT[u];
    toT[cntT]=v;
    headT[u]=cntT;
}


// HLD
int dep[MAXP];
int siz[MAXP];
int son[MAXP];
int top[MAXP];
int dfn[MAXP];
int out[MAXP];
int revv[MAXP];
int dfsCnt;


void dfs1(int u){
    siz[u]=1;
    for(int e=headT[u];e;e=nxtT[e]){
        int v=toT[e];
        dep[v]=dep[u]+1;
        dfs1(v);
        siz[u]+=siz[v];
        if(!son[u]||siz[v]>siz[son[u]])
            son[u]=v;
    }
}

void dfs2(int u,int tp){
    top[u]=tp;
    dfn[u]=++dfsCnt;
    revv[dfsCnt]=u;

    if(son[u])
        dfs2(son[u],tp);

    for(int e=headT[u];e;e=nxtT[e]){
        int v=toT[e];
        if(v!=son[u])
            dfs2(v,v);
    }

    out[u]=dfsCnt;
}


// 线段树
int ls[MAXT];
int rs[MAXT];
int segRoot;
int tot;


void buildSeg(int l,int r,int rt){
    if(l==r){
        int u=revv[l];

        // Trie节点上的所有字符串
        for(int x:endNode[u]){
            addEdge(rt,n-x);
        }
        return;
    }

    int mid=(l+r)>>1;

    ls[rt]=++tot;
    rs[rt]=++tot;

    buildSeg(l,mid,ls[rt]);
    buildSeg(mid+1,r,rs[rt]);

    addEdge(rt,ls[rt]);
    addEdge(rt,rs[rt]);
}


void rangeAdd(int rt,int l,int r,int L,int R,int from){
    if(L>R)
        return;

    if(L<=l&&r<=R){
        addEdge(from,rt);
        return;
    }

    int mid=(l+r)>>1;

    if(L<=mid)
        rangeAdd(ls[rt],l,mid,L,R,from);

    if(R>mid)
        rangeAdd(rs[rt],mid+1,r,L,R,from);
}


// 树链剖分路径
void pathAdd(int x,int y,int from){
    while(top[x]!=top[y]){
        if(dep[top[x]]<dep[top[y]])
            swap(x,y);

        rangeAdd(segRoot,1,trieCnt,
                 dfn[top[x]],dfn[x],from);

        x=faTrie[top[x]];
    }

    if(dep[x]>dep[y])
        swap(x,y);

    rangeAdd(segRoot,1,trieCnt,
             dfn[x],dfn[y],from);
}


// SCC
int dfnS[MAXT];
int low[MAXT];
int sta[MAXT];
int ins[MAXT];
int belong[MAXT];
int idx,topS,scc;


void tarjan(int u){
    dfnS[u]=low[u]=++idx;
    sta[++topS]=u;
    ins[u]=1;

    for(int e=head[u];e;e=nxt[e]){
        int v=to[e];

        if(!dfnS[v]){
            tarjan(v);
            low[u]=min(low[u],low[v]);
        }
        else if(ins[v]){
            low[u]=min(low[u],dfnS[v]);
        }
    }

    if(dfnS[u]==low[u]){
        ++scc;

        while(1){
            int x=sta[topS--];
            ins[x]=0;
            belong[x]=scc;

            if(x==u)
                break;
        }
    }
}


int other(int x){
    if(x<=n)
        return x+n;
    return x-n;
}


// 输入处理
void addString(int id,string str){
    int pos=-1;

    for(int i=0;i<(int)str.size();i++){
        if(str[i]=='?'){
            pos=i;
            break;
        }
    }

    if(pos==-1){
        s[id]=str;
        s[id+n]=str;

        if(str[0]=='0')
            addEdge(id+n,id);
        else
            addEdge(id,id+n);

        return;
    }

    str[pos]='0';
    s[id]=str;

    str[pos]='1';
    s[id+n]=str;
}


int main(){

    ios::sync_with_stdio(false);
    cin.tie(nullptr);


    cin>>n;


    for(int i=1;i<=n;i++){
        string x;
        cin>>x;
        addString(i,x);
    }


    // 建Trie
    for(int i=1;i<=2*n;i++){

        int u=1;

        for(char c:s[i]){

            int v=c-'0';

            if(!trie[u][v]){
                trie[u][v]=++trieCnt;
                faTrie[trieCnt]=u;

                addTrieEdge(u,trieCnt);
            }

            u=trie[u][v];
        }

        endNode[u].push_back(i);
    }


    // Trie树HLD
    dep[1]=1;
    dfs1(1);
    dfs2(1,1);


    // 线段树节点从2n之后开始
    tot=2*n;
    segRoot=++tot;

    buildSeg(1,trieCnt,segRoot);


    // 建约束

    for(int i=1;i<=2*n;i++){

        int u=1;

        for(char c:s[i])
            u=trie[u][c-'0'];


        // 同一个节点字符串冲突
        for(int x:endNode[u]){
            if(x!=i)
                addEdge(i,other(x));
        }


        // 后代冲突
        for(int v=0;v<2;v++){

            int sonNode=trie[u][v];

            if(sonNode){

                rangeAdd(segRoot,1,trieCnt,
                         dfn[sonNode],
                         out[sonNode],
                         i);
            }
        }


        // 祖先冲突
        if(u!=1)
            pathAdd(1,faTrie[u],i);
    }


    for(int i=1;i<=tot;i++){
        if(!dfnS[i])
            tarjan(i);
    }


    for(int i=1;i<=n;i++){

        if(belong[i]==belong[i+n]){
            cout<<"NO\n";
            return 0;
        }
    }


    cout<<"YES\n";

    for(int i=1;i<=n;i++){

        if(belong[i]<belong[i+n])
            cout<<s[i]<<"\n";
        else
            cout<<s[i+n]<<"\n";
    }

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 3e3+5;
const int MAXM = 5e6+5;
const int INF = 1e10;

int n,m,s,t;

int dep[MAXN];
int iter[MAXN];

int head[MAXN];
int nxt[MAXM];
int to[MAXM];
int now[MAXM];
int cap[MAXM];
int cnt=2;

int son[MAXN];

void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    cap[cnt]=w;
    head[u]=cnt++;
}

//BFS构建分层图，并判断是否存在增广路径
bool bfs(){
    for(int i=1;i<=n;i++){
        dep[i]=-1;
    }
    queue<int>q;
    dep[s]=0;
    q.push(s);
    while(!q.empty()){
        int u=q.front();
        q.pop();
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            int w=cap[i];
            int k=now[i];
            if(dep[v]<0&&(k<w)){
                dep[v]=dep[u]+1;
                q.push(v);
            }
        }
    }
    return dep[t]>=0;// 如果汇点未被访问到，说明无增广路径
}

// DFS寻找增广路径（多路增广）
//多路增广的含义是来到了一个节点 不仅仅是只去一条边增广  而是去多条边一起增广
int dfs(int u,int f){
    //表示当前来到了u节点 有f的流量可供使用  f就是目前这条路最多可以消耗掉的流量
    if(u==t){
        return f;
    }
    int flow=0;
    for(int &i=iter[u];i;i=nxt[i]){
        //注意这里是引用  iter会随着i发生变化
        int v=to[i];
        int w=cap[i];
        int k=now[i];
        if(dep[u]+1==dep[v]&&k<w){
            int d=dfs(v,min(f,w-k));
            if(d>0){
                now[i]+=d;
                now[i^1]-=d;//更新反向边
                flow+=d;
                f-=d;
                if(f==0){
                    break;
                }
            }
        }
    }
    return flow;
}

// Dinic算法主函数
int maxflow(){
    int flow=0;
    while(bfs()){
        //当前弧全部初始化为最初值
        for(int i=1;i<=n;i++){
            iter[i]=head[i];
        }
        int maxflow;
        while((maxflow=dfs(s,INF))>0){
            flow+=maxflow;
        }
    }
    return flow;
}

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

signed main()
{
    int ans=0;
    n=read();
    s=n+2,t=n+1;
    for(int i=1;i<=n;i++){
        int w=read();
        ans+=w;
        addedge(s,i,w);
        addedge(i,s,0);
    }
    for(int i=1;i<=n;i++){
        int w=read();
        ans+=w;
        addedge(i,t,w);
        addedge(t,i,0);
    }
    int tot=n+2;
    m=read();
    for(int i=1;i<=m;i++){
        int k=read();
        for(int j=1;j<=k;j++){
            son[j]=read();
        }
        int val1=read();
        int val2=read();
        ans+=(val1+val2);
        addedge(s,tot+1,val1);
        addedge(tot+1,s,0);
        addedge(tot+2,t,val2);
        addedge(t,tot+2,0);
        for(int j=1;j<=k;j++){
            addedge(tot+1,son[j],INF);
            addedge(son[j],tot+1,0);
            addedge(son[j],tot+2,INF);
            addedge(tot+2,son[j],0);
        }
        tot+=2;
    }
    n=tot;
    cout<<(ans-maxflow())<<endl;
