void del(int x){
    cnt[x]--;
    if(cnt[x]==0){
        bs1[x]=0;
        bs2[OFFSET-x]=0;
    }
}

bool calc(int op,int x){
    if(op==1){
        return (bs1&(bs1>>x)).any();
    }
    else if(op==2){
        return (bs1&(bs2>>(OFFSET-x))).any();
    }
    else if(op==3){
        for(int f=1;f*f<=x;f++){
            if(x%f==0&&bs1[f]&&bs1[x/f]){
                return true;
            }
        }
        return false;
    }
    else{
        for(int i=1;i*x<=OFFSET;i++){
            if(bs1[i]&&bs1[i*x]){
                return true;
            }
        }
        return false;
    }
}

