void special() {
    for (int x = 1; x < blen; x++) {
        if (headq[x] != 0) {
            memset(pre, 0, sizeof(int) * (OFFSET + 1));
            memset(dp, 0, sizeof(int) * (n + 1));
            for (int i = 1; i <= n; i++) {
                int v = val[i];
                pre[v] = i;
                dp[i] = dp[i-1];
                if (v * x <= OFFSET) {
                    dp[i] = max(dp[i], pre[v * x]);
