                if (v % x == 0) {
                    dp[i] = max(dp[i], pre[v / x]);
                }
            }
            for (int q = headq[x]; q > 0; q = nxtq[q]) {
                int l = ql[q];
                int r = qr[q];
                int id = qid[q];
                ans[id] = (l <= dp[r]);
            }
        }
    }
}

