	return fa[x]=find(fa[x]);
}
void merge(int x,int y,int x_,int y_){
	int s1=(x-1)*m+y,s2=(x_-1)*m+y_;
	int u=find(s1),v=find(s2);
	if(u!=v) fa[v]=u;
