		for(int j=1;j<=m;j++){
			int x;
			scanf("%d",&x);
			int ch=(int)str[i][j-1],p,q;
			if(ch==117) p=i-x,q=j;
			else if(ch==100) p=i+x,q=j;
			else if(ch==108) p=i,q=j-x;
			else p=i,q=j+x;
			if(p<1||q<1||p>n||q>m) continue;
			merge(i,j,p,q);
			d[(p-1)*m+q]++;
		}
