int X[42], Y[42];
map<pair<int, int>, map<int, int>> cntMap; // {x,y} -> {count: 使用k个向量的方案数}
int ans[42];

void dfs1(int u, int x, int y, int now) {
    if (u == n/2 + 1) {
        cntMap[{x, y}][now]++;
        return;
    }
    dfs1(u + 1, x + X[u], y + Y[u], now + 1);
    dfs1(u + 1, x, y, now);
}

void dfs2(int u, int x, int y, int now) {
    if (u == n + 1) {
        auto it = cntMap.find({X[n+1] - x, Y[n+1] - y});
        if (it != cntMap.end()) {
            for (auto& p : it->second) {
                ans[now + p.first] += p.second;
            }
        }
        return;
    }
    dfs2(u + 1, x + X[u], y + Y[u], now + 1);
    dfs2(u + 1, x, y, now);
}

signed main() {
    cin >> n;
    cin >> X[n+1] >> Y[n+1];
    for (int i = 1; i <= n; i++) {
        cin >> X[i] >> Y[i];
    }
    dfs1(1, 0, 0, 0);
    dfs2(n/2 + 1, 0, 0, 0);
    for (int i = 1; i <= n; i++) {
        cout << ans[i] << endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1501;
const int MAXM = 50001;

auto compare = [](const pair<int, int>& left, const pair<int, int>& right) {
    return left.second > right.second;
};

priority_queue<pair<int, int>, vector<pair<int, int>>, decltype(compare)> heap(compare);
int n,m;
int head[MAXN];
int Next[MAXM];
int to[MAXM];
int weight[MAXM];
int cnt=1;
bool vis[MAXN];
int dis[MAXN];

int main()
{
    cin>>n>>m;
    for(int i=1,u,v,w;i<=m;i++){
        cin>>u>>v>>w;
        Next[cnt]=head[u];
        to[cnt]=v;
        weight[cnt]=-w;
        head[u]=cnt++;
    }
    for(int i=1;i<=n;i++){
        dis[i]=INT_MAX;
    }
    dis[1]=0;
    heap.push({1,0});
    while(!heap.empty()){
        int u=heap.top().first;
        heap.pop();
        if(vis[u]){
            continue;
        }
        vis[u]=true;
        for(int i=head[u];i>0;i=Next[i]){
            int v=to[i];
            int w=weight[i];
            if(!vis[v]&&dis[u]<dis[v]-w){
                dis[v]=w+dis[u];
                heap.push({v,dis[v]});
            }
        }
    }
    if(dis[n]=INT_MAX)
        dis[n]=1;
    cout<<dis[n];
    return 0;
}

