#include <vector>
using namespace std;

const int MAXN = 100005;
int degree[MAXN];

void solve() {
    int n;
    scanf("%d", &n);

    // 初始化度数数组
    for (int i = 1; i <= n; i++) {
        degree[i] = 0;
    }

    // 读入边并统计度数
    for (int i = 1; i < n; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        degree[u]++;
        degree[v]++;
    }

    // 检查是否存在度数为偶数的节点
    for (int i = 1; i <= n; i++) {
        if (degree[i] % 2 == 0) {
            printf("Hifuu\n");
            return;
        }
    }

    // 所有节点度数都是奇数
    printf("Luna\n");
}

int main() {
    int T;
    scanf("%d", &T);
    while (T--) {
        solve();
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 3e4+5;
const int MAXH = 29;
const int MAXK = MAXN*40;

int n;
int p,q,all;
int val[MAXN];
map<int,int>mp;

int in[MAXN];
int out[MAXN];

bool tag[MAXN][2];
int ok[MAXN][2];

int cnt=1;
int trie[MAXK][2];

int fa[MAXN];
int sz[MAXN];
int son[MAXN];

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int weight[MAXN<<1];
int cntg=1;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v,int w){
    nxt[cntg]=head[u];
    to[cntg]=v;
    weight[cntg]=w;
    head[u]=cntg++;
}

void dfs1(int u,int f){
    fa[u]=f;
    sz[u]=1;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        int w=weight[i];
        if(v!=f){
            val[v]=val[u]^w;
            dfs1(v,u);
            sz[u]+=sz[v];
            if(sz[son[u]]<sz[v]){
                son[u]=v;
            }
        }
    }
}

int find(int val){
    int cur=1;
    int ans=0;
    for(int i=MAXH;i>=0;i--){
        int best=1-((val>>i)&1);
        if(trie[cur][best]){
            ans+=(1<<i);
            cur=trie[cur][best];
        }
        else{
            cur=trie[cur][1-best];
        }
    }
    return ans;
}

void insert(int val){
    int cur=1;
    for(int i=MAXH;i>=0;i--){
        int path=(val>>i)&1;
        if(trie[cur][path]==0){
            trie[cur][path]=++cnt;
        }
        cur=trie[cur][path];
    }
}

void clear(){
    for(int i=1;i<=cnt;i++){
        trie[i][0]=trie[i][1]=0;
    }
    all=0;
    cnt=1;
}

void dfs(int u){
    insert(val[u]);
    all=max(all,find(val[u]));
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa[u]){
            dfs(v);
        }
    }
}

void dfs2(int u,int keep){
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa[u]&&v!=son[u]){
            dfs2(v,0);
        }
    }
    if(son[u]){
        dfs2(son[u],1);
    }
    insert(val[u]);
    all=max(find(val[u]),all);
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa[u]&&v!=son[u]){
            dfs(v);
        }
    }
    in[u]=all;
    if(keep==0){
        clear();
    }
}

int main()
{
    n=read();
    for(int i=1;i<n;i++){
        int u,v,w;
        u=read(),v=read(),w=read();
        addedge(u,v,w);
        addedge(v,u,w);
    }
    dfs1(1,0);
    for(int i=n;i>=1;i--){
        mp[val[i]]=i;
    }
    for(int i=1;i<=n;i++){
        insert(val[i]);
        int ans=find(val[i]);
        if(all<=ans){
            all=ans;
            p=i,q=mp[all^val[i]];
        }
    }

    // cout<<p<<' '<<q<<' '<<all<<endl;

    while(p!=0){
        tag[p][0]=true;
        ok[fa[p]][0]=p;
        p=fa[p];
    }
    while(q!=0){
        tag[q][1]=true;
        ok[fa[q]][1]=q;
        q=fa[q];
    }
    for(int i=1;i<=n;i++){
        if(!tag[i][0]&&!tag[i][1]){
            // cout<<i<<endl;
            out[i]=all;
        }
    }

    clear();
    int u=1;
    while(tag[u][0]){
        out[u]=all;
        insert(val[u]);
        all=max(all,find(val[u]));
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            if(v!=ok[u][0]&&v!=fa[u]){
                dfs(v);
            }
        }
        u=ok[u][0];
    }

    clear();
    u=1;
    while(tag[u][1]){
        out[u]=all;
        insert(val[u]);
        all=max(all,find(val[u]));
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            if(v!=ok[u][1]&&v!=fa[u]){
                dfs(v);
            }
        }
        u=ok[u][1];
    }
    out[1]=INT_MIN;

    clear();
    dfs2(1,1);
    int ans=0;
    for(int i=1;i<=n;i++){
        // cout<<i<<":  "<<in[i]<<' '<<out[i]<<endl;
        ans=max(ans,in[i]+out[i]);
    }
    printf("%d\n",ans);
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 150005;
const int MAXV = 1e6+5;

int n,m;
int val[MAXN];

struct Update{
    int pos,val;
};
Update update[MAXN];

struct Query{
    int l,r,t,id;
};
Query query[MAXN];

int cntq,cntu;
int ans[MAXN];

int bi[MAXN];

int kind;
int cnt[MAXV];

bool cmp(Query &a,Query &b){
    if(bi[a.l]!=bi[b.l]){
        return bi[a.l]<bi[b.l];
    }
    if(bi[a.r]!=bi[b.r]){
        return bi[a.r]<bi[b.r];
    }
    return a.t<b.t;
}

void prepare(){
    int blen=max(1.0,pow(n,2.0/3));
    for(int i=1;i<=n;i++){
        bi[i]=(i+blen-1)/blen;
    }

    sort(query+1,query+cntq+1,cmp);
}

void add(int val){
    cnt[val]++;
    if(cnt[val]==1){
        kind++;
    }
}

void del(int val){
    cnt[val]--;
    if(cnt[val]==0){
        kind--;
    }
}

void movetime(int jobl,int jobr,int t){
    int pos=update[t].pos;
    int v=update[t].val;
    if(jobl<=pos&&pos<=jobr){
        del(val[pos]);
        add(v);
    }
    swap(val[pos],update[t].val);
}

void compute(){
    int winl=1,winr=0,wint=0;
    for(int i=1;i<=cntq;i++){
        int l=query[i].l;
        int r=query[i].r;
        int t=query[i].t;
        int id=query[i].id;

        while(winl>l){
            add(val[--winl]);
        }
        while(winr<r){
            add(val[++winr]);
        }
        while(winl<l){
            del(val[winl++]);
        }
        while(winr>r){
            del(val[winr--]);
        }
        while(wint<t){
            movetime(l,r,++wint);
        }
        while(wint>t){
            movetime(l,r,wint--);
        }

        ans[id]=kind;
    }
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m;
    for(int i=1;i<=n;i++){
        cin>>val[i];
    }
    for(int i=1;i<=m;i++){
        char op;
        cin>>op;
        if(op=='Q'){
            ++cntq;
            int l,r;
            cin>>l>>r;
            query[cntq]={l,r,cntu,cntq};
        }
        else{
            int pos,val;
            cin>>pos>>val;
            ++cntu;
            update[cntu]={pos,val};
        }
    }

    prepare();
    compute();

    for(int i=1;i<=cntq;i++){
        cout<<ans[i]<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;
const int INF = 1e9;

int n,m;

int top;
int sta[MAXN];

int head;
int ls[MAXN];
int rs[MAXN];
int sz[MAXN];
int sum[MAXN];
int key[MAXN];
double priority[MAXN];
int all[MAXN];
int premax[MAXN];
int sufmax[MAXN];
bool change[MAXN];
int tag[MAXN];
bool rev[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void up(int i){
    sz[i]=1+sz[ls[i]]+sz[rs[i]];
    sum[i]=sum[ls[i]]+sum[rs[i]]+key[i];
    premax[i]=max(premax[ls[i]],sum[ls[i]]+key[i]+premax[rs[i]]);
    sufmax[i]=max(sufmax[rs[i]],sum[rs[i]]+key[i]+sufmax[ls[i]]);
    all[i]=max(max(all[ls[i]],all[rs[i]]),key[i]+sufmax[ls[i]]+premax[rs[i]]);
}

int newnode(int val){
    int cnt=sta[top--];
    sz[cnt]=1;
    key[cnt]=val,sum[cnt]=val;
    all[cnt]=val,premax[cnt]=max(0,val),sufmax[cnt]=max(0,val);
    ls[cnt]=rs[cnt]=0;
    change[cnt]=0,rev[cnt]=0;
    priority[cnt]=(double)rand()/RAND_MAX;
    return cnt;
}

void lazyreverse(int i){
    if(i==0){
        return ;
    }
    rev[i]^=1;
    swap(premax[i],sufmax[i]);
    swap(ls[i],rs[i]);
}

void lazyreplace(int i,int v){
    if(i==0){
        return ;
    }
    key[i]=v;
    sum[i]=v*sz[i];
    rev[i]=false;
    premax[i]=max(0,sum[i]);
    sufmax[i]=max(0,sum[i]);
    all[i]=max(v,sum[i]);
    change[i]=true;
    tag[i]=v;
}

void down(int i){
    if(i==0){
        return ;
    }
    if(rev[i]){
        if(ls[i]){
            lazyreverse(ls[i]);
        }
        if(rs[i]){
            lazyreverse(rs[i]);
        }
        rev[i]=false;
    }
    if(change[i]){
        if(ls[i]){
            lazyreplace(ls[i],tag[i]);
        }
        if(rs[i]){
            lazyreplace(rs[i],tag[i]);
        }
        change[i]=false;
    }
}

void split(int l,int r,int i,int rk){
    if(i==0){
        rs[l]=ls[r]=0;
    }
    else{
        down(i);
        if(sz[ls[i]]+1<=rk){
            rs[l]=i;
            split(i,r,rs[i],rk-sz[ls[i]]-1);
        }
        else{
            ls[r]=i;
            split(l,i,ls[i],rk);
        }
        up(i);
    }
}

int merge(int l,int r){
    if(l==0||r==0){
        return l+r;
    }
    if (priority[l] >= priority[r]) {
        down(l);//下发懒信息
        rs[l] = merge(rs[l], r);
        up(l);
        return l;
    } else {
        down(r);
        ls[r] = merge(l, ls[r]);
        up(r);
        return r;
    }
}

void freenode(int u){
    if(u==0){
        return ;
    }
    sta[++top]=u;
    if(ls[u]){
        freenode(ls[u]);
    }
    if(rs[u]){
        freenode(rs[u]);
    }
}

void get(int rk){
    int u=head;
    while(rk){
        down(u);
        if(sz[ls[u]]+1==rk){
            cout<<key[u]<<endl;
            break;
        }
        else if(sz[ls[u]]+1<rk){
            rk-=sz[ls[u]]+1;
            u=rs[u];
        }
        else{
            u=ls[u];
        }
    }
}

int main()
{
    all[0]=-INF;
    for(int i=1;i<MAXN;i++){
        sta[i]=i;
    }
    top=MAXN-1;

    n=read(),m=read();
    for(int i=1;i<=n;i++){
        int val=read();
        head=merge(head,newnode(val));
    }

    while(m--){
        string s;
        int x;
        cin>>s>>x;
        if(s[0]=='I'){
            int t=read();
            split(0,0,head,x);
            int l=rs[0];
            int r=ls[0];
            for(int i=1;i<=t;i++){
                int val=read();
                l=merge(l,newnode(val));
            }
            head=merge(l,r);
        }
        else if(s[0]=='D'){
            int t=read();
            split(0,0,head,x+t-1);
            int lm=rs[0];
            int r=ls[0];
            split(0,0,lm,x-1);
            freenode(ls[0]);
            head=merge(rs[0],r);
        }
        else if(s[0]=='R'){
            int t=read();
            split(0,0,head,x+t-1);
            int lm=rs[0];
            int r=ls[0];
            split(0,0,lm,x-1);
            lazyreverse(ls[0]);
            head=merge(merge(rs[0],ls[0]),r);
        }
        else if(s[0]=='M'){
            int t=read();
            split(0,0,head,x+t-1);
            int lm=rs[0];
            int r=ls[0];
            split(0,0,lm,x-1);
            if((int)s.length()==7){
                cout<<all[ls[0]]<<endl;
            }
            else{
                int v=read();
                lazyreplace(ls[0],v);
            }
            head=merge(merge(rs[0],ls[0]),r);
        }
        else if(s[0]=='G'){
            if((int)s.length()==3){
                get(x);
            }
            else{
                int t=read();
                split(0,0,head,x+t-1);
                int lm=rs[0];
                int r=ls[0];
                split(0,0,lm,x-1);
                cout<<sum[ls[0]]<<endl;
                head=merge(merge(rs[0],ls[0]),r);
            }
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int MAXT = MAXN*40;
const int MAXC = 10;

int n,c;
int val[MAXN];
int in[MAXN];

// len[i]: 状态i表示的最长子串长度
int len[MAXT];
// fa[i]: 状态i的后缀链接（parent指针）
int fa[MAXT];
// nxt[i][c]: 状态i在字符c上的转移
int nxt[MAXT][MAXC];
int lst,tot;

int head[MAXN];
int nxtg[MAXN<<1];
int to[MAXN<<1];
int cntg=1;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v){
    nxtg[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
    in[v]++;
}

// 后缀自动机扩展函数：向自动机中添加一个字符
void extend(int c){
    int cur=++tot;
    // 新状态的长度是上一个状态长度+1  初始出现次数为1
    len[cur]=len[lst]+1;

    // 从上一个状态开始，沿着后缀链接向上遍历
    int p=lst;
    while(p&&!nxt[p][c]){
        // 为没有字符c转移的状态添加转移到cur
        nxt[p][c]=cur;
        p=fa[p];
    }

    // 情况1：没有找到有字符c转移的状态  也就是说这个字符是第一次出现
    if(p==0){
        // 直接挂到根节点上
        fa[cur]=1;
    }
    else{
        // 找到状态p在字符c上的转移状态q
        int q=nxt[p][c];

        // 情况2：q的长度正好是p的长度+1 直接将cur的后缀链接指向q
        if(len[p]+1==len[q]){
            fa[cur]=q;
        }
        else{
            int nq=++tot;
            len[nq]=len[p]+1;

            // 复制q的所有转移
            for(int i=0;i<10;i++){
                nxt[nq][i]=nxt[q][i];
            }
            // 设置nq的后缀链接为q的后缀链接，并更新q和cur的后缀链接
            fa[nq]=fa[q],fa[q]=nq,fa[cur]=nq;

            // 将原本指向q的转移重定向到nq
            while(p&&nxt[p][c]==q){
                nxt[p][c]=nq;
                p=fa[p];
            }
        }
    }
    lst=cur;
}

void dfs(int u,int fa){
    int old=lst;
    extend(val[u]);
    for(int i=head[u];i;i=nxtg[i]){
        int v=to[i];
        if(v!=fa){
            dfs(v,u);
        }
    }
    lst=old;
}

