inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    in[v]++;
    head[u]=cnt++;
}

int findroot(){
    queue<int>q;
    for(int i=1;i<=n;i++){
        if(in[i]==1){
            q.push(i);
        }
    }
    int cnt=0;
    int root=0;
    while(!q.empty()){
        int u=q.front();
        q.pop();
        cnt++;
        root=u;
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            if(--in[v]==1){
                q.push(v);
            }
        }
    }
    if(cnt!=n){
        return -1;
    }
    return root;
}

void dfs(int u,int fa){
    ans[u]=true;
    for(int i=head[u];i;i=nxt[i]){
        if(i>=now){
            continue;
        }
        int v=to[i];
        if(v!=fa&&!limit[v]){
            dfs(v,u);
        }
    }
}

