#include<bits/stdc++.h>
using namespace std;
const int MAXN = 5e4+5;

int n;

struct node{
    int a,b,c,d;
    bool left;
    int id;
};

node nums[MAXN];
node tmp1[MAXN];
node tmp2[MAXN];

int m=1;
int arr[MAXN];//用于离散化

int dp[MAXN];

int tree[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

bool cmpa(node a,node b){
    if(a.a!=b.a) return a.a<b.a;
    if(a.b!=b.b) return a.b<b.b;
    if(a.c!=b.c) return a.c<b.c;
    return a.d<b.d;
}

bool cmpb(node a,node b){
    if(a.b!=b.b) return a.b<b.b;
    return a.id<b.id;
}

bool cmpc(node a,node b){
    if(a.c!=b.c) return a.c<b.c;
    return a.id<b.id;
}

int find(int val){
    int l=1,r=m,ans=1;
    while(l<=r){
        int mid=(l+r)/2;
        if(arr[mid]>=val){
            ans=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    return ans;
}

void prepare(){
    for(int i=1;i<=n;i++){
        arr[i]=nums[i].d;
    }
    sort(arr+1,arr+n+1);
    for(int i=2;i<=n;i++){
        if(arr[i]!=arr[i-1]){
            arr[++m]=arr[i];
        }
    }
    for(int i=1;i<=n;i++){
        nums[i].d=find(nums[i].d);
    }
    sort(nums+1,nums+n+1,cmpa);
    for(int i=1;i<=n;i++){
        nums[i].id=i;
    }
    for(int i=1;i<=n;i++){
        dp[i]=1;
    }
}

inline int lowbit(int x){
    return x&(-x);
}

void update(int x,int val){
    while(x<=m){
        tree[x]=max(tree[x],val);
        x+=lowbit(x);
    }
}

int query(int x){
    int ans=0;
    while(x){
        ans=max(ans,tree[x]);
        x-=lowbit(x);
    }
    return ans;
}

void clear(int x){
    while(x<=m){
        tree[x]=0;
        x+=lowbit(x);
    }
}

void merge(int l,int mid,int r){
    for(int i=l;i<=r;i++){
        tmp2[i]=tmp1[i];
    }
    sort(tmp2+l,tmp2+mid+1,cmpc);
    sort(tmp2+mid+1,tmp2+r+1,cmpc);
    int p1=l-1,p2=mid+1;
    for(;p2<=r;p2++){
        while(p1+1<=mid&&tmp2[p1+1].c<=tmp2[p2].c){
            p1++;
            if(tmp2[p1].left){
                update(tmp2[p1].d,dp[tmp2[p1].id]);
            }
        }
        if(!tmp2[p2].left){
            dp[tmp2[p2].id]=max(dp[tmp2[p2].id],query(tmp2[p2].d)+1);
        }
    }
    for(int i=l;i<=p1;i++){
        if(tmp2[i].left){
            clear(tmp2[i].d);
        }
    }
}

void cdq2(int l,int r){
    if(l==r){
        return ;
    }
    int mid=(l+r)>>1;
    cdq2(l,mid);
    merge(l,mid,r);
    cdq2(mid+1,r);
}

void cdq1(int l,int r){
    if(l==r){
        return ;
    }
    int mid=(l+r)/2;
    cdq1(l,mid);
    for(int i=l;i<=r;i++){
        tmp1[i]=nums[i];
        tmp1[i].left=(i<=mid);
    }
    sort(tmp1+l,tmp1+r+1,cmpb);
    cdq2(l,r);
    cdq1(mid+1,r);
}

int main()
{
    n=read();
    for(int i=1;i<=n;i++){
        nums[i].a=read(),nums[i].b=read(),nums[i].c=read(),nums[i].d=read();
    }
    prepare();
    cdq1(1,n);
    int ans=0;
    for(int i=1;i<=n;i++){
        ans=max(ans,dp[i]);
    }
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e6+5;

char s1[MAXN];
char s2[MAXN];
int nxt[MAXN];
int n,m;

//使用栈结构维护
int st1[MAXN];
int st2[MAXN];//表示对于栈1中的同一个位置的元素对应上的s2中的位置  -1表示没对上
int sz;

void calcnext() {
    if (m == 1) {
        nxt[0] = -1;
        return ;
    }

    nxt[0] = -1;
    nxt[1] = 0;

    int i = 2, cn = 0;
    while (i < m) {
        if (s2[i - 1] == s2[cn]) {
            nxt[i++] = ++cn;
        } else if (cn > 0) {
            cn = nxt[cn];
        } else {
            nxt[i++] = 0;
        }
    }
}

void compute(){
    n=strlen(s1),m=strlen(s2);
    // cout<<n<<' '<<m<<endl;
    calcnext();
    int x=0,y=0;
    while(x<n){
        if(s1[x]==s2[y]){
            st1[sz]=x;
            st2[sz]=y;
            sz++;
            x++,y++;
        }
        else if(y==0){
            st1[sz]=x;
            st2[sz]=-1;//表示没有匹配上
            sz++;
            x++;
        }
        else{
            y=nxt[y];
        }

        if(y==m){
            //全部匹配上了  那么减去s2的长度
            sz-=m;
            y=sz>0?(st2[sz-1]+1):0;//如果栈中空了 那么从0开始   否则从栈顶的下一个位置开始
        }

    }
    for(int i=0;i<sz;i++){
        cout<<s1[st1[i]];
    }
}

int main()
{
    scanf("%s %s",s1,s2);
    compute();
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e4+5;
const int MAXM = 5e4+5;

int head[MAXN];
int Next[MAXM];
int to[MAXM];
int cnt=1;

int cost[MAXN];
int dfn[MAXN],low[MAXN];
int st[MAXN],top;
int color,Time;
int col[MAXN];
int in[MAXN],out[MAXN];
bool instack[MAXN];
int n,m;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v){
    Next[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

void tarjan(int x){
    dfn[x]=++Time;
    low[x]=Time;
    st[++top]=x;
    instack[x]=true;
    for(int i=head[x];i;i=Next[i]){
        int v=to[i];
        if(!dfn[v]){
            //表示这个节点没有被访问过
            tarjan(v);
            low[x]=min(low[x],low[v]);
        }
        else if(instack[v]){
            //表示这个属于是回溯了 一定是同一个环上的
            low[x]=min(low[x],dfn[v]);
        }
    }
    if(dfn[x]==low[x]){
        col[x]=++color;
        //将所有节点按照颜色分类  完成缩点
        while(st[top]!=x){
            //属于同一个强联通分量
            col[st[top]]=color;
            instack[st[top]]=false;
            top--;
        }
        instack[x]=false;
        top--;
    }
}

int main()
{
    n=read();
    for(int i=1;i<=n;i++){
        int u;
        u=read();
        while(u!=0){
            addedge(i,u);
            u=read();
        }
    }
    for(int i=1;i<=n;i++){
        if(!dfn[i]){
            tarjan(i);
        }
    }
    for(int i=1;i<=n;i++){
        for(int j=head[i];j;j=Next[j]){
            int v=to[j];
            if(col[i]!=col[v]){
                in[col[v]]++;
                out[col[i]]++;
            }
        }
    }
    int ans1=0,ans2=0;
    for(int i=1;i<=color;i++){
        if(in[i]==0){
            ans1++;
        }
        if(out[i]==0){
            ans2++;
        }
    }
    if(color==1){
        cout<<1<<endl<<0<<endl;
        return 0;
    }
    cout<<ans1<<endl<<max(ans1,ans2)<<endl;
    return 0;
}

#include <algorithm>
