    cin >> u >> v >> w;
    e[u].emplace_back(v, w);
    e[v].emplace_back(u, w);
  }
  get_diameter();
  sub1::solve();
  return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e6+5;
const int INF = 1e5;

int n,m,all;
int val[MAXN];

int k;
int black[MAXN];
bool special[MAXN];
bool white[MAXN];

int fa[MAXN];
int sum[MAXN];
int bsz[MAXN];
int minval[MAXN];

int walk[4][2]={{1,0},{-1,0},{0,1},{0,-1}};

int id(int x,int y){
    return (x-1)*m+y;
}

int find(int x){
    return x==fa[x]?x:fa[x]=find(fa[x]);
}

void un(int x,int y){
    int fx=find(x);
    int fy=find(y);
    if(fx!=fy){
        sum[fx]+=sum[fy];
        bsz[fx]+=bsz[fy];
        fa[fy]=fx;
        minval[fx]=min(minval[fx],minval[fy]);
    }
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m;
    all=n*m;
    for(int i=1;i<=all;i++){
        cin>>val[i];
        fa[i]=i;
        sum[i]=1;
        minval[i]=val[i];
    }

    cin>>k;
    for(int i=1;i<=k;i++){
        int x,y;
        cin>>x>>y;
        x++,y++;
        int node=id(x,y);
        special[node]=true;
        black[i]=node;
        bsz[node]++;
        minval[node]=INF;
        for(int j=0;j<4;j++){
            int nx=x+walk[j][0];
            int ny=y+walk[j][1];
            if(nx>n||ny>m||nx==0||ny==0){
                continue;
            }
            white[id(nx,ny)]=true;
        }
    }

    for(int i=1;i<=k;i++){
        int x=(black[i]-1)/m+1;
        int y=(black[i]-1)%m+1;
        int u=black[i];
        for(int j=0;j<4;j++){
            int nx=x+walk[j][0];
            int ny=y+walk[j][1];
            if(nx>n||ny>m||nx==0||ny==0||special[id(nx,ny)]){
                continue;
            }
            int v=id(nx,ny);
            un(u,v);
        }
    }

    int ans=0;
    for(int i=1;i<=all;i++){
        if(white[i]||special[i]){
            ans+=val[i];
        }
    }
    for(int i=1;i<=all;i++){
        if(i==find(i)){
            if(sum[i]<4*bsz[i]){
                cout<<"No"<<endl;
                return 0;
            }
            else if(sum[i]==4*bsz[i]){
                continue;
            }
            else{
                if(bsz[i])
                    ans-=minval[i];
            }
        }
    }
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e4+5;

int n,m,ans=0;
int tree[MAXN<<2];
int tree1[MAXN<<2];
bool cut[MAXN<<2],add[MAXN<<2];
int len[MAXN<<2];

void up(int i){
    tree[i]=tree[i<<1]+tree[i<<1|1];
    tree1[i]=tree1[i<<1]+tree1[i<<1|1];
}

void build(int l,int r,int i){
    if(l==r){
        tree[i]=1;
        tree1[i]=1;
    }
    else{
        int mid=(l+r)/2;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        up(i);
    }
    cut[i]=add[i]=false;
    len[i]=r-l+1;
}

void downlazy(int i){
    tree[i]=tree1[i]=0;
    cut[i]=true;
    add[i]=false;
}

void addlazy(int i){
    if(cut[i]){
        tree[i]=0;
        downlazy(i<<1);
        downlazy(i<<1|1);
    }
    tree1[i]=len[i];
    add[i]=true;
    cut[i]=false;
}

void down(int i){
    if(cut[i]){
        cut[i]=false;
        downlazy(i<<1);
        downlazy(i<<1|1);
    }
    if(add[i]){
        add[i]=false;
        addlazy(i<<1);
        addlazy(i<<1|1);
    }
}

void cutt(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        downlazy(i);
    }
    else{
        int mid=(l+r)/2;
        down(i);
        if(jobl<=mid){
            cutt(jobl,jobr,l,mid,i<<1);
        }
        if(jobr>mid){
            cutt(jobl,jobr,mid+1,r,i<<1|1);
        }
        up(i);
    }
}

void addd(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        addlazy(i);
    }
    else{
        int mid=(l+r)/2;
        down(i);
        if(jobl<=mid){
            addd(jobl,jobr,l,mid,i<<1);
        }
        if(jobr>mid){
            addd(jobl,jobr,mid+1,r,i<<1|1);
        }
        up(i);
    }
}

int query(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        return tree1[i];
    }
    else{
        int ans=0;
        int mid=(l+r)/2;
        down(i);
        if(jobl<=mid){
            ans+=query(jobl,jobr,l,mid,i<<1);
        }
        if(jobr>mid){
            ans+=query(jobl,jobr,mid+1,r,i<<1|1);
        }
        //up(i);
        return ans;
    }
}

