// 随机数生成器
unsigned int rng61(){
    SA ^= SA << 16;
    SA ^= SA >> 5;
    SA ^= SA << 1;
    unsigned int t = SA;
    SA = SB;
    SB = SC;
    SC ^= t ^ SA;
    return SC;
}

void gen(){
    // 读取输入参数
    n = read(), k = read() + 1, m = read(), p = read();
    SA = read(), SB = read(), SC = read(), A = read(), B = read();

    // 读取前p个钻石的数据
    for(int i = 1; i <= p; i++) {
        a[i] = read() % m;  // 对m取模，因为我们只关心模m的结果
        b[i] = read();
    }
    // 生成剩余钻石的数据
    for(int i = p + 1; i <= n; i++){
        a[i] = rng61() % A + 1;
        b[i] = rng61() % B + 1;
        a[i] %= m;  // 对m取模
    }
}

