void up(int i){
    sum[i]=(sum[i<<1]*sum[i<<1|1])%mod;
}

void build(int l,int r,int i){
    if(l==r){
        sum[i]=1;
    }else{
        int mid=(l+r)/2;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        up(i);
    }
}

void update(int jobi,double jobv,int l,int r,int i){
    if(l==r){
        sum[i]=(long long )(sum[i]*jobv)%mod;
    }else{
        int mid=(l+r)/2;
        if(jobi<=mid){
            update(jobi,jobv,l,mid,i<<1);
        }else{
            update(jobi,jobv,mid+1,r,i<<1|1);
        }
        up(i);
    }
}

