long long ans=0;

int in[MAXN];//这是重新开始加点时的度数
bool vis[MAXN];//表示是否已经被重新加入
int degree[MAXN];//这是最开始的入度

int head[MAXN];
int Next[MAXM<<1];
int to[MAXM<<1];
