void dfs1(int u, int f) {
    dep[u] = dep[f] + 1;
    depth = max(depth, dep[u]);
    siz[u] = 1;
    dfn[u] = ++cntd;
    for (int ei = head[u]; ei > 0; ei = nxt[ei]) {
        if (to[ei] != f) {
            dfs1(to[ei], u);
        }
    }
    for (int ei = head[u]; ei > 0; ei = nxt[ei]) {
        if (to[ei] != f) {
            siz[u] += siz[to[ei]];
        }
    }
}

