void dfs2(int u, int f) {
    root[dfn[u]] = add(dep[u], val[u] , 1, depth, root[dfn[u] - 1]);
    for (int ei = head[u]; ei > 0; ei = nxt[ei]) {
        if (to[ei] != f) {
            dfs2(to[ei], u);
        }
    }
}

void prepare() {
    depth = 0;
    dfs1(1, 0);
    root[0] = build(1, depth);
    dfs2(1, 0);
}

int query(int jobl,int jobr,int l,int r,int u,int v){
    if(jobl<=l&&r<=jobr){
        return sum[v]^sum[u];
    }
    int ans=0;
