inline bool is_prime(int x) {
    if (x == 1) return false;
    for (int i = 2; i * i <= x; i++) {
        if (x % i == 0) return false;
    }
    return true;
}

void dfs(int now, int x, int s) {
    if (now == 1) {
        ans[++cnt] = s;
        return;
    }
    if (is_prime(now - 1) && now > pr[x]) {
        ans[++cnt] = s * (now - 1);
    }
    for (int i = x; pr[i] * pr[i] <= now; i++) {
        int t = pr[i];
        int sum = pr[i] + 1;
        while (sum <= now) {
            if (now % sum == 0) {
                dfs(now / sum, i + 1, s * t);
            }
            t *= pr[i];
            sum += t;
        }
    }
}

