    for(int i=1;i<=n;i++){
        power[i]=compute(i,k);
    }

    dfs1(1,0);
    dfs2(1,1);

    for(int i=1;i<=n;i++){
        val[i]=(power[dep[i]]-power[dep[i]-1]+MOD)%MOD;
    }
    build(1,n,1);
}

void up(int i){
    tree[i]=(tree[i<<1]+tree[i<<1|1])%MOD;
}

void addlazy(int i,int x){
    tree[i]=(tree[i]+((sum[i]*x)%MOD+MOD))%MOD;
    lazy[i]+=x;
}

void down(int i){
    if(lazy[i]){
        addlazy(i<<1,lazy[i]);
        addlazy(i<<1|1,lazy[i]);
        lazy[i]=0;
    }
}

void add(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        addlazy(i,1);
    }
    else{
        int mid=(l+r)>>1;
        down(i);
        if(jobl<=mid){
            add(jobl,jobr,l,mid,i<<1);
        }
        if(jobr>mid){
            add(jobl,jobr,mid+1,r,i<<1|1);
        }
        up(i);
    }
}

int query(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        return tree[i];
    }
    else{
        int mid=(l+r)>>1;
        down(i);
        int ans=0;
        if(jobl<=mid){
            ans+=query(jobl,jobr,l,mid,i<<1);
        }
        if(jobr>mid){
            ans+=query(jobl,jobr,mid+1,r,i<<1|1);
        }
        ans=((ans%MOD)+MOD)%MOD;
        return ans;
    }
}

void add(int x){
    while(x){
        add(dfn[top[x]],dfn[x],1,n,1);
        x=fa[top[x]];
    }
}

int query(int x){
    int ans=0;
    while(x){
        ans+=query(dfn[top[x]],dfn[x],1,n,1);
        ans%=MOD;
        x=fa[top[x]];
    }
    ans=(ans%MOD+MOD)%MOD;
    return ans;
}

