#include<bits/stdc++.h>
using namespace std;
const int MAXN = 505;
const int MAXM = 4005;

int n,m;
int v[MAXN];
int c[MAXN];
int d[MAXN];

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int cnt=1;

bool vis[MAXN];
int sz[MAXN];

int dp[MAXN][MAXM];

int seg[MAXN];
int low[MAXN];
int dfncnt;

int val[MAXN];
int cost[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

void prepare(){
    cnt=1;
    for(int i=1;i<=n;i++){
        head[i]=0;
        vis[i]=false;
    }
}

void getsize(int u,int fa){
    sz[u]=1;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(!vis[v]&&v!=fa){
            getsize(v,u);
            sz[u]+=sz[v];
        }
    }
}

int getcentroid(int u,int fa){
    getsize(u,fa);
    int half=sz[u]>>1;
    bool find=false;
    while(!find){
        find=true;
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            if(!vis[v]&&v!=fa&&sz[v]>half){
                fa=u;
                u=v;
                find=false;
                break;
            }
        }
    }
    return u;
}

void dfs(int u,int fa){
    seg[++dfncnt]=u;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(!vis[v]&&v!=fa){
            dfs(v,u);
        }
    }
    low[u]=dfncnt;
}

int calc(int u){
    dfncnt=0;
    dfs(u,0);
    for(int i=dfncnt;i>=1;i--){
        int cur=seg[i];
        int cnt=d[cur]-1;
        int num=0;
        for(int k=1;k<=cnt;k<<=1){
            val[++num]=v[cur]*k;
            cost[num]=c[cur]*k;
            cnt-=k;
        }
        if(cnt>0){
            val[++num]=v[cur]*cnt;
            cost[num]=c[cur]*cnt;
        }

        for(int j=m;j>=c[cur];j--){
            dp[i][j]=dp[i+1][j-c[cur]]+v[cur];
        }
        for(int k=1;k<=num;k++){
            for(int j=m;j>=cost[k];j--){
                dp[i][j]=max(dp[i][j],dp[i][j-cost[k]]+val[k]);
            }
        }
        for(int j=0;j<=m;j++){
            dp[i][j]=max(dp[i][j],dp[low[cur]+1][j]);
        }
    }
    int ans=dp[1][m];
    for(int i=1;i<=dfncnt;i++){
        for(int j=0;j<=m;j++){
            dp[i][j]=0;
        }
    }
    return ans;
}

int solve(int u){
    vis[u]=true;
    int ans=calc(u);
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(!vis[v]){
            ans=max(ans,solve(getcentroid(v,u)));
        }
    }
    return ans;
}

int main()
{
    int T=read();
    while(T--){
        n=read(),m=read();
        for(int i=1;i<=n;i++){
            v[i]=read();
        }
        for(int i=1;i<=n;i++){
            c[i]=read();
        }
        for(int i=1;i<=n;i++){
            d[i]=read();
        }
        prepare();
        for(int i=1;i<n;i++){
            int u,v;
            u=read(),v=read();
            addedge(u,v);
            addedge(v,u);
        }
        cout<<solve(getcentroid(1,0))<<endl;
    }
    return 0;
}

#include <iostream>
#include <cstdio>
#include <cstring>
using namespace std;

typedef long long LL;

const int N = 100005;

int n, m, w[N];

struct Seg {
    int L0, R0;
    int L1, R1;
    int C0, C1;
    int L[2][2];
    int R[2][2];
    LL res;
} v[N << 2];

void seg_init(Seg &s) {
    s.L0 = s.R0 = s.L1 = s.R1 = s.C0 = s.C1 = s.res = 0;
    memset(s.L, 0, sizeof(s.L));
    memset(s.R, 0, sizeof(s.R));
}

void seg_init_single(Seg &s, int x) {
    seg_init(s);
    if (x) {
        s.L1 = s.R1 = s.C1 = 1;
        s.L[0][1] = s.R[0][1] = 1;
        s.res = 1;
    } else {
        s.L0 = s.R0 = s.C0 = 1;
        s.L[1][0] = s.R[1][0] = 1;
        s.res = 0;
    }
}

void seg_merge(Seg &c, const Seg &a, const Seg &b, int mid) {
    seg_init(c);

    c.C0 = a.C0 + b.C0;
    c.C1 = a.C1 + b.C1;

    c.L0 = a.L0;
    if (a.C1 == 0) c.L0 += b.L0;

    c.R0 = b.R0;
    if (b.C1 == 0) c.R0 += a.R0;

    c.L1 = a.L1;
    if (a.C1 == 0) c.L1 += b.L1;
    if (a.C1 == 1) c.L1 += b.L0;

    c.R1 = b.R1;
    if (b.C1 == 0) c.R1 += a.R1;
    if (b.C1 == 1) c.R1 += a.R0;

    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            c.L[i][j] = a.L[i][j];
            if (i >= a.C0) {
                int ni = i - a.C0;
                int nj = j ^ (a.C1 & 1);
                if (ni < 2) c.L[i][j] += b.L[ni][nj];
            }
            c.R[i][j] = b.R[i][j];
            if (i >= b.C0) {
                int ni = i - b.C0;
                int nj = j ^ (b.C1 & 1);
                if (ni < 2) c.R[i][j] += a.R[ni][nj];
            }
        }
    }

    c.res = a.res + b.res;
    c.res += (LL)a.R0 * b.L1 + (LL)a.R1 * b.L0;
    c.res += (LL)a.R[0][0] * (b.L[0][1] + b.L[1][1]) + (LL)a.R[0][1] * (b.L[0][0] + b.L[1][0]);
    c.res += (LL)a.R[1][0] * b.L[0][1] + (LL)a.R[1][1] * b.L[0][0];

    if (w[mid] + w[mid + 1] == 1) c.res--;
}

void build(int p, int l, int r) {
    if (l == r) {
        seg_init_single(v[p], w[l]);
        return;
    }
    int mid = (l + r) >> 1;
    build(p << 1, l, mid);
    build(p << 1 | 1, mid + 1, r);
    seg_merge(v[p], v[p << 1], v[p << 1 | 1], mid);
}

void change(int p, int l, int r, int x) {
    if (l == r) {
        seg_init_single(v[p], w[l]);
        return;
    }
    int mid = (l + r) >> 1;
    if (x <= mid) change(p << 1, l, mid, x);
    else change(p << 1 | 1, mid + 1, r, x);
    seg_merge(v[p], v[p << 1], v[p << 1 | 1], mid);
}

Seg query(int p, int l, int r, int x, int y) {
    if (x <= l && r <= y) return v[p];
    int mid = (l + r) >> 1;
    if (y <= mid) return query(p << 1, l, mid, x, y);
    if (x > mid) return query(p << 1 | 1, mid + 1, r, x, y);

    Seg left_seg = query(p << 1, l, mid, x, y);
    Seg right_seg = query(p << 1 | 1, mid + 1, r, x, y);
    Seg result;
    seg_merge(result, left_seg, right_seg, mid);
    return result;
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) scanf("%d", w + i);
    build(1, 1, n);
    scanf("%d", &m);
    while (m--) {
        int opt;
        scanf("%d", &opt);
        if (opt == 1) {
            int x;
            scanf("%d", &x);
            w[x] ^= 1;
            change(1, 1, n, x);
        } else {
            int l, r;
            scanf("%d%d", &l, &r);
            LL total = (LL)(r - l + 1) * (r - l + 2) / 2;
            Seg ans = query(1, 1, n, l, r);
            printf("%lld\n", total - ans.res);
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 5e5+5;
const double eps = 1e-8;

int n;
double f[MAXN];

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
double weight[MAXN<<1];
int cnt=1;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v,double w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    head[u]=cnt++;
}

void dfs1(int u,int fa){
    double ans=(1-f[u]);
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        double w=weight[i];
        if(v!=fa){
            dfs1(v,u);
            ans*=(1-f[v]*w);
        }
    }
    f[u]=1-ans;
}

void dfs2(int u,int fa){
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        double w=weight[i];
        if(v!=fa){
            double x;
            if(1-f[v]*w>eps){
                x=(f[u]-f[v]*w)/(1-f[v]*w);
            }
            else{
                x=0;
            }
            f[v]=1-(1-f[v])*(1-x*w);
            dfs2(v,u);
        }
    }
}

int main()
{
    n=read();
    for(int i=1;i<n;i++){
        int u,v,w;
        u=read(),v=read(),w=read();
        double ww=w*0.01;
        addedge(u,v,ww);
        addedge(v,u,ww);
    }
    for(int i=1;i<=n;i++){
        int u=read();
        f[i]=u*0.01;
    }
    dfs1(1,0);
    dfs2(1,0);
    double ans=0;
    for(int i=1;i<=n;i++){
        ans+=f[i];
    }
    printf("%.6lf\n",ans);
    return 0;
}

#include "bits/stdc++.h"
using namespace std;

int a[10][10], d, xx1, yy1, xx2, yy2;
int fx[4] = {0, 0, 1, -1}, fy[4] = {1, -1, 0, 0};

inline bool check() {
    for (register int i = 1; i <= 4; ++i)
        if (a[i][1] == a[i][2] && a[i][2] == a[i][3] && a[i][3] == a[i][4]) return true;

    for (register int j = 1; j <= 4; ++j)
        if (a[1][j] == a[2][j] && a[2][j] == a[3][j] && a[3][j] == a[4][j]) return true;

    if (a[1][1] == a[2][2] && a[2][2] == a[3][3] && a[3][3] == a[4][4]) return true;

    if (a[4][1] == a[3][2] && a[3][2] == a[2][3] && a[2][3] == a[1][4]) return true;

    return false;
}

bool dfs(int ax, int ay, int bx, int by, int col, int dep) {
    if (dep > d) {
        if (check()) return true;
        return false;
    }
    for (register int i = 0; i < 4; ++i) {
        int nx = ax + fx[i];
        int ny = ay + fy[i];
        if (nx > 0 && nx <= 4 && ny > 0 && ny <= 4 && a[nx][ny] == col) {
            swap(a[ax][ay], a[nx][ny]);
            if (dfs(nx, ny, bx, by, (col == 1) ? 2 : 1, dep + 1)) return true;
            swap(a[ax][ay], a[nx][ny]);
        }
    }
    for (register int i = 0; i < 4; ++i) {
        int nx = bx + fx[i];
        int ny = by + fy[i];
        if (nx > 0 && nx <= 4 && ny > 0 && ny <= 4 && a[nx][ny] == col) {
            swap(a[bx][by], a[nx][ny]);
            if (dfs(ax, ay, nx, ny, (col == 1) ? 2 : 1, dep + 1)) return true;
            swap(a[bx][by], a[nx][ny]);
        }
    }
    return false;
}

