#include<bits/stdc++.h>
using namespace std;
const int MAXN = 3e5+5;

int n;

int tree[MAXN][26];
int fail[MAXN];
int len[MAXN];// 节点代表的回文串长度
int num[MAXN];
int cnt;
int last;

char s[MAXN];
long long ans;

// 初始化回文自动机
void init(){
    cnt=1;
    last=0;
    len[0]=0,len[1]=-1;
    fail[0]=1;//偶根节点的fail指针指向奇根
    fail[1]=1;
    num[0]=0,num[1]=0;
    s[0]='#';// 特殊字符，防止越界
}

// 在fail链上查找满足条件的节点  即回文串前面一个字母是t[i]的位置  最大的位置
int getfail(int p,int i){
    while(s[i-len[p]-1]!=s[i]){
        p=fail[p];
    }
    return p;
}

// 添加字符t[i]到回文自动机
void insert(int i){
    // 当前字符的数值
    int c=s[i]-'a';
    // 查找合适的节点  其实这里找的是一个类似于父亲节点
    int cur=getfail(last,i);

    // 如果该节点不存在，创建新节点
    if(!tree[cur][c]){
        int x=++cnt;
        len[x]=len[cur]+2;

        // 这里要找的是fail指针指向的节点  意思是最长的回文后缀  但不能是整体  即子回文后缀
        // 所以这里必须是cur的fail指针所指向的节点
        int p=getfail(fail[cur],i);
        fail[x]=tree[p][c];

        tree[cur][c]=x;
    }
    last=tree[cur][c];
}

int main()
{
    scanf("%s",s+1);
    n=strlen(s+1);
    init();
    for(int i=1;i<=n;i++){
        insert(i);
        num[last]++;
    }
    for(int i=cnt;i>=1;i--){
        num[fail[i]]+=num[i];
    }
    for(int i=1;i<=cnt;i++){
        ans=max(ans,1ll*num[i]*len[i]);
    }
    cout<<ans<<endl;
    return 0;
}

// https://www.luogu.com.cn/problem/P2414
// 这道题的建图方式比较特殊 需要额外添加一个fa数组 然后继续跑AC自动机的常规代码
// 问题的关键就在于如何解决 第x个单词在第y个单词中出现的次数   
// 这个问题的推导的逻辑如下：
// 对于AC自动机而言 1、AC自动机的每个节点对应一个字符串前缀
//                2、节点u的fail指针指向v，表示v对应字符串是u对应字符串的最长后缀
// 对于通过fail指针建立的反向fail树而言：若节点v在节点u的Fail树子树中，则u对应的字符串是v对应字符串的后缀
// 比如u = "ab" → v = "xab"   ---->  则"ab"是"xab"的后缀
// x在y中出现的次数 = y的所有前缀中，以x为后缀的前缀数量(当然 你也可以说是所有后缀中 以x为前缀的数量  但是我们这里用到的是前面这种定义)  
// 从自动机的角度来看 我们假设 node_x是x的结束节点 path_y是y在Trie树上的路径（根节点到node_y）
// x在y中出现次数 = path_y上所有节点v中，满足 v 在 node_x 的 Fail树的子树中的数量
// 在某个节点的子树中出现的  这一类问题可以转换为  dfn序   在线性数组上处理
// 利用树状数组可以快速查询
// 于是 我们重新走建立AC自动机的过程  在这个过程中统计答案
#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;

string s;
int n;

int cnt;
int trie[MAXN][26];
int fail[MAXN];
int fa[MAXN];//这里比一般的AC自动机多出来的部分 是由于建立自动机时的特殊情况所决定的
int endpos[MAXN];//记录这个是为了在统计答案的时候更方便  具体参见代码

//fail树的建图
int head[MAXN];
int nxt[MAXN];
int to[MAXN];
int cntg=1;

//查询问题的建图
int headq[MAXN];
int nxtq[MAXN];
int toq[MAXN];
int idq[MAXN];
int cntq=1;

int dfn[MAXN];
int sz[MAXN];
int dfncnt;

int tree[MAXN];

int ans[MAXN];

void setfail(){
    queue<int>q;
    for(int i=0;i<26;i++){
        if(trie[0][i]){
            q.push(trie[0][i]);
        }
    }
    while(!q.empty()){
        int u=q.front();
        q.pop();
        for(int i=0;i<26;i++){
            if(trie[u][i]==0){
                trie[u][i]=trie[fail[u]][i];
            }
            else{
                fail[trie[u][i]]=trie[fail[u]][i];
                q.push(trie[u][i]);
            }
        }
    }
}

inline void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

inline void addedge(int u,int v,int w){
    nxtq[cntq]=headq[u];
    toq[cntq]=v;
    idq[cntq]=w;
    headq[u]=cntq++;
}

//得到dfn序和子树大小
void dfs(int u){
    dfn[u]=++dfncnt;
    sz[u]=1;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        dfs(v);
        sz[u]+=sz[v];
    }
}

inline int lowbit(int x){
    return x&-x;
}

void add(int x,int v){
    while(x<=dfncnt){
        tree[x]+=v;
        x+=lowbit(x);
    }
}

int query(int x){
    int ans=0;
    while(x){
        ans+=tree[x];
        x-=lowbit(x);
    }
    return ans;
}

int main()
{
    cin>>s;

    //直接建立AC自动机
    int cur=0;//当前来到的自动机节点编号
    int id=0;//当前字符串的序号
    for(char c:s){
        if(c=='B'){
            //回退操作
            cur=fa[cur];
        }
        else if(c=='P'){
            //新建一个单词
            endpos[++id]=cur;
        }
        else{
            int path=c-'a';
            if(trie[cur][path]==0){
                trie[cur][path]=++cnt;
                fa[cnt]=cur;
            }
            cur=trie[cur][path];
        }
    }

    setfail();

    //建立fail树  反向建树
    for(int i=1;i<=cnt;i++){
        addedge(fail[i],i);
    }

    //得到dfn序
    dfs(0);

    cin>>n;
    for(int i=1;i<=n;i++){
        int x,y;
        cin>>x>>y;
        addedge(y,x,i);
    }

    //重新跑一遍trie  统计答案
    cur=0;
    id=0;
    for(char c:s){
        if(c=='B'){
            add(dfn[cur],-1);//移除当前节点
            cur=fa[cur];
        }
        else if(c=='P'){
            id++;
            for(int i=headq[id];i;i=nxtq[i]){
                int v=toq[i];
                int w=idq[i];
                int node=endpos[v];
                ans[w]=query(dfn[node]+sz[node]-1)-query(dfn[node]-1);
            }
        }
        else{
            int path=c-'a';
            cur=trie[cur][path];
            add(dfn[cur],1);//当前节点加入树状数组中
        }
    }
    for(int i=1;i<=n;i++){
        cout<<ans[i]<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;
const int MAXB = 505;

int n,m;
int val[MAXN];

struct node{
    int l,r,id;
};
node nums[MAXN];
int ans[MAXN];

int blen,bnum;
int bi[MAXN];
int bl[MAXB];
int br[MAXB];

int mex;
int cnt[MAXN];

bool cmp(node &a,node &b){
    if(bi[a.l]!=bi[b.l]){
        return bi[a.l]<bi[b.l];
    }
    return a.r>b.r;
}

void prepare(){
    blen=sqrt(n);
    bnum=(n+blen-1)/blen;
    for(int i=1;i<=n;i++){
        bi[i]=(i+blen-1)/blen;
    }
    for(int i=1;i<=bnum;i++){
        bl[i]=(i-1)*blen+1;
        br[i]=min(n,i*blen);
    }

    sort(nums+1,nums+m+1,cmp);
}

void add(int val){
    cnt[val]++; 
}

void del(int val){
    cnt[val]--;
    if(val<mex&&cnt[val]==0){
        mex=val;
    }
}

void compute(){
    int winl=1,winr=n;
    for(int i=1;i<=n;i++){
        cnt[val[i]]++;
    }
    for(int i=0;i<=n;i++){
        if(cnt[i]==0){
            mex=i;
            break;
        }
    }

    for(int block=1,qi=1;block<=bnum&&qi<=m;block++){
        while(winl<bl[block]){
            del(val[winl++]);
        }
        int beforejob=mex;

        for(;qi<=m&&bi[nums[qi].l]==block;qi++){
            int l=nums[qi].l;
            int r=nums[qi].r;
            int id=nums[qi].id;

            while(winr>r){
                del(val[winr--]);
            }
            int backup=mex;
            while(winl<l){
                del(val[winl++]);
            }
            ans[id]=mex;
            while(winl>bl[block]){
                add(val[--winl]);
            }
            mex=backup;
        }
        while(winr<n){
            add(val[++winr]);
        }
        mex=beforejob;
    }
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m;
    for(int i=1;i<=n;i++){
        cin>>val[i];
    }
    for(int i=1;i<=m;i++){
        nums[i].id=i;
        cin>>nums[i].l>>nums[i].r;
    }

    prepare();
    compute();

    for(int i=1;i<=m;i++){
        cout<<ans[i]<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 1e5+5;
const int MAXT = MAXN*100;

int n,m;
long long ans;
int arr[MAXN];
struct node{
    int id,t,v;
};
node nums[MAXN];

bool vis[MAXN];

int fa[MAXN];

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int cnt=1;

int root[MAXN];
int ls[MAXT];
int rs[MAXT];
int sz[MAXT];
int cntv;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

int find(int val){
    int l=1,r=m,ans=0;
    while(l<=r){
        int mid=(l+r)>>1;
        if(arr[mid]>=val){
            ans=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    return ans;
}

bool cmp(node a,node b){
    return a.t>b.t;
}

void up(int x){
    sz[x]=sz[ls[x]]+sz[rs[x]];
}

int add(int val,int l,int r,int i){
    int rt=i;
    if(rt==0){
        rt=++cntv;
    }
    if(l==r){
        sz[rt]++;
    }
    else{
        int mid=(l+r)>>1;
        if(val<=mid){
            ls[rt]=add(val,l,mid,ls[rt]);
        }
        else{
            rs[rt]=add(val,mid+1,r,rs[rt]);
        }
        up(rt);
    }
    return rt;
}

int findfa(int x){
    return x==fa[x]?x:fa[x]=findfa(fa[x]);
}

int query(int jobl,int jobr,int l,int r,int i){
    if(i==0){
        return 0;
    }
    if(jobl<=l&&r<=jobr){
        return sz[i];
    }
    else{
        int mid=(l+r)>>1;
        int ans=0;
        if(jobl<=mid){
            ans+=query(jobl,jobr,l,mid,ls[i]);
        }
        if(jobr>mid){
            ans+=query(jobl,jobr,mid+1,r,rs[i]);
        }
        return ans;
    }
}

int merge(int l,int r,int t1,int t2){
    if(t1==0||t2==0){
        return t1+t2;
    }
    if(l==r){
        sz[t1]+=sz[t2];
    }
    else{
        int mid=(l+r)>>1;
        ls[t1]=merge(l,mid,ls[t1],ls[t2]);
        rs[t1]=merge(mid+1,r,rs[t1],rs[t2]);
        up(t1);
    }
    return t1;
}

void compute(){
    sort(arr+1,arr+n+1);
    m=1;
    for(int i=2;i<=n;i++){
        if(arr[i]!=arr[i-1]){
            arr[++m]=arr[i];
        }
    }
    for(int i=1;i<=n;i++){
        nums[i].v=find(nums[i].v);
        root[i]=add(nums[i].v,1,m,root[i]);
    }

    sort(nums+1,nums+n+1,cmp);

    for(int i=1;i<=n;i++){
        int u=nums[i].id;
        int val=nums[i].v;
        vis[u]=true;
        for(int ei=head[u];ei;ei=nxt[ei]){
            int v=to[ei];
            if(vis[v]){
                int fv=findfa(v);
                int fu=findfa(u);
                // int fu=u;
                if(fv!=fu){
                    fa[fv]=fu;

                    int sz1=query(1,val,1,m,root[fu]);
                    int sz2=query(val,m,1,m,root[fu]);
                    int sz3=query(1,val,1,m,root[fv]);
                    int sz4=query(val,m,1,m,root[fv]);

                    ans+=1ll*sz1*sz4*u+1ll*sz2*sz3*u;
                    root[fu]=merge(1,m,root[fu],root[fv]);
                }
            }
        }
        ans+=u;
    }
}

signed main()
{
    n=read();
    for(int i=1;i<=n;i++){
        fa[i]=i;
        nums[i].id=i;
    }
    for(int i=1;i<=n;i++){
        nums[i].t=read();
    }
    for(int i=1;i<=n;i++){
        nums[i].v=read();
        arr[i]=nums[i].v;
    }
    for(int i=1;i<n;i++){
        int u,v;
        u=read(),v=read();
        addedge(u,v);
        addedge(v,u);
    }
    compute();
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 1e6+5;
const int MAXH = 22;
const int MOD = 23333333333333333;
const int MAXM = 3e6+5;

int n,t,m;
// 注意这里开的是二倍空间  这样可以减少很多判断语句
char s[MAXN];

//桶数组x[i] 辅助数组y[i] 计数数组c[i]
int x[MAXN];
int y[MAXN];
int c[MAXN];

// 后缀数组：排名第i的后缀的起始位置
int sa[MAXN];
// 排名数组：起始位置为i的后缀的排名
int rk[MAXN];
// height[i]表示的是排名为i和排名为i-1的最长公共前缀的长度
int height[MAXN];

void getsa(){
    for(int i=1;i<=n;i++){
        x[i]=s[i]-'a'+1,c[x[i]]++;
    }
    for(int i=1;i<=m;i++){
        c[i]+=c[i-1];
    }
    for(int i=n;i>=1;i--){
        sa[c[x[i]]--]=i;
    }
    for(int k=1;k<=n;k<<=1){
        // 按照第二个关键字排序
        for(int i=0;i<=m;i++){
            c[i]=0;
        }
        for(int i=1;i<=n;i++){
            y[i]=sa[i];
        }
        for(int i=1;i<=n;i++){
            c[x[y[i]+k]]++;
        }
        for(int i=1;i<=m;i++){
            c[i]+=c[i-1];
        }
        for(int i=n;i>=1;i--){
            sa[c[x[y[i]+k]]--]=y[i];
        }

        // 按照第一个关键字排序
        for(int i=0;i<=m;i++){
            c[i]=0;
        }
        for(int i=1;i<=n;i++){
            y[i]=sa[i];
        }
        for(int i=1;i<=n;i++){
            c[x[y[i]]]++;
        }
        for(int i=1;i<=m;i++){
            c[i]+=c[i-1];
        }
        for(int i=n;i>=1;i--){
            sa[c[x[y[i]]]--]=y[i];
        }

        // 保存上一轮的组号到y数组
        for(int i=1;i<=n;i++){
            y[i]=x[i];
        }
        m=0;
        for(int i=1;i<=n;i++){
            if(y[sa[i]]==y[sa[i-1]]&&y[sa[i]+k]==y[sa[i-1]+k]){
                // 第一个关键字组号相同  第二个关键字组号相同  那么这一次也是一个组
                x[sa[i]]=m;
            }
            else{
                x[sa[i]]=++m;
            }
            if(m==n){
                break;
            }
        }
    }
}

void getheight(){
    for(int i=1;i<=n;i++){
        rk[sa[i]]=i;
    }
    for(int i=1,k=0;i<=n;i++){
        if(rk[i]==1){
            continue;
        }
        // 利用height性质：height[rk[i]] >= height[rk[i-1]] - 1
        if(k){
            k--;
        }
        int j=sa[rk[i]-1];
        while(i+k<=n&&j+k<=n&&s[i+k]==s[j+k]){
            k++;
        }
        height[rk[i]]=k;
    }
}

int lg2[MAXN];
int st[MAXN][MAXH];

void buildst(){
    lg2[0]=-1;
    for(int i=1;i<=n;i++){
        lg2[i]=lg2[i>>1]+1;
        st[i][0]=i;
    }
    for(int i=1;i<=lg2[n];i++){
        for(int j=1;j+(1<<(i-1))-1<=n;j++){
            if(height[st[j][i-1]]<height[st[j+(1<<(i-1))][i-1]]){
                st[j][i]=st[j][i-1];
            }
            else{
                st[j][i]=st[j+(1<<(i-1))][i-1];
            }
        }
    }
}

int query(int l,int r){
    int p=lg2[r-l+1];
    if(height[st[l][p]]<height[st[r-(1<<p)+1][p]]){
        return st[l][p];
    }
    else{
        return st[r-(1<<p)+1][p];
    }
}

int k;
int arr[MAXM];
int ans;
bool vis[MAXN];

bool cmp(int a,int b){
    return a<b;
}

int find(int val){
    int l=1,r=k,ans=0;
    while(l<=r){
        int mid=(l+r)>>1;
        if(arr[mid]<=val){
            ans=mid;
            l=mid+1;
        }
        else{
            r=mid-1;
        }
    }
    return ans;
}

// 处理在arr数组中排名为lt~rt的答案
void fun(int lt,int rt){
    // cout<<"   "<<lt<<' '<<rt<<endl;
    if(rt<=lt){
        return ;
    }

    int split=query(arr[lt]+1,arr[rt]);
    int pos=find(split);

    int l=pos-lt+1;
    int r=rt-pos;

    int val=height[split];

    if(vis[split]){
        ans=(ans+((l-1)*(r+1)%MOD)*val)%MOD;
        fun(lt,pos-1);
        fun(pos,rt);
    }
    else{
        ans=(ans+(l*r%MOD)*val)%MOD;
        fun(lt,pos);
        fun(pos+1,rt);
    }
}

void compute(){
    sort(arr+1,arr+k+1,cmp);
    m=1;
    for(int i=2;i<=k;i++){
        if(arr[i]!=arr[i-1]){
            arr[++m]=arr[i];
        }
    }
    k=m;
    if(k==1){
        cout<<0<<endl;
        return ;
    }

    // cout<<"   "<<k<<endl;
    for(int i=1;i<=k;i++){
        vis[arr[i]]=true;
    }
    ans=0;
    fun(1,k);
    for(int i=1;i<=k;i++){
        vis[arr[i]]=false;
    }
    cout<<ans<<endl;
    return ;
}

signed main()
{
    scanf("%d %d",&n,&t);
    m=26;
    scanf("%s",s+1);
    getsa();
    getheight();

    // for(int i=1;i<=n;i++){
    //     cout<<sa[i]<<' ';
    // }
    // cout<<endl;
    // for(int i=1;i<=n;i++){
    //     cout<<rk[i]<<' ';
    // }
    // cout<<endl;
    // for(int i=1;i<=n;i++){
    //     cout<<height[i]<<' ';
    // }
    // cout<<endl;

    buildst();
    for(int i=1;i<=t;i++){
        scanf("%d",&k);
        for(int i=1;i<=k;i++){
            scanf("%d",&arr[i]);
            arr[i]=rk[arr[i]];
        }
        if(k==1){
            cout<<0<<endl;
            continue;
        }
        compute();
    }
    return 0;
}
