#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e6+5;

int tree[MAXN][2];
int pass[MAXN];
int cnt=1;
int high;
int n,k;

void insert(int num) {
    int cur = 1;
    pass[cur]++;
    for (int i = high, path; i >= 0; i--) {
        path = (num >> i) & 1;
        if (tree[cur][path] == 0) {
            tree[cur][path] = ++cnt;
        }
        cur = tree[cur][path];
        pass[cur]++;
    }
}

int query(int x){
    int cur=1;
    int ans=0;
    for(int i=(1<<high);i>0;i>>=1){
        int a=x&i;
        int b=x&i;
        if(b==1){
            ans+=pass[tree[cur][1-(a^b)]];
        }
        cur=tree[cur][a^b];
        if(cur==0){
            return ans;
        }
    }
    return ans+pass[cur];
}

