void tarjan(int u,int fa){
    subsz++;
    dfn[u]=low[u]=++dfncnt;
    sta[++top]=u;
    val[u]=-1;

    for(int i=headg[u];i;i=nxtg[i]){
        int v=tog[i];
        if(v==fa){
            continue;
        }

        if(!dfn[v]){
            tarjan(v,u);
            low[u]=min(low[u],low[v]);
