                    int x=sta[top--];
                    addedge(cnt,x);
                    addedge(x,cnt);
                    val[cnt]++;
                }
                top--;
                addedge(cnt,v);
                addedge(v,cnt);

                addedge(u,cnt);
                addedge(cnt,u);
            }
        }
        else{
            low[u]=min(low[u],dfn[v]);
        }
    }
}

