void up(int i){
    maxx[i]=max(maxx[i<<1],maxx[i<<1|1]);
    maxval[i]=max(maxval[i<<1],maxval[i<<1|1]);
}

void build(int l,int r,int i){
    if(l==r){
        maxval[i]=val[l];
        maxx[i]=val[l];
    }
    else{
        int mid=(l+r)>>1;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        up(i);
    }
}

void addlazy(int i,int v,int val){
    maxval[i]=max(maxval[i],maxx[i]+val);
    maxx[i]+=v;
    if(vis[i]){
        maxup[i]=max(maxup[i],upval[i]+val);
        upval[i]+=v;
    }
    else{
        maxadd[i]=max(maxadd[i],addval[i]+val);
        addval[i]+=v;
    }
}

void updatelazy(int i,int v,int val){
    if(vis[i]){
        maxup[i]=max(maxup[i],val);
    }
    else{
        vis[i]=true;
        maxup[i]=val;
    }
    maxval[i]=max(maxval[i],val);
    maxx[i]=v,upval[i]=v,addval[i]=0;
}

void down(int i){
    addlazy(i<<1,addval[i],maxadd[i]);
    addlazy(i<<1|1,addval[i],maxadd[i]);
    addval[i]=maxadd[i]=0;

    if(vis[i]){
        vis[i]=false;
        updatelazy(i<<1,upval[i],maxup[i]);
        updatelazy(i<<1|1,upval[i],maxup[i]);
        upval[i]=maxup[i]=0;
    }
}

int query(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        return maxx[i];
    }
    else{
        int mid=(l+r)>>1;
        down(i);
        int ans=INT_MIN;
        if(jobl<=mid){
            ans=max(ans,query(jobl,jobr,l,mid,i<<1));
        }
        if(jobr>mid){
            ans=max(ans,query(jobl,jobr,mid+1,r,i<<1|1));
        }
        return ans;
    }
}

int querymax(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        return maxval[i];
    }
    else{
        int mid=(l+r)>>1;
        down(i);
        int ans=INT_MIN;
        if(jobl<=mid){
            ans=max(ans,querymax(jobl,jobr,l,mid,i<<1));
        }
        if(jobr>mid){
            ans=max(ans,querymax(jobl,jobr,mid+1,r,i<<1|1));
        }
        return ans;
    }
}

void add(int jobl,int jobr,int jobv,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        addlazy(i,jobv,jobv);
    }
    else{
        int mid=(l+r)>>1;
        down(i);
        if(jobl<=mid){
            add(jobl,jobr,jobv,l,mid,i<<1);
        }
        if(jobr>mid){
            add(jobl,jobr,jobv,mid+1,r,i<<1|1);
        }
        up(i);
    }
}

void update(int jobl,int jobr,int jobv,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        updatelazy(i,jobv,jobv);
    }
    else{
        int mid=(l+r)>>1;
        down(i);
        if(jobl<=mid){
            update(jobl,jobr,jobv,l,mid,i<<1);
        }
        if(jobr>mid){
            update(jobl,jobr,jobv,mid+1,r,i<<1|1);
        }
        up(i);
    }
}

