#include<bits/stdc++.h>
using namespace std;
const int MAXN = 105;
const int MAXV = MAXN+10;
const int MAXE = MAXN*MAXN*2;
const int INF = 1e9;

int n,m,s,t;
int ss,tt;// 附加源点、汇点

int dep[MAXV];
int iter[MAXV];

int cnt=2;
int head[MAXV];
int nxt[MAXE];
int to[MAXE];
int now[MAXE];
int cap[MAXE];
int ts_id; // 记录t->s边的编号

// 每个节点的下界净流量
int in[MAXV];

void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    cap[cnt]=w;
    now[cnt]=0;
    head[u]=cnt++;

    nxt[cnt]=head[v];
    to[cnt]=u;
    cap[cnt]=0;
    now[cnt]=0;
    head[v]=cnt++;
}

bool bfs(int s,int t){
    for(int i=1;i<=tt;i++){
        dep[i]=-1;
    }
    queue<int>q;
    dep[s]=0;
    q.push(s);
    while(!q.empty()){
        int u=q.front();
        q.pop();
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            int w=cap[i];
            int k=now[i];
            if(dep[v]<0&&(k<w)){
                dep[v]=dep[u]+1;
                q.push(v);
            }
        }
    }
    return dep[t]>=0;
}

int dfs(int u,int t,int f){
    if(u==t){
        return f;
    }
    int flow=0;
    for(int &i=iter[u];i;i=nxt[i]){
        int v=to[i];
        int w=cap[i];
        int k=now[i];
        if(dep[u]+1==dep[v]&&k<w){
            int d=dfs(v,t,min(f,w-k));
            if(d>0){
                now[i]+=d;
                now[i^1]-=d;
                flow+=d;
                f-=d;
                if(f==0){
                    break;
                }
            }
        }
    }
    return flow;
}

int maxflow(int s,int t){
    int flow=0;
    while(bfs(s,t)){
        for(int i=1;i<=tt;i++){
            iter[i]=head[i];
        }
        int maxflow;
        while((maxflow=dfs(s,t,INF))>0){
            flow+=maxflow;
        }
    }
    return flow;
}

