#include<bits/stdc++.h>
using namespace std;
const int MAXN = 100005;

int t,n,m,k;
int arr[MAXN],Sort[MAXN],tree[MAXN];

inline int lowbit(int x){
    return x&-x;
}

inline void add(int i, int v) {
    while (i <= m) {
        tree[i] += v;
        i += lowbit(i);
    }
}

// 1~i范围的累加和
inline int sum(int i) {
    int ans = 0;
    while (i > 0) {
        ans += tree[i];
        i -= lowbit(i);
    }
    return ans;
}

// 给定原始值v
// 返回排名值(排序部分1~m中的下标)
inline int Rank(int v) {
	int l = 1, r = m, mid;
    int ans = 0;
    while (l <= r) {
        mid = (l + r) / 2;
        if (Sort[mid] >= v) {
            ans = mid;
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }
    return ans;
}

inline bool check(long long  limit){
    int h=1;
    int i=m,R=m;
    long long  cnt=0;
    while(i>0){
        if(cnt+sum(arr[i]-1)<=limit){
            cnt+=sum(arr[i]-1);
            add(arr[i],1);
        }else{
            for(int j=i+1;j<=R;j++)
                add(arr[j],-1);
            R=i;
            h++;
            cnt=0;
            add(arr[i],1);
        }
        i--;
        if(h>k){
            return false;
        }
    }
    return true;
}

int main()
{
    cin>>t;
