            cin>>arr[i];
            Sort[i]=arr[i];
        }
        sort(Sort+ 1,Sort+ n + 1);
        m = 1;
        for (int i = 2; i <= n; i++) {
            if (Sort[m] != Sort[i]) {
                Sort[++m] = Sort[i];
            }
        }
        //将数组去重
        for (int i = 1; i <= n; i++) {
            arr[i] = Rank(arr[i]);
            //将原有数组的值改为他们在数组中的大小排名  原有的数据本来就没有什么用
            //这样还更方便计算  以及节约空间
        }
        long long  ans=1e10,l=0,r=1e10;
        while(l<=r){
            long long mid=l+(r-l)/2;
            if(check(mid)){
                ans=mid;
                r=mid-1;
                memset(tree,0,sizeof(tree));
            }else{
                l=mid+1;
                memset(tree,0,sizeof(tree));
            }
        }
        cout<<ans<<endl;
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <map>
using namespace std;

const int N = 100010;

int n, q;
vector<int> g[N];
int w[N];
int fa[N], dep[N], siz[N], son[N];
int top[N], dfn[N], rk[N], index;
map<int, int> cnt;

struct Node {
    int max1, max2;
    Node() : max1(-1), max2(-1) {}
    Node(int a, int b) : max1(a), max2(b) {}
};

Node tr[N << 2];

Node combine(Node a, Node b) {
    if (a.max1 == -1) return b;
    if (b.max1 == -1) return a;
    vector<int> v;
    v.push_back(a.max1);
    if (a.max2 != -1) v.push_back(a.max2);
    v.push_back(b.max1);
    if (b.max2 != -1) v.push_back(b.max2);
    sort(v.begin(), v.end(), greater<int>());
    auto last = unique(v.begin(), v.end());
    v.erase(last, v.end());
    Node res;
    res.max1 = v[0];
    if (v.size() >= 2) res.max2 = v[1];
    else res.max2 = -1;
    return res;
}

void build(int rt, int l, int r) {
    if (l == r) {
        int val = w[rk[l]];
        tr[rt] = Node(val, -1);
        return;
    }
    int mid = (l + r) >> 1;
    build(rt << 1, l, mid);
    build(rt << 1 | 1, mid + 1, r);
    tr[rt] = combine(tr[rt << 1], tr[rt << 1 | 1]);
}

void update(int rt, int l, int r, int pos, int val) {
    if (l == r) {
        tr[rt] = Node(val, -1);
        return;
    }
    int mid = (l + r) >> 1;
    if (pos <= mid) update(rt << 1, l, mid, pos, val);
    else update(rt << 1 | 1, mid + 1, r, pos, val);
    tr[rt] = combine(tr[rt << 1], tr[rt << 1 | 1]);
}

Node query_seg(int rt, int l, int r, int L, int R) {
    if (L <= l && r <= R) return tr[rt];
    int mid = (l + r) >> 1;
    Node res;
    if (L <= mid) res = combine(res, query_seg(rt << 1, l, mid, L, R));
    if (R > mid) res = combine(res, query_seg(rt << 1 | 1, mid + 1, r, L, R));
    return res;
}

void dfs1(int u, int f) {
    fa[u] = f;
    dep[u] = dep[f] + 1;
    siz[u] = 1;
    son[u] = 0;
    for (int v : g[u]) {
        if (v == f) continue;
        dfs1(v, u);
        siz[u] += siz[v];
        if (siz[v] > siz[son[u]]) son[u] = v;
    }
}

void dfs2(int u, int t) {
    top[u] = t;
    dfn[u] = ++index;
    rk[index] = u;
    if (son[u]) dfs2(son[u], t);
    for (int v : g[u]) {
        if (v == fa[u] || v == son[u]) continue;
        dfs2(v, v);
    }
}

Node query_chain(int x, int y) {
    Node res;
    while (top[x] != top[y]) {
        if (dep[top[x]] < dep[top[y]]) swap(x, y);
        Node tmp = query_seg(1, 1, n, dfn[top[x]], dfn[x]);
        res = combine(res, tmp);
        x = fa[top[x]];
    }
    if (dep[x] > dep[y]) swap(x, y);
    Node tmp = query_seg(1, 1, n, dfn[x], dfn[y]);
    res = combine(res, tmp);
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n;
    for (int i = 1; i < n; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    for (int i = 1; i <= n; i++) {
        cin >> w[i];
        cnt[w[i]]++;
    }

    dep[0] = 0;
    dfs1(1, 0);
    index = 0;
    dfs2(1, 1);
    build(1, 1, n);

    cin >> q;
    while (q--) {
        int opt, x, y;
        cin >> opt >> x >> y;
        if (opt == 0) {
            int old_val = w[x];
            w[x] += y;
            update(1, 1, n, dfn[x], w[x]);
            cnt[old_val]--;
            if (cnt[old_val] == 0) cnt.erase(old_val);
            cnt[w[x]]++;
        } else {
            Node res = query_chain(x, y);
            if (res.max2 == -1) {
                cout << -1 << '\n';
            } else {
                int a = res.max2;
                int b = res.max1;
                cnt[a]--;
                cnt[b]--;
                int M1 = -1, M2 = -1;
                for (auto it = cnt.rbegin(); it != cnt.rend(); it++) {
                    if (it->second > 0) {
                        if (M1 == -1) {
                            M1 = it->first;
                        } else {
                            M2 = it->first;
                            break;
                        }
                    }
                }
                cnt[a]++;
                cnt[b]++;
                cout << a << " " << M2 << '\n';
            }
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;

int n,m;
int val[MAXN];

int fa[MAXN];
int ls[MAXN];
int rs[MAXN];
bool rev[MAXN];
int sta[MAXN];
long long sum[MAXN];

int tail[MAXN];

void up(int x){
    sum[x]=sum[ls[x]]+sum[rs[x]]+val[x];
}

// 判断节点x是不是辅助splay的顶部节点
bool isroot(int x) {
    return ls[fa[x]] != x && rs[fa[x]] != x;
}

// x不是辅助splay的顶部节点才能调用，返回x是其父的哪侧儿子
int lr(int x) {
    return ls[fa[x]] == x ? 0 : 1;
}

// 翻转以x为根的辅助splay，交换左右儿子，打上翻转标记
void reverse(int x) {
    if (x != 0) {
        swap(ls[x], rs[x]);
        rev[x] = !rev[x];
    }
}

// 处理翻转懒更新
void down(int x) {
    if (rev[x]) {
        reverse(ls[x]);
        reverse(rs[x]);
        rev[x] = false;
    }
}

// x向上旋转
void rotate(int x) {
    int f = fa[x], g = fa[f];
    if (lr(x) == 0) {
        ls[f] = rs[x];
        if (ls[f] != 0) {
            fa[ls[f]] = f;
        }
        rs[x] = f;
    } else {
        rs[f] = ls[x];
        if (rs[f] != 0) {
            fa[rs[f]] = f;
        }
        ls[x] = f;
    }
    if (!isroot(f)) {
        if (lr(f) == 0) {
            ls[g] = x;
        } else {
            rs[g] = x;
        }
    }
    fa[f] = x;
    fa[x] = g;
    up(f);
    up(x);
}

// x提到辅助splay的顶部
void splay(int x) {
    int siz = 0;
    sta[++siz] = x;
    for (int y = x; !isroot(y); y = fa[y]) {
        sta[++siz] = fa[y];
    }
    while (siz != 0) {
        down(sta[siz--]);
    }
    while (!isroot(x)) {
        int f = fa[x];
        if (!isroot(f)) {
            if (lr(x) == lr(f)) {
                rotate(f);
            } else {
                rotate(x);
            }
        }
        rotate(x);
    }
}

void access(int x){
    for(int y=0;x;y=x,x=fa[x]){
        splay(x);
        rs[x]=y;
        up(x);
    }
}

void makeroot(int x){
    access(x);
    splay(x);
    reverse(x);
}

int findroot(int x){
    access(x);
    splay(x);
    down(x);
    while(ls[x]){
        x=ls[x];
        down(x);
    }
    splay(x);
    return x;
}

void link(int x,int y){
    fa[y]=x;
}

// void cut(int x,int y){
//     int rx=findroot(y);
//     makeroot(y);
//     down(y);
//     fa[ls[y]]=0;
//     ls[y]=0;
//     up(y);
//     makeroot(rx);
// }

void cut(int x,int y){
    int rx = findroot(y);

    makeroot(x);
    access(y);
    splay(y);

    ls[y] = 0;
    fa[x] = 0;
    up(y);

    makeroot(rx);
}

int pre(int x) {
    access(x);
    splay(x);

    int p = ls[x];

    down(p);
    while (rs[p]) {
        p = rs[p];
        down(p);
    }

    splay(p);
    return p;
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m;
    for(int i=1;i<=n;i++){
        cin>>val[i];
        sum[i]=val[i];
        tail[i]=i;
    }
    for(int i=1;i<=m;i++){
        char op;
        int x,y;
        cin>>op;
        if(op=='M'){
            cin>>x>>y;
            swap(x,y);

            int rx=findroot(x);
            int ry=findroot(y);
            if(rx==ry){
                continue;
            }
            link(tail[rx],ry);
            tail[rx]=tail[ry];
        }
        else if(op=='D'){
            cin>>x;
            int rx=findroot(x);
            if(rx==x){
                continue;
            }
            int p=pre(x);
            tail[x]=tail[rx];
            tail[rx]=p;
            cut(p,x);
        }
        else{
            cin>>x>>y;

            int rx=findroot(x);
            int ry=findroot(y);
            if(rx!=ry){
                cout<<-1<<endl;
                continue;
            }
            makeroot(x);
            access(y);
            splay(y);
            cout<<sum[y]<<endl;
            makeroot(rx);
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;

const int MAXN = 12;//字符数量
const int MAXS = 605;//所有字符的总数

int state[MAXS];//表示到达这个节点后，就会有什么样的状态

// AC自动机
int tree[MAXS][26];
int fail[MAXS];
int cnt = 0;

// 可以用作队列或者栈，一个容器而已 设立fail指针
int box[MAXS];
string s;
int path;

int n;//字符串数量

struct node{
    int now,status;
};
queue<node>q;

bool vis[600][1<<12];
int ans[600*(1<<12)],fa[600*(1<<12)],c[605];

void insert(int i,string word){
    //i是目标串的编号
    int cur=0;//头结点设置为0
    for (char ch : word){
        path=ch-'A';
        if(tree[cur][path]==0){
            tree[cur][path]=++cnt;
            //没有路就要新建一条路  并赋予编号
        }
        cur=tree[cur][path];
    }
    state[cur]|=(1<<i);
    //cout<<i<<' '<<state[cur]<<endl;
}

void setFail() {
    // box当做队列来使用
    int l = 0;
    int r = 0;
    for (int i = 0; i <= 25; i++) {
        if (tree[0][i] > 0) {
            box[r++] = tree[0][i];
            //0节点中只有有孩子的节点加入队列中
            //这个队列里面存储过的所有节点都要有fail
        }
    }
    while (l < r) {
        int u = box[l++];
        for (int i = 0; i <= 25; i++) {
            if (tree[u][i] == 0) {
                tree[u][i] = tree[fail[u]][i];
            } else {
                fail[tree[u][i]] = tree[fail[u]][i];//设置这个孩子节点的fail指针   直通表辅助不用绕环
                state[tree[u][i]]|=state[tree[fail[u]][i]];//它的fail指针包含的字符串它也包含
                box[r++] = tree[u][i];//表示有这条支路  加入到队列中
                //cout<<state[tree[u][i]]<<endl;
            }
        }
    }
}

int main()
{
    cin>>n;
    for(int i=0;i<n;i++){
        cin>>s;
        //cout<< "   "<<i<<endl;
        insert(i,s);
    }
    setFail();
    //cout<<endl;
    q.push({0,0});
    vis[0][0]=true;
    int t=0,nod=0,tot=0;
    while(!q.empty()){
        int now=q.front().now;
        int status=q.front().status;
        q.pop();
        if(status==((1<<n)-1)){
            while(t){
                c[++nod]=ans[t];
                t=fa[t];
            }//递归回去求答案
            for(int i=nod;i>0;i--)
                putchar(c[i]+'A');
            return 0;
        }
        for(int i=0;i<26;i++){
            if(!vis[tree[now][i]][status|state[tree[now][i]]]){
                vis[tree[now][i]][status|state[tree[now][i]]]=true;
                q.push({tree[now][i],status|state[tree[now][i]]});
                //找出现新的状态
                fa[++tot]=t;
                ans[tot]=i;
                //记录当前搜到的字符,同时建1棵关于答案的树,便于最后查询
            }
        }
        t++;//Ti表示当前的搜索到的编号
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e6+5;
const int LIMIT = 21;

int power;
int ans;
int stjump[MAXN << 1][LIMIT];
int n, m;
struct flag{
    int num,s,e;//表示编号  开始 结束位置
}line[MAXN<<1];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

bool cmp(flag a,flag b){
    return a.s < b.s;
}//比较函数

int log2(int n) {
    int ans = 0;
    while ((1 << ans) <= (n >> 1)) {
        ans++;
    }
    return ans;
}
//求出不超过n的最大2的幂次方是多少  即‘跳跃’次数不会超过

void build() {
    for (int i = 1; i <= n; i++) {
        if (line[i].s > line[i].e) {
            //所有左边界大于右边界的边 更改一下
            line[i].e += m;
        }
    }//首先将线段变成一个链的形式
    sort(line+1 ,line+n+1,cmp);
    // for(int i=1;i<=n;i++)
    //    printf("%d %d %d\n",line[i][0],line[i][1],line[i][2]);
    for (int i = 1; i <= n; i++) {
        line[i + n].num = line[i].num;
        line[i + n].s = line[i].s + m;
        line[i + n].e = line[i].e + m;
    }
    //实现线段的克隆
    int e = n << 1;//线段的数目变为原来两倍

    for (int i = 1, arrive = 1; i <= e; i++) {
        //arrive  表示寻找到的目前的线段条数
        while (arrive + 1 <= e && line[arrive + 1].s <= line[i].e) {
            //判断条件是  这条线段没有越界 即不是最后一条线段
            //并且这条线段的左边界小于等于目前线段的右边界
            arrive++;
        }
        stjump[i][0] = arrive;//表示跳跃2的0次方步可以到达的线段编号
    }//记录每条线段走一步可以到什么地方

    for (int p = 1; p <= power; p++) {
        for (int i = 1; i <= e; i++) {
            stjump[i][p] = stjump[stjump[i][p - 1]][p - 1];
        }
    }//完成st表
}

int jump(int i) {
    //表示现在来到了第i条线段  要统计这个战士的答案
    int aim = line[i].s + m, cur = i, next, ans = 0;
    //aim是这条线段期望的目标
    for (int p = power; p >= 0; p--) {
        next = stjump[cur][p];//表示跳2的p次方可以到哪
        if (next != 0 && line[next].e < aim) {
            ans += 1 << p;
            cur = next;
        }
    }
    return ans + 1 + 1;
}

void compute() {
    power = log2(n);
    build();
    ans=INT_MAX;
    for (int i = 1; i <= n; i++) {
        ans=min(ans,jump(i));
    }
}

int main()
{
    cin>>m>>n;
    for(int i=1;i<=n;i++){
        line[i].num=i;
        line[i].s=read();
        line[i].e=read()+1;
        if(line[i].s==line[i].e%m){
            cout<<1<<endl;
            return 0;
        }
    }
    compute();
    if(ans==INT_MAX||ans>n){
        cout<<"impossible";
        return 0;
    }
    cout<<ans<<endl;
    return 0;
}

