    for(int i=1;i<=n;i++){
        len+=w[i];
        while(len>limit){
            len-=w[now];
            now++;
        }
        updateh(now-1,i-1,h[i],0,n,1);
        f[i]=query(now-1,i-1,0,n,1);
        updatef(i,f[i],0,n,1);
    }
    cout<<f[n]<<endl;
