    d%=(MOD-1);
    f[1]=1;
    for(int i=2;i<=n;i++){
        if(!vis[i]){
            prime[++cnt]=i;
            f[i]=power(i,d)+1;
        }
        for(int j=1;j<=cnt&&i*prime[j]<=n;j++){
            vis[i*prime[j]]=true;
            if(i%prime[j]!=0){
                f[i*prime[j]]=(f[i]*f[prime[j]])%MOD;
            }
            else{
                int a=prime[j],b=i;
                while(b%prime[j]==0){
                    b/=prime[j];
                    a*=prime[j];
                }
                if(b==1){
                    f[i*prime[j]]=(f[i]+power(a,d))%MOD;
                }
                else{
                    f[i*prime[j]]=(f[a]*f[b])%MOD;
                }
                break;
            }
        }
    }
    for(int i=1;i<=n;i++){
        g[i]=(g[i-1]+f[i])%MOD;
    }
    while(q--){
        int l,r;
        cin>>l>>r;
        int ans=(g[r]-g[l-1]+MOD)%MOD;
        cout<<ans<<endl;
