int rt[MAXN];
int sz[MAXN];
int fa[MAXN];

int cnt;
int root[MAXN];
int trie[MAXK][2];
int pass[MAXK];
int one[MAXN][MAXH];

int tree[MAXN<<2];
int tag[MAXN<<2];

