inline void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

void insert(int val,int u){
    int cur=root[u];
    pass[cur]++;
    for(int i=0;i<=19;i++){
        int path=(val>>i)&1;
        if(path){
            one[u][i]++;
        }
        if(trie[cur][path]==0){
            trie[cur][path]=++cnt;
        }
        cur=trie[cur][path];
        pass[cur]++;
    }
}

void del(int val,int u){
    int cur=root[u];
    pass[cur]--;
    for(int i=0;i<=19;i++){
        int path=(val>>i)&1;
        if(path){
            one[u][i]--;
        }
        cur=trie[cur][path];
        pass[cur]--;
    }
}

void addone(int u,int cur,int d){
    if(cur==0||pass[cur]==0||d>19){
        return ;
    }
    one[u][d]+=pass[trie[cur][0]]-pass[trie[cur][1]];
    swap(trie[cur][0],trie[cur][1]);
    addone(u,trie[cur][0],d+1);
}

void dfs(int u,int f){
    lt[u]=dfncnt+1;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=f){
            fa[v]=u;
            dfn[v]=++dfncnt;
            seg[dfncnt]=v;
            insert(val[v],u);
        }
    }
    rt[u]=dfncnt;
    sz[u]=rt[u]-lt[u]+1;

    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=f){
            dfs(v,u);
        }
    }
}

void build(int l,int r,int i){
    if(l==r){
        tree[i]=val[seg[l]];
    }
    else{
        int mid=(l+r)>>1;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
    }
}

void lazy(int i,int val){
    tag[i]+=val;
    tree[i]+=val;
}

void down(int i){
    if(tag[i]){
        lazy(i<<1,tag[i]);
        lazy(i<<1|1,tag[i]);
        tag[i]=0;
    }
}

void add(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        lazy(i,1);
    }
    else{
        int mid=(l+r)>>1;
        down(i);
        if(jobl<=mid){
            add(jobl,jobr,l,mid,i<<1);
        }
        if(jobr>mid){
            add(jobl,jobr,mid+1,r,i<<1|1);
        }
    }
}

void update(int pos,int val,int l,int r,int i){
    if(l==r){
        tree[i]=val;
    }
    else{
        down(i);
        int mid=(l+r)>>1;
        if(pos<=mid){
            update(pos,val,l,mid,i<<1);
        }
        else{
            update(pos,val,mid+1,r,i<<1|1);
        }
    }
}

int query(int pos,int l,int r,int i){
    if(l==r){
        return tree[i];
    }
    else{
        int mid=(l+r)>>1;
        down(i);
        if(pos<=mid){
            return query(pos,l,mid,i<<1);
        }
        else{
            return query(pos,mid+1,r,i<<1|1);
        }
    }
}

