void dfs(int x,int y,int k,int f){
    //表示到了xy  花费为k  f=1表示可用魔法
    if(k>=ans||k>t[x][y]){
        return;
    }
    t[x][y]=min(t[x][y],k);
    if(x==m&&y==m){
        ans=k;
        return;
    }
    for(int i=0;i<4;i++){
        int ux=x+walk[i][0];
        int uy=y+walk[i][1];
        if(vis[ux][uy]||ux>m||uy>m||ux<=0||uy<=0||(f==0&&nums[ux][uy]==0)){
            continue;
        }
        vis[ux][uy]=true;
        if(nums[ux][uy]==0){
            nums[ux][uy]=nums[x][y];
            dfs(ux,uy,k+2,0);
            nums[ux][uy]=0;
        }
        else if(nums[ux][uy]==nums[x][y]){
            dfs(ux,uy,k,1);
        }
        else if(nums[ux][uy]!=nums[x][y]){
            dfs(ux,uy,k+1,1);
        }
        vis[ux][uy]=false;
    }
}

