int arr[MAXN];
// dfs判断负环，每个点的累积边权
double d[MAXN];
// dfs判断负环，每个点是否是递归路径上的点
bool vis[MAXN];
int num[MAXN];

void addedge(int u,int v,double w){
    Next[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    head[u]=cnt++;
}

int check(double x)
{
    queue<int> q;
    for(int i=1;i<=n;++i)//因为图不一定连通，所以初始所有结点入队
    {
    	q.push(i);
    	d[i]=0;
    	vis[i]=num[i]=1;
    }
    while(!q.empty())
    {
        int u=q.front();
        q.pop();
        vis[u]=0;
        for(int i=head[u];i;i=Next[i])
        {
            int v=to[i];
            double dis=weight[i];
            if(d[v]>d[u]+x*dis-arr[u])//边权为mid*Tim[e_i]-Fun[u_i]
            {
                d[v]=d[u]+x*dis-arr[u];
                if(!vis[v])
                {
                    q.push(v); vis[v]=1;
                    if(++num[v]>=n) return 1;
                }
            }
        }
    }
    return 0;
}

