}

bool cmpq(node a,node b){
    return a.q<b.q;
}

bool cmpp(node a,node b){
    return a.p<b.p;
}

int find(int val){
    int l=1,r=m,ans;
    while(l<=r){
        int mid=(l+r)/2;
        if(arr[mid]>=val){
            ans=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    return ans;
}

inline int lowbit(int x){
    return x&-x;
}

void update(int x,int val){
    while(x<=m){
        tree[x]=max(tree[x],val);
        x+=lowbit(x);
    }
}

int query(int x){
    int ans=0;
    while(x){
        ans=max(ans,tree[x]);
        x-=lowbit(x);
    }
    return ans;
}

void clear(int x){
    while(x<=m){
        tree[x]=0;
        x+=lowbit(x);
    }
}

void merge(int l,int mid,int r){
    for(int i=l;i<=r;i++){
        tmp[i]=nums[i];
    }
    sort(tmp+l,tmp+mid+1,cmpa);
    sort(tmp+mid+1,tmp+r+1,cmpp);
    int p1=l-1,p2=mid+1;
    for(;p2<=r;p2++){
        while(p1+1<=mid&&tmp[p1+1].a<=tmp[p2].p){
            p1++;
            update(tmp[p1].q,dp[tmp[p1].id]);
        }
        dp[tmp[p2].id]=max(dp[tmp[p2].id],query(tmp[p2].a)+1);
    }
    for(int i=l;i<=p1;i++){
        clear(tmp[i].q);
    }
}

void cdq(int l,int r){
    if(l==r){
        return ;
    }
    int mid=(l+r)/2;
    cdq(l,mid);
    merge(l,mid,r);
    cdq(mid+1,r);
}

