int calc(int s, int ban) {
    if (vis[s]) return 0;

    int top = 0;
    int ans = 0;

    sta[++top] = s;
    vis[s] = true;

    while (top) {
        int u = sta[top--];
        ans++;

        for (int i = head[u]; i; i = nxt[i]) {
            int v = to[i];

            if (v == ban || vis[v]) continue;

            vis[v] = true;
            sta[++top] = v;
        }
    }

    return ans;
}

int needone(long long need) {
    if (need <= 0) return 0;

    int l = 1, r = cntone, ans = INF;

    while (l <= r) {
        int mid = (l + r) >> 1;

        if (preOne[mid] >= need) {
            ans = mid;
            r = mid - 1;
        }
        else {
            l = mid + 1;
        }
    }

    return ans;
}

