int nxt[MAXM<<1];
int to[MAXM<<1];
int cntg=2;

int head2[MAXN];
int nxt2[MAXM];
int to2[MAXM];
int cnte=2;

int dfncnt;
int dfn[MAXN];
int low[MAXN];
int edgesta[MAXM];
int top;

int bccCnt;
int belong[MAXM];
int mask[MAXN];
int node[MAXN];
int vmask[MAXN];

