int sz[MAXN];

inline void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

inline void addedge2(int u,int v){
    nxt2[cnte]=head2[u];
    to2[cnte]=v;
    head2[u]=cnte++;
}

void tarjan(int u,int preedge)
{
    dfn[u]=low[u]=++dfncnt;

    for(int i=head[u];i;i=nxt[i]){
        if(i==(preedge^1)) continue;

        int v=to[i];

        if(dfn[v]==0){
            edgesta[++top]=i>>1;

            tarjan(v,i);

            low[u]=min(low[u],low[v]);

            if(low[v]>=dfn[u]){
                bccCnt++;

                int pop;
                do{
                    pop=edgesta[top--];
                    belong[pop]=bccCnt;
                }while(pop!=(i>>1));
            }
        }
        else if(dfn[v]<dfn[u]){
            edgesta[++top]=i>>1;
            low[u]=min(low[u],dfn[v]);
        }
    }
}

int find(int x){
    return x==fa[x]?x:fa[x]=find(fa[x]);
}

void un(int x,int y){
    int fx=find(x);
    int fy=find(y);
    if(fx!=fy){
        if(sz[fx]>sz[fy]){
            swap(fx,fy);
        }
        fa[fx]=fy;
        sz[fy]+=sz[fx];
    }
}

long long compute(int v){
    for(int i=1;i<=n;i++){
        fa[i]=i;
        sz[i]=1;
    }

    int b=1<<v;
    for(int i=1;i<=m;i++){
        if(mask[belong[i]]==b){
            un(ex[i],ey[i]);
        }
    }

    long long ans=0;
    for(int i=1;i<=n;i++){
        if(i==find(i)){
            ans+=1ll*sz[i]*(sz[i]-1)/2;
        }
    }
    return ans;
}

