    for(int i=1;i<=m;i++){
        char c;
        cin>>ex[i]>>ey[i]>>c;
        ew[i]=(c=='D');

        addedge(ex[i],ey[i]);
        addedge(ey[i],ex[i]);
    }

    tarjan(1,0);

    for(int i=1;i<=m;i++){
        int b=belong[i];
        addedge2(b,i);
        mask[b]|=1<<ew[i];
    }

    long long ans=1ll*(n-1)*n/2;

    ans-=compute(0);
    ans-=compute(1);

    for(int b=1;b<=bccCnt;b++){
        if(mask[b]!=3){
            continue;
        }

        int cnt=0;
        for(int i=head2[b];i;i=nxt2[i]){
            int v=to2[i];

            int x=ex[v];
            int y=ey[v];
            int w=ew[v];
            if(vmask[x]==0){
                node[++cnt]=x;
            }
            if(vmask[y]==0){
                node[++cnt]=y;
            }

            vmask[x]|=1<<w;
            vmask[y]|=1<<w;
        }

        int both=0;
        for(int i=1;i<=cnt;i++){
            int u=node[i];
            if(vmask[u]==3){
                both++;
            }
            vmask[u]=0;
        }
        if(both==2){
            ans--;
        }
    }

    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1<<24;

int st[13];
