inline int lowbit(int x){
    return x&-x;
}

void update(int x,int val){
    while(x<=v){
        tree[x]=max(tree[x],val);
        x+=lowbit(x);
    }
}

int query(int x){
    int ans=-INF;
    while(x){
        ans=max(ans,tree[x]);
        x-=lowbit(x);
    }
    return ans;
}

void clear(int x){
    while(x<=v){
        tree[x]=-INF;
        x+=lowbit(x);
    }
}

void merge(int l,int mid,int r){
    int p1=l-1,p2=mid+1;
    for(;p2<=r;p2++){
        while(p1+1<=mid&&tmp[p1+1].x<=tmp[p2].x){
            p1++;
            if(tmp[p1].op==1){
                update(tmp[p1].y,tmp[p1].x+tmp[p1].y);
            }
        }
        if(tmp[p2].op==2){
            ans[tmp[p2].id]=min(ans[tmp[p2].id],tmp[p2].x+tmp[p2].y-query(tmp[p2].y));
        }
    }
    for(int i=l;i<=p1;i++){
        if(tmp[i].op==1){
            clear(tmp[i].y);
        }
    }
    sort(tmp+l,tmp+r+1,cmp);
}

void cdq(int l,int r){
    if(l==r){
        return ;
    }
    int mid=(l+r)/2;
    cdq(l,mid);
    cdq(mid+1,r);
    merge(l,mid,r);
}

