void dfs(int cur,int fa){//因为是无向边，需要记录它的父亲以避免重复
	for(int i=0;i<vec[cur].size();i++){
		int to=vec[cur][i];
		if(to==fa)//判断父亲
			continue;
		dfs(to,cur);//先搜索，再转移，不然dp[to][0/1]还没有算出来，转移无效
		dp[cur][0]=(dp[cur][0]*(dp[to][0]+m*dp[to][1]%mod))%mod;
