inline int lowbit(int x){
    return x&-x;
}

void add(int *tree,int x,int v){
    x++;
    while(x<=n+1){
        tree[x]+=v;
        x+=lowbit(x);
    }
}

int query(int *tree,int x){
    x++;
    int ans=0;
    while(x){
        ans+=tree[x];
        x-=lowbit(x);
    }
    return ans;
}

void dfs1(int u,int fa){
    sz[u]=1;
    maxx[u]=0;
    bool flag=true;

    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa){
            dfs1(v,u);
            sz[u]+=sz[v];
            maxx[u]=max(maxx[u],sz[v]);
            if(sz[v]*2>n){
                flag=false;
            }
        }
    }

    if(2*(n-sz[u])>n){
        flag=false;
    }

    if(flag){
        root=u;
    }
}

void dfs2(int u,int fa){
    add(tree1,sz[fa],-1);
    add(tree1,n-sz[u],1);

    if(u!=root){
        ans-=u*query(tree1,n-2*sz[u]-1);
        ans+=u*query(tree1,n-2*maxx[u]);
        ans-=u*query(tree2,n-2*sz[u]-1);
        ans+=u*query(tree2,n-2*maxx[u]);

        if(in[fa]){
            in[u]=true;
        }

        ans+=root*(sz[u]<=n-2*sz[in[u]?son2:son1]);
    }

    add(tree2,sz[u],1);

    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa){
            dfs2(v,u);
        }
    }

    add(tree1,sz[fa],1);
    add(tree1,n-sz[u],-1);

    if(u!=root){
        ans+=u*query(tree2,n-2*sz[u]-1);
        ans-=u*query(tree2,n-2*maxx[u]);
    }
}

