void dijkstra(){
    while(!heap.empty()){
        int u=heap.top().u;
        heap.pop();
        if(vis[u]){
            continue;
        }
        vis[u]=true;
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            int w=weight[i];
            if(dis[v]>dis[u]+2*w){
                dis[v]=dis[u]+2*w;
                heap.push({v,dis[v]});
            }
        }
    }
}

