long long all;//表示全局最大值
long long val[MAXN];
long long ans[MAXN];
map<long long,int>mp;

int cnt=1;
int trie[MAXK][2];

int fa[MAXN];
int tag[MAXN][2];
int son[MAXN][2];

int head[MAXN];
int nxt[MAXN];
int to[MAXN];
int cntg=1;

inline void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

long long find(long long val){
    int cur=1;
    long long ans=0;
    for(int i=MAXH;i>=0;i--){
        int best=1-((val>>i)&1);
        if(trie[cur][best]){
            ans+=(1ll<<i);
            cur=trie[cur][best];
        }
        else{
            cur=trie[cur][1-best];
        }
    }
    return ans;
}

void insert(long long val){
    int cur=1;
    for(int i=MAXH;i>=0;i--){
        int path=(val>>i)&1;
        if(trie[cur][path]==0){
            trie[cur][path]=++cnt;
        }
        cur=trie[cur][path];
    }
}

void clear(){
    for(int i=1;i<=cnt;i++){
        trie[i][0]=trie[i][1]=0;
    }
    all=0;
    cnt=1;
}

void dfs(int u){
    insert(val[u]);
    all=max(all,find(val[u]));
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        dfs(v);
    }
}

