int head[MAXN];
int nxt[MAXM];
int to[MAXM];
int cntg=1;

int dfn[MAXN];
int low[MAXN];
int dfncnt;
int out[MAXN];

int dep[MAXN];
int st[MAXN][MAXH];

int head2[MAXN];
int nxt2[MAXE];
int to2[MAXE];
int cntg2=1;

bool win[MAXN];
int ans[MAXN];

int que[MAXN];

inline void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

inline void addedge2(int u,int v){
    nxt2[cntg2]=head2[u];
    to2[cntg2]=v;
    head2[u]=cntg2++;
}

void tarjan(int u){
    dfn[u]=low[u]=++dfncnt;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];

        if(dfn[v]==0){
            dep[v]=dep[u]+1;
            st[v][0]=u;
            for(int i=1;i<MAXH;i++){
                st[v][i]=st[st[v][i-1]][i-1];
            }

            tarjan(v);
            low[u]=min(low[u],low[v]);
        }
        else{
            low[u]=min(low[u],dfn[v]);
        }
    }
    out[u]=dfncnt;
}

bool inSubtree(int u, int v) {
    return dfn[u] <= dfn[v] && dfn[v] <= out[u];
}

// 删除 ban 后，x 所在连通块的编号
int getBlock(int ban, int x) {
    if (x == ban) {
        return -1;
    }

    if (!inSubtree(ban, x)) {
        return 0;
    }

    int cur = x;
    int up = dep[x] - dep[ban] - 1;

    for (int p = MAXH - 1; p >= 0; p--) {
        if (up & (1 << p)) {
            cur = st[cur][p];
        }
    }

    if (low[cur] >= dfn[ban]) {
        return cur;
    }

    return 0;
}

// Marin 从 v 走到 u 后，Luka 能否避开 u
bool canavoid(int v, int u) {
    if (a[v] == u || a[u] == u) {
        return false;
    }

    return getBlock(u, a[v]) == getBlock(u, a[u]);
}

