    head[u]=cnt++;

    nxt[cnt]=head[v];
    to[cnt]=u;
    cap[cnt]=0;
    now[cnt]=0;
    origin[cnt]=0;
    head[v]=cnt++;
}

bool bfs(){
    for(int i=1;i<=t;i++){
        dep[i]=-1;
    }
    queue<int>q;
    dep[s]=0;
    q.push(s);
    while(!q.empty()){
        int u=q.front();
        q.pop();
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            double w=cap[i];
            double k=now[i];
            if(dep[v]<0&&(k+eps<w)){
                dep[v]=dep[u]+1;
                q.push(v);
            }
        }
    }
    return dep[t]>=0;
}

double dfs(int u,double f){
    if(u==t){
        return f;
    }
    double flow=0;
    for(int &i=iter[u];i;i=nxt[i]){
        int v=to[i];
        double w=cap[i];
        double k=now[i];
        if(dep[u]+1==dep[v]&&k+eps<w){
            double d=dfs(v,min(f,w-k));
            if(d>eps){
                now[i]+=d;
                now[i^1]-=d;//更新反向边
                flow+=d;
                f-=d;
                if(f<=eps){
                    break;
                }
            }
        }
    }
    return flow;
}

double maxflow(){
    double flow=0;
    while(bfs()){
        for(int i=1;i<=t;i++){
            iter[i]=head[i];
        }
        double maxflow;
        while((maxflow=dfs(s,INF))>eps){
            flow+=maxflow;
        }
    }
    return flow;
}

bool check(double limit){
    for(int i=2;i<=cnt;i++){
        cap[i]=min(origin[i],limit);
        now[i]=0;
    }
    return maxflow()+eps>=total;
}

