        addedge(u,v);
        addedge(v,u);
    }
    tarjan(1);

    //缩点
    for(int i=1;i<=n;i++){
        if(!col[i]){
            color++;
            col[i]=color;
            q.push(i);
            while(!q.empty()){
                int u=q.front();
                q.pop();
                for(int j=head[u];j;j=nxt[j]){
                    int v=to[j];
                    if(col[v]||bridge[j]){
                        continue;
                    }
                    col[v]=color;
                    q.push(v);
                }
            }
        }
    }

    p=log2(color)+1;

    for(int i=1;i<=n;i++){
        for(int j=head[i];j;j=nxt[j]){
            int v=to[j];
            if(col[v]!=col[i]){
