    for(int i=1;i<=m;i++){
        addedge(nums[i].u,nums[i].v,INF,nums[i].c);
    }
    addedge(s,1,k,0);
    mincostmaxflow();
    cout<<maxflow1<<' '<<mincost<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e6+5;

int n;
char s[MAXN];
int op,k;

// len[i]: 状态i表示的最长子串长度
int len[MAXN];
// fa[i]: 状态i的后缀链接（parent指针）
int fa[MAXN];
// nxt[i][c]: 状态i在字符c上的转移
int nxt[MAXN][26];
// cnt[i]: 状态i对应的endpos集合大小，即该状态表示的子串在字符串中的出现次数
int cnt[MAXN];
int lst;
// 当前节点总数
int tot;

int sz[MAXN];
int now[MAXN];
int sum[MAXN];

// 后缀自动机扩展函数：向自动机中添加一个字符
void extend(char c){
    int cur=++tot;
    // 新状态的长度是上一个状态长度+1  初始出现次数为1
    len[cur]=len[lst]+1;
    cnt[cur]=1;

    // 从上一个状态开始，沿着后缀链接向上遍历
    int p=lst;
    while(p&&!nxt[p][c-'a']){
        // 为没有字符c转移的状态添加转移到cur
        nxt[p][c-'a']=cur;
        p=fa[p];
    }

    // 情况1：没有找到有字符c转移的状态  也就是说这个字符是第一次出现
    if(p==0){
        // 直接挂到根节点上
        fa[cur]=1;
    }
    else{
        // 找到状态p在字符c上的转移状态q
        int q=nxt[p][c-'a'];

        // 情况2：q的长度正好是p的长度+1 直接将cur的后缀链接指向q
        if(len[p]+1==len[q]){
            fa[cur]=q;
        }
        else{
            int nq=++tot;
            len[nq]=len[p]+1;

            // 复制q的所有转移
            for(int i=0;i<26;i++){
                nxt[nq][i]=nxt[q][i];
            }
            // 设置nq的后缀链接为q的后缀链接，并更新q和cur的后缀链接
            fa[nq]=fa[q],fa[q]=nq,fa[cur]=nq;

            // 将原本指向q的转移重定向到nq
            while(p&&nxt[p][c-'a']==q){
                nxt[p][c-'a']=nq;
                p=fa[p];
            }
        }
    }
    lst=cur;
}

void dfs(int u,int k){
    if(k<=now[u]){
        return ;
    }
    k-=now[u];
    for(int i=0;i<26;i++){
        int v=nxt[u][i];
        if(v){
            if(sum[v]<k){
                k-=sum[v];
            }
            else{
                cout<<(char)(i+'a');
                dfs(v,k);
                return ;
            }
        }
    }
}

int main()
{
    scanf("%s",s+1);
    n=strlen(s+1);

    lst=1,tot=1;
    for(int i=1;i<=n;i++){
        extend(s[i]);
    }
    scanf("%d %d",&op,&k);

    for(int i=tot;i>=1;i--){
        // sum[i]=len[i]-len[fa[i]];
        sz[i]=cnt[i];
    }
    for(int i=tot;i>=1;i--){
        sz[fa[i]]+=sz[i];
    }
    for(int i=tot;i>=1;i--){
        if(op==0){
            now[i]=len[i]-len[fa[i]];
        }
        else{
            now[i]=(len[i]-len[fa[i]])*sz[i];
        }
        sum[i]+=now[i];
        sum[fa[i]]+=sum[i];
    }
    if(sum[1]<=k){
        cout<<-1<<endl;
    }
    else{
        dfs(1,k);
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN =  2e5+5;

int n,m,p;

int father[MAXN];

int fa[MAXN];
int ls[MAXN];
int rs[MAXN];
int sta[MAXN];
bool rev[MAXN];

int sz[MAXN];

int find(int x){
    return x==father[x]?x:father[x]=find(father[x]);
}

// 判断节点x是不是辅助splay的顶部节点
bool isroot(int x) {
    return ls[fa[x]] != x && rs[fa[x]] != x;
}

// x不是辅助splay的顶部节点才能调用，返回x是其父的哪侧儿子
int lr(int x) {
    return ls[fa[x]] == x ? 0 : 1;
}

// 翻转以x为根的辅助splay，交换左右儿子，打上翻转标记
void reverse(int x) {
    if (x != 0) {
        swap(ls[x], rs[x]);
        rev[x] = !rev[x];
    }
}

// 处理翻转懒更新
void down(int x) {
    if (rev[x]) {
        reverse(ls[x]);
        reverse(rs[x]);
        rev[x] = false;
    }
}

// x向上旋转
void rotate(int x) {
    int f = fa[x], g = fa[f];
    if (lr(x) == 0) {
        ls[f] = rs[x];
        if (ls[f] != 0) {
            fa[ls[f]] = f;
        }
        rs[x] = f;
    } else {
        rs[f] = ls[x];
        if (rs[f] != 0) {
            fa[rs[f]] = f;
        }
        ls[x] = f;
    }
    if (!isroot(f)) {
        if (lr(f) == 0) {
            ls[g] = x;
        } else {
            rs[g] = x;
        }
    }
    fa[f] = x;
    fa[x] = g;
}

// x提到辅助splay的顶部
void splay(int x) {
    int siz = 0;
    sta[++siz] = x;
    for (int y = x; !isroot(y); y = fa[y]) {
        sta[++siz] = fa[y];
    }
    while (siz != 0) {
        down(sta[siz--]);
    }
    while (!isroot(x)) {
        int f = fa[x];
        if (!isroot(f)) {
            if (lr(x) == lr(f)) {
                rotate(f);
            } else {
                rotate(x);
            }
        }
        rotate(x);
    }
}

// 打通当前原树根到x的路径，使其成为一条实链
// 可以认为这个函数就是最关键的函数
void access(int x) {
    x=find(x);
    for(int y=0;x!=0;y=x,x=fa[x]){
        splay(x);
        rs[x]=y;
        fa[x]=find(fa[x]);
    }
}

// 让x变成原树的根，不改变连通方式
// 这个主要是为了access服务,因为access需要的是树根节点
void makeroot(int x) {
    // 保证x和树根在同一个实链上，也就是同一个辅助splay树
    access(x);
    // 提根x
    splay(x);
    // 因为此时x已经是根节点，所以相当于是最顶层了
    // 翻转左右节点
    reverse(x);
}

int findroot(int x) {
    access(x);
    splay(x);
    down(x);
    while (ls[x] != 0) {
        x = ls[x];
        down(x);
    }
    splay(x);
    return x;
}

void compute(int x,int root){
    if(x){
        father[x]=root;
        sz[root]+=sz[x];

        compute(ls[x],root);
        compute(rs[x],root);
    }
}

int link(int x,int y){
    x=find(x);
    y=find(y);
    if(x==y){
        return sz[x];
    }
    makeroot(x);
    if(findroot(y)!=x){
        fa[x]=y;
        return -1;
    }
    else{
        compute(rs[x],x);
        rs[x]=0;
        return sz[x];
    }
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m>>p;
    for(int i=1;i<=n;i++){
        father[i]=i;
        sz[i]=1;
    }
    for(int i=1;i<=m;i++){
        int u,v;
        cin>>u>>v;
        link(u,v);
    }
    for(int i=1;i<=p;i++){
        int x,y;
        cin>>x>>y;
        int ans=link(x,y);
        if(ans==-1){
            cout<<"No"<<endl;
        }
        else{
            cout<<ans<<endl;
        }
    }
    return 0;
}

