                ok[i]=true;
            }
        }
        dp[0]=1;
        for(int i=1;i<=n;i++){
            dp[i]=dp[i-1];
            if(ok[i-1]){
                dp[i]=(dp[i]+dp[i-m])%MOD;
            }
        }
        cout<<"Case #"<<t<<": "<<dp[n]<<endl;
    }
    return 0;
}

