    for(int i=1;i<=m;i++){
        nums[i].u=read()+1,nums[i].v=read()+1,nums[i].w=read(),nums[i].col=read();
    }
    int l=-105,r=105,ans;
    while(l<=r){
        mid=(l+r)>>1;
        if(check()){
            ans=mid;
            l=mid+1;
        }
        else{
            r=mid-1;
        }
    }
    mid=ans;
    int all=0;
