inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

void tarjan(int u,int f){
    fa[u]=f;
    dfn[u]=low[u]=++dfncnt;
    sum[u]=val[u];
    for(int i=head[u];i;i=nxt[i]){
        if(vis[i]){
            continue;
        }
        vis[i]=vis[((i-1)^1)+1]=true;
        int v=to[i];

        if(!dfn[v]){
            tarjan(v,u);
            sum[u]+=sum[v];
            low[u]=min(low[u],low[v]);
        }
        else {
            low[u]=min(low[u],dfn[v]);
        }
    }
}

