        if (opt == 'C') {
            update(1, 1, n, x, y); // 单点更新
        } else {
            vector<int> result = query(1, 1, n, x, y); // 区间查询
            if (result.size() == 8) {
                cout << result.back() << "\n"; // 输出第 8 大的值
            } else {
                cout << 0 << "\n"; // 不足 8 个元素时输出 0
            }
        }
    }
    return 0;
}

