    if(odd>=3){
        for(int m=odd;m>=3;m-=2){
            int l=(m+1)/2;
            int r=n-(m-1)/2;
            G[m]=max(G[m+2],max(g[l],g[r]));
        }
    }

    for(int i=0;i<n;i++){
        int m=n-i;
