        a=(a*a)%MOD;
    }
    return ans;
}

int comb(int a,int b){
    return fac[a]*inv[b]%MOD*inv[a-b]%MOD;
}

bool check(int u){
    bool flag=false;
    vis[u]=1;
    val[u]^=col[u];//这个地方实际上只对二分图有用

    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(!vis[v]){
            col[v]=col[u]^1;
            flag|=check(v);
        }
        if(col[v]!=(col[u]^1)){
            flag=true;
        }
    }
    return flag;
}

