{
    scanf("%d",&n);
    for(int i=1;i<=n;i++){
        scanf("%s",s+1);
        insert(i);
    }
    setfail();
    for(int i=1;i<=cnt;i++){
        addedge(fail[i],i);
    }
    p=log2(cnt)+1;
    dfs(0,0);
    scanf("%d",&q);
    while(q--){
        int op;
        scanf("%d",&op);
        if(op==1){
            scanf("%s",s+1);
            vector<int>vec;
            int cur=0;
            int len=strlen(s+1);
            for(int i=1;i<=len;i++){
                cur=trie[cur][s[i]-'a'];
                vec.push_back(cur);
            }
            sort(vec.begin(), vec.end());
            auto last = unique(vec.begin(), vec.end());
            vec.erase(last, vec.end());
            sort(vec.begin(), vec.end(), [&](int a, int b) {
                return dfn[a] < dfn[b];
            });
            for(int i=0;i<(int)vec.size();i++){
                add(dfn[vec[i]],1);
            }
            for(int i=1;i<(int)vec.size();i++){
                add(dfn[lca(vec[i],vec[i-1])],-1);
            }
        }
        else{
            int x;
            scanf("%d",&x);
            int node=endpos[x];
            cout<<(query(dfn[node]+sz[node]-1)-query(dfn[node]-1))<<endl;
        }
    }
    return 0;
}

