void swap(int& x,int& y){
    x^=y;y^=x;x^=y;
}//交换两个元素

void reverse(int l,int r){//翻转区间[l,r]内的元素
	for(int i=l;i<=r&&(i<<1)<l+r;++i)
        swap(a[i],a[r+l-i]);
	++ans;//顺便统计答案
}

int lowbit(int x){
    return x&-x;
}//下面三行是经典的树状数组

void update(int i,int v){
    for(;i<=n;i+=lowbit(i))
        c[i]+=v;
}

int getsum(int i){
    int ans=0;
    for(;i;i-=lowbit(i))
        ans+=c[i];
    return ans;
}

