        hs[i]=hs[i-1]*BASE+s[i]-'a';
    }
    for(int i=1;i<=m;i++){
        ht[i]=ht[i-1]*BASE+t[i]-'a';
    }
}

void compute(int pos){
    int l=0,r=min(m,n-pos+1),ans=0;
    while(l<=r){
        int mid=(l+r)>>1;
        if(gethashs(pos,pos+mid-1)==gethasht(1,mid)){
            ans=mid;
            l=mid+1;
        }
        else{
            r=mid-1;
        }
    }
    lt[pos]={ans,pos};
    // cout<<pos<<" : "<<ans<<' ';
    l=0,r=min(m,pos),ans=0;
    while(l<=r){
        int mid=(l+r)>>1;
        if(gethashs(pos-mid+1,pos)==gethasht(m-mid+1,m)){
            ans=mid;
            l=mid+1;
        }
        else{
            r=mid-1;
        }
    }
    // cout<<ans<<endl;
    rt[pos]={ans,pos};
}

inline int lowbit(int x){
    return x&-x;
}

void add(int x,int v,int op){
    while(x<=n){
        tree[op][x]+=v;
        x+=lowbit(x);
    }
}

int query(int x,int op){
    int ans=0;
    while(x){
        ans+=tree[op][x];
        x-=lowbit(x);
    }
    return ans;
}

bool cmp1(node a,node b){
    return a.len>b.len;
}

bool cmp2(node a,node b){
    return a.len<b.len;
}

