    head[u]=cntg++;
}

void addin(int u,int v){
    innxt[cntin]=inhead[u];
    into[cntin]=v;
    inhead[u]=cntin++;
}

void addno(int u,int v){
    nonxt[cntno]=nohead[u];
    noto[cntno]=v;
    nohead[u]=cntno++;
}

bool canroot(int u,int id){
    // u不能有当前点集中的必选祖先
    for(int i=inhead[u];i;i=innxt[i]){
        if(belong[into[i]]==id){
            return false;
        }
    }

    // u成为根后会成为其余所有点的祖先
    for(int i=nohead[u];i;i=nonxt[i]){
        if(belong[noto[i]]==id){
            return false;
        }
    }

    return true;
}

bool build(int l,int r,int pa){
    int id=++tim;

    for(int i=l;i<=r;i++){
        belong[ord[i]]=id;
    }

    // 寻找当前子树的根
    int root=0;

    for(int i=l;i<=r;i++){
        if(canroot(ord[i],id)){
            root=ord[i];
            break;
        }
    }

    if(root==0){
        return false;
    }

    father[root]=pa;

    // 删除当前根
    belong[root]=0;

    // 按T限制的无向连通块重新排列剩余节点
    int write=l;

    for(int i=l;i<=r;i++){
        int s=ord[i];

        if(s==root||vis[s]==id){
            continue;
        }

        int start=write;
        int ql=1;
        int qr=1;

        que[1]=s;
        vis[s]=id;

        while(ql<=qr){
            int u=que[ql++];

            tmp[write++]=u;

            for(int j=head[u];j;j=nxt[j]){
                int v=to[j];

                if(belong[v]==id&&vis[v]!=id){
                    vis[v]=id;
                    que[++qr]=v;
                }
            }
        }

        bound[start]=write-1;
    }

    for(int i=l;i<write;i++){
        ord[i]=tmp[i];
    }

    // 每个连通块作为root的一棵儿子子树
    int pos=l;

    while(pos<write){
        int end=bound[pos];

        if(!build(pos,end,root)){
            return false;
        }

        pos=end+1;
    }

    return true;
}

