}

inline void addedge2(int u,int v){
    nxt2[cntg2]=head2[u];
    to2[cntg2]=v;
    head2[u]=cntg2++;
}

void cyclelink(int u, int v) {
    cntn++;
    addedge2(u,cntn);
    int pop;
    do {
        pop = sta[stasz--];
        addedge2(cntn, pop);
    } while (pop != v);
}

void tarjan(int u,int preedge){
    dfn[u]=low[u]=++dfncnt;
    sta[++stasz]=u;
    for(int i=head[u];i;i=nxt[i]){
        if((i^1)==preedge){
