    }
    for(int i=1;i<=q;i++){
        qy[i]=find(qy[i]);
    }
    dfs(1);
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m;
    for(int i=1;i<=n;i++){
        cin>>val[i];
    }
