// 可持久化并查集模版题，C++版
// 数字从1到n，一开始每个数字所在的集合只有自己
// 实现如下三种操作，第i条操作发生后，所有数字的状况记为i版本，操作一共发生m次
// 操作 1 x y : 基于上个操作生成的版本，将x的集合与y的集合合并，生成当前的版本
// 操作 2 x   : 拷贝第x号版本的状况，生成当前的版本
// 操作 3 x y : 拷贝上个操作生成的版本，生成当前的版本，查询x和y是否属于一个集合
// 1 <= n <= 10^5
// 1 <= m <= 2 * 10^5
// 测试链接 : https://www.luogu.com.cn/problem/P3402
// 如下实现是C++的版本，C++版本和java版本逻辑完全一样
// 提交如下代码，可以通过所有测试用例
#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int MAXM = 2e5+5;
const int MAXT = MAXN*80;

int n,m;

int faroot[MAXM];
int szroot[MAXM];

int cnt=0;
int ls[MAXT];
int rs[MAXT];
int val[MAXT];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

int buildfa(int l,int r){
    int rt=++cnt;
    if(l==r){
        val[rt]=l;
    }
    else{
        int mid=(l+r)/2;
        ls[rt]=buildfa(l,mid);
        rs[rt]=buildfa(mid+1,r);
    }
    return rt;
}

int buildsz(int l,int r){
    int rt=++cnt;
    if(l==r){
        val[rt]=1;
    }
    else{
        int mid=(l+r)/2;
        ls[rt]=buildsz(l,mid);
        rs[rt]=buildsz(mid+1,r);
    }
    return rt;
}

int update(int pos,int v,int l,int r,int i){
    int rt=++cnt;
    ls[rt]=ls[i];
    rs[rt]=rs[i];
    if(l==r){
        val[rt]=v;
    }
    else{
        int mid=(l+r)/2;
        if(pos<=mid){
            ls[rt]=update(pos,v,l,mid,ls[rt]);
        }
        if(pos>mid){
            rs[rt]=update(pos,v,mid+1,r,rs[rt]);
        }
    }
    return rt;
}

int query(int pos,int l,int r,int i){
    if(l==r){
        return val[i];
    }
    else{
        int mid=(l+r)/2;
        if(pos<=mid){
            return query(pos,l,mid,ls[i]);
        }
        else{
            return query(pos,mid+1,r,rs[i]);
        }
    }
}

int find(int x,int v){
    int fa=query(x,1,n,faroot[v]);
    while(fa!=x){
        x=fa;
        fa=query(x,1,n,faroot[v]);
    }
    return x;
}

void un(int x,int y,int v){
    int fx=find(x,v);
    int fy=find(y,v);
    if(fx==fy){
        return ;
    }
    int xsz=query(fx,1,n,szroot[v]);
    int ysz=query(fy,1,n,szroot[v]);
    if(xsz>ysz){
        szroot[v]=update(fx,xsz+ysz,1,n,szroot[v]);
        faroot[v]=update(fy,fx,1,n,faroot[v]);
    }
    else{
        szroot[v]=update(fy,xsz+ysz,1,n,szroot[v]);
        faroot[v]=update(fx,fy,1,n,faroot[v]);
    }
}

int main()
{
    n=read(),m=read();
    faroot[0]=buildfa(1,n);
    szroot[0]=buildsz(1,n);
    for(int i=1;i<=m;i++){
        faroot[i]=faroot[i-1];
        szroot[i]=szroot[i-1];
        int op,x,y;
        op=read();
        if(op==1){
            x=read(),y=read();
            un(x,y,i);
        }
        else if(op==2){
            x=read();
            faroot[i]=faroot[x];
            szroot[i]=szroot[x];
        }
        else{
            x=read(),y=read();
            int fx=find(x,i);
            int fy=find(y,i);
            if(fx==fy){
                printf("1\n");
            }
            else{
                printf("0\n");
            }
        }
    }
    return 0;
}

//P9233
//这道题目将每棵子树变成一个区间查询
//我们记录的是每个颜色词频的词频
//因为这道题要求的是所有颜色的词频相同
//这道题的正解应该是树上启发式合并
#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;

int dfn[MAXN],id[MAXN];//dfn序  以及dfn对应的原来的序号
int dfncnt;
int sz[MAXN];
struct node{
    int l,r;
}q[MAXN];//改成n个区间查询
int qcnt;//记录区间查询编号
int n,m;
int cnt[MAXN];//统计元素出现个数
int tot[MAXN];//统计出现次数相同的个数
int ans;//记录出现次数的不同个数共有几个
int val[MAXN];
int pos[MAXN];

int head[MAXN];
int to[MAXN];
int Next[MAXN];
int tcnt=1;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void addedge(int u,int v){
    Next[tcnt]=head[u];
    to[tcnt]=v;
    head[u]=tcnt++;
}

void dfs(int u){
    dfn[u]=++dfncnt;
    id[dfncnt]=u;
    sz[u]=1;
    for(int i=head[u];i>0;i=Next[i]){
        int v=to[i];
        dfs(v);
        sz[u]+=sz[v];
    }
    q[++qcnt]={dfn[u],dfn[u]+sz[u]-1};
}

//奇偶性排序优化
inline bool cmp(node a,node b) {
	return (pos[a.l] ^ pos[b.l]) ? pos[a.l] < pos[b.l] : ((pos[a.l] & 1) ? a.r < b.r : a.r > b.r);
}

void add(int x){
    if(cnt[val[x]]){
        //表示以前存在
        tot[cnt[val[x]]]--;//那么和这个出现次数相同的元素个数减少一个
        if(tot[cnt[val[x]]]==0){
            ans--;
            //如果减到0  那么种类减少一个
        }
    }
    cnt[val[x]]++;//出现次数加一
    tot[cnt[val[x]]]++;//这个出现次数的元素个数加一
    if(tot[cnt[val[x]]]==1){
        ans++;
        //表示以前没有这个出现次数 现在出现了
    }
}

void sub(int x){
    tot[cnt[val[x]]]--;//以前肯定有  要不然不会进入到这个函数
    if(tot[cnt[val[x]]]==0){
        ans--;
        //这个出现次数的没有了
    }
    cnt[val[x]]--;
    if(cnt[val[x]]!=0){
        //出现次数是0的话  不能统计
        tot[cnt[val[x]]]++;
        if(tot[cnt[val[x]]]==1){
            ans++;
        }
    }
}

int main()
{
    n=read();
    int size=sqrt(n);
    for(int i=1;i<=n;i++){
        pos[i]=i/size;
        val[i]=read();
        int u=read();
        addedge(u,i);
    }
    dfs(1);
    sort(q+1,q+n+1,cmp);
    int l=1,r=0,res=0;
    for(int i=1;i<=n;i++){
        while (l > q[i].l) add(id[--l]);
		while (r < q[i].r) add(id[++r]);
		while (l < q[i].l) sub(id[l++]);
		while (r > q[i].r) sub(id[r--]);
		res += (ans == 1);
    }
    cout<<res<<endl;
    return 0;
}

