    for(int i=0;i<26;i++){
        sum[n+1][i]=INT_MAX;
    }
    for(int i=0;i<n;i++){
        if(sta&(1<<i)){
            for(int j=0;j<26;j++){
                sum[n+1][j]=min(sum[n+1][j],sum[i][j]);
            }
        }
    }
    int ans=0;
    for(int i=0;i<26;i++){
        ans+=sum[n+1][i];
    }
    return ans;
}

