{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n;
    for(int i=1;i<=n;i++){
        int op;
        cin>>op;
        if(op==1){
            int key;
            cin>>key;
            insert_node(key);
        }
        else if(op==2){
