}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int MAXT = MAXN*200;
const int MAXH = 18;

int n,m;

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int cntg=1;

int dep[MAXN];
int st[MAXN][MAXH];

bool vis[MAXN];
int centfa[MAXN];
int sz[MAXN];

int addroot[MAXN];
int minusroot[MAXN];
int ls[MAXT];
int rs[MAXT];
int tree[MAXT];
int cntt;

inline void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

void dfs(int u,int fa){
    dep[u]=dep[fa]+1;
    st[u][0]=fa;
    for(int p=1;p<MAXH;p++){
        st[u][p]=st[st[u][p-1]][p-1];
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa){
            dfs(v,u);
        }
    }
}

int getlca(int a,int b){
    if(dep[a]<dep[b]){
        swap(a,b);
    }
    for(int p=MAXH-1;p>=0;p--){
        if(dep[st[a][p]]>=dep[b]){
            a=st[a][p];
        }
    }
    if(a==b){
        return a;
    }
    for(int p=MAXH-1;p>=0;p--){
        if(st[a][p]!=st[b][p]){
            a=st[a][p];
            b=st[b][p];
        }
    }
    return st[a][0];
}

int getdist(int a,int b){
    return dep[a]+dep[b]-(dep[getlca(a,b)]<<1);
}

void getsize(int u,int fa){
    sz[u]=1;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa&&!vis[v]){
            getsize(v,u);
            sz[u]+=sz[v];
        }
    }
}

int getcentroid(int u,int fa){
    getsize(u,fa);
    int half=sz[u]>>1;
    bool find=false;
    while(!find){
        find=true;
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            if(v!=fa&&!vis[v]&&sz[v]>half){
                find=false;
                fa=u;
                u=v;
                break;
            }
        }
    }
    return u;
}

void centroidtree(int u,int fa){
    centfa[u]=fa;
    vis[u]=true;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(!vis[v]){
            centroidtree(getcentroid(v,u),u);
        }
    }
}

int add(int pos,int jobv,int l,int r,int i){
    if(i==0){
        i=++cntt;
    }
    if(l==r){
        tree[i]+=jobv;
    }
    else{
        int mid=(l+r)>>1;
        if(pos<=mid){
            ls[i]=add(pos,jobv,l,mid,ls[i]);
        }
        else{
            rs[i]=add(pos,jobv,mid+1,r,rs[i]);
        }
        tree[i]=tree[ls[i]]+tree[rs[i]];
    }
    return i;
}

int query(int jobl,int jobr,int l,int r,int i){
    if(i==0){
        return 0;
    }
    if(jobl<=l&&r<=jobr){
        return tree[i];
    }
    else{
        int mid=(l+r)>>1;
        int ans=0;
        if(jobl<=mid){
            ans+=query(jobl,jobr,l,mid,ls[i]);
        }
        if(jobr>mid){
            ans+=query(jobl,jobr,mid+1,r,rs[i]);
        }
        return ans;
    }
}

void add(int x,int k,int v){
    addroot[x]=add(k,v,0,n-1,addroot[x]);
    for(int cur=x,fa=centfa[cur];fa;cur=fa,fa=centfa[cur]){
        int dist=getdist(x,fa);
        if(k>=dist){
            addroot[fa]=add(k-dist,v,0,n-1,addroot[fa]);
            minusroot[cur]=add(k-dist,v,0,n-1,minusroot[cur]);
        }
    }
}

int query(int x){
    int ans=query(0,n-1,0,n-1,addroot[x]);
    for(int cur=x,fa=centfa[cur];fa;cur=fa,fa=centfa[cur]){
        int dist=getdist(x,fa);
        ans+=query(dist,n-1,0,n-1,addroot[fa]);
        ans-=query(dist,n-1,0,n-1,minusroot[cur]);
    }
    return ans;
}

int main()
{
    scanf("%d %d",&n,&m);
    for(int i=1;i<n;i++){
        int u,v;
        scanf("%d %d",&u,&v);
        addedge(u,v);
        addedge(v,u);
    }
    dfs(1,0);
    centroidtree(getcentroid(1,0),0);
    for(int i=1;i<=m;i++){
        char op;
        int x,k,v;
        scanf(" %c %d",&op,&x);
        if(op=='M'){
            scanf("%d %d",&k,&v);
            add(x,k,v);
        }
        else{
            cout<<query(x)<<endl;
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1e5 + 5;

int n, q;
int val[MAXN];

// 线段树节点结构体
struct Node {
    long long tree; // 区间内有趣子数组的数量
    int gcdval;     // 区间的GCD值
    vector<pair<int, int>> pre; // 前缀GCD列表 (GCD值, 连续长度)
    vector<pair<int, int>> suf; // 后缀GCD列表 (GCD值, 连续长度)

    // 构造函数
    Node() : tree(0), gcdval(0) {}
    Node(int value) {
        gcdval = value;
        tree = (value > 1) ? 1 : 0;
        pre.push_back({value, 1});
        suf.push_back({value, 1});
    }
};

Node tree[MAXN << 2]; // 线段树数组

// 快速读入函数
inline int read() {
    int x = 0, f = 1;
    char ch = getchar();
    while (ch < '0' || ch > '9') {
        if (ch == '-') f = -1;
        ch = getchar();
    }
    while (ch >= '0' && ch <= '9') {
        x = x * 10 + ch - '0';
        ch = getchar();
    }
    return x * f;
}

// 计算最大公约数
inline int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

// 合并两个线段树节点，返回合并后的节点
Node merge(const Node &left, const Node &right) {
    Node result;

    // 计算整个区间的GCD
    result.gcdval = gcd(left.gcdval, right.gcdval);

    // 计算跨越中点的有趣子数组数量
    long long tmp = 0;
    int len = 0;

    // 计算右子树前缀列表的总长度
    for (int i = 0; i < (int)right.pre.size(); i++) {
        len += right.pre[i].second;
    }

    // 遍历左子树后缀列表和右子树前缀列表
    for (int i = 0, j = (int)right.pre.size() - 1; i < (int)left.suf.size(); i++) {
        while (j != -1 && gcd(left.suf[i].first, right.pre[j].first) == 1) {
            len -= right.pre[j].second;
            j--;
        }
        tmp += (long long)left.suf[i].second * len;
    }

    result.tree = left.tree + right.tree + tmp;

    // 合并前缀GCD列表
    result.pre = left.pre;
    for (int i = 0; i < (int)right.pre.size(); i++) {
        int g = gcd(left.gcdval, right.pre[i].first);
        if (g == left.gcdval) {
            result.pre.back().second += right.pre[i].second;
        } else {
            result.pre.push_back({g, right.pre[i].second});
        }
    }

    // 合并后缀GCD列表
    result.suf = right.suf;
    for (int i = 0; i < (int)left.suf.size(); i++) {
        int g = gcd(right.gcdval, left.suf[i].first);
        if (g == right.gcdval) {
            result.suf.back().second += left.suf[i].second;
        } else {
            result.suf.push_back({g, left.suf[i].second});
        }
    }

    return result;
}

// 构建线段树
void build(int l, int r, int idx) {
    if (l == r) {
        tree[idx] = Node(val[l]);
        return;
    }
    int mid = (l + r) >> 1;
    build(l, mid, idx << 1);
    build(mid + 1, r, idx << 1 | 1);
    tree[idx] = merge(tree[idx << 1], tree[idx << 1 | 1]);
}

// 更新线段树
void update(int pos, int new_val, int l, int r, int idx) {
    if (l == r) {
        tree[idx] = Node(new_val);
        return;
    }
    int mid = (l + r) >> 1;
    if (pos <= mid) {
        update(pos, new_val, l, mid, idx << 1);
    } else {
        update(pos, new_val, mid + 1, r, idx << 1 | 1);
    }
    tree[idx] = merge(tree[idx << 1], tree[idx << 1 | 1]);
}

// 查询线段树
Node query(int ql, int qr, int l, int r, int idx) {
    if (ql <= l && r <= qr) {
        return tree[idx];
    }
    int mid = (l + r) >> 1;
    if (qr <= mid) {
        return query(ql, qr, l, mid, idx << 1);
    } else if (ql > mid) {
        return query(ql, qr, mid + 1, r, idx << 1 | 1);
    } else {
        Node left = query(ql, mid, l, mid, idx << 1);
        Node right = query(mid + 1, qr, mid + 1, r, idx << 1 | 1);
        return merge(left, right);
    }
}

int main() {
    n = read(), q = read();
    for (int i = 1; i <= n; i++) {
        val[i] = read();
    }

    build(1, n, 1);

    for (int i = 0; i < q; i++) {
        int op = read(), l = read(), r = read();
        if (op == 1) {
            update(l, r, 1, n, 1);
        } else {
            Node result = query(l, r, 1, n, 1);
            printf("%lld\n", result.tree);
        }
    }

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MOD = 1e9+7;

int n,m,k;
int cnt[32];

vector<vector<int>> multiply(vector<vector<int>>a,vector<vector<int>>b){
    int n=a.size();
    int m=b[0].size();
    int k=a[0].size();
    vector<vector<int>>ans(n,vector<int>(m,0));
    for(int i=0;i<n;i++){
        for(int j=0;j<m;j++){
            for(int p=0;p<k;p++){
                ans[i][j]+=a[i][p]*b[p][j];
                ans[i][j]%=MOD;
            }
        }
    }
    return ans;
}

vector<vector<int>> power(vector<vector<int>>a,int b){
    int n=a.size();
    vector<vector<int>> m(n,vector<int>(n,0));
    for(int i=0;i<n;i++){
        m[i][i]=1;
    }
    while(b){
        if(b&1){
            m=multiply(m,a);
        }
        b>>=1;
        a=multiply(a,a);
    }
    return m;
}

signed main()
{
    cnt[0]=0;
    for(int i=1;i<32;i++){
        cnt[i]=cnt[i-(i&-i)]+1;
    }
    cin>>n>>m>>k;
    int tot=(1<<m);
    vector<vector<int>>nums(tot,vector<int>(tot,0));
    for(int i=0,j;i<tot;i++){
        if(cnt[i]>k){
            continue;
        }
        j=i>>1;
        nums[j][i]=1;
        j = (i >> 1) | (1 << (m - 1));
		if (cnt[j] <= k){
			nums[j][i] = 1;
		}
    }
    nums=power(nums,n);
    int ans=0;
    for(int i=0;i<tot;i++){
        ans+=nums[i][i];
        ans%=MOD;
    }
    cout<<ans<<endl;
    return 0;
}

