int compute(int lt,int rt,int c){
    int ans1=0,ans2=vec[c].size();
    int l=0,r=vec[c].size()-1;
    while(l<=r){
        int mid=(l+r)/2;
        if(vec[c][mid]>=lt){
            ans1=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    l=0,r=vec[c].size()-1;
    while(l<=r){
        int mid=(l+r)/2;
        if(vec[c][mid]>rt){
            ans2=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    return ans2-ans1;
}

void change(int c,int pos,int idea){
    int l=0,r=vec[c].size()-1,ans=0;
    while(l<=r){
        int mid=(l+r)/2;
        if(vec[c][mid]>=pos){
            ans=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    vec[c][ans]=idea;
}

