bool check(){
    if(val[a[0]]!=-1&&val[b[0]]!=-1){
        if(val[a[0]]+val[b[0]]>=n){
            return false;
        }
    }
    for(int i=n-1;i>=0;i--){
        int A=val[a[i]],B=val[b[i]],C=val[c[i]];
        if(A==-1||B==-1||C==-1){
            continue;
        }
        if((A+B)%n!=C&&(A+B+1)%n!=C){
            return false;
        }
    }
    return true;
}

bool ok(){
    int add=0;
    for(int i=n-1;i>=0;i--){
        int A=val[a[i]],B=val[b[i]],C=val[c[i]];
        if((A+B+add)%n!=C){
            return false;
        }
        add=(A+B+add)/n;
    }
    return add==0;
}

