void dfs(int u,int d){
    for(int i=0;i<=(1<<d);i++){
        dp[u][i]=0;
    }

    if(d==0){
        for(int i=1;i<=n;i++){
            if(vis[i]){
                dp[u][1]+=f[u][i];
            }
            else{
                dp[u][0]+=g[u][i];
            }
        }
    }
    else{
        int lt=u<<1;
        int rt=u<<1|1;

        vis[d]=0;
        dfs(lt,d-1);
        dfs(rt,d-1);

        for(int i=0;i<=(1<<(d-1));i++){
            for(int j=0;j<=(1<<(d-1));j++){
                dp[u][i+j]=max(dp[u][i+j],dp[lt][i]+dp[rt][j]);
            }
        }

        vis[d]=1;
        dfs(lt,d-1);
        dfs(rt,d-1);

        for(int i=0;i<=(1<<(d-1));i++){
            for(int j=0;j<=(1<<(d-1));j++){
                dp[u][i+j]=max(dp[u][i+j],dp[lt][i]+dp[rt][j]);
            }
        }
    }
}

