        for(int j=1;j<m;j++){
            pre[lt+j]=s[l+j-1]^s[l+j];
        }
        pre[rt]=s[r];

        for(int j=1;j<=m+1;j++){
            h[i]+=p[j]*pre[lt+j-1];
        }
