            else if(ci=='b'){
                ci1='A',ci0='C';
            }
            else{
                ci1='A',ci0='B';
            }

            if(cj=='a'){
                cj1='B',cj0='C';
            }
            else if(cj=='b'){
                cj1='A',cj0='C';
            }
            else{
                cj1='A',cj0='B';
            }

            if(hi!=ci1&&hi!=ci0){
                continue;
            }
            else{
                int u=2*i+(hi==ci1?0:1);
                if(hj!=cj1&&hj!=cj0){
                    Addedge(u,u^1);
                }
                else{
                    int v=2*j+(hj==cj1?0:1);
                    Addedge(u,v);
                    Addedge(v^1,u^1);
                }
            }

        }

        for(int i=2;i<=2*n+1;i++){
