        addedge(u,v,w);
        addedge(v,u,w);
    }
    dijkstra(S,ds);
    dijkstra(T,dt);
    dijkstra(U,du);
    dijkstra(V,dv);

    long long dis=ds[T];

    for(int u=1;u<=n;u++){
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            int w=weight[i];
            if(ds[u]+dt[v]+w==dis){
                addedge1(u,v);
                addedge2(v,u);
            }
        }
    }

    for(int i=1;i<=n;i++){
        low1[i]=du[i];
        low2[i]=du[i];
    }
    queue<int>q;
    for(int i=1;i<=n;i++){
        if(in1[i]==0){
            q.push(i);
        }
    }
    while(!q.empty()){
        int u=q.front();
