        for(int i=head1[u];i;i=nxt1[i]){
            int v=to1[i];
            in1[v]--;
            low1[v]=min(low1[v],low1[u]);
            if(in1[v]==0){
                q.push(v);
            }
        }
    }

    for(int i=1;i<=n;i++){
        if(in2[i]==0){
            q.push(i);
        }
    }
    while(!q.empty()){
        int u=q.front();
