            in2[v]--;
            low2[v]=min(low2[v],low2[u]);
            if(in2[v]==0){
                q.push(v);
            }
        }
    }

    long long ans=du[V];
    for(int i=1;i<=n;i++){
        ans=min(ans,min(low1[i]+dv[i],low2[i]+dv[i]));
    }
    cout<<ans<<endl;
    return 0;
}

