        if(nums[i].x1>nums[i].x2){
            swap(nums[i].x1,nums[i].x2);
            swap(nums[i].y1,nums[i].y2);
        }
    }
    for(int i=1;i<=n;i++){
        for(int j=1+i;j<=n;j++){
            int op=check(nums[i],nums[j]);
            if(op==1){
                graph[j].push_back(i);
                indegree[i]++;
            }
            if(op==-1){
                graph[i].push_back(j);
                indegree[j]++;
            }
        }
    }
    for(int i=1;i<=n;i++){
        if(indegree[i]==0){
            q.push(i);
        }
    }
    while(!q.empty()){
        int cur=q.front();
        printf("%d ",cur);
        q.pop();
        for(int i=0;i<graph[cur].size();i++){
            indegree[graph[cur][i]]--;
            if(indegree[graph[cur][i]]==0){
                q.push(graph[cur][i]);
            }
        }
    }
    return 0;
}

