                continue;
            }
            // 设置可填字符范围
            char st='0',en='9';
            if(s[i+1]!='.'){
                st=s[i+1];
                en=s[i+1];
            }
            for(char c=st;c<=en;c++){
                int jj=trie[j][c-'0'];
                double v=f[i][j]+val[jj];
                if(v>f[i+1][jj]){
                    f[i+1][jj]=v;
                    // 记录好转移路径 方便最后回溯
                    g[i+1][jj]=j;
                    h[i+1][jj]=c;
                }
            }
        }
    }

    // 复原val数组
    for(int i=0;i<=cnt;i++){
        val[i]+=sum[i]*limit;
    }

    for(int i=0;i<=cnt;i++){
        if(f[n][i]>0){
            return true;
        }
    }
    return false;
}

// 回溯 得到字符数组
void compute(){
    int cur=0;
    for(int i=1;i<=cnt;i++){
        if(f[n][i]>f[n][cur]){
            cur=i;
        }
    }
    for(int i=n;i>=1;i--){
        ans[i]=h[i][cur];
        cur=g[i][cur];
    }
}

