#define int long long
const int MOD = 998244353;
const int MAXN = 35;

int n,m;
char s[MAXN];
int nxt[MAXN];

// 计算1-based next数组
void calcnext(){
    nxt[1]=0;
    for(int i=2,j=0;i<=m;i++){
        // 当不匹配时，通过next数组回溯
        while(j>0&&s[i]!=s[j+1]){
            j=nxt[j];
        }
        // 如果当前字符匹配，j增加
        if(s[i]==s[j+1]){
            j++;
        }
        // 设置当前位置的next值
        nxt[i]=j;
    }
}

// 矩阵相乘
// a的列数一定要等于b的行数
vector<vector<int>> multiply(vector<vector<int>>& a, const vector<vector<int>>& b) {
    int n = a.size();
    int m = b[0].size();
    int k = a[0].size();
    vector<vector<int>> ans(n, vector<int>(m, 0));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            for (int c = 0; c < k; c++) {
                ans[i][j] += a[i][c] * b[c][j];
                ans[i][j]%=MOD;
            }
        }
    }
    return ans;
}

// 矩阵快速幂
vector<vector<int>> power(vector<vector<int>>& m, int p) {
    int n = m.size();
    vector<vector<int>> ans(n, vector<int>(n, 0));
    for (int i = 0; i < n; i++) {
        ans[i][i] = 1;//单位矩阵 相当于乘法快速幂中的1
    }
    for (; p != 0; p >>= 1) {
        if ((p & 1) != 0) {
            ans = multiply(ans, m);
        }
        m = multiply(m, m);//每次都是倍增
    }
    return ans;
}

signed main()
{
    scanf("%s %lld",s+1,&n);
    m=strlen(s+1);
    calcnext();
    vector<vector<int>>trans(m+1,vector<int>(26,0));
    for(int i=0;i<=m;i++){
        for(int c=0;c<26;c++){
            int ch='a'+c;
            if(i<m&&ch==s[i+1]){
                trans[i][c]=i+1;
            }
            else{
                if(i==0){
                    trans[i][c]=0;//表示还是没有匹配上
                }
                else{
                    int k=nxt[i];
                    trans[i][c]=trans[k][c];
                }
            }
        }
    }
    vector<vector<int>>mat(4*m,vector<int>(4*m,0));
    for(int cnt=0;cnt<=3;cnt++){
        for(int pos=0;pos<m;pos++){
            for(int c=0;c<26;c++){
                int newcnt=cnt;
                int newpos=trans[pos][c];//表示这一位置之后选择一个c会跳到哪里
                if(newpos==m){
                    newcnt=min(newcnt+1,3ll);
                    newpos=nxt[m];
                }
                int from=cnt*m+pos;
                int to=newcnt*m+newpos;
                mat[from][to]=(mat[from][to]+1)%MOD;
            }
        }
    }
    vector<vector<int>>res=power(mat,n);
    vector<vector<int>>vec(1,vector<int>(4*m,0));
    vec[0][0]=1;
    vec=multiply(vec,res);
