{
    cin>>n>>c>>r;
    for(int i=1;i<=r;i++){
        for(int j=1;j<=c;j++){
            cin>>val[i][j];
        }
    }
    s=2*r*c+1,t=s+1;

    addedge(s,1,n,0);
    addedge(2*r*c,t,n,0);

    for(int i=1;i<=r;i++){
        for(int j=1;j<=c;j++){
            if(val[i][j]==1){
                continue;
            }

            int in=(i-1)*c+j;
            int out=in+r*c;

            if(val[i][j]==2){
                addedge(in,out,1,-1);
                addedge(in,out,n,0);
            }
            else{
                addedge(in,out,n,0);
            }

            if(i<r&&val[i+1][j]!=1){
                addedge(out,i*c+j,n,0);
            }
            if(j<c&&val[i][j+1]!=1){
                addedge(out,(i-1)*c+j+1,n,0);
            }
        }
    }

    mincostmaxflow();

    for(int i=1;i<=n;i++){
        dfs(i,1,1);
    }
