int z[MAXN];
int tree[MAXN<<2];

int head[MAXN];
int nxt[MAXN];
int to[MAXN];
int cnt=1;

int dep[MAXN];
int st[MAXN][MAXH];

void zarray(){
    z[1]=n;
    for(int i=2,c=2,r=2,len;i<=n;i++){
        len=r>i?min(r-i,z[i-c+1]):0;
        while (i + len <= n && s[i + len] == s[len+1]) {
            len++;
        }
        if (i + len > r) {
            r = i + len;
            c = i;
        }
        z[i] = len;
    }
}

void build(int l,int r,int i){
    if(l==r){
        tree[i]=z[l];
    }
    else{
        int mid=(l+r)>>1;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        tree[i]=max(tree[i<<1],tree[i<<1|1]);
    }
}

int query(int jobl,int jobr,int jobv,int l,int r,int i){
    if((tree[i]<jobv)||(jobl>jobr)){
        return 0;
    }
    if(l==r){
        return l;
    }
    else{
        int mid=(l+r)>>1;
        if(jobl<=mid&&jobr>=mid){
            int ans=query(jobl,jobr,jobv,l,mid,i<<1);
            if(ans==0){
                return query(jobl,jobr,jobv,mid+1,r,i<<1|1);
            }
            else{
                return ans;
            }
        }
        else if(jobl<=mid){
            return query(jobl,jobr,jobv,l,mid,i<<1);
        }
        else{
            return query(jobl,jobr,jobv,mid+1,r,i<<1|1);
        }
    }
}

void calcnext(){
    Next[1]=0;
    for(int i=2,j=0;i<=n;i++){
        // 当不匹配时，通过next数组回溯
        while(j>0&&s[i]!=s[j+1]){
            j=Next[j];
        }
        // 如果当前字符匹配，j增加
        if(s[i]==s[j+1]){
            j++;
        }
        // 设置当前位置的next值
        Next[i]=j;
    }
}

inline void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

void dfs(int u,int fa){
    // cout<<u<<' '<<fa<<endl;
    dep[u]=dep[fa]+1;
    st[u][0]=fa;
    for(int i=1;i<=p;i++){
        st[u][i]=st[st[u][i-1]][i-1];
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        dfs(v,u);
    }
}

int lca(int a,int b){
    if(dep[a]<dep[b]){
        swap(a,b);
    }
    for(int i=p;i>=0;i--){
        if(dep[st[a][i]]>=dep[b]){
            a=st[a][i];
        }
    }
    if(a==b){
        //如果相同说明就是祖先关系
        //那么还要向上跳一下  因为要求的是border
        //实际上也可以求stjump[u][0],stjump[v][0]的lca  这样不用跳  直接就是lca
        return st[a][0];
    }
    for(int i=p;i>=0;i--){
        if(st[a][i]!=st[b][i]){
            a=st[a][i];
            b=st[b][i];
        }
    }
    return st[a][0];
}

int find(int x, int k) {
    // 从x开始向上跳，找到最大的u使得vec[u]中至少有k次不重叠出现且第k次出现不超过x
    int u = x;

    // 从高位向低位尝试跳
    for(int i = p; i >= 0; i--) {
        if(st[u][i] == 0) continue;

        int candidate = st[u][i];
        // cout<<666<<' '<<vec[candidate].size()<<' '<<k<<endl;
        // 检查候选border长度candidate是否满足条件
        if(((int)vec[candidate].size() < k) ||(((int)vec[candidate].size() >= k)&& (vec[candidate][k-1] > x))) {
            // 如果满足条件，就跳过去
            // cout<<888<<endl;
            u = candidate;
        }
        // cout<<candidate<<' '<<u<<' '<<vec[candidate][k-1]<<endl;
    }

    // if((int)vec[u].size() >= k&& (vec[u][k-1] <= x)){
    //     return u;
    // }

    if((int)vec[Next[u]].size() < k ||(((int)vec[Next[u]].size() >= k)&& (vec[Next[u]][k-1] > x))) {
        u = Next[u];
    }
    return Next[u];
}

