int main()
{
    n=read(),m=read(),q=read();
    if(n>1){
        for(int i=1;i<=n;i++){
            for(int j=1;j<=m;j++){
                val[i][j]=read();
                pre[val[i][j]][i][j]=1;
            }
        }
        for(int v=1;v<=1000;v++){
            for(int i=1;i<=n;i++){
                for(int j=1;j<=m;j++){
                    pre[v][i][j]+=pre[v][i-1][j]+pre[v][i][j-1]-pre[v][i-1][j-1];
                }
            }
        }
        for(int i=1;i<=n;i++){
