            if(now<need){
                printf("Poor QLW\n");
            }
            else{
                int sum=0,ans=0;
                for(int v=1000;v>=1;v--){
                    int c=pre[v][x2][y2]-pre[v][x1-1][y2]-pre[v][x2][y1-1]+pre[v][x1-1][y1-1];
                    if(c==0){
                        continue;
                    }
                    if(sum+v*c<need){
                        sum+=v*c;
                        ans+=c;
                    }
                    else{
                        ans+=(need-sum+v-1)/v;
                        break;
