            }
            else{
                int sum=0,ans=0;
                for(int v=1000;v>=1;v--){
                    if(pos[v].empty()){
                        continue;
                    }
                    auto it1=lower_bound(pos[v].begin(),pos[v].end(),y1);
                    auto it2=upper_bound(pos[v].begin(),pos[v].end(),y2);
                    int c=it2-it1;
                    if(c==0){
