#include <bits/stdc++.h>
using namespace std;
#define maxn 1000005

int t;
int ed[maxn], cnt[maxn];
int tr[maxn][27], tot = 1;

void add(char *s, int len) {
    int p = 1;
    ++cnt[p];
    for (int i = 1; i <= len; ++i) {
        int u = s[i] - 'a' + 1;
        if (!tr[p][u]) {
            tr[p][u] = ++tot;
            memset(tr[tot], 0, sizeof tr[tot]); // 插入时顺便清空 trie
        }
        p = tr[p][u];
        ++cnt[p]; // 记录经过当前位置的字符串个数
    }
    ++ed[p]; // 记录从当前位置结束的字符串个数
    return;
}

char s[maxn];

void sol() {
    // 多测记得清空
    tot = 1;
    for (int i = 1; i <= 26; ++i)
        tr[1][i] = 0; // 清空首层
    int n, k;
    scanf("%d%d", &n, &k);
    for (int i = 1; i <= n; ++i) {
        scanf("%s", s + 1);
        int len = strlen(s + 1);
        add(s, len);
    }
    int p = 1;
    // 题解大部分写的是 dfs，这里用简单循环实现
    while (1) {
        int sum = ed[p];
        for (int i = 1; i <= 26; ++i)
            if (cnt[tr[p][i]])
                ++sum; // 下一位每个字符串最多选一个
        if (sum >= k) {
            // 判定答案合法
            for (int i = 1; i <= tot; ++i) {
                ed[i] = 0;
                cnt[i] = 0;
            }
            if (p == 1) // 在首层，即答案为空字符串
                printf("EMPTY");
            putchar('\n');
            // 已经找到最优合法答案，结束程序即可
            return;
        }
        for (int i = 1; i <= 26; ++i) {
            if (!cnt[tr[p][i]])
                continue;
            sum += cnt[tr[p][i]] - 1;
            // 之所以减一，因为上面已经每个算了一个
            if (sum >= k) {
                // 确定下一位字母
                k -= (sum - cnt[tr[p][i]]);
                // 把当前可选所有字符串数从 k 中减掉
                putchar((char)('a' + i - 1));
                // 已确定，直接输出即可
                p = tr[p][i];
                break; // 进入下一位的枚举
            }
        }
    }
    return;
}

int main() {
    scanf("%d", &t);
    while (t--)
        sol();
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 200005;

int n,m;
long long arr[MAXN];
long long  Min[MAXN<<2],sum[MAXN<<2],add[MAXN<<2];

void up(int i){
    sum[i]=sum[i<<1]+sum[i<<1|1];
    Min[i]=min(Min[i<<1],Min[i<<1]);
}

void lazy(int i, int v,int n) {
    sum[i] +=n*v;
    Min[i] += v;
    add[i] += v;//这个数组表示是否有信息可以向下传递
}

void down(int i,int l,int r) {
    if (add[i] != 0) {
        int mid=(l+r)/2;
        // 发左
        lazy(i << 1, add[i],mid-l+1);
        // 发右
        lazy(i << 1 | 1, add[i],r-mid);
        // 父范围懒信息清空
        add[i] = 0;
    }
}

void build(int l, int r, int i) {
    if (l == r) {
        Min[i] = arr[l];
        sum[i] = arr[l];
    } else {
        int mid = (l + r) >> 1;
        build(l, mid, i << 1);
        build(mid + 1, r, i << 1 | 1);
        up(i);
    }
    add[i]=0;//初始化每一个位置都没有向下传递的信息
}

void Add(int jobl,int jobr,int jobv,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        lazy(i,jobv,r-l+1);
    }else{
        int mid=(l+r)/2;
        down(i,l,r);
        if (jobl <= mid) {
            Add(jobl, jobr, jobv, l, mid, i << 1);
        }
        if (jobr > mid) {
            Add(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);
        }
        up(i);//汇总修改数据
    }
}

long long  sumquery(int jobl, int jobr, int l, int r, int i) {
    if (jobl <= l && r <= jobr) {
        return sum[i];
    }
    int mid = (l + r) >> 1;
    down(i,l,r);
    long ans = 0;
    if (jobl <= mid) {
        ans +=sumquery(jobl, jobr, l, mid, i << 1);
    }
    if (jobr > mid) {
        ans +=sumquery(jobl, jobr, mid + 1, r, i << 1 | 1);
    }
    return ans;
}

long long minquery(int jobl, int jobr, int l, int r, int i) {
    if (jobl <= l && r <= jobr) {
        return Min[i];
    }
    int mid = (l + r) >> 1;
    down(i,l,r);
    long long ans = 3e12;
    if (jobl <= mid) {
        ans =min(ans, minquery(jobl, jobr, l, mid, i << 1));
    }
    if (jobr > mid) {
        ans =min(ans, minquery(jobl, jobr, mid + 1, r, i << 1 | 1));
    }
    return ans;
}

signed main()
{
    cin>>n>>m;
    for(int i=1;i<=n;i++){
        cin>>arr[i];
    }
    build(1,n,1);
    char op;
    long long jobv;
    for(int i=1,jobl,jobr;i<=m;i++){
        cin>>op>>jobl>>jobr;
        if(op=='P'){
            cin>>jobv;
            Add(jobl,jobr,jobv,1,n,1);
        }else if(op=='M'){
            cout<<minquery(jobl,jobr,1,n,1)<<endl;
        }else{
            cout<<sumquery(jobl,jobr,1,n,1)<<endl;
        }
    }
    return 0;
}

