        int u,v;
        u=read(),v=read();
        addedge(u,v);
        addedge(v,u);
    }
    dfs(1,0);
    prepare();
    compute();
    for(int i=1;i<=n;i++){
        if(ans[i]==-1){
            ans[i]=ans[i-1];
        }
        printf("%d\n",ans[i]);
    }
    return 0;
}

