int d1[105];
int d2[105];

bool check(int limit){
    for(int i=0;i<=n;i++){
        for(int j=0;j<=m;j++){
            dp[i][j]=INT_MIN;
        }
    }
    dp[0][0]=0;
    for(int i=1;i<=n;i++){
        for(int j=0;j<=m;j++){
            for(int k=0;k<=j&&(limit>=k*d1[i]);k++){
                dp[i][j]=max(dp[i][j],dp[i-1][j-k]+(limit-k*d1[i])/d2[i]);
            }
        }
    }
    return dp[n][m]>=m;
}

