#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;
const int MAXH = 22;

int n,p,q,k,m;

int headg[MAXN];
int nxtg[MAXN<<1];
int tog[MAXN<<1];
int cntg=1;

int headv[MAXN];
int nxtv[MAXN<<1];
int tov[MAXN<<1];
int cntv=1;

int dep[MAXN];
int dfn[MAXN];
int st[MAXN][MAXH];
int dfncnt;

int arr[MAXN<<1];
int tmp[MAXN<<2];
int len;

int start[MAXN];
int speed[MAXN];
int query[MAXN];

bool vis[MAXN];
int mintime[MAXN];
int findvirus[MAXN];

struct node {
    int id, dist, time, virus;
    bool operator<(const node &other) const {
        if (time != other.time) {
            return time > other.time;
        }
        return virus > other.virus;
    }
};
priority_queue<node>heap;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedgeg(int u,int v){
    nxtg[cntg]=headg[u];
    tog[cntg]=v;
    headg[u]=cntg++;
}

void dfs(int u,int fa){
    dep[u]=dep[fa]+1;
    dfn[u]=++dfncnt;
    st[u][0]=fa;
    for(int i=1;i<=p;i++){
        st[u][i]=st[st[u][i-1]][i-1];
    }
    for(int i=headg[u];i;i=nxtg[i]){
        int v=tog[i];
        if(v!=fa){
            dfs(v,u);
        }
    }
}

bool cmp(int a,int b){
    return dfn[a]<dfn[b];
}

int lca(int a,int b){
    if(dep[a]<dep[b]){
        swap(a,b);
    }
    for(int i=p;i>=0;i--){
        if(dep[st[a][i]]>=dep[b]){
            a=st[a][i];
        }
    }
    if(a==b){
        return a;
    }
    for(int i=p;i>=0;i--){
        if(st[a][i]!=st[b][i]){
            a=st[a][i];
            b=st[b][i];
        }
    }
    return st[a][0];
}

inline void addedgev(int u,int v){
    nxtv[cntv]=headv[u];
    tov[cntv]=v;
    headv[u]=cntv++;
}

int buildvirtualtree(){
    int tot=0;
    for(int i=1;i<=k;i++){
        arr[++tot]=start[i];
    }
    for(int i=1;i<=m;i++){
        arr[++tot]=query[i];
    }
    sort(arr+1,arr+tot+1,cmp);

    len=0;
    for(int i=1;i<tot;i++){
        tmp[++len]=arr[i];
        tmp[++len]=lca(arr[i],arr[i+1]);
    }
    tmp[++len]=arr[tot];
    sort(tmp+1,tmp+len+1,cmp);

    int m=1;
    for(int i=2;i<=len;i++){
        if(tmp[i]!=tmp[i-1]){
            tmp[++m]=tmp[i];
        }
    }

    cntv=1;
    for(int i=1;i<=m;i++){
        headv[tmp[i]]=0;
    }
    for(int i=1;i<m;i++){
        int fa=lca(tmp[i],tmp[i+1]);
        addedgev(fa,tmp[i+1]);
        addedgev(tmp[i+1],fa);
    }
    len=m;
    return tmp[1];
}

void dijkstra(){
    for(int i=1;i<=len;i++){
        int u=tmp[i];
        mintime[u]=n+1;
        findvirus[u]=k+1;
        vis[u]=false;
    }
    for(int i=1;i<=k;i++){
        int s=start[i];
        mintime[s]=0;
        findvirus[s]=i;
        heap.push({s,0,0,i});
    }

    while(!heap.empty()){
        node cur=heap.top();
        heap.pop();
        int u=cur.id;
        int udist=cur.dist;
        int uvirus=cur.virus;
        if(vis[u]){
            continue;
        }
        vis[u]=true;
        for(int i=headv[u];i;i=nxtv[i]){
            int v=tov[i];
            if(!vis[v]){
                int vdist=udist+abs(dep[u]-dep[v]);
                int vtime=(vdist+speed[uvirus]-1)/speed[uvirus];
                if(vtime<mintime[v]||(vtime==mintime[v]&&uvirus<findvirus[v])){
                    mintime[v]=vtime;
                    findvirus[v]=uvirus;
                    heap.push({v,vdist,vtime,uvirus});
                }
            }
        }
    }
}

int main()
{
    n=read();
    p=log2(n)+1;
    for(int i=1;i<n;i++){
        int u,v;
        u=read(),v=read();
        addedgeg(u,v);
        addedgeg(v,u);
    }
    dfs(1,0);
    q=read();
    for(int t=1;t<=q;t++){
        k=read(),m=read();
        for(int i=1;i<=k;i++){
            start[i]=read();
            speed[i]=read();
        }
        for(int i=1;i<=m;i++){
            query[i]=read();
        }
        buildvirtualtree();
        dijkstra();
        for(int i=1;i<=m;i++){
            cout<<findvirus[query[i]]<<' ';
        }
        cout<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int MAXH = 20;

int n,m,q,p;
int val[MAXN];
int weight[MAXN];
int kind[MAXN];

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int cntg=1;

int dfncnt;
int sta[MAXN];
int ove[MAXN];
int seg[MAXN<<1];

int dep[MAXN];
int st[MAXN][MAXH];

long long sum;
int cnt[MAXN];

struct Query{
    int l,r,lca,t,id;
};
Query query[MAXN];
long long ans[MAXN];

struct Update{
    int pos,val;
};
Update update[MAXN];
int cntq,cntu;

int blen;
int bi[MAXN<<1];
bool vis[MAXN];

void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

void dfs(int u,int fa){
    sta[u]=++dfncnt;
    seg[dfncnt]=u;

    dep[u]=dep[fa]+1;
    st[u][0]=fa;
    for(int i=1;i<=p;i++){
        st[u][i]=st[st[u][i-1]][i-1];
    }

    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa){
            dfs(v,u);
        }
    }

    ove[u]=++dfncnt;
    seg[dfncnt]=u;
}

void prepare(){
    p=log2(n)+1;
    dfs(1,0);

    blen=max(1.0,pow(dfncnt,2.0/3));
    for(int i=1;i<=dfncnt;i++){
        bi[i]=(i-1)/blen+1;
    }
}

int lca(int a,int b){
    if(dep[a]<dep[b]){
        swap(a,b);
    }
    for(int i=p;i>=0;i--){
        if(dep[st[a][i]]>=dep[b]){
            a=st[a][i];
        }
    }
    if(a==b){
        return a;
    }

    for(int i=p;i>=0;i--){
        if(st[a][i]!=st[b][i]){
            a=st[a][i];
            b=st[b][i];
        }
    }
    return st[a][0];
}

bool cmp(Query &a,Query &b){
    if(bi[a.l]!=bi[b.l]){
        return bi[a.l]<bi[b.l];
    }
    if(bi[a.r]!=bi[b.r]){
        return bi[a.r]<bi[b.r];
    }
    return a.t<b.t;
}

void add(int v){
    cnt[v]++;
    sum+=1ll*val[v]*weight[cnt[v]];
}

void del(int v){
    sum-=1ll*val[v]*weight[cnt[v]];
    cnt[v]--;
}

void change(int pos){
    vis[pos]^=1;
    if(vis[pos]){
        add(kind[pos]);
    }
    else{
        del(kind[pos]);
    }
}

void movetime(int t){
    int pos=update[t].pos;
    int val=update[t].val;
    if(vis[pos]){
        add(val);
        del(kind[pos]);
    }
    swap(update[t].val,kind[pos]);
}

void compute(){
    sort(query+1,query+cntq+1,cmp);

    int winl=1,winr=0,wint=0;
    for(int i=1;i<=cntq;i++){
        int l=query[i].l;
        int r=query[i].r;
        int t=query[i].t;
        int lca=query[i].lca;
        int id=query[i].id;

        while(winl>l){
            change(seg[--winl]);
        }
        while(winr<r){
            change(seg[++winr]);
        }
        while(winl<l){
            change(seg[winl++]);
        }
        while(winr>r){
            change(seg[winr--]);
        }
        while(wint<t){
            movetime(++wint);
        }
        while(wint>t){
            movetime(wint--);
        }
        if(lca){
            change(lca);
        }
        ans[id]=sum;
        if(lca){
            change(lca);
        }
    }
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m>>q;
    for(int i=1;i<=m;i++){
        cin>>val[i];
    }
    for(int i=1;i<=n;i++){
        cin>>weight[i];
    }
    for(int i=1;i<n;i++){
        int u,v;
        cin>>u>>v;
        addedge(u,v);
        addedge(v,u);
    }
    for(int i=1;i<=n;i++){
        cin>>kind[i];
    }

    prepare();

    for(int i=1;i<=q;i++){
        int op,x,y;
        cin>>op>>x>>y;
        if(op==1){
            int fa=lca(x,y);
            if(sta[x]>sta[y]){
                swap(x,y);
            }
            ++cntq;
            if(fa==x){
                query[cntq]={sta[x],sta[y],0,cntu,cntq};
            }
            else{
                query[cntq]={ove[x],sta[y],fa,cntu,cntq};
            }
        }
        else{
            ++cntu;
            update[cntu]={x,y};
        }
    }

