            rtup[u]=merge(1,n,rtup[u],rtup[v]);
            rtdn[u]=merge(-n,n,rtdn[u],rtdn[v]);
        }
    }
    ans[u]=query(dep[u]+val[u],1,n,rtup[u])+query(dep[u]-val[u],-n,n,rtdn[u]);
}

