            int v=mp[{b-a,c-a}]+a;
            if(s){
                if(v>ans){
                    ans=v;
                    ans1=s;
                    ans2=sta;
                }
            }
        }
    }
    else{
        dfs(u+1,a+nums[u][0],b+nums[u][1],c,limit,op,sta*3+2);
        dfs(u+1,a+nums[u][0],b,c+nums[u][2],limit,op,sta*3+1);
        dfs(u+1,a,b+nums[u][1],c+nums[u][2],limit,op,sta*3);
    }
}

