    for(int i=2;i<=n;i++){
        if(arr[i]!=arr[i-1]){
            arr[++m]=arr[i];
        }
    }
    for(int i=1;i<=n;i++){
        v[i]=find(v[i]);
    }
    for(int i=1;i<=n;i++){
        len1[i]=len2[i]=1;
        cnt1[i]=cnt2[i]=1.0;
    }
    compute();
    int len = 0;
    double cnt = 0.0;
    for (int i = 1; i <= n; i++) {
        len = max(len, len1[i]);
    }
