bool spfa(){
    for(int i=0;i<=n+1;i++){
        vis[i]=false;
    }
    dis[0] = 0;
    updatecnt[0]++;
    q.push(0) ;
    vis[0] = true;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        vis[u] = false;
        for (int ei = head1[u], v, w; ei > 0; ei = nxt1[ei]) {
            v = to1[ei];
            w = weight[ei];
            if (dis[u] + w < dis[v]) {
                //如果值变小了  那么就要改变
                dis[v] = dis[u] + w;
                if (!vis[v]) {
                    if (++updatecnt[v] > n) {
                        return true;
                    }
                    q.push(v);
                    vis[v] = true;
                }
            }
        }
    }
    return false;
}

