bool dp[MAXN][MAXN];
int from[MAXN][MAXN];
int diff[MAXN];

int in[4][MAXN];

void compute(){
    dp[0][0]=true;
    for(int i=1;i<=block;i++){
        int k=abs(cnta[i]-cntb[i]);
        for(int j=0;j<=n;j++){
            if(j+k<=n&&dp[i-1][j+k]){
                dp[i][j]=true;
                from[i][j]=j+k;
            }
            if(j>=k){
                if(dp[i-1][j-k]){
                    dp[i][j]=true;
                    from[i][j]=j-k;
                }
            }
            else{
                if(dp[i-1][k-j]){
                    dp[i][j]=true;
                    from[i][j]=k-j;
                }
            }
        }
    }

    for(int i=0;i<=n;i++){
        if(dp[block][i]){
            diff[block]=i;
            break;
        }
    }
    for(int i=block;i>=1;i--){
        diff[i-1]=from[i][diff[i]];
    }

    int big=2;
    for(int i=1;i<=block;i++){
        int k=abs(cnta[i]-cntb[i]);
        int maxx=(cnta[i]>cntb[i])?2:3;

        if(diff[i]==diff[i-1]+k){
            in[maxx][i]=big;
            in[maxx^1][i]=big^1;
            continue;
        }
        if(diff[i]>=k){
            in[maxx][i]=big^1;
            in[maxx^1][i]=big;
            continue;
        }
        else{
            in[maxx][i]=big^1;
            in[maxx^1][i]=big;
            big^=1;
            continue;
        }
    }

    vector<int>lt;
    vector<int>rt;
    for(int i=1;i<=n;i++){
        if(in[col[i]][belong[i]]==2){
            lt.push_back(i);
        }
        else{
            rt.push_back(i);
        }
    }
    cout<<lt.size()<<' ';
    for(int i=0;i<lt.size();i++){
        cout<<lt[i]<<' ';
    }
    cout<<endl;
