        int l=bl[i];
        int r=br[i];
        for(int i=l;i<=r;i++){
            pre[i]=max(maxval,val[i]);
            maxval=pre[i];
        }
        maxval=0;
        for(int i=r;i>=l;i--){
            suf[i]=max(maxval,val[i]);
            maxval=suf[i];
        }

        maxx[i]=pre[r];
    }

    lg2[0]=-1;
    for(int i=1;i<=bnum;i++){
        lg2[i]=lg2[i>>1]+1;
    }

    for(int i=1;i<=bnum;i++){
        st[0][i]=maxx[i];
    }
    for(int i=1;i<=lg2[bnum];i++){
        for(int j=1;j+(1<<i)-1<=bnum;j++){
            st[i][j]=max(st[i-1][j],st[i-1][j+(1<<(i-1))]);
        }
    }
}

int query(int l,int r){
    int len=r-l+1;
    int i=lg2[len];
    return max(st[i][l],st[i][r-(1<<i)+1]);
}

