#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int MAXV = 3e4+5;
const int MAXB = 401;
const int MAXH = 20;

int n,m,f,p;
int val[MAXN];

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int cntg=1;

int marknum;
// 表示这个节点的被标记编号 没有就是0
int kthnum[MAXN];
int marknode[MAXN];
// 记录每个节点上方的第一个被标记的节点
int up[MAXN];

int dep[MAXN];
int st[MAXN][MAXH];

bitset<MAXV>downset[MAXB];

bitset<MAXV>ans;

void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

int lca(int a,int b){
    if(dep[a]<dep[b]){
        swap(a,b);
    }
    for(int i=p;i>=0;i--){
        if(dep[st[a][i]]>=dep[b]){
            a=st[a][i];
        }
    }
    if(a==b){
        return a;
    }

    for(int i=p;i>=0;i--){
        if(st[a][i]!=st[b][i]){
            a=st[a][i];
            b=st[b][i];
        }
    }
    return st[a][0];
}

void dfs(int u,int fa){
    dep[u]=dep[fa]+1;
    st[u][0]=fa;
    for(int i=1;i<=p;i++){
        st[u][i]=st[st[u][i-1]][i-1];
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa){
            dfs(v,u);
        }
    }
}

void query(int x,int y){
    while(kthnum[x]==0&&x!=y){
        ans[val[x]]=1;
        x=st[x][0];
    }
    while(up[x]&&dep[up[x]]>dep[y]){
        ans|=downset[kthnum[x]];
        x=up[x];
    }
    while(x!=y){
        ans[val[x]]=1;
        x=st[x][0];
    }
}

void prepare(){
    p=log2(n);
    dfs(1,0);
    int len=(int)sqrt(n*10);
    marknum=(n+len-1)/len;
    for(int b=1,pick;b<=marknum;b++){
        do{
            pick=rand()%n+1;
        }while(kthnum[pick]);
        kthnum[pick]=b;
        marknode[b]=pick;
    }
    for(int b=1,cur;b<=marknum;b++){
        downset[b][val[marknode[b]]]=1;
        cur=st[marknode[b]][0];
        while(cur!=0){
            if(kthnum[cur]){
                up[marknode[b]]=cur;
                break;
            }
            else{
                downset[b][val[cur]]=1;
                cur=st[cur][0];
            }
        }
    }
}

