    ls[rt]=ls[i];
    rs[rt]=rs[i];
    sz[rt]=sz[i];

    if(l==r){
        sz[rt]++;
    }
    else{
        int mid=(l+r)>>1;
        if(val<=mid){
            ls[rt]=insert(val,l,mid,ls[rt]);
        }
        else{
            rs[rt]=insert(val,mid+1,r,rs[rt]);
        }
        sz[rt]=sz[ls[rt]]+sz[rs[rt]];
    }
    return rt;
}

void dfs(int u,int fa){
    root[u]=insert(find(val[u]),1,len,root[fa]);
    dep[u]=dep[fa]+1;
    st[u][0]=fa;
    for(int i=1;i<=p;i++){
        st[u][i]=st[st[u][i-1]][i-1];
    }

    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa){
            dfs(v,u);
        }
    }
}

int build(int l,int r){
    int rt=++cnt;
    if(l<r){
        int mid=(l+r)>>1;
        ls[rt]=build(l,mid);
        rs[rt]=build(mid+1,r);
    }
    return rt;
}

void prepare(){
    for(int i=1;i<=n;i++){
        sorted[i]=val[i];
    }
    sort(sorted+1,sorted+n+1);
    len=1;
    for(int i=2;i<=n;i++){
        if(sorted[i]!=sorted[i-1]){
            sorted[++len]=sorted[i];
        }
    }

    root[0]=build(1,len);

    p=log2(n)+1;
    dfs(1,0);

}

int lca(int a,int b){
    if(dep[a]<=dep[b]){
        swap(a,b);
    }

    for(int i=p;i>=0;i--){
        if(dep[st[a][i]]>=dep[b]){
            a=st[a][i];
        }
    }
    if(a==b){
        return a;
    }

    for(int i=p;i>=0;i--){
        if(st[a][i]!=st[b][i]){
            a=st[a][i];
            b=st[b][i];
        }
    }
    return st[a][0];
}

int query(int jobk,int l,int r,int u,int v,int x,int y){
    if(l==r){
        return l;
    }
    else{
        int mid=(l+r)>>1;
        int lsz=sz[ls[u]]+sz[ls[v]]-sz[ls[x]]-sz[ls[y]];
        if(lsz>=jobk){
            return query(jobk,l,mid,ls[u],ls[v],ls[x],ls[y]);
        }
        else{
            return query(jobk-lsz,mid+1,r,rs[u],rs[v],rs[x],rs[y]);
        }
    }
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m;
    for(int i=1;i<=n;i++){
        cin>>val[i];
    }

    for(int i=1;i<n;i++){
        int u,v;
        cin>>u>>v;
        addedge(u,v);
        addedge(v,u);
    }

    prepare();

    int lastans=0;
    for(int i=1;i<=m;i++){
        int u,v,k;
        cin>>u>>v>>k;
        u^=lastans;
        int fa=lca(u,v);
        lastans=sorted[query(k,1,len,root[u],root[v],root[fa],root[st[fa][0]])];
        cout<<lastans<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 1e5+5;

int n,limitl,limitw;

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int weight[MAXN<<1];
int cnt=1;

bool vis[MAXN];
int sz[MAXN];

struct node{
    int dis,edge;
};
node nums[MAXN];
int cnta;

int tree[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline int lowbit(int x){
    return x&-x;
}

void add(int x,int v){
    x++;
    while(x<=limitl+1){
        tree[x]+=v;
        x+=lowbit(x);
    }
}

int sum(int x){
    x++;
    int ans=0;
    while(x>0){
        ans+=tree[x];
        x-=lowbit(x);
    }
    return ans;
}

bool cmp(node a,node b){
    return a.dis<b.dis;
}

inline void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    head[u]=cnt++;
}

void getsize(int u,int fa){
    sz[u]=1;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa&&!vis[v]){
            getsize(v,u);
            sz[u]+=sz[v];
        }
    }
}

int getcentroid(int u,int fa){
    getsize(u,fa);
    int half=sz[u]>>1;
    bool find=false;
    while(!find){
        find=true;
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            if(v!=fa&&!vis[v]&&sz[v]>half){
                fa=u;
                u=v;
                find=false;
                break;
            }
        }
    }
    return u;
}

void dfs(int u,int fa,int dis,int edge){
    if(dis>limitw||edge>limitl){
        return ;
    }
    nums[++cnta]={dis,edge};
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        int w=weight[i];
        if(v!=fa&&!vis[v]){
            dfs(v,u,dis+w,edge+1);
        }
    }
}

int calc(int u,int dis,int edge){
    cnta=0;
    dfs(u,0,dis,edge);
    sort(nums+1,nums+cnta+1,cmp);
    for(int i=1;i<=cnta;i++){
        add(nums[i].edge,1);
    }
    int ans=0;
    for(int l=1,r=cnta;l<=r;){
        if(nums[l].dis+nums[r].dis<=limitw){
            add(nums[l].edge,-1);
            ans+=sum(limitl-nums[l].edge);
            l++;
        }
        else{
            add(nums[r].edge,-1);
            r--;
        }
    }
    return ans;
}

int compute(int u){
    vis[u]=true;
    int ans=calc(u,0,0);
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        int w=weight[i];
        if(!vis[v]){
            ans-=calc(v,w,1);
            ans+=compute(getcentroid(v,u));
        }
    }
    return ans;
}

signed main()
{
    n=read(),limitl=read(),limitw=read();
    for(int i=2;i<=n;i++){
        int u,w;
        u=read(),w=read();
        addedge(i,u,w);
        addedge(u,i,w);
    }
    cout<<compute(getcentroid(1,0))<<endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 150000 * 3 + 10;

int n, m;
struct Node {
    int mi, cnt;
    int ans, ad;
} t[4 * N];
int a[N], buc[N];
int st, lim;

void pushup(int x) {
    t[x].mi = min(t[x * 2].mi, t[x * 2 + 1].mi);
    t[x].cnt = (t[x * 2].mi == t[x].mi ? t[x * 2].cnt : 0) + 
               (t[x * 2 + 1].mi == t[x].mi ? t[x * 2 + 1].cnt : 0);
    t[x].ans = t[x * 2].ans + t[x * 2 + 1].ans;
}

void tag(int x, int c) {
    t[x].mi += c;
    t[x].ans = (t[x].mi == 0) ? t[x].cnt : 0;
    t[x].ad += c;
}

void pushdown(int x) {
    if (t[x].ad) {
        tag(x * 2, t[x].ad);
        tag(x * 2 + 1, t[x].ad);
        t[x].ad = 0;
    }
}

void build(int x, int l, int r) {
    if (l == r) {
        t[x].cnt = 1;
        t[x].ans = 1;
        return;
    }
    int mid = (l + r) / 2;
    build(x * 2, l, mid);
    build(x * 2 + 1, mid + 1, r);
    pushup(x);
}

void update(int x, int l, int r, int L, int R, int c) {
    if (L <= l && r <= R) {
        tag(x, c);
        return;
    }
    pushdown(x);
    int mid = (l + r) / 2;
    if (L <= mid) update(x * 2, l, mid, L, R, c);
    if (R > mid) update(x * 2 + 1, mid + 1, r, L, R, c);
    pushup(x);
}

int query(int x, int l, int r, int L, int R) {
    if (L <= l && r <= R) return t[x].ans;
    pushdown(x);
    int mid = (l + r) / 2;
    if (R <= mid) return query(x * 2, l, mid, L, R);
    if (L > mid) return query(x * 2 + 1, mid + 1, r, L, R);
    return query(x * 2, l, mid, L, R) + query(x * 2 + 1, mid + 1, r, L, R);
}

void change(int x, int c) {
    int k = x - buc[x] + 1 - (c > 0);
    update(1, 1, lim, k, k, c);
    buc[x] += c;
}

int main() {
    cin >> n >> m;
    st = 150000 + 1;
    lim = 450000 + 5;
    build(1, 1, lim);
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        a[i] += st;
        change(a[i], 1);
    }
    int p, x;
    while (m--) {
        cin >> p >> x;
        if (p > 0) {
            if (a[p] <= st + n) {
                change(a[p], -1);
            } else {
                buc[a[p]]--;
            }
            a[p] = st + x;
            if (a[p] <= st + n) {
                change(a[p], 1);
            } else {
                buc[a[p]]++;
            }
        } else if (x > 0) {
            int pos = st + n;
            if (buc[pos]) update(1, 1, lim, pos - buc[pos] + 1, pos, -1);
            st--;
        } else {
            st++;
            int pos = st + n;
            if (buc[pos]) update(1, 1, lim, pos - buc[pos] + 1, pos, 1);
        }
        cout << query(1, 1, lim, st + 1, st + n) << endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;
const int MAXT = 5e6+5;

int n;

int ls[MAXT];
int rs[MAXT];
int sz[MAXT];
int cntv;

long long ans,no,yes;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void up(int x){
    sz[x]=sz[ls[x]]+sz[rs[x]];
}

int build(int jobv,int l,int r){
    int rt=++cntv;
    if(l==r){
        sz[rt]++;
    }
    else{
        int mid=(l+r)>>1;
        if(jobv<=mid){
            ls[rt]=build(jobv,l,mid);
        }
        else{
            rs[rt]=build(jobv,mid+1,r);
        }
        up(rt);
    }
    return rt;
}

int merge(int l,int r,int t1,int t2){
    if(t1==0||t2==0){
        return t1+t2;
    }
    if(l==r){
        sz[t1]+=sz[t2];
    }
    else{
        no+=1ll*sz[rs[t1]]*sz[ls[t2]];
        yes+=1ll*sz[rs[t2]]*sz[ls[t1]];
        int mid=(l+r)>>1;
        ls[t1]=merge(l,mid,ls[t1],ls[t2]);
        rs[t1]=merge(mid+1,r,rs[t1],rs[t2]);
        up(t1);
    }
    return t1;
}

