    int rt;
    if(val==0){
        int left=dfs();
        int right=dfs();
        no=yes=0;
        rt=merge(1,n,left,right);
        ans+=min(no,yes);
    }
    else{
        rt=build(val,1,n);
    }
    return rt;
}

