    dfs();
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MOD = 999911659;
const int MAXN = 505;

int n,p;
// 记录每个余数的后缀1出现数量
int cnt[MAXN];
// 记录循环节长度
int cyclelen;
// 循环节开始的数字  这里也可以记录位置   我使用的是位置
int cyclestpos;
// 记录循环节的内容
int cycle[MAXN];
// 记录循环节中每个位置出现的数字
int firstpos[MAXN];
// dp[i][j][k]表示当前完成了前i个集合  已经选择了j个数字  余数为k的方案数
int dp[MAXN][10][MAXN];

int power(int a,int b){
    int ans=1;
    while(b){
        if(b&1){
            ans=(ans*a)%MOD;
        }
        b>>=1;
        a=(a*a)%MOD;
    }
    return ans;
}

// 这里的b是小于等于8的   a是特别大的  所以这里是暴力计算
int comb(int a, int b) {
    if (b == 0) return 1;
    int x = 1, y = 1;
    for (int i = 0; i < b; i++) {
        x = x * (a - i) % MOD;
        y = y * (i + 1) % MOD;
    }
    return x * power(y, MOD - 2) % MOD;
}

signed main()
{
    cin>>n>>p;

    int base=0;//这个适用于记录全部都是1的余数  这个是必选的  因为没有前导零

    // 长度为1的后缀  其实就是1
    cycle[1]=1%p;
    firstpos[1%p]=1;
    // 一直循环直到遇见已经出现过的数字 即循环节出现
    for(int i=2;;i++){
        cycle[i]=(cycle[i-1]*10+1)%p;

        // 遇到了已经访问过的数字
        if(firstpos[cycle[i]]){
            // 记录循环节之前的  并且不能超过n  其实这里包含了第一个循环节
            for(int j=1;j<i&&j<=n;j++){
                cnt[cycle[j]]++;
                base=cycle[j];
            }
            n-=i-1;//没有处理的部分
            cyclestpos=firstpos[cycle[i]];
            cyclelen=i-firstpos[cycle[i]];
            break;
        }
        else{
            firstpos[cycle[i]]=i;
        }
    }

    n=max(n,0ll);
    int times=n/cyclelen;
    int rest=n%cyclelen;

    // 处理完整循环节
    for(int i=0;i<cyclelen;i++){
        cnt[cycle[i+cyclestpos]]+=times;
        cnt[cycle[i+cyclestpos]]%=MOD;
    }

    for(int i=0;i<rest;i++){
        cnt[cycle[i+cyclestpos]]++;
        base=cycle[i+cyclestpos];
    }

    // cnt[base]--;//这个一定会选  所以要减去

    // 因为长度为n的必选要选 所以我们这个设置为默认值 可以选择的就只有8个了
    dp[0][0][base]=1;

    // 目前来到的集合是%p余数为i的集合
    for(int i=0;i<p;i++){
        // 这个集合以及之前已经使用过的量  注意这里是i+1  因为0被用过了
        for(int j=0;j<=8;j++){
            // 这个集合使用的量
            for(int k=0;k<=j;k++){
                int tmp=comb(cnt[i]+k-1,k);
                if(tmp==0){
                    continue;
                }
                for(int d=0;d<p;d++){
                    if(!dp[i][j-k][((d-k*i)%p+p)%p]){
                        continue;
                    }
                    // 这个以及之前的集合之后的余数
                    dp[i+1][j][d]=(dp[i+1][j][d]+tmp*dp[i][j-k][((d-k*i)%p+p)%p]%MOD)%MOD;
                }
            }
        }
    }

    int ans=0;
    for(int i=0;i<=8;i++){
        ans=(ans+dp[p][i][0])%MOD;
    }
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;

int n,m,C,q;

int fa[MAXN];
int ls[MAXN];
int rs[MAXN];
int sta[MAXN];
bool rev[MAXN];

int arr[MAXN];
int maxv[MAXN];

int nodedegree[MAXN];
map<pair<int,int>,int>edgecolor;

void up(int x){
    maxv[x]=max(arr[x],max(maxv[ls[x]],maxv[rs[x]]));
}

bool isroot(int x){
    return ls[fa[x]]!=x&&rs[fa[x]]!=x;
}

int lr(int x){
    return ls[fa[x]]==x?0:1;
}

void reverse(int x) {
   if (x != 0) {
       swap(ls[x], rs[x]);
       rev[x] = !rev[x];
   }
}

void down(int x) {
   if (rev[x]) {
       reverse(ls[x]);
       reverse(rs[x]);
       rev[x] = false;
   }
}

void rotate(int x) {
   int f = fa[x], g = fa[f];
   if (lr(x) == 0) {
       ls[f] = rs[x];
       if (ls[f] != 0) {
           fa[ls[f]] = f;
       }
       rs[x] = f;
   } else {
       rs[f] = ls[x];
       if (rs[f] != 0) {
           fa[rs[f]] = f;
       }
       ls[x] = f;
   }
   if (!isroot(f)) {
       if (lr(f) == 0) {
           ls[g] = x;
       } else {
           rs[g] = x;
       }
   }
   fa[f] = x;
   fa[x] = g;
   up(f);
   up(x);
}

void splay(int x) {
   int siz = 0;
   sta[++siz] = x;
   for (int y = x; !isroot(y); y = fa[y]) {
       sta[++siz] = fa[y];
   }
   while (siz != 0) {
       down(sta[siz--]);
   }
   while (!isroot(x)) {
       int f = fa[x];
       if (!isroot(f)) {
           if (lr(x) == lr(f)) {
               rotate(f);
           } else {
               rotate(x);
           }
       }
       rotate(x);
   }
}

void access(int x){
    for(int y=0;x!=0;y=x,x=fa[x]){
        splay(x);
        rs[x]=y;
        up(x);
    }
}

void makeroot(int x){
    access(x);
    splay(x);
    reverse(x);
}

int findroot(int x){
    access(x);
    splay(x);
    down(x);
    while(ls[x]){
        x=ls[x];
        down(x);
    }
    splay(x);
    return x;
}

void split(int x,int y){
    makeroot(x);
    access(y);
    splay(y);
}

void link(int x,int y){
    makeroot(x);
    if(findroot(y)!=x){
        fa[x]=y;
    }
}

void cut(int x,int y){
    makeroot(x);
    if(findroot(y)==x&&fa[y]==x&&ls[y]==0&&rs[x]==y){
        fa[y]=rs[x]=0;
        up(x);
    }
}

int node(int c,int x){
    return c*n+x;
}

pair<int,int>edge(int x,int y){
    int a=min(x,y);
    int b=max(x,y);
    return {a,b};
}

void connect(int c,int x,int y){
    int u=node(c,x);
    int v=node(c,y);
    nodedegree[u]++;
    nodedegree[v]++;
    link(u,v);
    edgecolor[edge(x,y)]=c;
}

void disconnect(int c,int x,int y){
    edgecolor.erase(edge(x,y));
    x=node(c,x);
    y=node(c,y);
    nodedegree[x]--;
    nodedegree[y]--;
    cut(x,y);
}

void updatenode(int x,int v){
    for(int c=0;c<C;c++){
        int u=node(c,x);
        splay(u);
        arr[u]=v;
        up(u);
    }
}

int updateedge(int x,int y,int c){
    auto it=edgecolor.find(edge(x,y));
    if(it==edgecolor.end()){
        return 3;
    }
    int p=it->second;
    if(p==c){
        return 4;
    }
    if(nodedegree[node(c,x)]>=2||nodedegree[node(c,y)]>=2){
        return 1;
    }
    if(findroot(node(c,x))==findroot(node(c,y))){
        return 2;
    }
    disconnect(p,x,y);
    connect(c,x,y);
    return 4;
}

int query(int c,int x,int y){
    int u=node(c,x);
    int v=node(c,y);
    if(findroot(u)!=findroot(v)){
        return -1;
    }
    split(u,v);
    return maxv[v];
}

int main()
{
    cin>>n>>m>>C>>q;
    for(int i=1;i<=n;i++){
        int v;
        cin>>v;
        for(int c=0;c<C;c++){
            int cur=node(c,i);
            arr[cur]=v;
            maxv[cur]=v;
        }
    }
    for(int i=1;i<=m;i++){
        int x,y,c;
        cin>>x>>y>>c;
        connect(c,x,y);
    }
    for(int i=1;i<=q;i++){
        int op,x,y,c;
        cin>>op;
        if(op==0){
            cin>>x>>y;
            updatenode(x,y);
        }
        else if(op==1){
            cin>>x>>y>>c;
            int ans=updateedge(x,y,c);
            if(ans==1){
                cout<<"Error 1."<<endl;
            }
            else if(ans==2){
                cout<<"Error 2."<<endl;
            }
            else if(ans==3){
                cout<<"No such edge."<<endl;
            }
            else{
                cout<<"Success."<<endl;
            }
        }
        else{
            cin>>c>>x>>y;
            cout<<query(c,x,y)<<endl;
        }
    }
    return 0;
}

#include <iostream>
