int a,b;

int C(int n,int m){
    int ans=1;
    for(int i=1;i<=m;i++){
        ans*=(n-i+1);
        ans/=i;
    }
    return ans;
}

int f(int num,int i,int gap,int free){
    //表示数字是num 目前是第i位  0-1数量是gap  free表示前缀是否一样及是否可以自由选择
    if(i==-1){
        if(gap>=0)
            return 1;
        else
            return 0;
    }
    if(free&&(gap==-1)){
        return sum[i];
    }
    int ans=0;
    if(free==0){
        int cur=(num&(1<<i));
        if(cur==1){
            ans+=f(num,i-1,gap+1,1);//表示这个位置填0
            ans+=f(num,i-1,gap-1,0);//表示这个位置填1
        }
        else{
            ans+=f(num,i-1,gap+1,0);
        }
    }
    else{
        //可以随便填，但是还没有直接触发上面的那个 说明差值不是1
            ans+=f(num,i-1,gap+1,1);//表示这个位置填0
            ans+=f(num,i-1,gap-1,1);//表示这个位置填1
    }
    return ans;
}

int cnt(int num){
    int tmp=num;
    int len=0;
    while(tmp){
        len++;
        tmp>>=1;
    }
    //cout<<len<<' ';
    int ans=0;
    for(int i=0;i<len-1;i++){
        ans+=sum[i];//首先将位数不足的情况加上
    }
    cout<<ans<<endl;
    ans+=f(num,len-1,0,0);
    //为什么有free  是因为如果是1000000000  即使第3位0就比1多  但是不能随便选
    return ans;
}

