ll read() {
    ll ret = 0, sign = 1;
    char ch;
    while ((ch = getchar()) < '0' || ch > '9') {
        if (ch == '-') sign = -1;
    }
    while (ch >= '0' && ch <= '9') {
        ret = ret * 10 + (ch - '0');
        ch = getchar();
    }
    return ret * sign;
}

void write(ll x) {
    if (x < 0) {
        putchar('-');
        x = -x;
    }
    if (x > 9) write(x / 10);
    putchar(x % 10 + '0');
}

void writeln(ll x) {
    write(x);
    putchar('\n');
}

int main() {
    ll n, k;
    n = read();
    k = read();

    // 初始化优先队列
    for (int i = 1; i <= MAX_PRIME; ++i) {
        ll now = primes[i];
        for (int j = 1; now <= n; ++j, now *= primes[i]) {
            pq.push({now, primes[i], j, i - 1});
        }
    }

    // 取出前 k 大的数
    while (k--) {
        Node top = pq.top();
        pq.pop();
        if (k == 0) {
            writeln(top.value);
            break;
        }
        if (top.power > 1) {
            for (int i = max(1,top.limit-10); i <= top.limit; ++i) {
                pq.push({top.value / top.prime * primes[i], top.prime, top.power - 1, i});
            }
        }
    }

    return 0;
}

