using namespace std;
const int MAXN = 1e5+5;
const int MAXM = 5e5+5;

int n,m;
int val[MAXN];
long long tree[MAXN];
vector<int>fac[MAXM];

vector<vector<int>::iterator> need;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline int lowbit(int x){
    return x&-x;
}

void add(int x,int v){
    while(x<=n){
        tree[x]+=v;
        x+=lowbit(x);
    }
}

long long query(int x){
    long long ans=0;
    while(x){
        ans+=tree[x];
        x-=lowbit(x);
    }
    return ans;
}

void prepare(){
    for(int i=1;i<=n;i++){
        add(i,val[i]);
        if(val[i]==0){
            continue;
        }
        for(int j=1;j*j<=val[i];j++){
            if(val[i]%j==0){
                fac[j].push_back(i);
                if(j*j!=val[i]){
                    fac[val[i]/j].push_back(i);
                }
            }
        }
    }
    for(int i=1;i<MAXM;i++){
        if(!fac[i].empty()){
            sort(fac[i].begin(),fac[i].end());
        }
    }
}

int main()
{
