inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void build(int l,int r,int i){
    tree[i]=0;
    if(l==r){
        return ;
    }
    else{
        int mid=(l+r)>>1;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
    }
}

void add(int pos,int val,int l,int r,int i){
    tree[i]+=val;
    if(l==r){
        return ;
    }
    else{
        int mid=(l+r)>>1;
        if(pos<=mid){
            add(pos,val,l,mid,i<<1);
        }
        else{
            add(pos,val,mid+1,r,i<<1|1);
        }
    }
}

int query(int l,int r,int i){
    if(tree[i]==0){
        return 0;
    }
    if(l==r){
        return l;
    }
    int mid=(l+r)>>1;
    if(tree[i<<1]){
        return query(l,mid,i<<1);
    }
    else{
        return query(mid+1,r,i<<1|1);
    }
}

int sum(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        return tree[i];
    }
    else{
        int ans=0;
        int mid=(l+r)>>1;
        if(jobl<=mid){
            ans+=sum(jobl,jobr,l,mid,i<<1);
        }
        if(jobr>mid){
            ans+=sum(jobl,jobr,mid+1,r,i<<1|1);
        }
        return ans;
    }
}

