        cin>>val[i];
    }
    for(int i=2;i<=n;i++){
        int fa;
        cin>>fa;
        addedge(fa,i);
    }

    prepare();
    dfs(1);
    cout<<query(1,len,1,len,root[1])<<endl;
    return 0;
}

