        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline int lowbit(int x){
    return x&-x;
}

void add(int x,int v){
    while(x<=m){
        tree[x]+=v;
        x+=lowbit(x);
    }
}

int sum(int x){
    int ans=0;
    while(x){
        ans+=tree[x];
        x-=lowbit(x);
    }
    return ans;
}

int find(int val){
    int l=1,r=m,ans=m;
    while(l<=r){
        int mid=(l+r)>>1;
        if(arr[mid]>=val){
            ans=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    return ans;
}

void build(){
    int top=0;
    for (int i = 1; i <= n; i++) {
        int pos = top;

        while (pos > 0 && val[sta[pos]] < val[i]) {
            pos--;
        }
        if (pos > 0) {
            rs[sta[pos]] = i;
        }
        if (pos < top) {
            ls[i] = sta[pos + 1];
        }

        sta[++pos] = i;
        top = pos;
    }
    root=sta[1];
}

void dfs1(int u,int f){
    fa[u]=f;
    sz[u]=1;
    if(ls[u]){
        dfs1(ls[u],u);
    }
    if(rs[u]){
        dfs1(rs[u],u);
    }
    sz[u]+=sz[ls[u]];
