        dfs(rs[u],rt);
    }
}

void dfs3(int u,int v){
    add(val[u],v);
    if(ls[u]){
        dfs3(ls[u],v);
    }
    if(rs[u]){
        dfs3(rs[u],v);
    }
}

void dfs2(int u,int keep){
    int v=ls[u]+rs[u]-son[u];
    if(v){
        dfs2(v,0);
    }
    if(son[u]){
