    p[0]=1;
    for(int i=1;i<=d;i++){
        p[i]=p[i-1]*BASE;
    }
    for(int k=1;k<=d;k++){
        for(int i=1;i<=n;i++){
            root[k][i]=i;
            h[i]+=i*p[k];
            vec[k][i].push_back(i);
        }
    }
    for(int i=1;i<=n;i++){
        add(h[i]);
    }
    while(m--){
        int u,v,k;
        u=read(),v=read(),k=read();
