        int fy=root[k][v];
        if(fx==fy){
            printf("%d\n",ans);
            continue;
        }
        if(vec[k][fx].size()<vec[k][fy].size()){
            swap(fx,fy);
        }
        for(int i=0;i<(int)vec[k][fy].size();i++){
            int v=vec[k][fy][i];
            vec[k][fx].push_back(v);
            root[k][v]=fx;
            del(h[v]);
            h[v]+=1ll*(fx-fy)*p[k];
            add(h[v]);
        }
        printf("%d\n",ans);
    }
    return 0;
}

