void merge(int l,int m,int r){
    int p1,p2;
    for(p1=l-1,p2=m+1;p2<=r;p2++){
        while(p1+1<=m&&nums[p1+1].b<=nums[p2].b){
            p1++;
            add(nums[p1].lt,1);
        }
        ans[nums[p2].i]+=query(nums[p2].rt)-query(nums[p2].lt-1);
    }
    for(int i=l;i<=p1;i++){
        add(nums[i].lt,-1);
    }
    sort(nums+l,nums+r+1,cmp2);
}

void cdq(int l,int r){
    if(l==r){
        return ;
    }
    int mid=(l+r)>>1;
    cdq(l,mid);
    cdq(mid+1,r);
    merge(l,mid,r);
}

