    }
    int tmp=num;
    int a=(tmp/100000)%10;
    int b=(tmp/p[c])%10;
    tmp-=a*100000;
    tmp-=b*p[c];
    tmp+=a*p[c];
    tmp+=b*100000;
    return tmp;
}

inline int fun2(int num){
    int c=num/1000000;
    if(c==6){
