int sorted[MAXN];

int head[MAXN];
int nxt[MAXN];
int to[MAXN];
int cntg=1;

int ans[MAXN];

int root[MAXN];
int ls[MAXT];
int rs[MAXT];
int sz[MAXT];
int cnt;

void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

int find(int val){
    int l=1,r=len,ans=1;
    while(l<=r){
        int mid=(l+r)>>1;
        if(sorted[mid]>=val){
            ans=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    return ans;
}

int add(int val,int l,int r,int i){
    if(i==0){
        i=++cnt;
    }
    if(l==r){
        sz[i]++;
    }
    else{
        int mid=(l+r)>>1;
        if(val<=mid){
            ls[i]=add(val,l,mid,ls[i]);
        }
        else{
            rs[i]=add(val,mid+1,r,rs[i]);
        }
        sz[i]=sz[ls[i]]+sz[rs[i]];
    }
    return i;
}

int merge(int l,int r,int v,int u){
    if(u==0||v==0){
        return u+v;
    }
    if(l==r){
        sz[u]+=sz[v];
    }
    else{
        int mid=(l+r)>>1;
        ls[u]=merge(l,mid,ls[v],ls[u]);
        rs[u]=merge(mid+1,r,rs[v],rs[u]);
        sz[u]=sz[ls[u]]+sz[rs[u]];
    }
    return u;
}

int query(int jobl,int jobr,int l,int r,int i){
    if(jobl>jobr||i==0){
        return 0;
    }
    if(jobl<=l&&r<=jobr){
        return sz[i];
    }
    else{
        int ans=0;
        int mid=(l+r)>>1;
        if(jobl<=mid){
            ans+=query(jobl,jobr,l,mid,ls[i]);
        }
        if(jobr>mid){
            ans+=query(jobl,jobr,mid+1,r,rs[i]);
        }
        return ans;
    }
}

void calc(int u){
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        calc(v);
        root[u]=merge(1,len,root[v],root[u]);
    }
    ans[u]=query(val[u]+1,len,1,len,root[u]);
}

void prepare(){
    for(int i=1;i<=n;i++){
        sorted[i]=val[i];
    }
