#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> p, r;
    DSU() {}
    DSU(int n) { init(n); }
    void init(int n) {
        p.resize(n + 1);
        r.assign(n + 1, 0);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) { return p[x] == x ? x : p[x] = find(p[x]); }
    bool unite(int a, int b) {
        a = find(a), b = find(b);
        if (a == b) return false;
        if (r[a] < r[b]) swap(a, b);
        p[b] = a;
        if (r[a] == r[b]) r[a]++;
        return true;
    }
};

struct OldEdge {
    int u, v, w;
    bool operator<(const OldEdge &o) const { return w < o.w; }
};

struct NewEdge {
    int u, v;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, K;
    cin >> N >> M >> K;

    vector<OldEdge> oldEdges(M);
    for (int i = 0; i < M; i++) {
        cin >> oldEdges[i].u >> oldEdges[i].v >> oldEdges[i].w;
    }
    sort(oldEdges.begin(), oldEdges.end());

    vector<NewEdge> newEdges(K);
    for (int i = 0; i < K; i++) {
        cin >> newEdges[i].u >> newEdges[i].v;
    }

    vector<long long> p(N + 1);
    for (int i = 1; i <= N; i++) cin >> p[i];

    // Step 1: shrink into <= K+1 components
    DSU dsuA(N), dsuB(N);
    for (int i = 0; i < K; i++) dsuA.unite(newEdges[i].u, newEdges[i].v);

    for (auto &e : oldEdges) {
        if (dsuA.find(e.u) != dsuA.find(e.v)) {
            dsuA.unite(e.u, e.v);
            dsuB.unite(e.u, e.v);
        }
    }

    // Map dsuB components to 0..C-1
    unordered_map<int, int> id;
    id.reserve((size_t)N * 2);
    vector<int> compOf(N + 1, -1);
    int C = 0;
    for (int i = 1; i <= N; i++) {
        int r = dsuB.find(i);
        auto it = id.find(r);
        if (it == id.end()) {
            id[r] = C;
            compOf[i] = C++;
        } else {
            compOf[i] = it->second;
        }
    }

    vector<long long> compPop(C, 0);
    for (int i = 1; i <= N; i++) compPop[compOf[i]] += p[i];
    int rootComp = compOf[1];

    // Compress edges
    for (int i = 0; i < K; i++) {
        newEdges[i].u = compOf[newEdges[i].u];
        newEdges[i].v = compOf[newEdges[i].v];
    }

    vector<OldEdge> compOld;
    compOld.reserve(M);
    for (auto &e : oldEdges) {
        int u = compOf[e.u], v = compOf[e.v];
        if (u != v) compOld.push_back({u, v, e.w});
    }

    // Step 2: keep only useful old edges q (MST edges on compressed graph)
    DSU dsuC(C);
    vector<OldEdge> q;
    q.reserve(max(0, C - 1));
    for (auto &e : compOld) {
        if (dsuC.unite(e.u, e.v)) q.push_back(e);
    }

    // Enumerate subsets of new edges
    long long ans = 0;
    const int INF = 0x3f3f3f3f;

    int totalMasks = 1 << K;
    vector<int> parent(C), depth(C);
    vector<long long> sub(C), mn(C);
    vector<vector<pair<int, int>>> g(C);

    for (int mask = 0; mask < totalMasks; mask++) {
        // Build spanning tree over compressed components
        DSU d(C - 1); // dummy; we'll re-init properly below
        d.init(C);
        for (int i = 0; i < C; i++) g[i].clear();

        bool bad = false;
        int used = 0;

        // Add selected new edges first
        for (int i = 0; i < K; i++) {
            if ((mask >> i) & 1) {
                int u = newEdges[i].u, v = newEdges[i].v;
                if (!d.unite(u + 1, v + 1)) { // cycle among selected new edges
                    bad = true;
                    break;
                }
                g[u].push_back({v, -1}); // -1 means new edge
                g[v].push_back({u, -1});
                used++;
            }
        }
        if (bad) continue;

        // Add old q edges by Kruskal order
        for (auto &e : q) {
            int u = e.u, v = e.v;
            if (d.unite(u + 1, v + 1)) {
                g[u].push_back({v, e.w});
                g[v].push_back({u, e.w});
                used++;
            }
        }

        if (used != C - 1) continue; // should not happen, but safe

        // DFS from rootComp: parent/depth/subtree sum
        for (int i = 0; i < C; i++) {
            parent[i] = -1;
            depth[i] = 0;
            sub[i] = 0;
            mn[i] = INF;
        }

        vector<int> order;
        order.reserve(C);
        {
            stack<int> st;
            st.push(rootComp);
            parent[rootComp] = rootComp;
            depth[rootComp] = 0;
            while (!st.empty()) {
                int u = st.top();
                st.pop();
                order.push_back(u);
                for (auto &nx : g[u]) {
                    int v = nx.first;
                    if (parent[v] != -1) continue;
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    st.push(v);
                }
            }
        }

        for (int i = 0; i < C; i++) sub[i] = compPop[i];
        for (int i = (int)order.size() - 1; i >= 0; i--) {
            int u = order[i];
            if (u != rootComp) sub[parent[u]] += sub[u];
        }

        // For each old q edge, constrain all tree edges on its path by weight w
        for (auto &e : q) {
            int u = e.u, v = e.v, w = e.w;
            while (depth[u] > depth[v]) {
                mn[u] = min(mn[u], (long long)w);
                u = parent[u];
            }
            while (depth[v] > depth[u]) {
                mn[v] = min(mn[v], (long long)w);
                v = parent[v];
            }
            while (u != v) {
                mn[u] = min(mn[u], (long long)w);
                mn[v] = min(mn[v], (long long)w);
                u = parent[u];
                v = parent[v];
            }
        }

        // Revenue from selected new edges
        long long cur = 0;
        for (int i = 0; i < K; i++) {
            if ((mask >> i) & 1) {
                int u = newEdges[i].u, v = newEdges[i].v;
                int child = (depth[u] > depth[v]) ? u : v;
                cur += mn[child] * sub[child];
            }
        }
        ans = max(ans, cur);
    }

    cout << ans << '\n';
    return 0;
}

#include<bits/stdc++.h>
using namespace std;

const int MAXN = 100000 + 10;

int n,k;
int scc[MAXN],sum,low[MAXN],dfn[MAXN],cnt,tot[MAXN];
//以上是强连通图的必备变量，唯一tot是记录每个强连通分量里面有多少个点
int dp[MAXN];
//这个用于DP记录答案
int in[MAXN];
//这个记录入度，用于Topo
long long ans;
//最终答案
struct Node{
	int next;//记录每个点的下一个点
	int v;//记录边权
};
vector<Node>nei[MAXN];//旧图
vector<Node>nnei[MAXN];//新图
bool Stack[MAXN];//用于Tarjan
stack<int> s;//用于Tarjan

inline int read(){//快速读入
    int f = 1, x = 0;
    char c = getchar();

    while (c < '0' || c > '9')
    {
        if (c == '-')
            f = -1;
        c = getchar();
    }

    while (c >= '0' && c <= '9')
    {
        x = x * 10 + c - '0';
        c = getchar();
    }

    return f * x;
}


void Tarjan(int u){//Tarjan模板
	low[u] = dfn[u] = ++cnt;
	Stack[u] = true;
	s.push(u);

	int len = nei[u].size();
	for(int i = 0;i < len; i++){
		int next = nei[u][i].next;

		if(dfn[next] == 0){
			Tarjan(next);
			low[u] = min(low[u],low[next]);
		}else
		if(Stack[next]){
			low[u] = min(low[u],dfn[next]);
		}
	}

	if(dfn[u] == low[u]){
		sum++;
		scc[u] = sum;
		Stack[u] = false;
		tot[sum]++;

		while(s.top() != u){
			Stack[s.top()] = false;
			scc[s.top()] = sum;
			s.pop();
			tot[sum]++;
		}
		s.pop();
	}
}

int main()
{
	n = read(),k = read();//读入

	for(int i = 1;i <= k; i++){
		int z = read(),x = read(),y = read();
		switch(z){//使用开关函数
			case 1:{//一号情况
				nei[x].push_back((Node){y,0});
				nei[y].push_back((Node){x,0});
				//这里一定要建两条边！
				break;
			}
			case 2:{//二号情况
				nei[x].push_back((Node){y,1});
				break;
			}
			case 3:{//三号情况
				nei[y].push_back((Node){x,0});
				break;
			}
			case 4:{//四号情况
				nei[y].push_back((Node){x,1});
				break;
			}
			case 5:{//五号情况
				nei[x].push_back((Node){y,0});
				break;
			}
		}
	}

	for(int i = 1;i <= n; i++){
    	if(dfn[i] == 0)Tarjan(i);//Tajan
    }

    for(int i = 1;i <= n; i++){//建新图
    	int len = nei[i].size();

		for(int j = 0;j < len; j++){
			int next = nei[i][j].next;
			int xx = scc[i];
        	int yy = scc[next];

        	if(xx == yy && nei[i][j].v == 1){//判断无解
        		cout<<-1<<"\n";
        		return 0;
			}

        	if(xx != yy){//建新图
        	    nnei[xx].push_back((Node){yy,nei[i][j].v});
        	    in[yy]++;
        	}
		}
    }

    queue<int>q;//Topo模板

    for(int i = 1;i <= sum; i++){//将入读为0的压入队列
    	if(!in[i]){
    		q.push(i);
    		dp[i] = 1;//初始化
		}
	}

	while(!q.empty()){//拓扑模板
		int cur = q.front();
		q.pop();
		int len = nnei[cur].size();

		for(int i = 0;i < len; i++){
			int next = nnei[cur][i].next;
			in[next]--;
			dp[next] = max(dp[next],dp[cur] + nnei[cur][i].v);//Dp方程

			if(!in[next])q.push(next);
		}
	}

	for(int i = 1;i <= sum; i++){//累加答案
		ans += (long long) dp[i] * tot[i];
	}
	cout<<ans;//输出
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 100001;

long arr[MAXN];
long sum[MAXN << 2];
long add[MAXN << 2];
int n,m;

// 累加和信息的汇总
void up(int i) {
    // 父范围的累加和 = 左范围累加和 + 右范围累加和
    sum[i] = sum[i << 1] + sum[i << 1 | 1];
}

// 建树
void build(int l, int r, int i) {
    if (l == r) {
        sum[i] = arr[l];
    } else {
        int mid = (l + r) >> 1;
        build(l, mid, i << 1);
        build(mid + 1, r, i << 1 | 1);
        up(i);
    }
    add[i] = 0;
}

// 当前来到l~r范围，对应的信息下标是i，范围上数字的个数是n = r-l+1
// 现在收到一个懒更新任务 : l~r范围上每个数字增加v
// 这个懒更新任务有可能是任务范围把当前线段树范围全覆盖导致的
// 也有可能是父范围的懒信息下发下来的
// 总之把线段树当前范围的sum数组和add数组调整好
// 就不再继续往下下发了，懒住了
void lazy(int i, long v, int n) {
    sum[i] += v * n;
    add[i] += v;
}

// 懒信息的下发
void down(int i, int ln, int rn) {
    if (add[i] != 0) {
        // 发左
        lazy(i << 1, add[i], ln);
        // 发右
        lazy(i << 1 | 1, add[i], rn);
        // 父范围懒信息清空
        add[i] = 0;
    }
}

// 范围修改
// jobl ~ jobr范围上每个数字增加jobv
void Add(int jobl, int jobr, long jobv, int l, int r, int i) {
    if (jobl <= l && r <= jobr) {
        lazy(i, jobv, r - l + 1);
    } else {
        int mid = (l + r) >> 1;
        down(i, mid - l + 1, r - mid);
        if (jobl <= mid) {
            Add(jobl, jobr, jobv, l, mid, i << 1);
        }
        if (jobr > mid) {
            Add(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);
        }
        up(i);//汇总修改数据
    }
}

// 查询累加和
long query(int jobl, int jobr, int l, int r, int i) {
    if (jobl <= l && r <= jobr) {
        return sum[i];
    }
    int mid = (l + r) >> 1;
    down(i, mid - l + 1, r - mid);
    long ans = 0;
    if (jobl <= mid) {
        ans += query(jobl, jobr, l, mid, i << 1);
    }
    if (jobr > mid) {
        ans += query(jobl, jobr, mid + 1, r, i << 1 | 1);
    }
    return ans;
}

