            cout << "NO\n";
        }
    }

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 75;
const long long INF = 1e15;

int n,K;
struct node{
    int key,weight,freq;
};
node nums[MAXN];
int val[MAXN];
int sum[MAXN];

long long dp[MAXN][MAXN][MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

bool cmp(node a,node b){
    return a.key<b.key;
}

int find(int v){
    int l=1,r=n,ans=0;
    while(l<=r){
        int mid=(l+r)>>1;
        if(val[mid]>=v){
            ans=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    return ans;
}

int main()
{
    n=read(),K=read();
    for(int i=1;i<=n;i++){
        nums[i].key=read();
    }
    for(int i=1;i<=n;i++){
        nums[i].weight=read();
        val[i]=nums[i].weight;
    }
    for(int i=1;i<=n;i++){
        nums[i].freq=read();
    }
    sort(val+1,val+n+1);
    sort(nums+1,nums+n+1,cmp);
    for(int i=1;i<=n;i++){
        sum[i]=sum[i-1]+nums[i].freq;
        nums[i].weight=find(nums[i].weight);
    }
    for(int i=1;i<=n+1;i++){
        for(int j=1;j<=n;j++){
            for(int k=1;k<=n;k++){
                dp[i][j][k]=INF;
            }
        }
    }
    for(int i=1;i<=n+1;i++){
        for(int k=1;k<=n;k++){
            dp[i][i-1][k]=0;
        }
    }
    for(int len=1;len<=n;len++){
        for(int i=1;i+len-1<=n;i++){
            int j=i+len-1;
            for(int k=1;k<=n;k++){
                for(int t=i;t<=j;t++){
                    long long cost=sum[j]-sum[i-1];

                    if(nums[t].weight>=k){
                        dp[i][j][k]=min(dp[i][j][k],dp[i][t-1][nums[t].weight]+dp[t+1][j][nums[t].weight]+cost);
                    }
                    dp[i][j][k]=min(dp[i][j][k],dp[i][t-1][k]+dp[t+1][j][k]+cost+K);
                }
            }
        }
    }
    cout<<dp[1][n][1]<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 5e5+5;

int n;
int val[MAXN];
bool root[MAXN];

int depval[MAXN];
int tot[MAXN];

int sz[MAXN];
int dep[MAXN];
int son[MAXN];
int mindep[MAXN];
int maxdep[MAXN];

int cnt=1;
int head[MAXN];
int nxt[MAXN];
int to[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

void dfs1(int u,int f){
    sz[u]=1;
    maxdep[u]=dep[u]=dep[f]+1;
    mindep[u]=n;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        dfs1(v,u);
        mindep[u]=min(mindep[u],mindep[v]);
        maxdep[u]=max(maxdep[u],maxdep[v]);
        sz[u]+=sz[v];
        if(son[u]==0||sz[v]>sz[son[u]]){
            son[u]=v;
        }
    }
    if(head[u]==0){
        mindep[u]=dep[u];
    }
}

void effect(int u,int d){
    if(dep[u]>=d){
        return ;
    }
    tot[depval[dep[u]]]--;
    depval[dep[u]]^=val[u];
    tot[depval[dep[u]]]++;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        effect(v,d);
    }
}

void cancel(int u,int d){
    if(dep[u]>=d){
        return ;
    }
    tot[depval[dep[u]]]--;
    depval[dep[u]]^=val[u];
    tot[depval[dep[u]]]++;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        cancel(v,d);
    }
}

void dfs2(int u,int keep){
    // cout<<' '<<u<<' '<<keep<<endl;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=son[u]){
            dfs2(v,0);
        }        
    }
    if(son[u]!=0){
        dfs2(son[u],1);
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=son[u]){
            effect(v,mindep[u]+2);
        }
    }
    // for(int i=mindep[u]+2;i<=maxdep[u];i++){
    //     tot[depval[i]]--;
    //     depval[i]=0;
    //     tot[0]++;
    // }
    for(int i=(mindep[u]==maxdep[u])?1:0;i<=n;i++){
        if(tot[i]<=0){
            val[u]=i;
            break;
        }
    }
    tot[depval[dep[u]]]--;
    depval[dep[u]]^=val[u];
    tot[depval[dep[u]]]++;
    if(keep==0){
        cancel(u,mindep[u]+2);
    }
}

void prepare(){
    cnt=1;
    for(int i=1;i<=n;i++){
        head[i]=0;
        root[i]=0;
        son[i]=0;
    }
    for(int i=1;i<=n;i++){
        depval[i]=0;
        tot[i]=0;
    }
}

int main()
{
    int T;
    T=read();
    while(T--){
        n=read();
        prepare();
        for(int i=1;i<=n;i++){
            int u;
            u=read();
            if(u==0){
                root[i]=true;
            }
            else{
                addedge(u,i);
            }
        }
        int ans=0;
        for(int i=1;i<=n;i++){
            if(root[i]){
                dfs1(i,0);
                dfs2(i,0);
                ans^=val[i];
            }
        }
        // cout<<ans<<endl;
        // for(int i=1;i<=n;i++){
        //     cout<<val[i]<<' ';
        // }
        // cout<<endl;
        // for(int i=1;i<=n;i++){
        //     cout<<i<<": "<<mindep[i]<<' '<<maxdep[i]<<endl;
        // }
        // cout<<endl;
        if(ans){
            printf("YES\n");
        }
        else{
            printf("NO\n");
        }
    }
    return 0;
}

