#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;

int n,m;

int fa[MAXN];
int ls[MAXN];
int rs[MAXN];
int sta[MAXN];
bool rev[MAXN];

bool isroot(int x){
    return ls[fa[x]]!=x&&rs[fa[x]]!=x;
}

int lr(int x){
    return ls[fa[x]]==x?0:1;
}

void reverse(int x){
    if(x!=0){
        swap(ls[x],rs[x]);
        rev[x]=!rev[x];
    }
}

void down(int x){
    if(rev[x]){
        reverse(ls[x]);
        reverse(rs[x]);
        rev[x]=false;
    }
}

void rotate(int x) {
   int f = fa[x], g = fa[f];
   if (lr(x) == 0) {
       ls[f] = rs[x];
       if (ls[f] != 0) {
           fa[ls[f]] = f;
       }
       rs[x] = f;
   } else {
       rs[f] = ls[x];
       if (rs[f] != 0) {
           fa[rs[f]] = f;
       }
       ls[x] = f;
   }
   if (!isroot(f)) {
       if (lr(f) == 0) {
           ls[g] = x;
       } else {
           rs[g] = x;
       }
   }
   fa[f] = x;
   fa[x] = g;
}

void splay(int x) {
   int siz = 0;
   sta[++siz] = x;
   for (int y = x; !isroot(y); y = fa[y]) {
       sta[++siz] = fa[y];
   }
   while (siz != 0) {
       down(sta[siz--]);
   }
   while (!isroot(x)) {
       int f = fa[x];
       if (!isroot(f)) {
           if (lr(x) == lr(f)) {
               rotate(f);
           } else {
               rotate(x);
           }
       }
       rotate(x);
   }
}

void access(int x){
    for(int y=0;x!=0;y=x,x=fa[x]){
        splay(x);
        rs[x]=y;
    }
}

void makeroot(int x){
    access(x);
    splay(x);
    reverse(x);
}

int findroot(int x){
    access(x);
    splay(x);
    down(x);
    while(ls[x]!=0){
        down(ls[x]);
        x=ls[x];
    }
    splay(x);
    return x;
}

void link(int x,int y){
    makeroot(x);
    if(findroot(y)!=x){
        fa[x]=y;
    }
}

void cut(int x,int y){
    makeroot(x);
    if(findroot(y)==x&&fa[y]==x&&rs[x]==y&&ls[y]==0){
        fa[y]=rs[x]=0;
    }
}

int main()
{
    cin>>n>>m;
    for(int i=1;i<=m;i++){
        string s;
        int x,y;
        cin>>s>>x>>y;
        if(s=="Connect"){
            link(x,y);
        }
        else if(s=="Destroy"){
            cut(x,y);
        }
        else{
            if(findroot(x)==findroot(y)){
                cout<<"Yes"<<endl;
            }
            else{
                cout<<"No"<<endl;
            }
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 40;

// 表示目前来到了第i位  a的进位输入是j  b的进位输入是k  是否有限制
// 从高位到低位推
int f[MAXN][2][2][2];
int a[MAXN],b[MAXN],d[MAXN];

bool check(int x,int y){
    if(x<0||x>2||y<0||y>2){
        return false;
    }
    return (x&1)==(y&1);
}

int dfs(int x,int aa,int bb,int free){
    if(x<0){
        // 最低位一定是没有进制的
        return (aa==0)&&(bb==0);
    }
    if(f[x][aa][bb][free]!=-1){
        return f[x][aa][bb][free];
    }

    int ans=0;
    int up=free?2:d[x];
    for(int v=0;v<=up;v++){
        // 枚举下一位的进位输入  也就是下一位要向这一位的进位
        for(int aaa=0;aaa<=1;aaa++){
            for(int bbb=0;bbb<=1;bbb++){
                if(check(a[x]+v+aaa-3*aa,b[x]+v+bbb-3*bb)){
                    // 检查这一位是否可以符合条件  条件是在下一位的进位输入以及这一位上d的贡献加上本身的值  减去对上一位的贡献
                    // 最终的数字是否符合条件  处于0~2并且奇偶性相同
                    ans+=dfs(x-1,aaa,bbb,free||v<d[x]);
                }
            }
        }
    }

    f[x][aa][bb][free]=ans;
    return ans;
}

signed main()
{
    int T;
    cin>>T;
    while(T--){
        int x,y,z;
        cin>>z>>x>>y;
        memset(f,-1,sizeof(f));
        for(int i=0;i<MAXN;i++){
            a[i]=x%3;
            b[i]=y%3;
            d[i]=z%3;
            x/=3,y/=3,z/=3;
        }
        // 这个位置上根本不会有数字 所以进位一定是0
        cout<<dfs(MAXN-1,0,0,0)<<endl;
    }
    return 0;
}

// 约束条件，C++版
// 你需要构造长度为n的数组arr，每个元素的值在1~k之间，数组是非递减的
// 接下来给定m个约束条件，构造方案要满足所有约束条件，约束的格式如下
// 约束 1 i x   : arr[i] != x
// 约束 2 i j x : arr[i] + arr[j] <= x
// 约束 3 i j x : arr[i] + arr[j] >= x
// 如果不存在构造方案打印-1，存在方案就打印arr，任何一种方案都可以
// n、m <= 2 * 10^4
// 2 <= k <= 10
// 测试链接 : https://www.luogu.com.cn/problem/CF1697F
// 测试链接 : https://codeforces.com/problemset/problem/1697/F
// 如下实现是C++的版本，C++版本和java版本逻辑完全一样
// 提交如下代码，可以通过所有测试用例

#include <bits/stdc++.h>

using namespace std;

const int MAXN = 20001;
const int MAXM = 2000001;
const int MAXK = 12;
const int MAXT = MAXN * MAXK * 2;
int t, n, m, k;

int id[MAXN][MAXK][2];
int cntt;

int head[MAXT];
int nxt[MAXM];
int to[MAXM];
int cntg;

int dfn[MAXT];
int low[MAXT];
int cntd;

int sta[MAXT];
int top;

int belong[MAXT];
int sccCnt;

void addEdge(int u, int v) {
    nxt[++cntg] = head[u];
    to[cntg] = v;
    head[u] = cntg;
}

void tarjan(int u) {
    dfn[u] = low[u] = ++cntd;
    sta[++top] = u;
    for (int e = head[u]; e > 0; e = nxt[e]) {
        int v = to[e];
        if (dfn[v] == 0) {
            tarjan(v);
            low[u] = min(low[u], low[v]);
        } else {
            if (belong[v] == 0) {
                low[u] = min(low[u], dfn[v]);
            }
        }
    }
    if (dfn[u] == low[u]) {
        sccCnt++;
        int pop;
        do {
            pop = sta[top--];
            belong[pop] = sccCnt;
        } while (pop != u);
    }
}

void prepare() {
    cntg = cntd = sccCnt = 0;
    for (int i = 1; i <= cntt; i++) {
        head[i] = dfn[i] = low[i] = belong[i] = 0;
    }
    cntt = 0;
    for (int i = 1; i <= n; i++) {
        for (int v = 1; v <= k + 1; v++) {
            id[i][v][0] = ++cntt;
            id[i][v][1] = ++cntt;
        }
    }
    for (int i = 1; i <= n; i++) {
        for (int v = 1; v <= k; v++) {
            addEdge(id[i][v][0], id[i][v + 1][0]);
            addEdge(id[i][v + 1][1], id[i][v][1]);
        }
    }
    for (int i = 1; i < n; i++) {
        for (int v = 1; v <= k; v++) {
            addEdge(id[i + 1][v][0], id[i][v][0]);
            addEdge(id[i][v][1], id[i + 1][v][1]);
        }
    }
    for (int i = 1; i <= n; i++) {
        addEdge(id[i][1][0], id[i][1][1]);
        addEdge(id[i][k + 1][1], id[i][k + 1][0]);
    }
}

void notEqual(int i, int x) {
    addEdge(id[i][x][1], id[i][x + 1][1]);
    addEdge(id[i][x + 1][0], id[i][x][0]);
}

void lessEqual(int i, int j, int x) {
    for (int w = 1; w <= k; w++) {
        if (w >= x) {
            notEqual(i, w);
        } else {
            if (x - w + 1 <= k) {
                addEdge(id[i][w][1], id[j][x - w + 1][0]);
                addEdge(id[j][x - w + 1][1], id[i][w][0]);
            }
        }
    }
}

void moreEqual(int i, int j, int x) {
    for (int w = 1; w <= k; w++) {
        if (w <= x - k - 1) {
            notEqual(i, w);
        } else {
            if (x - w > 1) {
                addEdge(id[i][w + 1][0], id[j][x - w][1]);
                addEdge(id[j][x - w][0], id[i][w + 1][1]);
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> t;
    for (int c = 1; c <= t; c++) {
        cin >> n >> m >> k;
        prepare();
        for (int i = 1, op, x, y, v; i <= m; i++) {
            cin >> op;
            if (op == 1) {
                cin >> x >> v;
                notEqual(x, v);
            } else if (op == 2) {
                cin >> x >> y >> v;
                lessEqual(x, y, v);
                swap(x, y);
                lessEqual(x, y, v);
            } else {
                cin >> x >> y >> v;
                moreEqual(x, y, v);
                swap(x, y);
                moreEqual(x, y, v);
            }
        }
        for (int i = 1; i <= cntt; i++) {
            if (dfn[i] == 0) {
                tarjan(i);
            }
        }
        bool check = true;
        for (int i = 1; i <= n; i++) {
            for (int v = 1; v <= k + 1; v++) {
                if (belong[id[i][v][0]] == belong[id[i][v][1]]) {
                    check = false;
                    break;
                }
            }
            if (!check) {
                break;
            }
        }
        if (check) {
            for (int i = 1; i <= n; i++) {
                for (int v = k; v >= 1; v--) {
                    if (belong[id[i][v][1]] < belong[id[i][v][0]]) {
                        cout << v << " ";
                        break;
                    }
