{
    n=read(),m=read(),limitl=read(),limitr=read();
    for(int i=1;i<=m;i++){
        val[i]=read();
    }
    for(int i=1;i<n;i++){
        int u,v,c;
        u=read(),v=read(),c=read();
        addedge(u,v,c);
        addedge(v,u,c);
    }
    build(curtree,0,n,1);
    build(pretree,0,n,1);
    cout<<solve(getcentroid(1,0))<<endl;
    return 0;
}

