    for(int &i=iter[u];i;i=nxt[i]){
        int v=to[i];
        int w=cap[i];
        int k=now[i];
        if(dep[u]+1==dep[v]&&k<w){
            int d=dfs(v,min(f,w-k));
            if(d>0){
                now[i]+=d;
                now[i^1]-=d;
                flow+=d;
                f-=d;
                if(f==0){
                    break;
                }
            }
        }
    }
    return flow;
}

int maxflow(){
    int flow=0;
    while(bfs()){
        for(int i=1;i<=t;i++){
            iter[i]=head[i];
        }
        int maxflow;
        while((maxflow=dfs(s,INF))>0){
            flow+=maxflow;
        }
    }
    return flow;
}

int id(int x,int y,int z){
    return (z-1)*p*q+(x-1)*q+y;
}

int main()
{
    scanf("%d %d %d %d",&p,&q,&r,&d);
    for(int z=1;z<=r;z++){
        for(int x=1;x<=p;x++){
            for(int y=1;y<=q;y++){
                scanf("%d",&val[x][y][z]);
            }
        }
    }

    s = p*q*(r+1)+1;
    t = s+1;
    for(int x=1;x<=p;x++){
        for(int y=1;y<=q;y++){
            addedge(s,id(x,y,1),INF);
            for(int z=1;z<=r;z++){
                addedge(id(x,y,z),id(x,y,z+1),val[x][y][z]);
            }
            addedge(id(x,y,r+1),t,INF);
        }
    }

    for(int x=1;x<=p;x++){
        for(int y=1;y<=q;y++){
            for(int i=0;i<4;i++){
