                        // 这里要注意  边的方向一定是从高层指向低层
                        // 这样才可以体现出约束
                        addedge(id(x,y,z),id(nx,ny,z-d),INF);
                        // addedge(id(x,y,d),id(nx,ny,z-d),INF);
                    }
                }
            }
        }
    }

