#include <iostream>
#include <cmath>
#include <set>
#include <algorithm>
using namespace std;

typedef long long LL;

LL gcd_binary(LL a, LL b) {
    if (a == 0) return b;
    if (b == 0) return a;
    LL shift = 0;
    while (((a | b) & 1) == 0) {
        a >>= 1;
        b >>= 1;
        shift++;
    }
    while ((a & 1) == 0) {
        a >>= 1;
    }
    do {
        while ((b & 1) == 0) {
            b >>= 1;
        }
        if (a > b) {
            swap(a, b);
        }
        b = b - a;
    } while (b != 0);
    return a << shift;
}

int main() {
    LL M, N;
    long double R;
    cin >> M >> N;
    cin >> R;

    long double min_diff = 1e30;
    LL count = 0;
    LL ans_num = 0, ans_den = 0;
    const long double eps = 1e-14;

    for (LL a = 1; a <= N; a++) {
        long double x = (long double)a * R;
        LL b1 = (LL)floor(x);
        LL b2 = (LL)ceil(x);

        set<LL> cand;
        if (b1 >= 0 && b1 <= M) {
            cand.insert(b1);
        }
        if (b2 >= 0 && b2 <= M) {
            cand.insert(b2);
        }

        for (LL b : cand) {
            long double diff = fabsl((long double)b - x) / (long double)a;
            LL g = gcd_binary(a, b);
            if (g != 1) {
                continue;
            }

            if (diff < min_diff - eps) {
                min_diff = diff;
                count = 1;
                ans_num = b;
                ans_den = a;
            } else if (fabsl(diff - min_diff) <= eps) {
                count++;
            }
        }
    }

    if (count == 1) {
        cout << ans_num << "/" << ans_den << endl;
    } else {
        cout << "TOO MANY" << endl;
    }

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;

int n,m;
int p[MAXN<<1];
int f[MAXN<<1];
int fa[MAXN];
int id[MAXN];

int head[MAXN];
int nxt[MAXN<<2];
int to[MAXN<<2];
int cnt=1;

bool ok[27];

void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

int find(int x){
    return x==fa[x]?x:fa[x]=find(fa[x]);
}

void un(int x,int y){
    int fx=find(x);
    int fy=find(y);
    if(fx!=fy){
        fa[fx]=fy;
    }
}

int main()
{
    scanf("%d",&n);
    // 读入真实回文长度数组  注意读入时的顺序
    for(int i=2;i<=2*n;i+=2){
        scanf("%d",&p[i]);
    }
    for(int i=3;i<2*n;i+=2){
        scanf("%d",&p[i]);
    }
    for(int i=1;i<=n;i++){
        fa[i]=i;
    }

    int mid=0,r=0;
    m=2*n;
    for(int i=2;i<=m;i++){
        // len是回文半径
        int len=(r>i)?min(f[2*mid-i],r-i):1;

        while(len-1<p[i]){
            // 回文半径的长度应该是真实回文长度+1
            len++;
            if((i-len+1)%2==0){
                // 对称的字母一样
                int lt=(i-len+1)/2;
                int rt=(i+len-1)/2;
                if(lt<1||rt>n){
                    break;
                }
                un(lt,rt);
            }
        }

        // 这两个字母一定不一样
        int lt=(i-len)/2;
        int rt=(i+len)/2;
        if(lt>=1&&lt<=n&&rt>=1&&rt<=n){
            addedge(lt,rt);
            addedge(rt,lt);
        }

        f[i]=len;

        if(i+len>r){
            r=i+len;
            mid=i;
        }
    }

    for(int i=1;i<=n;i++){
        int root=find(i);
        if(id[root]==0){
            for(int j=1;j<=26;j++){
                ok[j]=true;
            }
            // 注意这里 应该是查询和i不能是一个颜色的位置  不是和root不同颜色的位置
            // 因为root可能在i的后面
            // 这里其实是一个贪心算法  就是前面出现的越小越好
            for(int ei=head[i];ei;ei=nxt[ei]){
                int v=find(to[ei]);
                ok[id[v]]=false;
            }
            for(int j=1;j<=26;j++){
                if(ok[j]){
                    id[root]=j;
                    break;
                }
            }
        }
        cout<<char('a'+id[root]-1);
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 3e5+5;
const int MAXH = 22;

int n,p,q,k;

int headg[MAXN];
int nxtg[MAXN<<1];
int tog[MAXN<<1];
int cntg=1;

int headv[MAXN];
int nxtv[MAXN];
int tov[MAXN];
int cntv=1;

int dep[MAXN];
int sz[MAXN];
int dfn[MAXN];
int st[MAXN][MAXH];
int dfncnt;

int order[MAXN];
int arr[MAXN];
bool iskey[MAXN];
int tmp[MAXN<<1];

int manager[MAXN];
int dist[MAXN];
int ans[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedgeg(int u,int v){
    nxtg[cntg]=headg[u];
    tog[cntg]=v;
    headg[u]=cntg++;
}

void dfs(int u,int fa){
    dep[u]=dep[fa]+1;
    sz[u]=1;
    dfn[u]=++dfncnt;
    st[u][0]=fa;
    for(int i=1;i<=p;i++){
        st[u][i]=st[st[u][i-1]][i-1];
    }
    for(int i=headg[u];i;i=nxtg[i]){
        int v=tog[i];
        if(v!=fa){
            dfs(v,u);
            sz[u]+=sz[v];
        }
    }
}

bool cmp(int a,int b){
    return dfn[a]<dfn[b];
}

int lca(int a,int b){
    if(dep[a]<dep[b]){
        swap(a,b);
    }
    for(int i=p;i>=0;i--){
        if(dep[st[a][i]]>=dep[b]){
            a=st[a][i];
        }
    }
    if(a==b){
        return a;
    }
    for(int i=p;i>=0;i--){
        if(st[a][i]!=st[b][i]){
            a=st[a][i];
            b=st[b][i];
        }
    }
    return st[a][0];
}

inline void addedgev(int u,int v){
    nxtv[cntv]=headv[u];
    tov[cntv]=v;
    headv[u]=cntv++;
}

int buildvirtualtree(){
    sort(arr+1,arr+k+1,cmp);
    int len=0;
    tmp[++len]=1;
    for(int i=1;i<k;i++){
        tmp[++len]=arr[i];
        tmp[++len]=lca(arr[i],arr[i+1]);
    }
    tmp[++len]=arr[k];
    sort(tmp+1,tmp+len+1,cmp);

    int m=1;
    for(int i=2;i<=len;i++){
        if(tmp[i]!=tmp[i-1]){
            tmp[++m]=tmp[i];
        }
    }

    cntv=1;
    for(int i=1;i<=m;i++){
        headv[tmp[i]]=0;
    }
    for(int i=1;i<m;i++){
        addedgev(lca(tmp[i],tmp[i+1]),tmp[i+1]);
    }
    return tmp[1];
}

void dp1(int u){
    dist[u]=1e9+1;
    for(int i=headv[u];i;i=nxtv[i]){
        int v=tov[i];
        dp1(v);
        int w=dep[v]-dep[u];
        if(dist[v]+w<dist[u]||((dist[v]+w==dist[u])&&manager[v]<manager[u])){
            dist[u]=dist[v]+w;
            manager[u]=manager[v];
        }
    }
    if(iskey[u]){
        dist[u]=0;
        manager[u]=u;
    }
}

void dp2(int u){
    for(int i=headv[u];i;i=nxtv[i]){
        int v=tov[i];
        int w=dep[v]-dep[u];
        if(dist[u]+w<dist[v]||((dist[u]+w==dist[v])&&manager[u]<manager[v])){
            dist[v]=dist[u]+w;
            manager[v]=manager[u];
        }
        dp2(v);
    }
}

void amend(int u,int v){
    if(manager[u]==manager[v]){
        return ;
    }
    int x=v;
    for(int i=p;i>=0;i--){
        int jump=st[x][i];
        if(dep[u]<dep[jump]){
            int tou=dep[jump]-dep[u]+dist[u];
            int tov=dep[v]-dep[jump]+dist[v];
            if(tov<tou||(tov==tou&&manager[v]<manager[u])){
                x=jump;
            }
        }
    }
    int delta=sz[x]-sz[v];
    ans[manager[u]]-=delta;
    ans[manager[v]]+=delta;
}

void dp3(int u){
    ans[manager[u]]+=sz[u];
    for(int i=headv[u];i;i=nxtv[i]){
        int v=tov[i];
        amend(u,v);
        ans[manager[u]]-=sz[v];
        dp3(v);
    }
}

void compute(){
    for(int i=1;i<=k;i++){
        arr[i]=order[i];
    }
    for(int i=1;i<=k;i++){
        iskey[arr[i]]=1;
        ans[arr[i]]=0;
    }
    int tree=buildvirtualtree();
    dp1(tree);
    dp2(tree);
