// P4255
// 这道题非常独特的地方在于它是通过边来保存点的信息
// 比如  a号城市  有3个人信仰A  4个人信仰B  那么就是a->A 权值为3   a->B 权值为4
// 那么如果 a号城市和b号城市合并了  那么就是在连边
#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MOD = 19260817;
const int MAXN = 4e5+5;
const int MAXT = 3*MAXN;

int n,m,q;

struct Edge{
    int u,v;
}edge[MAXN];
bool ok[MAXN];//表示这条路是否可以存在

int cnt=1;
int head[MAXN];
int nxt[MAXT];
int to[MAXT];
int weight[MAXT];
map<int,int>vis[MAXN];//vis[i][j]这个含义是  对于  城市i  他的信仰为j的  边  编号是多少

struct node{
    int op,x,n,c;
}nums[MAXN];

int sz[MAXN];
int fa[MAXN];

stack<int>ans;

int fac[MAXN*10];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

int power(int a,int b){
    long long ans=1;
    while(b){
        if(b&1){
            ans=(ans*a)%MOD;
        }
        b>>=1;
        a=(a*a)%MOD;
    }
    return (int)ans;
}

inline void addedge(int u,int v,int w){
    int num=vis[u][v];//表示是否有过u城市和信仰v的连边
    if(num==0){
        vis[u][v]=cnt;

        nxt[cnt]=head[u];
        to[cnt]=v;
        weight[cnt]=w;
        head[u]=cnt++;
    }
    else{
        weight[num]+=w;
    }
}

int find(int x){
    return x==fa[x]?x:fa[x]=find(fa[x]);
}

void un(int x,int y){
    int fx=find(x);
    int fy=find(y);
    if(fx==fy){
        return ;
    }
    if(vis[fx].size()>vis[fy].size()){
        swap(fx,fy);//启发式合并  种类少的给到种类多的中去
    }
    for(int i=head[fx];i;i=nxt[i]){
        addedge(fy,to[i],weight[i]);
    }
    sz[fy]+=sz[fx];
    fa[fx]=fy;
}

int query(int x,int num,int c){
    long long res=1;
    int all=sz[x];
    c=vis[x][c];
    if(weight[c]<num){
        return 15578602;
    }
    int need=weight[c];
    // cout<<' '<<all<<' '<<need<<' '<<num<<endl;
    int t1=(long long)(fac[need]*fac[all-num])%MOD;
    int t2=(long long)(fac[need-num]*fac[all])%MOD;
    res=t1*power(t2,MOD-2);
    res=(res%MOD+MOD)%MOD;
    return (int)res;
}

