    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    head[u]=cnt++;
}

bool cmp(node a,node b){
    return a.w>b.w;
}

int find(int x){
    return x==fa[x]?x:fa[x]=find(fa[x]);
}

void dfs(int u,int fa){
    // cout<<u<<' '<<fa<<endl;
    dep[u]=dep[fa]+1;
    for(int i=1;i<MAXH;i++){
        st[u][i]=st[st[u][i-1]][i-1];
        dis[u][i]=min(dis[u][i-1],dis[st[u][i-1]][i-1]);
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        int w=weight[i];
        if(v==fa){
            continue;
        }
        st[v][0]=u;
        dis[v][0]=w;
        dfs(v,u);
    }
}

int lca(int a,int b){
    if(dep[a]<dep[b]){
        swap(a,b);
    }
    for(int i=MAXH-1;i>=0;i--){
        if(dep[st[a][i]]>=dep[b]){
            a=st[a][i];
        }
    }
    if(a==b){
        return a;
    }
    for(int i=MAXH-1;i>=0;i--){
        if(st[a][i]!=st[b][i]){
            a=st[a][i];
            b=st[b][i];
        }
    }
    return st[a][0];
}

int query(int s,int d){
    // cout<<"   "<<s<<' '<<d<<' ';
    if(s==d){
        // cout<<INF<<endl;
        return INF;
    }
    int ans=INF;
    for(int i=MAXH-1;i>=0;i--){
        if(dep[st[s][i]]>dep[d]){
            ans=min(ans,dis[s][i]);
            s=st[s][i];
        }
    }
    ans=min(ans,dis[s][0]);
    // cout<<ans<<endl;
    return ans;
}

