                    ans=(ans+f[x+1][1][1]*base%MOD)%MOD;
                    ans=(ans+f[x+1][1][0]*((2*k-b+1)*b/2%MOD)%MOD)%MOD;
                    ans=(ans+f[x+1][0][1]*((a+1)*a/2%MOD)%MOD)%MOD;
                    if(a>b){
                        ans=(ans+((a*2-b+1)*b/2%MOD)*f[x+1][0][0]%MOD)%MOD;
                    }
                    else {
