                    }
                    ans=(ans+(k-b)*f[x+1][1][0])%MOD;
                }
                else if(!free1&&free2){
                    if(a>b-1){
                        ans=(ans+b*f[x+1][0][0]%MOD)%MOD;
                    }
                    else{
                        ans=(ans+(a+1)*f[x+1][0][0]%MOD)%MOD;
                    }
                    ans=(ans+(a+1)*f[x+1][0][1]%MOD)%MOD;
                }
                else{
                    if(a>=b){
                        ans=1*f[x+1][0][0];
                    }
                    else{
                        ans=0;
                    }
                }

                f[x][free1][free2]=ans;
            }
        }
    }
    return (f[1][0][0]+f[1][1][0]+f[1][0][1]+f[1][1][1])%MOD;
}

