void calcnext(){
    nxt[1]=0;
    for(int i=2,j=0;i<=m;i++){
        // 当不匹配时，通过next数组回溯
        while(j>0&&b[i]!=b[j+1]){
            j=nxt[j];
        }
        // 如果当前字符匹配，j增加
        if(b[i]==b[j+1]){
            j++;
        }
        // 设置当前位置的next值
        nxt[i]=j;
    }
}

int comb(int a,int b){
    if(b<0||a<b){
        return 0;
    }
    return fac[a]*inv[b]%MOD*inv[a-b]%MOD;
}

void kmp(){
    for(int i=1,j=0;i<=len;i++){
        // 当不匹配时，通过next数组回溯
        while(j>0&&c[i]!=b[j+1]){
