    build(1,n,1);
    long long ans=0;
    for(int i=1;i<=n;i++){
        update(1,n,-1,1,n,1);

        while(top1&&val[st1[top1]]<val[i]){
            int pos=st1[top1];
            top1--;
            int lt=st1[top1]+1;
            update(lt,pos,val[i]-val[pos],1,n,1);
        }
        st1[++top1]=i;

        while(top2&&val[st2[top2]]>val[i]){
            int pos=st2[top2];
            top2--;
            int lt=st2[top2]+1;
            update(lt,pos,val[pos]-val[i],1,n,1);
        }
        st2[++top2]=i;

        ans+=query(1,i,1,n,1);
    }
    cout<<ans<<endl;
    return 0;
}

