int query(int u,int v){
    if(u==v){
        return 0;
    }
    int ans=0;
    for(int i=MAXH-1;i>=0;i--){
        if(r[u][i]>=v){
            continue;
        }
        ans+=(1<<i);
        u=r[u][i];
    }
    ans++;
    return ans;
}

int main()
{
