        if(s[i]=='L'){
            cnt++;
        }
        else{
            r[now][0]=cnt;
            now++;
        }
    }
    cnt=n+1,now=n;
    for(int i=2*n;i>=1;i--){
        if(s[i]=='R'){
            cnt--;
        }
        else{
            l[now][0]=cnt;
            now--;
        }
    }

    for(int i=1;i<=n;i++){
        sum[i]=sum[i-1]+t[i]-'0';
    }
    for(int i=1;i<=n;i++){
        sr[i][0]=sum[r[i][0]];
        sl[i][0]=sum[l[i][0]-1];
    }

    for(int k=1;k<MAXH;k++){
        for(int i=1;i<=n;i++){
            l[i][k]=l[l[i][k-1]][k-1];
            r[i][k]=r[r[i][k-1]][k-1];
