        }
    }
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            row[i][j]=row[i][j-1]+val[i][j];
            col[i][j]=col[i-1][j]+val[i][j];
        }
    }

    for(int i=1;i<=n;i++){
