                ans=min(ans,n-len+m);
                flag=true;
                break;
            }
            if(row[l][q]-row[l][p-1]<=k){
                f[l+1][r][0]=p;
                f[l+1][r][1]=q;
            }
            if(row[r][q]-row[r][p-1]<=k){
                f[l][r-1][0]=p;
                f[l][r-1][1]=q;
            }
        }
        if(flag){
            break;
        }
    }

    for(int i=1;i<=m;i++){
        for(int j=i;j<=m;j++){
            f[i][j][0]=0;
            f[i][j][1]=n;
