            if(col[q][l]-col[p-1][l]<=k){
                f[l+1][r][0]=p;
                f[l+1][r][1]=q;
            }
            if(col[q][r]-col[p-1][r]<=k){
                f[l][r-1][0]=p;
                f[l][r-1][1]=q;
            }
