#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int MAXT = 30*MAXN;

int n,m,maxdep;

int tot;
map<string,int>nameid;
bool rooted[MAXN];
int id[MAXN];

int dep[MAXN];

int head[MAXN];
int nxt[MAXN];
int to[MAXN];
int cnt=1;

int headq[MAXN];
int nxtq[MAXN];
int toq[MAXN];
int idq[MAXN];
int cntq=1;

int ans[MAXN];

int root[MAXN];
int ls[MAXT];
int rs[MAXT];
set<int>st[MAXT];
int cntv;

inline int getnameid(string s){
    int k=nameid[s];
    if(k!=0){
        return k;
    }
    else{
        nameid[s]=++tot;
        return tot;
    }
}

inline void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

inline void addquestion(int u,int v,int i){
    nxtq[cntq]=headq[u];
    toq[cntq]=v;
    idq[cntq]=i;
    headq[u]=cntq++;
}

void dfs(int u,int fa){
    dep[u]=dep[fa]+1;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        dfs(v,u);
    }
}

int add(int pos,int jobv,int l,int r,int i){
    int rt=i;
    if(rt==0){
        rt=++cntv;
    }
    if(l==r){
        st[rt].insert(jobv);
    }
    else{
        int mid=(l+r)>>1;
        if(pos<=mid){
            ls[rt]=add(pos,jobv,l,mid,ls[rt]);
        }
        else{
            rs[rt]=add(pos,jobv,mid+1,r,rs[rt]);
        }
    }
    return rt;
}

int merge(int l,int r,int t1,int t2){
    if(t1==0||t2==0){
        return t1+t2;
    }
    if(l==r){
        if(st[t1].size()<st[t2].size()){
            swap(t1,t2);
        }
        for(auto it:st[t2]){
            st[t1].insert(it);
        }
    }
    else{
        int mid=(l+r)>>1;
        ls[t1]=merge(l,mid,ls[t1],ls[t2]);
        rs[t1]=merge(mid+1,r,rs[t1],rs[t2]);
    }
    return t1;
}

int query(int pos,int l,int r,int i){
    if(i==0){
        return 0;
    }
    if(l==r){
        return st[i].size();
    }
    else{
        int mid=(l+r)>>1;
        if(pos<=mid){
            return query(pos,l,mid,ls[i]);
        }
        else{
            return query(pos,mid+1,r,rs[i]);
        }
    }
}

void dfs(int u){
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        dfs(v);
        root[u]=merge(1,maxdep,root[u],root[v]);
    }
    for(int i=headq[u];i;i=nxtq[i]){
        int v=toq[i];
        int id=idq[i];
        if(dep[u]+v>maxdep){
            ans[id]=0;
        }
        else{
            ans[id]=query(dep[u]+v,1,maxdep,root[u]);
        }
    }
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);
    cin>>n;
    string name;
    int fa;
    for(int i=1;i<=n;i++){
        cin>>name>>fa;
        id[i]=getnameid(name);
        if(fa==0){
            rooted[i]=true;
        }
        else{
            addedge(fa,i);
        }
    }
    maxdep=0;
    for(int i=1;i<=n;i++){
        if(rooted[i]){
            dfs(i,0);
        }
        maxdep=max(maxdep,dep[i]);
    }
    for(int i=1;i<=n;i++){
        root[i]=add(dep[i],id[i],1,maxdep,root[i]);
    }
    cin>>m;
    for(int i=1;i<=m;i++){
        int u,k;
        cin>>u>>k;
        addquestion(u,k,i);
    }
    for(int i=1;i<=n;i++){
        if(rooted[i]){
            dfs(i);
        }
    }
    for(int i=1;i<=m;i++){
        cout<<ans[i]<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 205;
const int MAXM = 4005;
const int INF = 1e12;

int n,m,s,t,x;

int dep[MAXN];//记录深度数组
int iter[MAXN];//当前弧数组 记录这个节点有效访问的第一条边的编号

//这里编号从2开始 为了正反边编号寻找方便
int cnt=2;
int head[MAXN];
int nxt[MAXM];
int to[MAXM];
int now[MAXM];//表示现在的流量
int weight[MAXM];//表示流量限制

void addedge(int u,int v,int k,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    now[cnt]=k;
    weight[cnt]=w;
    head[u]=cnt++;
}

//BFS构建分层图，并判断是否存在增广路径
bool bfs(){
    for(int i=1;i<=n;i++){
        dep[i]=-1;
    }
    queue<int>q;
    dep[s]=0;
    q.push(s);
    while(!q.empty()){
        int u=q.front();
        q.pop();
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            int w=weight[i];
            int k=now[i];
            if(dep[v]<0&&(k<w)){
                dep[v]=dep[u]+1;
                q.push(v);
            }
        }
    }
    return dep[t]>=0;// 如果汇点未被访问到，说明无增广路径
}

// DFS寻找增广路径（多路增广）
//多路增广的含义是来到了一个节点 不仅仅是只去一条边增广  而是去多条边一起增广
int dfs(int u,int f){
    //表示当前来到了u节点 有f的流量可供使用  这条路就是最多可以消耗掉f的流量
    if(u==t){
        return f;
    }
    int flow=0;
    for(int&i=iter[u];i;i=nxt[i]){
        //注意这里是引用  iter会随着i发生变化
        int v=to[i];
        int w=weight[i];
        int k=now[i];
        if(dep[u]+1==dep[v]&&k<w){
            int d=dfs(v,min(f,w-k));
            if(d>0){
                now[i]+=d;
                now[i^1]-=d;//更新反向边
                flow+=d;
                f-=d;
                if(f==0){
                    break;
                }
            }
        }
    }
    return flow;
}

// Dinic算法主函数
int maxflow(){
    int flow=0;
    while(bfs()){
        //当前弧全部初始化为最初值
        for(int i=1;i<=n;i++){
            iter[i]=head[i];
        }
        int maxflow;
        while((maxflow=dfs(s,INF))>0){
            flow+=maxflow;
        }
    }
    return flow;
}

signed main()
{
    cin>>n>>m>>x;
    s=1,t=n;
    for(int i=1;i<=m;i++){
        int u,v,w;
        cin>>u>>v>>w;
        addedge(u,v,0,w);
        addedge(v,u,0,0);
    }
    int ans=maxflow();
    if(ans==0){
        cout<<"Orz Ni Jinan Saint Cow!"<<endl;
        return 0;
    }
    cout<<ans<<' '<<((x+ans-1)/ans)<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 4e4+5;
const int MAXB = 205;

int n,m;
int val[MAXN];
int len;
int sortv[MAXN];

int blen,bnum;
int bi[MAXN];
int bl[MAXB];
int br[MAXB];

int freq[MAXB][MAXN];
int mode[MAXB][MAXB];
int numcnt[MAXN];

int find(int val){
    int l=1,r=len,ans=0;
    while(l<=r){
        int mid=(l+r)>>1;
        if(sortv[mid]>=val){
            ans=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    return ans;
}

int getcnt(int l,int r,int val){
    return freq[r][val]-freq[l-1][val];
}

void prepare(){
    blen=sqrt(n);
    bnum=(n+blen-1)/blen;
    for(int i=1;i<=n;i++){
        bi[i]=(i-1)/blen+1;
    }
    for(int i=1;i<=bnum;i++){
        bl[i]=(i-1)*blen+1;
        br[i]=min(n,i*blen);
    }

    for(int i=1;i<=n;i++){
        sortv[i]=val[i];
    }
    sort(sortv+1,sortv+n+1);
    len=1;
    for(int i=2;i<=n;i++){
        if(sortv[i]!=sortv[i-1]){
            sortv[++len]=sortv[i];
        }
    }
    for(int i=1;i<=n;i++){
        val[i]=find(val[i]);
    }

    for(int i=1;i<=n;i++){
        freq[bi[i]][val[i]]++;
    }
    for(int i=1;i<=bnum;i++){
        for(int j=1;j<=len;j++){
            freq[i][j]+=freq[i-1][j];
        }
    }

    for(int i=1;i<=bnum;i++){
        for(int j=i;j<=bnum;j++){
            int most=mode[i][j-1];
            int mostcnt=getcnt(i,j,most);
            for(int k=bl[j];k<=br[j];k++){
                int cnt=getcnt(i,j,val[k]);
                if(cnt>mostcnt||mostcnt==cnt&&val[k]<most){
                    most=val[k];
                    mostcnt=cnt;
                }
            }
            mode[i][j]=most;
        }
    }
}

int compute(int l,int r){
    int lb=bi[l];
    int rb=bi[r];
    int most=len+1;
    int mostcnt=0;
    if(lb==rb){
        for(int i=l;i<=r;i++){
            numcnt[val[i]]++;
            if(numcnt[val[i]]>mostcnt){
                most=val[i];
                mostcnt=numcnt[val[i]];
            }
            else if(numcnt[val[i]]==mostcnt&&most>val[i]){
                most=val[i];
            }
        }
        for(int i=l;i<=r;i++){
            numcnt[val[i]]=0;
        }
    }
    else{
        for (int i = l; i <= br[bi[l]]; i++) {
            numcnt[val[i]]++;
        }
        for (int i = bl[bi[r]]; i <= r; i++) {
            numcnt[val[i]]++;
        }
        most=mode[lb+1][rb-1];
        mostcnt=getcnt(lb+1,rb-1,most)+numcnt[most];
        for (int i = l; i <= br[bi[l]]; i++) {
            int cur = val[i];
            int curCnt = getcnt(bi[l] + 1, bi[r] - 1, cur) + numcnt[cur];
            if (curCnt > mostcnt || (curCnt == mostcnt && cur < most)) {
                most = cur;
                mostcnt = curCnt;
            }
        }
        //枚举右散块
        for (int i = bl[bi[r]]; i <= r; i++) {
            int cur = val[i];
            int curCnt = getcnt(bi[l] + 1, bi[r] - 1, cur) + numcnt[cur];
            if (curCnt > mostcnt || (curCnt == mostcnt && cur < most)) {
                most = cur;
                mostcnt = curCnt;
            }
        }
        for (int i = l; i <= br[bi[l]]; i++) {
            numcnt[val[i]]=0;
        }
        for (int i = bl[bi[r]]; i <= r; i++) {
            numcnt[val[i]]=0;
        }
    }
    return most;
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m;
    for(int i=1;i<=n;i++){
        cin>>val[i];
    }
    prepare();
    int ans=0;
    for(int i=1;i<=m;i++){
        int l,r;
        cin>>l>>r;
        l=(l+ans-1)%n+1;
        r=(r+ans-1)%n+1;
        if(l>r){
            swap(l,r);
        }
        ans=sortv[compute(l,r)];
        cout<<ans<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 405;
const int MAXM = 14005;
const int INF = 0x3f3f3f3f;

int st,en,n,m;

int col[MAXN];      // 0:蓝色, 1:紫色
int remain[MAXN];   // 初始颜色剩余时间
int blue[MAXN];     // 蓝色持续时间
int pruple[MAXN];   // 紫色持续时间
int all[MAXN];      // 总周期时间

int head[MAXN];
int nxt[MAXM<<1];
int to[MAXM<<1];
int weight[MAXM<<1];  // 修正：应该是MAXM而不是MAXN
int cnt=1;

// 距离数组，存储到达每个节点的最短时间
int dist[MAXN];

// 优先队列元素
struct Node {
    int id, time;
    bool operator>(const Node& other) const {
        return time > other.time;
    }
};

inline void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    head[u]=cnt++;
}

int getcolor(int x,int t){
    // 如果还在初始颜色的剩余时间内
    if(t < remain[x]){
        return col[x];
    }

    // 计算进入周期循环后的时间
    int cyc = t - remain[x];
    int res = cyc % all[x];

    if(col[x] == 0){ // 初始为蓝色
        // 蓝色 -> 紫色 -> 蓝色循环
        if(res < pruple[x]){
            return 1; // 紫色时间段
        } else {
            return 0; // 蓝色时间段
        }
    } else { // 初始为紫色
        // 紫色 -> 蓝色 -> 紫色循环
        if(res < blue[x]){
            return 0; // 蓝色时间段
        } else {
            return 1; // 紫色时间段
        }
    }
}

int gettime(int x,int y,int t){
    int maxwait = 2 * max(all[x], all[y]);

    // 遍历所有可能的等待时间
    for(int wait = 0; wait <= maxwait; wait++){
        int current_time = t + wait;
        if(getcolor(x, current_time) == getcolor(y, current_time)){
            return wait;
        }
    }

    return INF; // 无法等到相同颜色
}

void dijkstra(){
    // 初始化距离数组
    memset(dist, 0x3f, sizeof(dist));
    dist[st] = 0;

    // 优先队列（最小堆）
    priority_queue<Node, vector<Node>, greater<Node>> pq;
    pq.push({st, 0});

    while(!pq.empty()){
        Node current = pq.top();
        pq.pop();

        int u = current.id;
        int current_time = current.time;

        // 如果当前时间不是最短时间，跳过
        if(current_time > dist[u]){
            continue;
        }

        // 如果到达终点，可以提前结束
        if(u == en){
            break;
        }

        // 遍历所有邻接边
        for(int i = head[u]; i; i = nxt[i]){
            int v = to[i];
            int travel_time = weight[i];

            // 计算等待时间
            int wait_time = gettime(u, v, current_time);

            if(wait_time != INF){
                int new_time = current_time + wait_time + travel_time;

                if(new_time < dist[v]){
                    dist[v] = new_time;
                    pq.push({v, new_time});
                }
            }
        }
    }
}

int main()
{
    cin >> st >> en >> n >> m;

    // 读取节点信息
    for(int i = 1; i <= n; i++){
        char c;
        cin >> c >> remain[i] >> blue[i] >> pruple[i];
        col[i] = (c == 'B') ? 0 : 1;  // B->0, P->1
        all[i] = blue[i] + pruple[i];
    }

    // 读取边信息并建图
    for(int i = 1; i <= m; i++){
        int u, v, w;
        cin >> u >> v >> w;
        addedge(u, v, w);
        addedge(v, u, w);  // 无向图，双向添加
    }

    // 运行Dijkstra算法
    dijkstra();

    // 输出结果
    if(dist[en] == INF){
        cout << 0 << endl;
    } else {
        cout << dist[en] << endl;
    }

    return 0;
}

#include<bits/stdc++.h>
using namespace std;

int m,n;
int dp[105][1005];

int power(int a,int b,int mod){
    int ans=1;
    while(b>0){
        if(b&1){
            ans=(ans*a)%mod;
        }
        a=(a*a)%mod;//a每次相当于倍增  只有b的这一位上有1的时候 才会将a乘进ans中
        b>>=1;//b想右移动一位
    }
    return ans;
}

