int dfncnt;
int dfn[MAXN];
int low[MAXN];
int sta[MAXN];
int top;

int edgecnt[MAXN];
int cntc;

int cyclecnt[MAXN];

string ans;

inline void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

void multiply(int x) {
    int carry = 0;
    for (int i = ans.size() - 1; i >= 0; i--) {
        int cur = (ans[i] - '0') * x + carry;
        ans[i] = cur % 10 + '0';
        carry = cur / 10;
    }
    string pre = "";
    while (carry > 0) {
        pre += carry % 10 + '0';
        carry /= 10;
    }
    reverse(pre.begin(), pre.end());
    ans = pre + ans;
}

void tarjan(int u,int preedge){
    dfn[u]=low[u]=++dfncnt;
    sta[++top]=u;
    for(int i=head[u];i;i=nxt[i]){
        if((i^1)==preedge){
            continue;
        }
        int v=to[i];
        if(dfn[v]==0){
            tarjan(v,i);
            if(low[v]<dfn[u]){
                low[u]=min(low[u],low[v]);
                cyclecnt[u]++;
            }
            else if(low[v]>dfn[u]){
                top--;
            }
            else{
                cntc++;
                edgecnt[cntc]=1;
                int pop;
                do{
                    pop=sta[top--];
                    edgecnt[cntc]++;
                }while(pop!=v);
            }
        }
        else if(dfn[v]<dfn[u]){
            // 这里表示的是合围成环前的最后一个节点 下一个节点就是入环顶点了
            low[u]=min(low[u],dfn[v]);
            cyclecnt[u]++;
        }
    }
}

