}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 5e5+5;

int n, m, w;
int val[MAXN];
set<int> pos[MAXN];
int tree[MAXN<<2];

inline int read() {
    int x=0, f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9') {
        if(ch=='-') f=-1;
        ch=getchar();
    }
    while(ch>='0'&&ch<='9') {
        x=x*10+ch-'0';
        ch=getchar();
    }
    return x*f;
}

void up(int i) {
    tree[i] = max(tree[i<<1], tree[i<<1|1]);
}

void build(int l, int r, int i) {
    if(l == r) {
        tree[i] = 0;
    } else {
        int mid = (l + r) >> 1;
        build(l, mid, i<<1);
        build(mid+1, r, i<<1|1);
        up(i);
    }
}

void update(int pos, int jobv, int l, int r, int i) {
    if(l == r) {
        tree[i] = jobv;
    } else {
        int mid = (l + r) >> 1;
        if(pos <= mid) {
            update(pos, jobv, l, mid, i<<1);
        } else {
            update(pos, jobv, mid+1, r, i<<1|1);
        }
        up(i);
    }
}

int query(int jobl, int jobr, int l, int r, int i) {
    if(jobl <= l && r <= jobr) {
        return tree[i];
    } else {
        int mid = (l + r) >> 1;
        int ans = 0;
        if(jobl <= mid) {
            ans = max(ans, query(jobl, jobr, l, mid, i<<1));
        }
        if(jobr > mid) {
            ans = max(ans, query(jobl, jobr, mid+1, r, i<<1|1));
        }
        return ans;
    }
}

int get_pre(int i) {
    int v = val[i];
    int need = w - v;
    if (need < 0 || need > w) return 0;

    int k = 0;
    auto it_v = pos[v].lower_bound(i);
    if (it_v != pos[v].begin()) {
        it_v--;
        k = *it_v;
    }

    int j = 0;
    auto it_need = pos[need].lower_bound(i);
    if (it_need != pos[need].begin()) {
        it_need--;
        j = *it_need;
    }

    if (j == 0) return 0;
    if (j >= k) return j;
    else return 0;
}

int main() {
    n = read(), m = read(), w = read();
    for (int i = 1; i <= n; i++) {
        val[i] = read();
    }

    build(1, n, 1);

    for (int i = 1; i <= n; i++) {
        int pre_val = get_pre(i);
        update(i, pre_val, 1, n, 1);
        pos[val[i]].insert(i);
    }

    int cnt = 0;
    for (int i = 1; i <= m; i++) {
        int op, x, y;
        op = read(), x = read(), y = read();
        if (op == 1) {
            int old_val = val[x];
            int new_val = y;
            set<int> affected;
            affected.insert(x);

            auto it = pos[old_val].upper_bound(x);
            if (it != pos[old_val].end()) {
                affected.insert(*it);
            }

            it = pos[w - old_val].upper_bound(x);
            if (it != pos[w - old_val].end()) {
                affected.insert(*it);
            }

            pos[old_val].erase(x);
            val[x] = new_val;
            pos[new_val].insert(x);

            it = pos[new_val].upper_bound(x);
            if (it != pos[new_val].end()) {
                affected.insert(*it);
            }

            it = pos[w - new_val].upper_bound(x);
            if (it != pos[w - new_val].end()) {
                affected.insert(*it);
            }

            for (int p : affected) {
                int new_pre = get_pre(p);
                update(p, new_pre, 1, n, 1);
            }
        } else {
            int l = x ^ cnt;
            int r = y ^ cnt;
            if (l > r) swap(l, r);
            if (l < 1) l = 1;
            if (r > n) r = n;
            int max_pre = query(l, r, 1, n, 1);
            if (max_pre >= l) {
                printf("Yes\n");
                cnt++;
            } else {
                printf("No\n");
            }
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ull = unsigned long long;
using ll = long long;

const int MAXK = 1000000 + 5;

// 最多需要存：删除点 k + BFS 访问点 n*k
// n*k <= 5e6，k <= 1e6，所以开 6e6 多一点
const int MAXNODE = 6000000 + 10;

// 哈希桶数量，取一个较大的质数，减少冲突
const int MOD = 3000017;

int n, m;
ull st, en;
ull blocked[MAXK];

// 链式哈希表
struct HashTable {
    ull val[MAXNODE];
    int nxt[MAXNODE];
    int head[MOD];
    int tot;

    void clear() {
        tot = 0;
        memset(head, 0, sizeof(head));
    }

    int get_hash(ull x) {
        // 混合一下，避免低位冲突严重
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return x % MOD;
    }

    bool find(ull x) {
        int h = get_hash(x);
        for (int i = head[h]; i; i = nxt[i]) {
            if (val[i] == x) return true;
        }
        return false;
    }

    void insert(ull x) {
        int h = get_hash(x);
        ++tot;
        val[tot] = x;
        nxt[tot] = head[h];
        head[h] = tot;
    }
} hsh;

// 读入一个 01 串，并转成整数
ull read01() {
    string s;
    cin >> s;

    ull x = 0;
    for (char c : s) {
        x = (x << 1) | (c - '0');
    }

    return x;
}

// bfs(start, target) 返回 true 表示：
// 1. 直接搜到了 target
// 2. 或者搜到超过 n*m 个点，说明 start 在唯一大连通块中
bool bfs(ull start, ull target) {
    if (start == target) return true;

    hsh.clear();

    // 先把删除点放进哈希表
    for (int i = 1; i <= m; i++) {
        hsh.insert(blocked[i]);
    }

    static ull q[MAXNODE];

    int head = 0, tail = 0;
    q[tail++] = start;
    hsh.insert(start);

    ll cnt = 1;
    ll limit = 1LL * n * m;

    while (head < tail) {
        ull u = q[head++];

        for (int i = 0; i < n; i++) {
            ull v = u ^ (1ULL << i);

            if (v == target) {
                return true;
            }

            if (hsh.find(v)) {
                continue;
            }

            hsh.insert(v);
            q[tail++] = v;
            cnt++;

            if (cnt > limit) {
                return true;
            }
        }
    }

    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;

    st = read01();
    en = read01();

    for (int i = 1; i <= m; i++) {
        blocked[i] = read01();
    }

    if (bfs(st, en) && bfs(en, st)) {
        cout << "TAK\n";
    } else {
        cout << "NIE\n";
    }

    return 0;
}

