		for(int i=1;i<=n;++i){
			b^=B[i];//数组B为记录差分的数组
			if(!(A[i]^b)){//若当前位置为0
				if(i+len-1>n){
                    flag=0;
                    break;
                }
				b^=1,B[i+len]^=1;
				++cnt;
			}
		}
		if(flag){
            if(cnt<mincnt)
                mincnt=cnt,anslen=len;
        }
	}
	cout<<anslen<<' '<<mincnt;
}

