#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 400050;

int rec[MAXN][4];
struct Line{
    int a1,a2,a3,a4;
}line[MAXN];
//y的数据需要离散化
int ysort[MAXN];
// 线段树某范围总长度
int length[MAXN << 2];
// 线段树某范围覆盖长度
int cover[MAXN << 2];
// 线段树某范围覆盖次数
int times[MAXN << 2];

int prepare(int n) {
    sort(ysort+1,ysort+ n + 1);
    int m = 1;
    for (int i = 2; i <= n; i++) {
        if (ysort[m] != ysort[i]) {
            ysort[++m] = ysort[i];
        }
    }
    ysort[m + 1] = ysort[m];//加一个数据防止越界
    return m;
}
//实现元素的去重

int Rank(int n, int num) {
    int ans = 0;
    int l = 1, r = n, mid;
    while (l <= r) {
        mid = (l + r) >> 1;
        if (ysort[mid] >= num) {
            ans = mid;
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }
    return ans;
}
//二分法求出对应下标

void build(int l, int r, int i) {
    if (l < r) {
        int mid = (l + r) >> 1;
        build(l, mid, i << 1);
        build(mid + 1, r, i << 1 | 1);
    }
    length[i] = ysort[r + 1] - ysort[l];
    times[i] = 0;
    cover[i] = 0;
}

void up(int i) {
    if (times[i] > 0) {
        cover[i] = length[i];
    } else {
        cover[i] = cover[i << 1] + cover[i << 1 | 1];
    }
}

// 这个题的特殊性在于
// 1) 查询操作永远查的是整个范围，不会有小范围的查询，每次都返回cover[1]
// 2) 增加操作之后，后续一定会有等规模的减少操作
// 根据以上两点分析出不需要懒更新机制
// 首先当一次修改完成从下往上返回时，up方法能保证最上方的cover[1]是修改正确的
// 同时任何一次增加操作所涉及的线段树范围，后续一定能被等规模的减少操作取消掉
// 课上重点图解这个特殊性
void add(int jobl, int jobr, int jobv, int l, int r, int i) {
    if (jobl <= l && r <= jobr) {
        times[i] += jobv;
    } else {
        int mid = (l + r) >> 1;
        if (jobl <= mid) {
            add(jobl, jobr, jobv, l, mid, i << 1);
        }
        if (jobr > mid) {
            add(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);
        }
    }
    up(i);
}

bool cmp(Line a,Line b){
    return a.a1<b.a1;
}

long compute(int n) {
    for (int i = 1, j = 1 + n, x1, y1, x2, y2; i <= n; i++, j++) {
        x1 = rec[i][0]; y1 = rec[i][1]; x2 = rec[i][2]; y2 = rec[i][3];
        ysort[i] = y1; ysort[j] = y2;
        line[i].a1 = x1; line[i].a2 = y1; line[i].a3 = y2; line[i].a4 = 1;//开始位置 起止位置 效果
        line[j].a1 = x2; line[j].a2 = y1; line[j].a3 = y2; line[j].a4 = -1;
        //一个矩形两条线
    }
    n <<= 1;
    int m = prepare(n);
    build(1, m, 1);
    sort(line+1,line+ n + 1,cmp);
    long ans = 0;
    for (int i = 1, pre = 0; i <= n; i++) {
        ans += (long) cover[1] * (line[i].a1 - pre);
        //每一发生变化的时候都计算一下上一个区域（可能是多个矩形）所产生的面积  即长乘宽
        //即结算操作  表示这个范围有多少被覆盖
        //pre是上一次的左边
        //这个cover[1]是此时总的覆盖长度
        pre = line[i].a1;
        add(Rank(m, line[i].a2), Rank(m, line[i].a3) - 1, line[i].a4, 1, m, 1);
        // 区间的加操作
    }
    return ans;
}

signed main()
{
    int n,k;
    cin>>k>>n;
    int prex=0,prey=0;
    rec[1][0]=0;
    rec[1][1]=0;
    rec[1][2]=k;
    rec[1][3]=k;
    for (int i = 2; i <= n+1; i++) {
        char op;
        int v;
        cin>>op>>v;
        if(op=='W'){
            rec[i][2]=prex;
            rec[i][3]=prey+k;
            prex-=v;
            rec[i][0]=prex;
            rec[i][1]=prey;
        }
        else if(op=='E'){
            rec[i][0]=prex+k;
            rec[i][1]=prey;
            prex+=v;
            rec[i][2]=prex+k;
            rec[i][3]=prey+k;
        }
        else if(op=='N'){
            rec[i][0]=prex;
            rec[i][1]=prey+k;
            prey+=v;
            rec[i][2]=prex+k;
            rec[i][3]=prey+k;
        }
        else{
            rec[i][2]=prex+k;
            rec[i][3]=prey;
            prey-=v;
            rec[i][0]=prex;
            rec[i][1]=prey;
        }
    }
    cout<<compute(n+1);
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int MAXM = 3e5+5;
const int LIMIT = 17;

int n,m,q;
struct node{
    int u,v,w;
}nums[MAXM];

int deep[MAXN];
int fa[MAXN];
bool vis[MAXN];

int st[MAXN][LIMIT+1];
int val[MAXN][LIMIT+1];

int cnt=1;
int head[MAXN];
int Next[MAXN<<1];
int to[MAXN<<1];
int weight[MAXN<<1];

inline void addedge(int u,int v,int w){
    Next[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    head[u]=cnt++;
}

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

bool cmp(node a,node b){
    return a.w>b.w;
}

int find(int x){
    return x==fa[x]?x:fa[x]=find(fa[x]);
}

void un(int x,int y){
    int fx=find(x);
    int fy=find(y);
    if(fx!=fy){
        fa[fx]=fy;
    }
}

void dfs(int u,int f){
    vis[u]=true;
    st[u][0]=f;
    deep[u]=deep[f]+1;
    for(int i=1;i<=LIMIT;i++){
        if(st[u][i-1]>0){
            st[u][i]=st[st[u][i-1]][i-1];
            val[u][i]=min(val[u][i-1],val[st[u][i-1]][i-1]);
        }
    }
    for(int i=head[u];i;i=Next[i]){
        int v=to[i];
        int w=weight[i];
        if(v!=f){
            val[v][0]=w;
            dfs(v,u);
        }
    }
}

int lca(int a,int b){
    int ans=INT_MAX;
    if (deep[a] < deep[b]) {
        int tmp = a;
        a = b;
        b = tmp;
    }
    //确定大小关系  将a永远变为深度更深的点(与b相比)  这样仅仅是为了方便操作
    for (int p = LIMIT ;p >= 0; p--) {
        if (deep[st[a][p]] >= deep[b]) {
            ans=min(ans,val[a][p]);
            a = st[a][p];
            //注意这两行代码  不要换位置 不然a发生改变  得到的ans不是我们想要的
        }
    }
    //首先将两者变为同一高度
    if (a == b) {
        return ans;
    }
    //如果相同说明就是祖先关系  是祖先关系直接返回ans就可以了
    //如果不理解的话  仔细想想val这个倍增表的含义
    for (int p = LIMIT; p >= 0; p--) {
        if (st[a][p] != st[b][p]) {
            ans=min(ans,min(val[a][p],val[b][p]));
            a = st[a][p];
            b = st[b][p];
        }
        //判断跳完后是否符合规则
    }
    //跑到了这里  那么fa[a][0]和fa[b][0]是一样的  就是他们的祖先
    //不会的话建议学一下lca
    ans = min(ans,min(val[a][0],val[b][0]));
    return ans;
}

