        l1=read(),r1=read(),l2=read(),r2=read();
        int k=one[r1-l1+1];
        // 在k层上合并区间
        un(l1,l2,k);
        un(r1-(1<<k)+1,r2-(1<<k)+1,k);
    }

    for(int k=one[n];k>=1;k--){
        for(int i=1;i+(1<<k)-1<=n;i++){
            int fa=find(i,k);
