        int lsz=sz[ls[u]]-sz[ls[v]];
        if(lsz>=jobk){
            return query(jobk,l,mid,ls[v],ls[u]);
        }
        else{
            return query(jobk-lsz,mid+1,r,rs[v],rs[u]);
        }
    }
}

