inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v,int id){
    nxtq[cnt]=head[u];
    qid[cnt]=id;
    qpos[cnt]=v;
    head[u]=cnt++;
}

inline int lowbit(int x){
    return x&-x;
}

void add(int x,int v){
    while(x<=n){
        tree[x]+=v;
        x+=lowbit(x);
    }
}

int query(int x){
    int ans=0;
    while(x){
        ans+=tree[x];
        x-=lowbit(x);
    }
    return ans;
}

pair<int,int>find(int x){
    int pos=0,sum=0;
    for(int i=17;i>=0;i--){
        int nxt=pos+(1<<i);
        if(nxt<=n&&sum+tree[nxt]<x){
            pos=nxt;
            sum+=tree[nxt];
        }
    }
    return {pos+1,x-sum};
}

