    }
    vector<vector<int>>base1(k+1,vector<int>(k+1,0));
    vector<vector<int>>base2(k+1,vector<int>(1,0));
    base2[0][0]=all;
    for(int i=1;i<=k;i++){
        base2[i][0]=b[k-i+1];
    }
    base1[0][0]=1;
    for(int i=1;i<=k;i++){
        base1[0][i]=c[i];
        base1[1][i]=c[i];
    }
    for(int i=2;i<=k;i++){
        base1[i][i-1]=1;
    }
    cin>>m>>n>>mod;
    int ans=0;
    if(m-1>=k){
        vector<vector<int>>ans1=multiply(power(base1,m-1-k),base2);
        ans-=ans1[0][0];
    }
    else{
        for(int i=1;i<=m-1;i++){
            ans-=b[i];
        }
    }
    if(n>=k){
