void addedge(int u,int v,int w){
    Next[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    head[u]=cnt++;
}

void insert(int num) {
    int cur = 1;
    for (int i = 30, path; i >= 0; i--) {
        path = (num >> i) & 1;
        if (tree[cur][path] == 0) {
            tree[cur][path] = ++tot;
        }
        cur = tree[cur][path];
    }
}

void dfs(int u,int f){
    for(int i=head[u];i>0;i=Next[i]){
        int v=to[i];
        int w=weight[i];
        if(v!=f){
            nums[v]=nums[f]^w;
            insert(nums[v]);
            //cout<<v<<' '<<num<<endl;
            dfs(v,u);
        }
    }
}

int maxXor(int num) {
    // 最终异或的结果(尽量大)
    int ans = 0;
    // 前缀树目前来到的节点编号
    int cur = 1;
    for (int i = 30, status, want; i >= 0; i--) {
        // status : num第i位的状态
        status = (num >> i) & 1;
        // want : num第i位希望遇到的状态
        want = status ^ 1;
        if (tree[cur][want] == 0) { // 询问前缀树，能不能达成
            // 不能达成
            want ^= 1;
        }
        // want变成真的往下走的路
        ans |= (status ^ want) << i;
        cur = tree[cur][want];
    }
    return ans;
}

