inline void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

inline void addEdge(int u,int v){
    nxtq[cntq]=headq[u];
    toq[cntq]=v;
    headq[u]=cntq++;
}

void dfs(int u){
    dfn[u]=++dfncnt;
    sz[u]=1;
    for(int i=headq[u];i;i=nxtq[i]){
        int v=toq[i];
        dfs(v);
        sz[u]+=sz[v];
    }
}

inline int lowbit(int x){
    return x&-x;
}

void add(int x,int v){
