        tree[x]+=v;
        x+=lowbit(x);
    }
}

void update(int id,int v){
    int cur=0;
    for(char ch:s[id]){
        cur=trie[cur][ch-'a'];
    }
    add(dfn[cur],v);
    add(dfn[cur]+sz[cur],-v);
}

int query(int u){
    int ans=0;
    int cur=0;
    for(char ch:s[u]){
        cur=trie[cur][ch-'a'];
        int x=dfn[cur];
        while(x){
            ans+=tree[x];
            x-=lowbit(x);
        }
    }
    return ans;
}

void dfs1(int u){
    if(op[u]==1){
        update(u,1);
