#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MOD = 19940417;
const int MAXN = 5e4+5;
const int MAXC = 21;

int n,q;
int val[MAXN];
int res[MAXC];

int f[MAXN<<2][MAXC];
int addtag[MAXN<<2];
bool rev[MAXN<<2];
int len[MAXN<<2];

int comb[MAXN][MAXC];

void merge(int *f,int *a,int *b){
    for(int i=0;i<MAXC;i++){
        f[i]=0;
    }
    for(int i=0;i<MAXC;i++){
        for(int j=0;j+i<MAXC;j++){
            f[i+j]=(f[i+j]+a[i]*b[j])%MOD;
        }
    }
}

void build(int l,int r,int i){
    len[i]=r-l+1;
    if(l==r){
        f[i][0]=1;
        f[i][1]=val[l]%MOD;
    }
    else{
        int mid=(l+r)>>1;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        merge(f[i],f[i<<1],f[i<<1|1]);
    }
}

void reverselazy(int i){
    for(int p=1;p<MAXC;p+=2){
        f[i][p]=(MOD-f[i][p])%MOD;
    }
    addtag[i]=(MOD-addtag[i])%MOD;
    rev[i]^=1;
}

void addlazy(int i,int v){
    int temp[MAXC];
    for(int p=0;p<MAXC;p++){
        temp[p]=0;
    }
    int length=len[i];
    int p[MAXC];
    p[0]=1;
    for(int id=1;id<MAXC;id++){
        p[id]=(p[id-1]*v)%MOD;
    }

    for(int k=0;k<min(length+1,MAXC);k++){
        for(int j=0;j<=k;j++){
            temp[k]=(temp[k]+f[i][j]*comb[length-j][k-j]%MOD*p[k-j])%MOD;
        }
    }
    for(int p=0;p<MAXC;p++){
        f[i][p]=temp[p];
    }
    addtag[i]=(addtag[i]+v)%MOD;
}

