	for (int i = 1, u, v, w; i < n; i++) {
		cin >> u >> v >> w;
		nbr[u].emplace_back((Edge){v, w});
		nbr[v].emplace_back((Edge){u, w});
	}
	for (int i = 1, u; i <= k; i++) {
		cin >> u;
		isK[u] = 1;
		root = u;
	}
