}

void tarjan(int x){
    dfn[x]=++dfncnt;
    low[x]=dfncnt;
    st[++top]=x;
    instack[x]=true;
    for(int i=head[x];i;i=nxt[i]){
        int v=to[i];
        if(now[i]==cap[i]){
            continue;
        }
        if(!dfn[v]){
            tarjan(v);
            low[x]=min(low[x],low[v]);
        }
        else if(instack[v]){
            low[x]=min(low[x],dfn[v]);
        }
