int help[MAXN];

long long val1[MAXN<<2];
long long val2[MAXN<<2];
long long val3[MAXN<<2];
long long val4[MAXN<<2];
bool tag[MAXN<<2];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
