    return a.val<b.val;
}

void floyd(){
    for(int k=1;k<=n;k++){
        //表示只经历1到k这些节点作为中间节点的情况
        for(int i=1;i<=n;i++){
            for(int j=1;j<=n;j++){
                int u=nums[i].sub,v=nums[j].sub,w=nums[k].sub;
                dis[u][v]=min(dis[u][v],dis[u][w]+dis[w][v]);
                ans[u][v]=min(ans[u][v],dis[u][v]+max(nums[i].val,max(nums[j].val,nums[k].val)));
            }
        }
    }
}

