    bnum=(n+blen-1)/blen;
    for(int i=1;i<=n;i++){
        bi[i]=(i+blen-1)/blen;
    }
    for(int i=1;i<=bnum;i++){
        bl[i]=(i-1)*blen+1;
        br[i]=min(n,i*blen);
    }

    for(int i=1;i<=n;i++){
        sortv[i]=val[i];
    }
    sort(sortv+1,sortv+n+1);
    len=1;
    for(int i=2;i<=n;i++){
        if(sortv[i]!=sortv[i-1]){
            sortv[++len]=sortv[i];
        }
    }

    for(int i=1;i<=n;i++){
        val[i]=find(val[i]);
    }

    sort(nums+1,nums+m+1,cmp);
}

int force(int l,int r){
    int ans=0;
    for(int i=l;i<=r;i++){
        cnt[val[i]]++;
        ans=max(ans,cnt[val[i]]*sortv[val[i]]);
    }
    for(int i=l;i<=r;i++){
        cnt[val[i]]--;
    }
    return ans;
}

void add(int val){
    cnt[val]++;
    maxval=max(maxval,cnt[val]*sortv[val]);
}

void del(int val){
    cnt[val]--;
}

void compute(){
    for(int qi=1,block=1;block<=bnum&&qi<=m;block++){
        maxval=0;
        for(int i=1;i<=len;i++){
            cnt[i]=0;
        }

        int winl=br[block]+1,winr=br[block];
        for(;qi<=m&&bi[nums[qi].l]==block;qi++){
            int l=nums[qi].l;
            int r=nums[qi].r;
            int id=nums[qi].id;

            if(r<=br[block]){
                ans[id]=force(l,r);
            }
            else{
                while(winr<r){
                    add(val[++winr]);
                }
                int backup=maxval;
                while(winl>l){
                    add(val[--winl]);
                }
                ans[id]=maxval;
                maxval=backup;
                while(winl<=br[block]){
                    del(val[winl++]);
                }
            }
        }
    }
}

