int tmpx[MAXN],tot=1;
int tmpy[MAXN],cnt=1;

int sum1[MAXN][MAXN];
int sum2[MAXN][MAXN];

int findx(int val){
    int l=1,r=tot,ans=1;
    while(l<=r){
        int mid=(l+r)/2;
        if(tmpx[mid]>=val){
            ans=mid;
