void build(){
    p[0]=1;
    for(int i=1;i<=n;i++){
        p[i]=p[i-1]*BASE;
        p[i]%=MOD;
    }
    for(int i=1;i<=n;i++){
        h[i]=h[i-1]*BASE+s[i]-'a'+1;
        h[i]%=MOD;
    }
}

int gethash(int l,int r){
