#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;

int n,m;

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int weight[MAXN<<1];
int cntg=1;

double dn[MAXN];
double up[MAXN];
int facnt[MAXN];
int soncnt[MAXN];

int from[MAXN];
int fromedge[MAXN];
int cycle[MAXN];
int dfncnt;
int dfn[MAXN];
int cnta;
int arr[MAXN];
int edgel[MAXN];
int edger[MAXN];

inline void addedge(int u,int v,int w){
    nxt[cntg]=head[u];
    to[cntg]=v;
    weight[cntg]=w;
    head[u]=cntg++;
}

void dfs1(int u,int fa){
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        int w=weight[i];
        if(v!=fa&&!cycle[v]){
            facnt[v]=1;
            dfs1(v,u);
            soncnt[u]++;
            dn[u]+=dn[v]+w;
        }
    }
    if(soncnt[u]){
        dn[u]/=soncnt[u];
    }
}

void dfs2(int u,int fa,int edgew){
    up[u]=edgew;
    int rest=facnt[fa]+soncnt[fa]-1;
    if(rest){
        up[u]+=(up[fa]*facnt[fa]+dn[fa]*soncnt[fa]-dn[u]-edgew)/rest;
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa&&!cycle[v]){
            dfs2(v,u,weight[i]);
        }
    }
}

void computeTree(){
    dfs1(1,0);
    for(int i=head[1];i;i=nxt[i]){
        int v=to[i];
        int w=weight[i];
        dfs2(v,1,w);
    }
}

void dfs(int u){
    dfn[u]=++dfncnt;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(dfn[v]==0){
            from[v]=u;
            fromedge[v]=i;
            dfs(v);
        }
        else if(dfn[u]<dfn[v]){
            cycle[u]=true;
            arr[++cnta]=u;
            facnt[u]=2;
            edger[u]=edgel[v]=i;
            for(int j=v;j!=u;j=from[j]){
                cycle[j]=true;
                arr[++cnta]=j;
                facnt[j]=2;
                int k=from[j];
                edger[j]=edgel[k]=fromedge[j];
            }
        }
    }
}

int leftid(int x){
    if(x==cnta){
        return 1;
    }
    return x+1;
}

int rightid(int x){
    if(x==1){
        return cnta;
    }
    return x-1;
}

void dponcycle(){
    for(int i=1;i<=cnta;i++){
        int u=arr[i];

        double p=0.5;
        for(int j=rightid(i);j!=i;j=rightid(j)){
            int x=arr[j];
            if(rightid(j)==i){
                up[u]+=p*(dn[x]+weight[edger[arr[j]]]);
            }
            else{
                up[u]+=p*(weight[edger[arr[j]]]+dn[x]*soncnt[x]/(soncnt[x]+1));
            }

            p/=(soncnt[x]+1);
        }

        p=0.5;
        for(int j=leftid(i);j!=i;j=leftid(j)){
            int x=arr[j];
            if(leftid(j)==i){
                up[u]+=p*(dn[x]+weight[edgel[arr[j]]]);
            }
            else{
                up[u]+=p*(weight[edgel[arr[j]]]+dn[x]*soncnt[x]/(soncnt[x]+1));
            }

            p/=(soncnt[x]+1);
        }
    }
}

void computeCycle(){
    dfs(1);
    for(int i=1;i<=cnta;i++){
        dfs1(arr[i],0);
    }
    dponcycle();
    for(int i=1;i<=cnta;i++){
        int u=arr[i];
        for(int e=head[u];e;e=nxt[e]){
            int v=to[e];
            int w=weight[e];
            if(!cycle[v]){
                dfs2(v,u,w);
            }
        }
    }
}

double compute(){
    double ans=0;
    for(int i=1;i<=n;i++){
        int cnt=facnt[i]+soncnt[i];
        if(cnt){
            ans+=(dn[i]*soncnt[i]+up[i]*facnt[i])/cnt;
        }
    }
    return ans;
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m;
    for(int i=1;i<=m;i++){
        int u,v,w;
        cin>>u>>v>>w;
        addedge(u,v,w);
        addedge(v,u,w);
    }

    if(m==(n-1)){
        computeTree();
    }
    else{
        computeCycle();
    }
    printf("%.8lf",compute()/n);
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;
const int LIMIT = 18;
#define int long long

struct node{
    int u,v;
}edge[MAXN];

struct ro{
    int w,w1,w2;
}nums[MAXN];

int head[MAXN];
int Next[MAXN<<1];
int to[MAXN<<1];
int road[MAXN<<1];
int cnt=1;
//链式前向星建图
int deep[MAXN],stjump[MAXN][LIMIT];
//倍增算法
int power;
int n;
int num[MAXN];

void dfs1(int u, int f) {
    deep[u] = deep[f] + 1;
    stjump[u][0] = f;
    for (int p = 1; p <= power; p++) {
        stjump[u][p] = stjump[stjump[u][p - 1]][p - 1];
    }
    //完成u的deep  stjump
    for (int e = head[u]; e != 0; e = Next[e]) {
        if (to[e] != f) {
            dfs1(to[e], u);
        }
        //向下递归
    }
}
//这个函数的作用是建立deep  st的信息
//为了方便下面查询lca

int lca(int a, int b) {
    if (deep[a] < deep[b]) {
        int tmp = a;
        a = b;
        b = tmp;
    }
    //确定大小关系
    for (int p = power; p >= 0; p--) {
        if (deep[stjump[a][p]] >= deep[b]) {
            a = stjump[a][p];
        }
    }
    //首先将两者变为同一高度
    if (a == b) {
        return a;
    }
    //如果相同说明就是祖先关系
    for (int p = power; p >= 0; p--) {
        if (stjump[a][p] != stjump[b][p]) {
            a = stjump[a][p];
            b = stjump[b][p];
        }
        //判断跳完后是否符合规则
    }
    return stjump[a][0];
    //我们将头结点的祖先设置为0  实际上没有0
}

void dfs(int u,int f){
    for(int i=head[u];i>0;i=Next[i]){
        int v=to[i];
        if(v!=f){
            dfs(v,u);
        }
    }
    for(int i=head[u];i>0;i=Next[i]){
        int v=to[i];
        int id=road[i];
        if(v!=f){
            nums[id].w+=num[v];
            num[u]+=num[v];
        }
    }
}

