        head[edge[i].u]=cnt++;

        Next[cnt]=head[edge[i].v];
        to[cnt]=edge[i].u;
        road[cnt]=i;
        head[edge[i].v]=cnt++;
    }
    dfs1(1,0);
    for(int i=1;i<n;i++){
