#define int long long
const int MAXN = 1505;
const int MAXM = 5005;
const int INF = 1e9;
const int MOD = 1e9+7;

int n,m;
struct Edge{
    int u,v,w;
};
Edge edge[MAXM];

int head[MAXN];
int nxt[MAXM];
int to[MAXM];
int weight[MAXM];
int cnt=1;

int ans[MAXM];

int dis[MAXN];
bool vis[MAXN];
int cntfrom[MAXN];
int cntto[MAXN];

int nums[MAXN];

struct node{
    int pos,dis;
};
struct compare{
    bool operator()(const node &a,const node &b){
        return a.dis>b.dis;
    }
};
priority_queue<node,vector<node>,compare>heap;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    head[u]=cnt++;
}

void dijkstra(int s){
    for(int i=1;i<=n;i++){
        dis[i]=INF;
        vis[i]=false;
    }
    dis[s]=0;
    heap.push({s,0});
    while(!heap.empty()){
        node tmp=heap.top();
        heap.pop();
        int u=tmp.pos;
        if(vis[u]){
            continue;
        }
        vis[u]=true;
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            int w=weight[i];
            if(dis[v]>dis[u]+w){
                dis[v]=dis[u]+w;
                heap.push({v,dis[v]});
            }
        }
    }
}

bool cmp(int a,int b){
    return dis[a]<dis[b];
}

void compute(int s){
    dijkstra(s);

    for(int i=1;i<=n;i++){
        nums[i]=i;
    }
    sort(nums+1,nums+n+1,cmp);

    for(int i=1;i<=n;i++){
        cntfrom[i]=0;
        cntto[i]=0;
    }
    cntfrom[s]=1;

    for(int i=1;i<=n;i++){
        int u=nums[i];
        if(dis[u]==INF){
            break;
        }
        for(int ei=head[u];ei;ei=nxt[ei]){
            int v=to[ei];
            int w=weight[ei];
            if(dis[v]==dis[u]+w){
                cntfrom[v]=(cntfrom[v]+cntfrom[u])%MOD;
            }
        }
    }

    for(int i=n;i>=1;i--){
        int u=nums[i];
        cntto[u]=1;
        if(dis[u]==INF){
            continue;
        }
        for(int ei=head[u];ei;ei=nxt[ei]){
            int v=to[ei];
            int w=weight[ei];
            if(dis[v]==dis[u]+w){
                cntto[u]=(cntto[v]+cntto[u])%MOD;
            }
        }
    }

    for(int i=1;i<=m;i++){
        int u=edge[i].u;
        int v=edge[i].v;
        int w=edge[i].w;
        if(dis[u]!=INF&&dis[v]!=INF&&dis[u]+w==dis[v]){
            ans[i]=(ans[i]+cntfrom[u]*cntto[v]%MOD)%MOD;
        }
    }
}

signed main()
{
    n=read(),m=read();
    for(int i=1;i<=m;i++){
        int u,v,w;
        u=read(),v=read(),w=read();
        addedge(u,v,w);
        edge[i]={u,v,w};
    }

    for(int i=1;i<=n;i++){
        compute(i);
    }

    for(int i=1;i<=m;i++){
        cout<<ans[i]<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int MAXT = 3e6+5;

int n,q;
map<pair<int,int>,int>mp;
char op[MAXN];
int x[MAXN],y[MAXN];

int fa[MAXN];
int sz[MAXN];
int st[MAXN][2];
int top;

int head[MAXN<<2];
int nxt[MAXT];
int tox[MAXT];
int toy[MAXT];
int cnt=1;

long long ans[MAXN];

inline void addedge(int u,int x,int y){
    nxt[cnt]=head[u];
    tox[cnt]=x;
    toy[cnt]=y;
    head[u]=cnt++;
}

int find(int x){
    while(x!=fa[x]){
        x=fa[x];
    }
    return x;
}

void add(int jobl, int jobr, int jobx, int joby, int l, int r, int i) {
    if (jobl <= l && r <= jobr) {
        addedge(i, jobx, joby);
    } else {
        int mid = (l + r) >> 1;
        if (jobl <= mid) {
            add(jobl, jobr, jobx, joby, l, mid, i << 1);
        }
        if (jobr > mid) {
            add(jobl, jobr, jobx, joby, mid + 1, r, i << 1 | 1);
        }
    }
}

void prepare(){
    for(int i=1;i<=n;i++){
        fa[i]=i;
        sz[i]=1;
    }
    for(int i=1;i<=q;i++){
        int v=mp[{x[i],y[i]}];
        if(v){
            if(op[v]=='Q'){
                v++;
            }
            add(v,i-1,x[i],y[i],1,q,1);
        }
        mp[{x[i],y[i]}]=i;
    }
    for(int i=1;i<=q;i++){
        int v=mp[{x[i],y[i]}];
        if(i==v){
            if(op[i]=='Q'){
                v++;
            }
            if(v<=q)
                add(v,q,x[i],y[i],1,q,1);
        }
    }
}

void un(int x,int y){
    int fx=find(x);
    int fy=find(y);
    if(sz[fx]<sz[fy]){
        swap(fx,fy);
    }
    fa[fy]=fx;
    sz[fx]+=sz[fy];
    st[++top][0]=fx;
    st[top][1]=fy;
}

void undo(){
    int fx=st[top][0];
    int fy=st[top--][1];
    fa[fy]=fy;
    sz[fx]-=sz[fy];
}

void dfs(int l, int r, int i) {
    int unioncnt=0;
    for(int ei=head[i];ei;ei=nxt[ei]){
        un(tox[ei],toy[ei]);
        unioncnt++;
    }
    if(l==r){
        if(op[l]=='Q'){
            ans[l]=1ll*sz[find(x[l])]*sz[find(y[l])];
        }
    }
    else{
        int mid=(l+r)>>1;
        dfs(l,mid,i<<1);
        dfs(mid+1,r,i<<1|1);
    }
    while(unioncnt--){
        undo();
    }
}

int main()
{
    scanf("%d %d",&n,&q);
    for(int i=1;i<=q;i++){
        scanf(" %c %d %d",&op[i],&x[i],&y[i]);
        // cout<<op[i]<<' '<<x[i]<<' '<<y[i]<<endl;
        if(x[i]>y[i]){
            swap(x[i],y[i]);
        }
    }
    prepare();
    dfs(1,q,1);
    for(int i=1;i<=q;i++){
        if(op[i]=='Q'){
            cout<<ans[i]<<endl;
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 5e5+5;
const int MAXH = 20;

int n,m,k;
int p;

int val[MAXN];
int pre[MAXN];
int f[MAXN];

int up[MAXH][MAXN];
int sum[MAXH][MAXN];

set<pair<long long,int>>st;

int MOD(int x){
    x%=k;
    if(x<0){
        x+=k;
    }
    return x;
}

void compute(int l,int r,int pos){
    auto it=st.lower_bound({l,-1});

    vector<pair<long long,int>>vec;
    while(it!=st.end()&&it->first<=r){
        vec.push_back(*it);
        it++;
    }
    for(auto p:vec){
        st.erase(p);
        f[p.second]=pos;
    }
}

signed main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m>>k;
    for(int i=1;i<=n;i++){
        cin>>val[i];
    }
    for(int i=1;i<=n;i++){
        if(i&1){
            pre[i]=pre[i-1]+val[i];
        }
        else{
            pre[i]=pre[i-1]-val[i];
        }
    }

    for(int i=1;i<=n+1;i++){
        f[i]=n+1;
    }

    for(int i=1;i<=n;i++){
        if(i&1){
            st.insert({MOD(pre[i-1]),i});
        }
        else{
            f[i]=i;
            int high=MOD(pre[i-1]);

            if(val[i]>=k-1){
                compute(0,k-1,i);
            }
            else{
                int low=MOD(high-val[i]);
                if(low<high){
                    compute(low,high,i);
                }
                else{
                    compute(low,k-1,i);
                    compute(0,high,i);
                }
            }
        }
    }

    for(int i=1;i<=n;i++){
        if(f[i]<=n){
            up[0][i]=f[i]+1;
            sum[0][i]=(pre[f[i]-1]-pre[i-1])/k;
        }
        else{
            up[0][i]=n+2;
        }
    }

    p=log2(n);
    for(int k=1;k<=p;k++){
        for(int i=1;i<=n;i++){
            int mid=up[k-1][i];
            if(mid<=n){
                up[k][i]=up[k-1][mid];
                sum[k][i]=sum[k-1][i]+sum[k-1][mid];
            }
            else{
                up[k][i]=n+2;
                sum[k][i]=sum[k-1][i];
            }
        }
    }

    for(int i=1;i<=m;i++){
        int l,r;
        cin>>l>>r;

        int ans=0;
        int cur=l;
        for(int k=p;k>=0;k--){
            if(cur<=n&&up[k][cur]<=r+1){
                ans+=sum[k][cur];
                cur=up[k][cur];
            }
        }
        if(cur<=r){
            ans+=(pre[r]-pre[cur-1])/k;
        }
        cout<<ans<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 1e5+5;
const int MAXM = 1e3+5;

int n,m;
int arr[MAXN];

struct node{
    int op,pos,t,val,id;
};
node event[MAXN<<2];
int cntq,cnte;

int blen,bnum;
int bl[MAXM];
int br[MAXM];
int bi[MAXN];
int lazy[MAXN];

int nums[MAXN];
int sorted[MAXN];

int ans[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

bool cmp(node a,node b){
    return (a.pos!=b.pos)?(a.pos<b.pos):(a.t<b.t);
}

void addchange(int pos,int t,int val){
    event[++cntq]={1,pos,t,val,0};
}

void addquery(int pos,int t,int val){
    event[++cntq]={2,pos,t,val,++cnte};
}

void inneradd(int l,int r,int v){
    for(int i=l;i<=r;i++){
        nums[i]+=v;
    }
    for(int i=bl[bi[l]];i<=br[bi[l]];i++){
        sorted[i]=nums[i];
    }
    sort(sorted+bl[bi[l]],sorted+br[bi[l]]+1);
}

void add(int l,int r,int v){
    int lb=bi[l],rb=bi[r];
    if(lb==rb){
        inneradd(l,r,v);
    }
    else{
        inneradd(l,br[bi[l]],v);
        inneradd(bl[bi[r]],r,v);
        for(int i=lb+1;i<=rb-1;i++){
            lazy[i]+=v;
        }
    }
}

int innerquery(int l,int r,int v){
    v-=lazy[bi[l]];
    int ans=0;
    for(int i=l;i<=r;i++){
        if(nums[i]>=v){
            ans++;
        }
    }
    return ans;
}

int getcnt(int i,int v){
    v-=lazy[i];
    int l=bl[i],r=br[i],ans=br[i]+1;
    while(l<=r){
        int mid=(l+r)>>1;
        if(sorted[mid]>=v){
            ans=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    return br[i]-ans+1;
}

int query(int l,int r,int v){
    int lb=bi[l],rb=bi[r],ans=0;
    if(lb==rb){
        ans=innerquery(l,r,v);
    }
    else{
        ans+=innerquery(l,br[bi[l]],v);
        ans+=innerquery(bl[bi[r]],r,v);
        for(int i=lb+1;i<=rb-1;i++){
            ans+=getcnt(i,v);
        }
    }
    return ans;
}

void prepare(){
    blen=sqrt(m);
    bnum=(m+blen-1)/blen;
    for(int i=1;i<=m;i++){
        bi[i]=(i-1)/blen+1;
    }
    for(int i=1;i<=bnum;i++){
        bl[i]=(i-1)*blen+1;
        br[i]=min(m,i*blen);
    }
    sort(event+1,event+cntq+1,cmp);
}

signed main()
{
    n=read(),m=read();
    for(int i=1;i<=n;i++){
        arr[i]=read();
    }
    m++;
    for(int t=2;t<=m;t++){
        int op,pos,val,l,r;
        op=read();
        if(op==1){
            l=read(),r=read(),val=read();
            addchange(l,t,val);
            addchange(r+1,t,-val);
        }
        else{
            pos=read(),val=read();
            addquery(pos,t,val);
        }
    }
    prepare();
    for(int i=1;i<=cntq;i++){
        if(event[i].op==1){
            add(event[i].t,m,event[i].val);
        }
        else{
            ans[event[i].id]=query(1,event[i].t-1,event[i].val-arr[event[i].pos]);
        }
    }
    for(int i=1;i<=cnte;i++){
        printf("%lld\n",ans[i]);
    }
    return 0;
}

// 监狱，C++版
// 一共有n个房间，给定n-1条无向边，所有房间组成一棵树
// 一共有m个囚犯，每个囚犯给出卧室房间号和工作室房间号，囚犯初始时都在卧室
// 每个囚犯的卧室和工作室一定不同，任何两个囚犯既不共用卧室，也不共用工作室
// 但是有可能某个房间，作为一个囚犯的卧室，同时作为另一个囚犯的工作室
// 你的任务是让所有囚犯从自己的卧室出发，只走最短路去自己的工作室
// 你可以随意下达指令，每条指令只能选择一个囚犯，沿一条边移动一步
// 任何时刻不能让任何房间里出现两个囚犯，打印你能否完成任务
// 1 <= n、m <= 1.2 * 10^5
// 测试链接 : https://www.luogu.com.cn/problem/P9520
// 如下实现是C++的版本，C++版本和java版本逻辑完全一样
// 提交如下代码，可以通过所有测试用例

#include <bits/stdc++.h>

using namespace std;

const int MAXN = 120001;
const int MAXT = MAXN * 50;
const int MAXE = MAXN * 200;
const int MAXP = 18;
int t, n, m;

int startTag[MAXN];
int endTag[MAXN];

int head1[MAXN];
int next1[MAXN << 1];
int to1[MAXN << 1];
int cnt1;

int indegree[MAXT];
int head2[MAXT];
int next2[MAXE];
int to2[MAXE];
int cnt2;

int dep[MAXN];
int dfn[MAXN];
int siz[MAXN];
int stjump[MAXN][MAXP];
int cntd;

int stout[MAXN][MAXP];
int stin[MAXN][MAXP];
int cntt;

int que[MAXT];

void addEdge1(int u, int v) {
   next1[++cnt1] = head1[u];
   to1[cnt1] = v;
   head1[u] = cnt1;
}

void addEdge2(int u, int v) {
   indegree[v]++;
   next2[++cnt2] = head2[u];
   to2[cnt2] = v;
   head2[u] = cnt2;
}

void build(int u, int fa) {
   dep[u] = dep[fa] + 1;
   dfn[u] = ++cntd;
   siz[u] = 1;
   stjump[u][0] = fa;
   stout[u][0] = ++cntt;
   addEdge2(startTag[u], cntt);
   addEdge2(startTag[fa], cntt);
   stin[u][0] = ++cntt;
   addEdge2(cntt, endTag[u]);
   addEdge2(cntt, endTag[fa]);
   for (int p = 1; p < MAXP; p++) {
       stjump[u][p] = stjump[stjump[u][p - 1]][p - 1];
       stout[u][p] = ++cntt;
       addEdge2(stout[u][p - 1], cntt);
       addEdge2(stout[stjump[u][p - 1]][p - 1], cntt);
       stin[u][p] = ++cntt;
       addEdge2(cntt, stin[u][p - 1]);
       addEdge2(cntt, stin[stjump[u][p - 1]][p - 1]);
   }
   for (int e = head1[u]; e > 0; e = next1[e]) {
       int v = to1[e];
       if (v != fa) {
           build(v, u);
           siz[u] += siz[v];
       }
   }
}

bool isAncestor(int a, int b) {
   return dfn[a] <= dfn[b] && dfn[b] < dfn[a] + siz[a];
}

int kthAncestor(int x, int k) {
   for (int p = 0; p < MAXP; p++) {
       if (((k >> p) & 1) != 0) {
           x = stjump[x][p];
       }
   }
   return x;
}

int nearest(int x, int y) {
   if (isAncestor(y, x)) {
       return kthAncestor(x, dep[x] - dep[y] - 1);
   } else {
       return stjump[y][0];
   }
}

void pathSet(int x, int y, int prisoner) {
   if (dep[x] < dep[y]) {
       swap(x, y);
   }
   addEdge2(startTag[y], prisoner);
   addEdge2(prisoner, endTag[y]);
   for (int p = MAXP - 1; p >= 0; p--) {
       if (dep[stjump[x][p]] >= dep[y]) {
           addEdge2(stout[x][p], prisoner);
           addEdge2(prisoner, stin[x][p]);
           x = stjump[x][p];
       }
   }
   if (x == y) {
       return;
   }
   for (int p = MAXP - 1; p >= 0; p--) {
       if (stjump[x][p] != stjump[y][p]) {
           addEdge2(stout[x][p], prisoner);
           addEdge2(stout[y][p], prisoner);
           addEdge2(prisoner, stin[x][p]);
           addEdge2(prisoner, stin[y][p]);
           x = stjump[x][p];
           y = stjump[y][p];
       }
   }
   addEdge2(stout[x][0], prisoner);
   addEdge2(prisoner, stin[x][0]);
}

void link(int x, int y) {
   int prisoner = ++cntt;
   addEdge2(prisoner, startTag[x]);
   addEdge2(prisoner, endTag[x]);
   addEdge2(startTag[y], prisoner);
   addEdge2(endTag[y], prisoner);
   if (stjump[x][0] != y && stjump[y][0] != x) {
       int a = nearest(y, x);
       int b = nearest(x, y);
       pathSet(a, b, prisoner);
   }
}

bool topo() {
   int qi = 1, qsiz = 0;
   for (int i = 1; i <= cntt; i++) {
       if (indegree[i] == 0) {
           que[++qsiz] = i;
       }
   }
   while (qi <= qsiz) {
       int u = que[qi++];
       for (int e = head2[u]; e > 0; e = next2[e]) {
           int v = to2[e];
           if (--indegree[v] == 0) {
               que[++qsiz] = v;
           }
       }
   }
   return qsiz == cntt;
}

void clear() {
   for (int i = 1; i <= n; i++) {
       head1[i] = 0;
   }
   for (int i = 1; i <= cntt; i++) {
       head2[i] = indegree[i] = 0;
   }
   cnt1 = cnt2 = cntt = cntd = 0;
   dep[1] = 0;
}

int main() {
   ios::sync_with_stdio(false);
   cin.tie(nullptr);
   cin >> t;
   for (int c = 1; c <= t; c++) {
       cin >> n;
       cntt = n << 1;
       for (int i = 1; i <= n; i++) {
           startTag[i] = i;
           endTag[i] = i + n;
       }
       for (int i = 1, u, v; i < n; i++) {
           cin >> u >> v;
           addEdge1(u, v);
           addEdge1(v, u);
       }
       build(1, 1);
       cin >> m;
       for (int i = 1, x, y; i <= m; i++) {
           cin >> x >> y;
           link(x, y);
       }
       bool ans = topo();
       cout << (ans ? "Yes" : "No") << "\n";
       clear();
   }
   return 0;
}

//对数组进行更新操作，并求最大值
#include<bits/stdc++.h>
using namespace std;
const int MAXN = 50005;

int arr[MAXN];
int Max[MAXN<<2];
int Min[MAXN<<2];
int n,m;

//比较左右两边最大值
void maxup(int i) {
    Max[i] = max(Max[i << 1] ,Max[i << 1 | 1]);
}

void minup(int i) {
    Min[i] = min(Min[i << 1] ,Min[i << 1 | 1]);
}

int maxquery(int jobl, int jobr, int l, int r, int i) {
    if (jobl <= l && r <= jobr) {
        return Max[i];
    }
    int mid = (l + r) >> 1;
    int ans = 0;
    if (jobl <= mid) {
        ans =max(ans, maxquery(jobl, jobr, l, mid, i << 1));
    }
    if (jobr > mid) {
        ans =max(ans, maxquery(jobl, jobr, mid + 1, r, i << 1 | 1));
    }
    return ans;
}

int minquery(int jobl, int jobr, int l, int r, int i) {
    if (jobl <= l && r <= jobr) {
        return Min[i];
    }
    int mid = (l + r) >> 1;
    int ans = 1e9;
    if (jobl <= mid) {
        ans =min(ans, minquery(jobl, jobr, l, mid, i << 1));
    }
    if (jobr > mid) {
        ans =min(ans, minquery(jobl, jobr, mid + 1, r, i << 1 | 1));
    }
    return ans;
}

void maxbuild(int l, int r, int i) {
    if (l == r) {
        Max[i] = arr[l];
    } else {
        int mid = (l + r) >> 1;
        maxbuild(l, mid, i << 1);
        maxbuild(mid + 1, r, i << 1 | 1);
        maxup(i);
    }
}

void minbuild(int l, int r, int i) {
    if (l == r) {
        Min[i] = arr[l];
    } else {
        int mid = (l + r) >> 1;
        minbuild(l, mid, i << 1);
        minbuild(mid + 1, r, i << 1 | 1);
        minup(i);
    }
}

