            int l,r,w;
            cin>>l>>r>>w;
            addEdge(l-1,r,w);
            addEdge(r,l-1,-w);
        }
        if(!spfa(n+1)){
            cout<<"true"<<endl;
        }else
            cout<<"false"<<endl;
    }
    return 0;
}

