int querymax(int l,int r){
    int p=lg2[r-l+1];
    return max(stmax[l][p],stmax[r-(1<<p)+1][p]);
}

int querymin(int l,int r){
    int p=lg2[r-l+1];
    return min(stmin[l][p],stmin[r-(1<<p)+1][p]);
}

signed main()
{
