}

bool spfa(double k){
    while(!q.empty()){
        q.pop();
    }
    for(int i=1;i<=n+1;i++){
        dis[i]=INT_MAX;
        updatecnt[i]=0;
        enter[i]=false;
    }
    dis[n+1]=0;
    updatecnt[n+1]++;
    enter[n+1]=false;
    q.push(n+1);
    while(!q.empty()){
        int u=q.front();
        q.pop();
        enter[u]=false;
        for(int i=head[u];i;i=nxt[i]){
