#include<bits/stdc++.h>
using namespace std;
const int MAXN = 5e5+5;
const int MAXT = MAXN*25;

int n,m;
int root[MAXT];
int ls[MAXT];
int rs[MAXT];
int sum[MAXT];
int cnt;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

int build(int l, int r) {
    int rt = ++cnt;
    if (l < r) {
        int mid = (l + r) / 2;
        ls[rt] = build(l, mid);
        rs[rt] = build(mid + 1, r);
    }
    sum[rt] = 0;
    return rt;
}

int add(int pos,int l,int r,int i){
    int rt=++cnt;
    ls[rt] = ls[i];
	rs[rt] = rs[i];
	sum[rt] = sum[i] + 1;
    if(l==r){
        //cout<<' '<<l<<endl;
        return rt;
    }
    else{
        int mid=(l+r)/2;
        if(pos<=mid)
            ls[rt]=add(pos,l,mid,ls[i]);
        else
            rs[rt]=add(pos,mid+1,r,rs[i]);
    }
    return rt;
}

int query(int l,int r,int u,int v,int len){
    if(l==r){
        if(sum[v]-sum[u]>=len){
            return l;
        }
        return 0;
    }
    int lsize=sum[ls[v]]-sum[ls[u]];
    int rsize=sum[rs[v]]-sum[rs[u]];
    int mid=(l+r)/2;
    if(lsize>=len){
        return query(l,mid,ls[u],ls[v],len);
    }
    else if(rsize>=len){
        return query(mid+1,r,rs[u],rs[v],len);
    }
    else{
        return 0;
    }
}

