bool cmp(node a,node b){
    if(a.x!=b.x){
        return a.x<b.x;
    }
    if(a.y!=b.y){
        return a.y<b.y;
    }
    return a.op<b.op;
}

void merge(int l,int m,int r){
    int p1,p2;
    int minn=4e9;
    for(p1=l-1,p2=m+1;p2<=r;p2++){
        while(p1+1<=m&&nums[p1+1].y<=nums[p2].y){
            p1++;
            if(nums[p1].op==1){
                minn=min(minn,nums[p1].id-nums[p1].x-nums[p1].y);
            }
        }
        if(nums[p2].op==2){
            ans[nums[p2].id]=min(ans[nums[p2].id],nums[p2].x+nums[p2].y+minn);
        }
    }
    p1=l,p2=m+1;
    int i=l;
    while(p1<=m&&p2<=r){
        tmp[i++]=(nums[p1].y<=nums[p2].y)?nums[p1++]:nums[p2++];
    }
    while(p1<=m){
        tmp[i++]=nums[p1++];
    }
    while(p2<=r){
        tmp[i++]=nums[p2++];
    }
    for(int i=l;i<=r;i++){
        nums[i]=tmp[i];
    }
}

void cdq(int l,int r){
    if(l==r){
        return ;
    }
    int mid=(l+r)>>1;
    cdq(l,mid);
    cdq(mid+1,r);
    merge(l,mid,r);
}

