        u=read(),v=read(),w=read();
        addedge(u,v,w);
        addedge(v,u,w);
    }
    dfs(1,0);
    dfs1(1,0,0);
    for(int u=1;u<=n;u++){
        minval[u]=minval[u]*2-arr[u];
    }
    dfs2(1,0);
    dfs3(1,1);
    build(1,n,1);
    for(int i=1;i<=m;i++){
        int u,v;
        u=read(),v=read();
