int getcentroid(int u,int fa){
    getsize(u,fa);
    int half=sz[u]>>1;
    bool flag=false;
    while(!flag){
        flag=true;
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            if(v!=fa&&!vis[v]&&sz[v]>=half){
                flag=false;
                fa=u;
                u=v;
                break;
            }
        }
    }
    return u;
}

void addedge(int u,int v,int w){
    nxt[cntg]=head[u];
    to[cntg]=v;
    weight[cntg]=w;
    head[u]=cntg++;
}

int gcd(int a,int b){
    return b==0?a:gcd(b,a%b);
}

int cur[3];
int all[3];

void dfs(int u,int fa,int w){
    cur[w]++;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        int ww=weight[i];
        if(v!=fa&&!vis[v]){
            dfs(v,u,(ww+w)%3);
        }
    }
}

int calc(int u){
    int ans=1;
    all[0]=all[1]=all[2]=0;
    cur[0]=cur[1]=cur[2]=0;
    all[0]=1;

    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        int w=weight[i];
        if(!vis[v]){
            cur[0]=cur[1]=cur[2]=0;
            dfs(v,u,w);

            ans+=all[0]*cur[0]*2+all[1]*cur[2]*2+all[2]*cur[1]*2;
            all[0]+=cur[0];
            all[1]+=cur[1];
            all[2]+=cur[2];
        }
    }
    return ans;
}

int solve(int u){
    int ans=0;
    vis[u]=true;
    ans+=calc(u);
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(!vis[v]){
            ans+=solve(getcentroid(v,u));
        }
    }
    return ans;
}

