            sum[i]+=x;
            if(i<j){
                addedge(i,j,2*x);
                addedge(j,i,2*x);
            }
        }
    }

    int total=0;
    for(int i=1;i<=n;i++){
        int val=sum[i]-a[i];
        if(val>0){
            total+=val;
            addedge(s,i,val);
        }
        else{
            addedge(i,t,-val);
        }
    }

    int flow=maxflow();
    cout<<(total-flow)<<endl;
    return 0;
