}

struct Cmp {
    inline bool operator()(const int x, const int y) {
        return b[x] > b[y];
    }
};

bool check1(long long x) {
    int i = 1;
    while (x >= a[tmp[i]]) {
        x += c[tmp[i]];
        if (++i > n) return true;
    }
    return false;
}

bool check2(long long x) {
    std::priority_queue<int, std::vector<int>, Cmp> Q;
    int i = 1, j;
    long long y = fusu;

    while (true) {
        while (i <= n && a[tmp[i]] <= y) {
            Q.push(tmp[i++]);
        }
        if (Q.empty()) {
            return i > n;
        }
        bool flag = false;
        while (!Q.empty() && b[j = Q.top()] <= x) {
            flag = true;
            Q.pop();
            y += c[j];
            x += d[j];
        }
        if (!flag) return false;
    }
}

