#include<bits/stdc++.h>
using namespace std;
const int MAXN = 155;
const int INF = 1e9;

int n,m;
int val[MAXN][MAXN];
int cost[MAXN][MAXN];
int d[MAXN][MAXN];
bool vis[MAXN][MAXN];
int fa[MAXN][MAXN];

int find(int i,int j){
    if(j>=m+1){
        return m+1;
    }
    return fa[i][j]==j?j:fa[i][j]=find(i,fa[i][j]);
}

struct node{
    int x,y,dis;
};
struct compare{
    bool operator()(node a,node b){
        return a.dis>b.dis;
    }
};
priority_queue<node,vector<node>,compare>heap;

void dijkstra(int sx,int sy){
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            fa[i][j]=j;
            vis[i][j]=false;
            d[i][j]=INF;
        }
    }
    d[sx][sy]=0;
    heap.push({sx,sy,0});
    while(!heap.empty()){
        node u=heap.top();
        heap.pop();
        int x=u.x,y=u.y,dis=u.dis;
        if(vis[x][y]){
            continue;
        }
        vis[x][y]=true;
        int f=find(x,y+1);
        fa[x][y]=f;

        int range=val[x][y];
        if(range==0){
            continue;
        }

        int sti=max(1,x-range);
        int eni=min(n,x+range);

        for(int i=sti;i<=eni;i++){
            int d1=range-abs(i-x);
            int l=max(1,y-d1);
            int r=min(m,y+d1);
            int j=find(i,l);
            while(j<=r){
                int d2=cost[x][y]+dis;
                if(d2<d[i][j]){
                    d[i][j]=d2;
                    heap.push({i,j,d2});
                }
                j=find(i,j+1);
            }
        }
    }
}

int main()
{
    cin>>n>>m;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            cin>>val[i][j];
        }
    }
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            cin>>cost[i][j];
        }
    }
    int x1,y1,x2,y2,x3,y3;
    cin>>x1>>y1>>x2>>y2>>x3>>y3;

    int d1=0,d2=0,d3=0;
    dijkstra(x1,y1);
    d2+=d[x2][y2];
    d3+=d[x3][y3];


    dijkstra(x2,y2);
    d1+=d[x1][y1];
    d3+=d[x3][y3];

    dijkstra(x3,y3);
    d2+=d[x2][y2];
    d1+=d[x1][y1];

    if(d1>=INF&&d2>=INF&&d3>=INF){
        cout<<"NO"<<endl;
    }
    else{
        if(d1<=d2&&d1<=d3){
            cout<<'X'<<endl<<d1<<endl;
        }
        else if(d2<=d3){
            cout<<'Y'<<endl<<d2<<endl;
        }
        else{
            cout<<'Z'<<endl<<d3<<endl;
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;
const int MAXT = MAXN*10;

int n,m;

int root[MAXN];
int ls[MAXT];
int rs[MAXT];
long long sum[MAXT];
int version;

int pool[MAXT];
int top;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void prepare(){
    top=0;
    for(int i=1;i<MAXT;i++){
        pool[++top]=i;
    }
}

int newnode(){
    return pool[top--];
}

void del(int x){
    pool[++top]=x;
    ls[x]=0;
    rs[x]=0;
    sum[x]=0;
}

void up(int x){
    sum[x]=sum[ls[x]]+sum[rs[x]];
}

int add(int pos,int jobv,int l,int r,int i){
    int rt=i;
    if(rt==0){
        rt=newnode();
    }
    if(l==r){
        sum[rt]+=jobv;
    }
    else{
        int mid=(l+r)>>1;
        if(pos<=mid){
            ls[rt]=add(pos,jobv,l,mid,ls[rt]);
        }
        else{
            rs[rt]=add(pos,jobv,mid+1,r,rs[rt]);
        }
        up(rt);
    }
    return rt;
}

long long query(int jobl,int jobr,int l,int r,int i){
    if(i==0){
        return 0;
    }
    if(jobl<=l&&r<=jobr){
        return sum[i];
    }
    else{
        int mid=(l+r)>>1;
        long long ans=0;
        if(jobl<=mid){
            ans+=query(jobl,jobr,l,mid,ls[i]);
        }
        if(jobr>mid){
            ans+=query(jobl,jobr,mid+1,r,rs[i]);
        }
        return ans;
    }
}

int kth(int jobk,int l,int r,int i){
    if(i==0){
        return -1;
    }
    if(l==r){
        return l;
    }
    else{
        int mid=(l+r)>>1;
        if(sum[ls[i]]>=jobk){
            return kth(jobk,l,mid,ls[i]);
        }
        else{
            return kth(jobk-sum[ls[i]],mid+1,r,rs[i]);
        }
    }
}

int merge(int l,int r,int t1,int t2){
    if(t1==0||t2==0){
        return t1+t2;
    }
    if(l==r){
        sum[t1]+=sum[t2];
    }
    else{
        int mid=(l+r)>>1;
        ls[t1]=merge(l,mid,ls[t1],ls[t2]);
        rs[t1]=merge(mid+1,r,rs[t1],rs[t2]);
        up(t1);
    }
    del(t2);
    return t1;
}

int tree1,tree2;

void split(int jobl,int jobr,int l,int r,int t1){
    if(t1==0){
        tree1=t1;
        tree2=0;
        return ;
    }
    if(jobl<=l&&r<=jobr){
        tree1=0;
        tree2=t1;
        return ;
    }
    int t2=newnode();
    int mid=(l+r)>>1;
    if(jobl<=mid){
        split(jobl,jobr,l,mid,ls[t1]);
        ls[t1]=tree1;
        ls[t2]=tree2;
    }
    if(jobr>mid){
        split(jobl,jobr,mid+1,r,rs[t1]);
        rs[t1]=tree1;
        rs[t2]=tree2;
    }
    up(t1);
    up(t2);
    tree1=t1;
    tree2=t2;
}

int main()
{
    prepare();
    n=read(),m=read();
    version=1;
    for(int i=1;i<=n;i++){
        int x=read();
        root[version]=add(i,x,1,n,root[version]);
    }
    for(int i=1;i<=m;i++){
        int op,x,y,z;
        op=read(),x=read(),y=read();
        if(op==0){
            z=read();
            split(y,z,1,n,root[x]);
            root[x]=tree1;
            root[++version]=tree2;
        }
        else if(op==1){
            root[x]=merge(1,n,root[x],root[y]);
        }
        else if(op==2){
            z=read();
            root[x]=add(z,y,1,n,root[x]);
        }
        else if(op==3){
            z=read();
            cout<<query(y,z,1,n,root[x])<<endl;
        }
        else{
            cout<<kth(y,1,n,root[x])<<endl;
        }
    }
    return 0;
}

