node nums[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

bool cmp(node a,node b){
    return a.w<b.w;
}

int find(int x){
    return fa[x]==x?x:fa[x]=find(fa[x]);
}

long long compute(int s,int t){
    for(int i=1;i<=n;i++){
        fa[i]=i;
    }
    degree[s]++,degree[t]++;
    long long ans=sum;
    fa[find(s)]=find(t);
    int pre=0;
    for(int i=1;i<=n;i++){
        if(degree[i]&1){
            if(pre){
                ans+=i-pre;
                for(int j=pre;j<i;j++){
                    fa[find(belong[j])]=find(belong[i]);
                }
                pre=0;
            }
            else{
                pre=i;
            }
        }
    }
    cnt=0;
    pre=0;
    for(int i=1;i<=n;i++){
        if(degree[i]){
            if(pre&&find(belong[i])!=find(belong[pre])){
                nums[++cnt]={belong[i],belong[pre],i-pre};
            }
            pre=i;
        }
    }
    sort(nums+1,nums+cnt+1,cmp);
    for(int i=1;i<=cnt;i++){
        if(find(nums[i].u)!=find(nums[i].v)){
            fa[find(nums[i].u)]=find(nums[i].v);
            ans+=nums[i].w*2;
        }
    }
    degree[s]--,degree[t]--;
    return ans;
}

