        cin>>u>>v>>p>>e;

        addedge(u,v,p,e);
        addedge(v,u,p,e);
    }

    dfs1(1,0);

    for(int i=1;i<=n;i++){
        best[i]=INF;
    }

    best[1]=0;

    for(int s=1;s<=n;s++){
        dfs2(s,s,0,0,0);
    }

    priority_queue<
        pair<long long,int>,
        vector<pair<long long,int>>,
        greater<pair<long long,int>>
    > heap;

    for(int i=1;i<=n;i++){
        dis[i]=best[i];

        if(dis[i]<INF){
            heap.push({dis[i],i});
        }
    }

    while(!heap.empty()){
        long long du=heap.top().first;
        int u=heap.top().second;
        heap.pop();

        if(du!=dis[u]){
            continue;
        }

        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            long long nd=du+we[i];

            if(nd<dis[v]){
                dis[v]=nd;
                heap.push({nd,v});
            }
        }
    }

    safe[1]=true;
    dfs3(1,0);

    if(cntans<l){
        cout<<"no solution\n";
        return 0;
    }

    sort(ans+1,ans+cntans+1);

    long long k=ans[l];
    int r=upper_bound(ans+1,ans+cntans+1,k)-ans-1;

    cout<<k<<'\n';
    cout<<r<<'\n';

    return 0;
}

