int maxx[MAXN<<2];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void up(int i){
    tree[i]=(tree[i<<1]|tree[i<<1|1]);
    maxx[i]=max(maxx[i<<1],maxx[i<<1|1]);
}

void build(int l,int r,int i){
    if(l==r){
        tree[i]=maxx[i]=val[l];
    }
    else{
        int mid=(l+r)>>1;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        up(i);
    }
}

void change(int pos,int jobv,int l,int r,int i){
    if(l==r){
        tree[i]=jobv;
        maxx[i]=jobv;
    }
    else{
        int mid=(l+r)/2;
        if(pos<=mid){
            change(pos,jobv,l,mid,i<<1);
        }
        else{
            change(pos,jobv,mid+1,r,i<<1|1);
        }
        up(i);
    }
}

void update(int jobl,int jobr,int jobv,int l,int r,int i){
    if((tree[i]&jobv)==tree[i]){
        return ;
    }
    if(jobl<=l&&r<=jobr){
        if(l==r){
            tree[i]=tree[i]&jobv;
            maxx[i]=tree[i];
            return;
        }
        int mid=(l+r)>>1;
        update(jobl,jobr,jobv,l,mid,i<<1);
        update(jobl,jobr,jobv,mid+1,r,i<<1|1);
        up(i);
    }
    else{
        int mid=(l+r)>>1;
        if(jobl<=mid){
            update(jobl,jobr,jobv,l,mid,i<<1);
        }
        if(jobr>mid){
            update(jobl,jobr,jobv,mid+1,r,i<<1|1);
        }
        up(i);
    }
}

int query(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        return maxx[i];
    }
    else{
        int mid=(l+r)>>1;
        int ans=0;
        if(jobl<=mid){
            ans=max(ans,query(jobl,jobr,l,mid,i<<1));
        }
        if(jobr>mid){
            ans=max(ans,query(jobl,jobr,mid+1,r,i<<1|1));
        }
        return ans;
    }
}

