using namespace std;
const int MOD = 1e9+7;

int n,m;
int dis[1<<24];//表示在状态i下，走到哪个位置
bool ok[1<<24];//表示在状态i下，走到的位置是否有效
int bad[2];//表示厄运数字
int dp[1<<24];//表示在i的情况下有多少种方案

int main()
{
    //cout<<change(16)<<' '<<change(64)<<' '<<endl;
    cin>>n;
    for(int i=0;i<n;i++){
        cin>>dis[1<<i];
    }
    cin>>m;
    for(int i=0;i<m;i++){
        cin>>bad[i];
    }
    //完成输入与输出

    dis[0]=0;
    for(int s=1;s<(1<<n); s++){
        int j=s&-s,k=s;
        dis[s]=dis[s^j]+dis[j];//子集和自己的补集  补集一定是只含有最右边的那个1
		ok[s]=true;
		for(int i=0;i<m;i++){
            if(dis[s]==bad[i]){
                ok[s]=false;
                break;
            }
		}
	}
	//完成dis  ok数组的初始化

	dp[0]=1;
	for(int s=1;s<(1<<n);s++){
        int k=s;
        while(k&&ok[s]){
            int j = k & -k; //j是当前找到的lowbit
            dp[s] = (dp[s] + dp[s ^ j])%MOD;
            k ^= j; //k中去掉这个"1"，这样下次lowbit会找到另一个"1"
        }
	}
	cout<<dp[(1<<n)-1]<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 250005;
const int MAXK = 5e5+5;
const int MAXH = 20;

int n,m,p;

int headg[MAXN];
int nxtg[MAXN<<1];
int tog[MAXN<<1];
int weightg[MAXN<<1];
int cntg=1;

int k;
int key[MAXN];
int tmp[MAXN<<1];
bool iskey[MAXN];
int cost[MAXN];

int st[MAXN][MAXH];
int dis[MAXN][MAXH];
int dep[MAXN];

int dfncnt;
int dfn[MAXN];

int headv[MAXN];
int nxtv[MAXN];
int tov[MAXN];
int weightv[MAXN];
int cntv=1;

void addedgeg(int u,int v,int w){
    nxtg[cntg]=headg[u];
    tog[cntg]=v;
    weightg[cntg]=w;
    headg[u]=cntg++;
}

void dfs(int u,int fa){
    dep[u]=dep[fa]+1;
    dfn[u]=++dfncnt;
    st[u][0]=fa;
    for(int i=1;i<=p;i++){
        st[u][i]=st[st[u][i-1]][i-1];
        dis[u][i]=min(dis[u][i-1],dis[st[u][i-1]][i-1]);
    }

    for(int i=headg[u];i;i=nxtg[i]){
        int v=tog[i];
        if(v!=fa){
            int w=weightg[i];
            dis[v][0]=w;
            dfs(v,u);
        }
    }
}

void prepare(){
    p=log2(n)+1;
    dfs(1,0);
}

int lca(int a,int b){
    if(dep[a]<=dep[b]){
        swap(a,b);
    }
    for(int i=p;i>=0;i--){
        if(dep[st[a][i]]>=dep[b]){
            a=st[a][i];
        }
    }
    if(a==b){
        return a;
    }
    for(int i=p;i>=0;i--){
        if(st[a][i]!=st[b][i]){
            a=st[a][i];
            b=st[b][i];
        }
    }
    return st[a][0];
}

int getdist(int a,int b){
    if(a==b){
        return 0;
    }
    if(dep[a]<=dep[b]){
        swap(a,b);
    }
    int ans=1e6;
    for(int i=p;i>=0;i--){
        if(dep[st[a][i]]>=dep[b]){
            ans=min(ans,dis[a][i]);
            a=st[a][i];
        }
    }
    return ans;
}

void addedgev(int u,int v,int w){
    // cout<<"   "<<u<<' '<<v<<' '<<w<<endl;
    nxtv[cntv]=headv[u];
    tov[cntv]=v;
    weightv[cntv]=w;
    headv[u]=cntv++;
}

bool cmp(int a,int b){
    return dfn[a]<dfn[b];
}

int buildvirtualtree(){
    sort(key+1,key+k+1,cmp);

    int len=k;
    for(int i=1;i<=k;i++){
        tmp[i]=key[i];
    }
    for(int i=1;i<k;i++){
        tmp[++len]=lca(key[i],key[i+1]);
    }

    sort(tmp+1,tmp+len+1,cmp);

    len=1;
    for(int i=2;i<=2*k-1;i++){
        if(tmp[i]!=tmp[i-1]){
            tmp[++len]=tmp[i];
        }
    }

    cntv=1;
    for(int i=1;i<=len;i++){
        headv[tmp[i]]=0;
        // cout<<' '<<tmp[i];
    }
    // cout<<endl;

    for(int i=1;i<len;i++){
        int fa=lca(tmp[i],tmp[i+1]);
        addedgev(fa,tmp[i+1],getdist(fa,tmp[i+1]));
    }
    return tmp[1];
}

void dp(int u){
    cost[u]=0;
    for(int i=headv[u];i;i=nxtv[i]){
        int v=tov[i];
        int w=weightv[i];
        dp(v);
        if(iskey[v]){
            cost[u]+=w;
        }
        else{
            cost[u]+=min(cost[v],w);
        }
    }
}

int compute(){
    int ans=0;
    key[++k]=1;
    for(int i=1;i<=k;i++){
        iskey[key[i]]=true;
    }

    int tree=buildvirtualtree();
    dp(tree);
    ans=cost[tree];

    for(int i=1;i<=k;i++){
        iskey[key[i]] = false;
    }
    return ans;
}

