{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n;
    for(int i=1;i<n;i++){
        int u,v,w;
        cin>>u>>v>>w;
        addedgeg(u,v,w);
        addedgeg(v,u,w);
    }

    prepare();

    cin>>m;
    for(int i=1;i<=m;i++){
        cin>>k;
        for(int j=1;j<=k;j++){
            cin>>key[j];
        }
        cout<<compute()<<endl;
    }
    return 0;
}

