        dp[i][0]=0;
        for(int j=1;j<(1<<m);j++){
            int low=j&-j;
            int bit=log2(low);
            dp[i][j]=dp[i][j-low]-cost[i][bit];
        }
    }
}

void dfs(int u,int fa){
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa){
