            for(int j=(1<<m)-1;j>=0;j--){
                for(int k=j;k;k=(k-1)&j){
                    dp[u][j]=max(dp[u][j],dp[u][j^k]+dp[v][k]);
                }
            }
        }
    }
    for(int i=0;i<(1<<m);i++){
        dp[u][i]+=val[i];
    }
}

