        double sum=0;
        for(int j=1;j<i;j++){
            sum+=p[i-j]*dp[i-1][j];
        }
        sum/=3;
        sum=sum+1.0/6;
        dp[i][1]=sum/(1-p[i]);
        for(int j=2;j<=i;j++){
            dp[i][j]=0.5*dp[i][j-1]+1.0/3*dp[i-1][j-1];
        }
    }
    printf("%.9lf",dp[n][m]);
    return 0;
}

