#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;
const int MAXT = MAXN*20;

int n,m,k;

int fa[MAXN];
int sz[MAXN];
int traceback[MAXT][2];
int opsize;

int head[MAXN<<2];
int nxt[MAXT];
int tox[MAXT];
int toy[MAXT];
int cnt=1;

map<pair<int,int>,int>mp;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

int find(int x){
    while(x!=fa[x]){
        x=fa[x];
    }
    return x;
}

void undo(){
    int fx=traceback[opsize][0];
    int fy=traceback[opsize][1];
    fa[fy]=fy;
    sz[fx]-=sz[fy];
    opsize--;
}

void addedge(int u,int x,int y){
    nxt[cnt]=head[u];
    tox[cnt]=x;
    toy[cnt]=y;
    head[u]=cnt++;
}

void add(int jobl,int jobr,int jobx,int joby,int l,int r,int i){
    if(jobl>jobr){
        return ;
    }
    if(jobl<=l&&r<=jobr){
        addedge(i,jobx,joby);
    }
    else{
        int mid=(l+r)>>1;
        if(jobl<=mid){
            add(jobl,jobr,jobx,joby,l,mid,i<<1);
        }
        if(jobr>mid){
            add(jobl,jobr,jobx,joby,mid+1,r,i<<1|1);
        }
    }
}

void un(int x,int y){
    if(sz[x]<sz[y]){
        swap(x,y);
    }
    fa[y]=x;
    sz[x]+=sz[y];
    ++opsize;
    traceback[opsize][0]=x;
    traceback[opsize][1]=y;
}

void dfs(int l,int r,int i){
    bool flag=false;
    int unioncnt=0;
    for(int ei=head[i];ei;ei=nxt[ei]){
        int x=tox[ei];
        int y=toy[ei];
        int fx=find(x);
        int fy=find(y);
        if(fx==fy){
            flag=true;
            break;
        }
        else{
            un(fx,fy);
            unioncnt++;
        }
    }

    if(flag){
        for(int p=l;p<=r;p++){
            cout<<"Yes\n";
        }
    }
    else{
        if(l==r){
            cout<<"No\n";
        }
        else{
            int mid=(l+r)>>1;
            dfs(l,mid,i<<1);
            dfs(mid+1,r,i<<1|1);
        }
    }

    while(unioncnt){
        undo();
        unioncnt--;
    }
}

int main()
{
    n=read(),m=read();
    for(int i=1;i<=2*n;i++){
        fa[i]=i;
        sz[i]=1;
    }

    for(int i=1;i<=m;i++){
        int x=read();
        int y=read()+n;
        mp[{x,y}]=1;
    }

    k=read();
    for(int i=1;i<=k;i++){
        int x=read();
        int y=read()+n;
        if(mp.count({x,y})&&mp[{x,y}]){
            add(mp[{x,y}],i-1,x,y,1,k,1);
            mp[{x,y}]=0;
        }
        else{
            mp[{x,y}]=i;
        }
    }

    for(auto it=mp.begin();it!=mp.end();it++){
        if(it->second!=0){
            add(it->second,k,it->first.first,it->first.second,1,k,1);
        }
    }
    dfs(1,k,1);
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 55;
const int MAXM = 1050;

int n,m;
int arr[MAXN];
int nums[MAXM];
int pre[MAXM];
int sum;

int totalCake;
int needCake;
int wasteCake;

bool sub_DFS(int toTest, int origin)            // origin：遍历蛋糕数组的起点
{
    /* 结束递归 */
    if(toTest<1)
        return true;                            // 已经完成1~toTest的人的喂食，测试通过
    if(totalCake-wasteCake<needCake)
        return false;                           // 总蛋糕小于总需求，必然失败，停止搜索

    /* 搜索 */
    bool flag = false;
    for(int i=origin;i<=n;++i)                  // 遍历蛋糕，尝试将蛋糕喂给第toTest号人
    {
        if(arr[i]>=nums[toTest])
        {
            needCake-=nums[toTest];            // 喂食：消耗蛋糕，满足需求
            totalCake-=nums[toTest];
            arr[i]-=nums[toTest];

            bool wasted = false;                // 回溯：是否使用了蛋糕渣优化
            if(arr[i]<nums[1])                // 优化：蛋糕渣不能满足最低需求，不可用
            {
                wasteCake+=arr[i];             // 此蛋糕渣将被浪费，设置优化启动的标志
                wasted = true;
            }
            if(nums[toTest]==nums[toTest-1])  // 下一个测试对象的嘴和当前的嘴一样大
            {
                if(sub_DFS(toTest-1,i))         // 优化：从当前的位置继续遍历蛋糕列表
                    flag = true;                // 优化：找到解决方案，就不再继续搜索
            }
            else if(sub_DFS(toTest-1,1))        // 无法优化，直接递归。
                flag = true;                    // 优化：同上分支

            /* 回溯 */
            if(wasted)                          // 若做了优化，则撤回
                wasteCake-=arr[i];
            arr[i]+=nums[toTest];             // 撤回全部变化
            totalCake+=nums[toTest];
            needCake+=nums[toTest];

            if(flag)
                return true;
        }
    }

    /* 结束递归 */
    return false;                               // 无法找到合适的蛋糕，测试失败
}

inline bool DFS(int toTest)                     // DFS：检查答案toTest是否可行
{
    /* 准备变量 */
    totalCake = sum;
    needCake = pre[toTest];
    wasteCake = 0;

    /* 启动递归 */
    return sub_DFS(toTest,1);
}

int main()
{
    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>arr[i];
        sum+=arr[i];
    }
    sort(arr+1,arr+n+1);
    cin>>m;
    for(int i=1;i<=m;i++){
        cin>>nums[i];
    }
    sort(nums+1,nums+m+1);
    for(int i=1;i<=m;i++){
        pre[i]=pre[i-1]+nums[i];
    }
    int l=0,r=m;
    for(int i=1;i<=m;i++){
        if(nums[i]>arr[n]){
            r=i-1;
            break;
        }
        if(pre[i]>sum){
            r=i-1;
            break;
        }
    }
    int ans=0;
    while(l<=r){
        int mid=(l+r)>>1;
        if(DFS(mid)){
            ans=mid;
            l=mid+1;
        }
        else{
            r=mid-1;
        }
    }
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 55;
const int MAXV = 105;
const int MAXE = 4*MAXN*MAXN;
const int INF = 1e9;
const double eps = 1e-8;

int n,m,s,t;
double all;
int a[MAXN],b[MAXN];
int node[MAXN];

int dep[MAXV];
int iter[MAXV];

int cnt=2;
int head[MAXV];
int nxt[MAXE];
int to[MAXE];
double now[MAXE];
double cap[MAXE];

void addedge(int u,int v,double w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    cap[cnt]=w;
    now[cnt]=0;
    head[u]=cnt++;

    nxt[cnt]=head[v];
    to[cnt]=u;
    cap[cnt]=0;
    now[cnt]=0;
    head[v]=cnt++;
}

bool bfs(){
    for(int i=1;i<=t;i++){
        dep[i]=-1;
    }
    queue<int>q;
    dep[s]=0;
    q.push(s);
    while(!q.empty()){
        int u=q.front();
        q.pop();
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            double w=cap[i];
            double k=now[i];
            if(dep[v]<0&&(k+eps<w)){
                dep[v]=dep[u]+1;
                q.push(v);
            }
        }
    }
    return dep[t]>=0;
}

double dfs(int u,double f){
    if(u==t){
        return f;
    }
    double flow=0;
    for(int &i=iter[u];i;i=nxt[i]){
        int v=to[i];
        double w=cap[i];
        double k=now[i];
        if(dep[u]+1==dep[v]&&k+eps<w){
            double d=dfs(v,min(f,w-k));
            if(d>eps){
                now[i]+=d;
                now[i^1]-=d;
                flow+=d;
                f-=d;
                if(f<=eps){
                    break;
                }
            }
        }
    }
    return flow;
}

double maxflow(){
    double flow=0;
    while(bfs()){
        //当前弧全部初始化为最初值
        for(int i=1;i<=t;i++){
            iter[i]=head[i];
        }
        double maxflow;
        while((maxflow=dfs(s,INF))>0){
            flow+=maxflow;
        }
    }
    return flow;
}

bool check(double limit){
    for(int i=2;i<=cnt;i++){
        now[i]=0;
    }
    for(int i=1;i<=m;i++){
        cap[node[i]]=limit*b[i];
    }
    double flow=maxflow();
    return flow+eps>=all;
}

