    for(int i=1;i<=n;i++){
        while(tot<=m&&nums[tot].l<=i){
            if(nums[tot].r>=i){
                heap.push({nums[tot].l,nums[tot].r});
            }
            tot++;
        }
        while(sum(i)<limit){
            if(heap.empty()){
                //表示已经没有任何区间可以帮助这个点达标
                return false;
            }
            if(cnt==k){
                //表示前面的点已经耗费了所有的指标
                return false;
            }
            if(heap.top().first<=i&&heap.top().second>=i){
                cnt++;
                add(heap.top().first,q);
                add(heap.top().second+1,-q);
            }
            heap.pop();
        }
    }
    return true;
}

int main()
{
    int T;
    T=read();
    while(T--){
        n=read(),m=read(),k=read(),q=read();
        int l=1e8,r=1e8;
        for(int i=1;i<=n;i++){
            arr[i]=read();
            l=min(l,arr[i]);
        }
        r=k*q+l;
        for(int i=1;i<=m;i++){
            nums[i].l=read(),nums[i].r=read();
        }
        sort(nums+1,nums+m+1,cmp);//按照左端点排序 左端点相同 按照右端点排序
        int ans=l;
        while(l<=r){
            int mid=(l+r)/2;
            if(check(mid)){
                ans=mid;
                l=mid+1;
            }
            else{
                r=mid-1;
            }
        }
        cout<<ans<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int INF = 1e9;

int n,m;

bool vis[MAXN];
int dis[MAXN];
int change[MAXN];
int pre[MAXN];

struct edge{
    int u,v,w;
    bool flag;
}nums[MAXN];

struct node{
    int u,dis,change;
};

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int weight[MAXN<<1];
int id[MAXN<<1];
int cnt=1;

struct compare{
    bool operator()(const node&a,const node&b){
        if(a.dis==b.dis){
            return a.change>b.change;
        }
        else{
            return a.dis>b.dis;
        }
    }
};
priority_queue<node,vector<node>,compare>heap;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    head[u]=cnt++;
}

void dijkstra(){
    for(int i=1;i<=n;i++){
        dis[i]=INF;
        change[i]=INF;
    }
    dis[1]=0;
    change[1]=0;
    heap.push({1,0,0});
    while(!heap.empty()){
        int u=heap.top().u;
        heap.pop();
        if(vis[u]){
            continue;
        }
        vis[u]=true;
        if(u==n){
            break;
        }
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            if(dis[v]>dis[u]+1){
                dis[v]=1+dis[u];
                pre[v]=(i+1)/2;
                change[v]=change[u]+(1-weight[i]);
                heap.push({v,dis[v],change[v]});
            }
            else if(dis[v]==dis[u]+1&&change[v]>(change[u]+(1-weight[i]))){
                pre[v]=(i+1)/2;
                change[v]=change[u]+(1-weight[i]);
                heap.push({v,dis[v],change[v]});
            }
        }
    }
}

int main()
{
    n=read(),m=read();
    int ans=0;
    for(int i=1;i<=m;i++){
        nums[i].u=read();
        nums[i].v=read();
        nums[i].w=read();
        ans+=nums[i].w;
        addedge(nums[i].u,nums[i].v,nums[i].w);
        addedge(nums[i].v,nums[i].u,nums[i].w);
    }
    dijkstra();
    printf("%d\n",ans-dis[n]+2*change[n]);
    int i=n;
    while(1){
        nums[pre[i]].flag=true;
        i=(nums[pre[i]].u+nums[pre[i]].v)-i;
        if(i==1){
            break;
        }
    }
    for(int i=1;i<=m;i++){
        if(nums[i].flag){
            if(nums[i].w!=1){
                printf("%d %d 1\n",nums[i].u,nums[i].v);
            }
        }
        else{
            if(nums[i].w!=0){
                printf("%d %d 0\n",nums[i].u,nums[i].v);
            }
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;

int n,m;
int f[55][1 << 8][1 << 8], dp[55][1 << 8][1 << 8];
int sum[55][1 << 8], nums[55][8], ans1 = INT_MAX, ans2 = INT_MAX;
int cnt[1<<8];

int main()
{
    cin>>n>>m;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            cin>>nums[i][j];
        }
    }
    for(int i=0;i<=n;i++){
        for(int j=0;j<(1<<m);j++){
            for(int k=0;k<(1<<m);k++){
                f[i][j][k]=1e9;
            }
        }
    }
    for(int j=0;j<(1<<m);j++){
        for(int k=0;k<m;k++){
            if(j&(1<<k)){
                cnt[j]++;
            }
        }
    }
    for(int i=1;i<=n;i++){
        for(int j=0;j<(1<<m);j++){
            for(int k=0;k<m;k++){
                if(j&(1<<k)){
                    sum[i][j]+=nums[i][k+1];
                }
            }
        }
    }
    for(int i=0;i<(1<<m);i++){
        f[1][i][0]=sum[1][i];
        dp[1][i][0]+=cnt[i];
    }
    for(int i=2;i<=n;i++){
        for(int j=0;j<(1<<m);j++){//当前行
            for(int k=0;k<(1<<m);k++){//上一行
                for(int u=0;u<(1<<m);u++){//上上一行
                    if(((j|k|u|k>>1|k<<1)&(1<<m)-1)==(1<<m)-1){
                        int t = f[i - 1][k][u] + sum[i][j], p = dp[i - 1][k][u] + cnt[j];
						if (f[i][j][k] > t || f[i][j][k] == t && dp[i][j][k] > p)
							f[i][j][k] = t, dp[i][j][k] = p;
                    }
                }
            }
        }
    }
    for (int i = 0; i < 1 << m; i ++)
		for (int j = 0; j < 1 << m; j ++)
			if (((i | j | i << 1 | i >> 1) & (1 << m) - 1) == (1 << m) - 1)
				if (ans1 > f[n][i][j] || f[n][i][j] == ans1 && dp[n][i][j] < ans2)
					ans1 = f[n][i][j], ans2 = dp[n][i][j];
	cout << ans2 << ' ' << ans1 <<'\n';
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 1e5+5;

int n,m;
int val[MAXN];

//链式前向星建图
int head[MAXN];
int Next[MAXN<<1];
int to[MAXN<<1];
int tot=1;

//线段树
int tree[MAXN<<2];
int lazy[MAXN<<2];
int len[MAXN<<2];//要记录长度 因为这里加的话是每一个元素都要加

//树链剖分部分
int son[MAXN];//重儿子编号  叶子结点没有
int id[MAXN];//重新编号后的编号
int rk[MAXN];//重新编号后的编号对应原来的编号是什么
int cnt;
int fa[MAXN];//父亲节点编号
int deep[MAXN];//节点深度
int sz[MAXN];//以该节点为首的子树节点总数
int top[MAXN];//这条重链的头结点

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v){
    Next[tot]=head[u];
    to[tot]=v;
    head[u]=tot++;
}

//第一遍dfs 完成sz、deep、fa、son数组的统计
void dfs1(int u,int f){
    fa[u]=f;
    deep[u]=deep[f]+1;
    sz[u]=1;
    for(int i=head[u];i;i=Next[i]){
        int v=to[i];
        if(v==f){
            continue;
        }
        dfs1(v,u);
        sz[u]+=sz[v];
        if(sz[son[u]]<sz[v]){
            son[u]=v;
        }
    }
}

//第二遍dfs 完成top、rk、id
void dfs2(int u,int t){
    top[u]=t;
    id[u]=++cnt;
    rk[cnt]=u;
    if(son[u]){
        //存在重儿子  优先遍历
        dfs2(son[u],t);
    }
    for(int i=head[u];i;i=Next[i]){
        int v=to[i];
        if(v!=fa[u]&&v!=son[u]){
            dfs2(v,v);
            //另外在开一条重链
        }
    }
}

//线段树部分
void up(int i){
    tree[i]=tree[i<<1]+tree[i<<1|1];
}

//注意编号问题
void build(int l,int r,int i){
    lazy[i]=0;
    len[i]=r-l+1;
    if(l==r){
        tree[i]=val[rk[l]];
    }
    else{
        int mid=(l+r)/2;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        up(i);
    }
}

void downlazy(int i,int v){
    tree[i]+=len[i]*v;
    lazy[i]+=v;
}

void down(int i){
    if(lazy[i]){
        downlazy(i<<1,lazy[i]);
        downlazy(i<<1|1,lazy[i]);
        lazy[i]=0;
    }
}

void add(int jobl,int jobr,int jobv,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        downlazy(i,jobv);
    }
    else{
        int mid=(l+r)/2;
        down(i);
        if(jobl<=mid){
            add(jobl,jobr,jobv,l,mid,i<<1);
        }
        if(jobr>mid){
            add(jobl,jobr,jobv,mid+1,r,i<<1|1);
        }
        up(i);
    }
}

int query(int jobl,int jobr,int l,int r,int i){
    if(jobl<=l&&r<=jobr){
        return tree[i];
    }
    else{
        int mid=(l+r)/2;
        down(i);
        int ans=0;
        if(jobl<=mid){
            ans+=query(jobl,jobr,l,mid,i<<1);
        }
        if(jobr>mid){
            ans+=query(jobl,jobr,mid+1,r,i<<1|1);
        }
        return ans;
    }
}

inline void update(int x,int y,int val){
    while(top[x]!=top[y]){
        if(deep[top[x]]<deep[top[y]])
            swap(x,y);
        add(id[top[x]],id[x],val,1,n,1);//结算这条重链上存在的贡献
        x=fa[top[x]];
    }
    //两点在同一条重链上
    if(id[x]>id[y])
        swap(x,y);
    add(id[x],id[y],val,1,n,1);
    //结算贡献区间
}

inline int sum(int x,int y){
    int ans=0;
    while(top[x]!=top[y]){
        if(deep[top[x]]<deep[top[y]])
            swap(x,y);
        ans+=query(id[top[x]],id[x],1,n,1);
        x=fa[top[x]];
    }
    if(id[x]>id[y])
        swap(x,y);
    ans+=query(id[x],id[y],1,n,1);
    return ans;
}

signed main()
{
    n=read(),m=read();
    for(int i=1;i<=n;i++){
        cin>>val[i];
    }
    for(int i=1;i<n;i++){
        int u,v;
        u=read(),v=read();
        addedge(u,v);
        addedge(v,u);
    }
    dfs1(1,0);
    dfs2(1,1);
    build(1,n,1);
    for(int i=1;i<=m;i++){
        int op,u,v;
        cin>>op;
        if(op==1){
            u=read(),v=read();
            add(id[u],id[u],v,1,n,1);
        }
        else if(op==2){
            u=read(),v=read();
            add(id[u],id[u]+sz[u]-1,v,1,n,1);
        }
        else{
            u=read();
            cout<<sum(1,u)<<endl;
        }
    }
    return 0;
}
